#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    MAC_Header header;
    char* payload;
    int payload_length;
    MAC_Trailer trailer;
} MAC_PDU_T;

void validate_MAC_PDU(const MAC_PDU_T *pdu) {
    if (!pdu || !pdu->payload) return;

    size_t total_len = sizeof(MAC_Header) + pdu->payload_length + sizeof(MAC_Trailer);
    if (total_len > sizeof(*pdu)) {
        fprintf(stderr, "Buffer overflow in MAC_PDU\n");
        return;
    }

    if (pdu->header.length_or_fcs != pdu->payload_length + sizeof(MAC_Header) + sizeof(MAC_Trailer)) {
        fprintf(stderr, "Invalid MAC_PDU: FCS does not match calculated value\n");
    }
}

void generate_random_payload(char* buffer, int len) {
    srand(time(NULL));
    for (int i = 0; i < len; ++i) {
        buffer[i] = rand() % 256;
    }
}

MAC_PDU_T* create_MAC_PDU(int max_payload_len) {
    MAC_PDU_T *pdu = (MAC_PDU_T*)malloc(sizeof(MAC_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Error: Failed to allocate memory for MAC_PDU\n");
        return NULL;
    }

    pdu->payload_length = rand() % (max_payload_len + 1);
    if (pdu->payload_length == 0) {
        fprintf(stderr, "Error: Payload length cannot be zero\n");
        free(pdu);
        return NULL;
    }

    pdu->payload = malloc(pdu->payload_length);
    if (!pdu->payload) {
        fprintf(stderr, "Error: Failed to allocate memory for MAC_Payload\n");
        free(pdu);
        return NULL;
    }

    generate_random_payload(pdu->payload, pdu->payload_length);

    // Fill in the MAC_Header and MAC_Trailer with appropriate values (excluding FCS)
    // Note: FCS should be calculated and filled after filling in the payload

    pdu->header.dst_addr = 0x01;
    pdu->header.src_addr = 0x02;
    pdu->header.type = 0x03;

    // Set the FCS field in MAC_Header to zero initially, as it will be calculated later

    return pdu;
}

void destroy_MAC_PDU(MAC_PDU_T *pdu) {
    if (!pdu) return;

    free(pdu->payload);
    free(pdu);
}

void verify_and_print_MAC_PDUs(MAC_PDU_T *pdus, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        validate_MAC_PDU(pdus + i);
        if (pdus[i]) {
            printf("MAC PDU %ld:\n", i);
            printf("\tHeader: ");
            print_MAC_Header(&pdus[i]->header);
            printf("\tPayload (%d bytes):", pdus[i]->payload_length);
            for (int j = 0; j < pdus[i]->payload_length; ++j) {
                printf(" %hhx", pdus[i]->payload[j]);
            }
            printf("\tTrailer: ");
            print_MAC_Trailer(&pdus[i]->trailer);
        }
    }
}

// Implement functions for printing MAC_Header and MAC_Trailer structures here
