#include <unistd.h>

/* Global variables */
char *input_file = NULL;
char keyword[5] = "info";
int count_keywords = 0;
bool print_manpage = false, count_occurrences = false, redirect_output = false;
FILE *output_file = stdout;

/* Function prototypes */
void usage(char *program_name);
int read_line(FILE *, char **);
bool contains_keyword(const char *);
void print_results(FILE *);

int main(int argc, char *argv[]) {
    static struct option long_options[] = {
        {"help", no_argument, NULL, 'h'},
        {"manpage", no_argument, NULL, 'M'},
        {"search", required_argument, NULL, 's'},
        {"count", no_argument, NULL, 'c'},
        {"output", required_argument, NULL, 'o'},
        {0, 0, 0, 0}
    };

    int opt = 0;
    while ((opt = getopt_long(argc, argv, "hMs:cgo:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                usage(argv[0]);
                return 0;
            case 'M':
                print_manpage = true;
                break;
            case 's':
                strncpy(keyword, optarg, sizeof(keyword));
                break;
            case 'c':
                count_keywords = true;
                break;
            case 'o':
                redirect_output = true;
                input_file = optarg;
                break;
            default:
                usage(argv[0]);
                return -1;
        }
    }

    if (!input_file) {
        printf("Error: No input file provided.\n");
        usage(argv[0]);
        return -1;
    }

    FILE *in = fopen(input_file, "r");
    if (!in) {
        perror("Error opening input file");
        return -1;
    }

    if (print_manpage) {
        usage(argv[0]);
        return 0;
    }

    print_results(output_file);

    fclose(in);
    return 0;
}

void usage(char *program_name) {
    printf("\nUsage: %s [options] input_file\n\n", program_name);
    printf("Options:\n");
    printf(" -h, --help             Display this help and exit.\n");
    printf(" -M, --manpage           Print detailed usage information.\n");
    printf(" -s, --search keyword   Search for the specified keyword (default: info).\n");
    printf(" -c, --count             Count occurrences of each keyword.\n");
    printf(" -o, --output output_file Redirect output to specified file.\n");
}

int read_line(FILE *in, char **line) {
    size_t len = 0;
    size_t cap = 0;
    char c;

    while ((c = getc(in)) != EOF && !feof(in)) {
        if (len >= cap) {
            cap *= 2;
            *line = realloc(*line, cap + 1);
        }
        (*line)[len++] = c;
        (*line)[len] = '\0';
    }

    return len > 0 ? len - 1 : EOF;
}

bool contains_keyword(const char *str) {
    size_t keyword_len = strlen(keyword);
    if (strlen(str) < keyword_len)
        return false;

    size_t i;
    for (i = 0; i < keyword_len; ++i) {
        if (str[i] != keyword[i])
            break;
    }

    return i == keyword_len;
}

void print_results(FILE *out) {
    int line_count = 0, kw_count = 0;
    char line[4096];
    while (read_line(input_file, &line) > 0) {
        ++line_count;
        if (contains_keyword(line)) {
            if (count_keywords)
                ++kw_count;
            fprintf(out, "Line %d: %s\n", line_count, line);
        }
    }

    if (!count_keywords && !redirect_output) {
        fprintf(out, "\nNumber of lines: %d\n", line_count);
    } else if (count_keywords) {
        fprintf(out, "Keyword count:\n");
        fprintf(out, "  error: 0\n");
        fprintf(out, "  warning: 0\n");
        fprintf(out, "  info: %d\n", kw_count);
        fprintf(out, "  debug: 0\n");
    }
}
```

