#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>

typedef struct {
    time_t timestamp;
    int error_count;
    char event[256];
} LogEntry;

void parse_log(const char *input_file, const char *output_file, const char *criteria, int max_entries) {
    FILE *input = fopen(input_file, "r");
    FILE *output = fopen(output_file, "w");

    if (!input || !output) {
        perror("Error opening files");
        return;
    }

    LogEntry current_entry;
    size_t entries_count = 0;
    LogEntry *entries = NULL;

    while (fscanf(input, "%ld %s %*[^\n]\n", &current_entry.timestamp, current_entry.event) == 2) {
        if (entries_count >= max_entries) break;

        current_entry.error_count = strstr(current_entry.event, "ERROR") != NULL ? 1 : 0;
        current_entry.timestamp -= current_entry.timestamp % 86400; // Align timestamp to start of day

        if (entries == NULL) {
            entries = malloc(max_entries * sizeof(LogEntry));
            memset(entries, 0, max_entries * sizeof(LogEntry));
        }

        int index = time((time_t*)NULL) / 86400 % max_entries;
        for (size_t i = index; i < entries_count; ++i) {
            if ((current_entry.timestamp == entries[i].timestamp) && (strcmp(current_entry.event, entries[i].event) == 0)) {
                entries[i].error_count += current_entry.error_count;
                goto next;
            }
        }

        entries[entries_count++] = current_entry;

    next: {}
    }

    if (entries) free(entries);
    fclose(input);
    fclose(output);

    time_t now = time(NULL);
    char date_str[32];
    strftime(date_str, sizeof(date_str), "%Y-%m-%d %H:%M", localtime(&now));
    fprintf(output, "Summary for %s:\n\n", date_str);

    struct {
        char *name;
        int (*aggregator)(LogEntry*, size_t, FILE*);
    } aggregators[] = {
        {"Error Count", count_errors},
        {"Event Frequency", count_events}
    };

    for (size_t i = 0; i < sizeof(aggregators) / sizeof(aggregators[0]); ++i) {
        fprintf(output, "%s:\n", aggregators[i].name);
        aggregators[i].aggregator(entries, entries_count, output);
    }
}

void count_errors(LogEntry *entries, size_t count, FILE *output) {
    for (size_t i = 0; i < count; ++i)
        fprintf(output, " - %ld: %d error(s)\n", entries[i].timestamp, entries[i].error_count);
}

void count_events(LogEntry *entries, size_t count, FILE *output) {
    for (size_t i = 0; i < count; ++i)
        fprintf(output, " - %s: %ld event(s)\n", entries[i].event, entries[i].error_count + 1);
}
