        if (is_integer(line)) {
            arr = realloc(arr, sizeof(int)*(++count));
            arr[count-1] = atoi(line);
        }
    }

    if (!arr) {
        free(arr);
        arr = NULL;
    }

    return arr;
}

void find_largest(int *arr, int size) {
    int i, largest = arr[0];

    for (i = 1; i < size; ++i) {
        if (arr[i] > largest)
            largest = arr[i];
    }

    printf("Largest integer: %d\n", largest);
}

