import subprocess, os, sys, ast, json, hashlib, typing

class Pokemon:
    def __init__(self, name, type):
        self.name = name
        self.type = type

    def weaknesses(self) -> str:
        if self.type == "fire":
            return ["water", "ground"]
        elif self.type == "water":
            return ["electric", "grass"]
        elif self.type == "grass":
            return ["fire", "ice", "poison"]
        elif self.type == "electric":
            return ["water"]
        elif self.type == "ground":
            return ["water", "grass"]
        elif self.type == "ice":
            return ["grass", "water", "fire"]
        elif self.type == "fighting":
            return ["flying", "psychic"]
        elif self.type == "flying":
            return ["electric", "rock"]
        elif self.type == "psychic":
            return ["ghost", "dark"]
        else:
            raise ValueError(f"Invalid Pokemon type: {self.type}")

def encrypt_password(password: str) -> str:
    salt = b'my_salt_here'
    password_encoded = password.encode()
    hashed = hashlib.pbkdf2_hmac('sha256', password_encoded, salt, 100000)
    return base64.b64encode(hashed).decode()

def replace_placeholders(file_path: str, placeholders: dict) -> None:
    with open(file_path, 'r') as file:
        content = file.read()
        for key, value in placeholders.items():
            content = content.replace(f'{{{key}}}', value)
    with open(file_path, 'w') as file:
        file.write(content)

def modify_kickstart_config(file_path: str, params: dict) -> None:
    replacement_placeholders = {'api_password': encrypt_password(params['api_password'])}
    replace_placeholders(file_path, replacement_placeholders)
    password_line = f'api_password={params["api_password"]}\n'
    new_content = f"{os.linesep}{password_line".join(open(file_path).readlines())
    with open(f'modified_{file_path}', 'w') as file:
        file.write(new_content)

def main() -> None:
    params = json.loads(sys.argv[1])
    pokemon = Pokemon('pikachu', params['type'])
    print(', '.join(pokemon.weaknesses()))
    modify_kickstart_config(params['config'], params)

if __name__ == "__main__":
    main()
