import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.json.JSONObject;

import com.mashape.unirest.http.HttpResponse;
import com.mashape.unirest.http.JsonNode;
import com.mashape.unirest.http.Unirest;

public class PokemonReport {
    private static final Map<Integer, Pokemon> pokemonCache = new ConcurrentHashMap<>();

    public String generatePokemonReport(Pokemon pokemon) {
        try {
            if (!pokemonCache.containsKey(pokemon.getId())) {
                // Retrieve Pokemon data and cache it
                HttpResponse<JsonNode> response = Unirest.get("https://pokeapi.co/api/v2/pokemon/" + pokemon.getId())
                        .asJson();
                if (response.getStatus() != 200) {
                    throw new IOException("Failed to fetch Pokemon data");
                }
                JsonNode jsonNode = response.getBody();
                Pokemon fetchedPokemon = new Pokemon(jsonNode);
                pokemonCache.put(pokemon.getId(), fetchedPokemon);
                pokemon = fetchedPokemon;
            }
        } catch (IOException e) {
            // Log the error and return an empty report
            System.err.println("Error fetching Pokemon data: " + e.getMessage());
            return new JSONObject().toString();
        }

        Map<String, Object> report = new HashMap<>();
        report.put("name", pokemon.getName());
        report.put("type", getTypeName(pokemon.getType()));
        report.put("generation", pokemon.getGeneration());

        if (pokemon.getGeneration() > 7) {
            try {
                // Fetch additional details from external API and add to the report
                HttpResponse<JsonNode> additionalDetailsResponse = Unirest.get("https://pokeapi.co/api/v2/pokemon/" + pokemon.getId())
                        .header("cache-control", "no-store") // Avoid caching for this specific API call to ensure fresh data
                        .asJson();
                if (additionalDetailsResponse.getStatus() != 200) {
                    throw new IOException("Failed to fetch additional Pokemon details");
                }
                JsonNode additionalDetails = additionalDetailsResponse.getBody();
                // Add more details to the report based on the structure of the response from the external API
                // ...
            } catch (IOException e) {
                // Log the error and continue with the existing report data
                System.err.println("Error fetching additional Pokemon details: " + e.getMessage());
            }
        }

        Map<String, String[]> weaknessesAndStrengths = getWeaknessesAndStrengths(pokemon.getType());
        report.put("weaknesses", weaknessesAndStrengths.get("weaknesses"));
        report.put("strengths", weaknessesAndStrengths.get("strengths"));
        report.put("types", getTypeNames(pokemon.getType()));

        return new JSONObject(report).toString();
    }

    private String[] getTypeNames(int... types) {
        StringBuilder typeNames = new StringBuilder();
