} AlgorithmImpl;

typedef struct AlgorithmList {
    pthread_mutex_t mutex;
    AlgorithmImpl** data;
    size_t count;
    size_t capacity;
} AlgorithmList;

AlgorithmList* initialize_algorithm_list() {
    AlgorithmList* list = malloc(sizeof(AlgorithmList));
    pthread_mutex_init(&list->mutex, NULL);
    list->data = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

void add_algorithm_impl(AlgorithmList* list, AlgorithmImpl* impl) {
    pthread_mutex_lock(&list->mutex);

    if (list->capacity <= list->count) {
        void** tmp = realloc(list->data, sizeof(AlgorithmImpl*) * 2 * list->capacity);
        if (!tmp) {
            fprintf(stderr, "Failed to allocate memory for algorithm list\n");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->data = tmp;
        list->capacity *= 2;
    }

    list->data[list->count++] = impl;

    pthread_mutex_unlock(&list->mutex);
}

AlgorithmImpl* load_algorithm_impl(const char* lib_name, const char* entry) {
    void* handle;
    AlgorithmImpl* impl;

    if (!is_static) {
        handle = dlopen(lib_name, RTLD_LAZY);
        if (!handle) {
            fprintf(stderr, "Failed to load library: %s\n", dlerror());
            return NULL;
        }
    }

    impl = malloc(sizeof(AlgorithmImpl));
    impl->name = lib_name;
    impl->is_static = is_static;

    void* init_ptr = dlsym(handle, entry);
    if ((impl->init = (void*(*)())init_ptr) == NULL) {
        fprintf(stderr, "Failed to find symbol %s in library %s\n", entry, lib_name);
        dlclose(handle);
        free(impl);
        return NULL;
    }

    return impl;
}

void* init_algorithm(AlgorithmImpl* impl) {
    if (!impl->init)
        return NULL;

    void* ret = impl->init();
    if (ret == NULL) {
        fprintf(stderr, "Failed to initialize algorithm %s\n", impl->name);
        // Handle error and clean up resources as needed
        return NULL;
    }

    return impl;
}

AlgorithmImpl* get_algorithm(AlgorithmList* list, const char* name) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->data[i]->name, name) == 0) {
            pthread_mutex_unlock(&list->mutex);
            return list->data[i];
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}
