typedef struct {
    int* numbers;
    size_t len;
} IntegerList;

IntegerList* readInput() {
    IntegerList* list = malloc(sizeof(IntegerList));
    if (!list) return NULL;

    list->len = 0;
    char c;
    while ((c = getchar()) != EOF && list->len < 10000) {
        if (sscanf(stdin, "%d%n", &list->numbers[list->len], &c) == 1) {
            ++list->len;
        }
    }
    list->numbers = realloc(list->numbers, sizeof(int) * list->len);
    if (!list->numbers) return NULL;
    return list;
}

int findLargest(IntegerList* list) {
    int max = list->numbers[0];
    for (size_t i = 1; i < list->len; ++i) {
        if (list->numbers[i] > max) {
            max = list->numbers[i];
        }
    }
    return max;
}

void printErrorAndExit(const char* message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

int isInt(const char* str) {
    int i = 0;
    if (str[i] == '-') ++i;
    for (; str[i] != '\0'; ++i) {
        if (str[i] < '0' || str[i] > '9') return 0;
    }
    return 1;
}

RSA* parseKey(const char* key) {
    RSA* rsa = PEM_read_RSAPrivateKey(NULL, key, NULL, NULL);
    if (!rsa) printErrorAndExit("Invalid private key");
    return rsa;
}

AES_KEY* generateEncryptionKey(IntegerList* numbers) {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];

    aes_init(&key, AES_MODE_CBC, NULL);
    for (size_t i = 0; i < AES_BLOCK_SIZE; ++i) {
        iv[i] = (unsigned char)(numbers->numbers[0] % 256);
        numbers->numbers[0] /= 256;
    }
    aes_set_encrypt(&key, iv, &key.key);
    return &key;
}

void* processInputAndEncrypt(const char* commandLineOption) {
    IntegerList* input = readInput();
    if (!input) printErrorAndExit("Failed to read input");

    if (input->len == 0) {
        printf("No valid integers found.\n");
        free(input);
        return NULL;
    }

    int max = findLargest(input);
    printf("The largest integer is: %d\n", max);

    FILE* keyFile = fopen("key.pem", "r");
    if (!keyFile) printErrorAndExit("Failed to open private key file");

    RSA* rsa = parseKey(PEM_read_RSAPrivateKey(keyFile, NULL, NULL, NULL));
    fclose(keyFile);

    AES_KEY* encryptionKey = generateEncryptionKey(input);

    free(input->numbers);
    free(input);

    return rsa;
}
