['```c
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>
#include <queue>

typedef void (*TaskFunc)(void*);
struct ThreadPool {
    std::queue<TaskFunc> tasks;
    pthread_t* threads;
    int numThreads, nextTask;
    bool running;
};

void thread_func(void* arg) {
    struct ThreadPool* pool = (struct ThreadPool*)arg;
    while (pool->running) {
        if (!pool->tasks.empty()) {
            pool->tasks.front()(NULL);
            pool->tasks.pop();
        } else {
            pthread_yield();
        }
    }
}

struct ThreadPool* createThreadPool(int numThreads) {
    struct ThreadPool* pool = (struct ThreadPool*)malloc(sizeof(struct ThreadPool));
    pool->numThreads = numThreads;
    pool->running = true;
    pool->nextTask = 0;
    pool->threads = (pthread_t*)malloc(numThreads * sizeof(pthread_t));

    for (int i = 0; i < numThreads; ++i) {
        pthread_create(&pool->threads[i], NULL, &thread_func, pool);
    }

    return pool;
}

void destroyThreadPool(struct ThreadPool* pool) {
    pool->running = false;
    for (int i = 0; i < pool->numThreads; ++i) {
        pthread_join(pool->threads[i], NULL);
    }

    free(pool->threads);
    free(pool);
}

void queueTask(struct ThreadPool* pool, TaskFunc task) {
    pool->tasks.push(task);
}
