#include <mt19937ar>
#include <uniform_int_distribution>
#include <uniform_real_distribution>

namespace RandomPool {
    class Generator {
        std::mt19937 m_engine;
        std::mutex m_mutex;

        public:
            Generator() : m_engine(rand()) {}
            ~Generator() = default;

            int getInt() {
                std::lock_guard<std::mutex> lock(m_mutex);
                return m_engine();
            }

            float getFloat() {
                std::lock_guard<std::mutex> lock(m_mutex);
                std::uniform_real_distribution<float> dist(0.0, 1.0);
                return dist(m_engine);
            }
    };

    static std::vector<Generator> pool;

    void reset() {
        std::lock_guard<std::mutex> lock(pool[0].m_mutex);
        for (auto& gen : pool) {
            gen.m_engine.reset();
        }
    }
}

int main() {
    const int numThreads = 10;
    RandomPool::pool.resize(numThreads);
    std::vector<std::thread> threads;

    for (int i = 0; i < numThreads; ++i) {
        threads.emplace_back([&]() {
            while (true) {
                RandomPool::Generator gen = RandomPool::pool[rand() % numThreads];
                int rngInt = gen.getInt();
                float rngFloat = gen.getFloat();
                std::cout << "Thread ID: " << std::this_thread::get_id() << ", Integer: " << rngInt << ", Float: " << rngFloat << "\n";
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    RandomPool::reset(); // Reset the state of all generators in the pool
}
