using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;
using System.Diagnostics;

namespace SQLBatchExecutor
{
    public class SQLBatchExecutor
    {
        private readonly Dictionary<string, Task<Tuple<bool, object>>> _tasks;
        private readonly string _connectionString;
        private readonly int _timeout;
        private readonly TraceSource _traceSource;

        public SQLBatchExecutor(string connectionString, int timeout)
        {
            _connectionString = connectionString;
            _timeout = timeout;
            _tasks = new Dictionary<string, Task<Tuple<bool, object>>>();
            _traceSource = new TraceSource("SQLBatchExecutor");
        }

        public async Task<Dictionary<string, (bool Status, object Result)>> ExecuteAsync(IEnumerable<string> sqlCommands)
        {
            var results = new Dictionary<string, (bool Status, object Result)>();

            foreach (var command in sqlCommands)
            {
                var task = Task.Run(() => ExecuteCommand(command));
                _tasks[command] = task;
            }

            await Task.WhenAll(_tasks.Values);

            foreach (var pair in _tasks)
            {
                results[pair.Key] = pair.Value.Result;
            }

            return results;
        }

        private Tuple<bool, object> ExecuteCommand(string sqlCommand)
        {
            var connection = new SqlConnection(_connectionString);
            try
            {
                using (connection)
                {
                    connection.Open();
                    var commandObject = new SqlCommand(sqlCommand, connection);
                    commandObject.CommandTimeout = _timeout;
                    var result = commandObject.ExecuteNonQuery() > 0 ? (object)true : commandObject.ExecuteScalar();
                    return Tuple.Create((int)commandObject.ExecuteNonQuery() > 0, result);
                }
            }
            catch (Exception ex)
            {
                _traceSource.TraceEvent(TraceEventType.Error, 0, ex.Message);
                return Tuple.Create(false, null);
            }
        }
    }
}
