public class Config
{
    public int PlayerHP { get; set; }
    public int PlayerMP { get; set; }
    public float[] EnemySpawnRates { get; set; }
    public string[] EnemyTypes { get; set; }
    public Vector3 GameWorldDimensions { get; set; }
    public Vector2 UIElementPositions { get; set; }
    public Vector2 UIElementSizes { get; set; }
}

public static class ConfigLoader
{
    private const string CONFIG_FILE = "config.json";

    public static Config LoadConfig()
    {
        if (!File.Exists(CONFIG_FILE))
        {
            Console.WriteLine("Error: Configuration file not found.");
            return null;
        }

        var json = File.ReadAllText(CONFIG_FILE);
        JObject configObj = JObject.Parse(json);

        int playerHP, playerMP;
        float[] enemySpawnRates;
        string[] enemyTypes;
        Vector3 gameWorldDimensions;
        Vector2 uiElementPositions, uiElementSizes;

        if (!int.TryParse(configObj["PlayerHP"].ToString(), out playerHP) ||
            !int.TryParse(configObj["PlayerMP"].ToString(), out playerMP) ||
            !(enemySpawnRates = JsonConvert.DeserializeObject<float[]>(configObj["EnemySpawnRates"].ToString()))
            || !(enemyTypes = configObj["EnemyTypes"].ToObject<string[]>()) ||
            !Vector3.TryParse(configObj["GameWorldDimensions"].ToString(), out gameWorldDimensions) ||
            !Vector2.TryParse(configObj["UIElementPositions"].ToString(), out uiElementPositions) ||
            !Vector2.TryParse(configObj["UIElementSizes"].ToString(), out uiElementSizes))
        {
            Console.WriteLine("Error: Invalid configuration values.");
            return null;
        }

        if (playerHP <= 0 || playerMP <= 0 || gameWorldDimensions.X <= 0 || gameWorldDimensions.Y <= 0 || gameWorldDimensions.Z <= 0 || uiElementPositions.X < 0 || uiElementPositions.Y < 0)
        {
            Console.WriteLine("Error: Configuration values out of valid range.");
            return null;
        }

        Config config = new Config()
        {
            PlayerHP = playerHP,
            PlayerMP = playerMP,
            EnemySpawnRates = enemySpawnRates,
            EnemyTypes = enemyTypes,
            GameWorldDimensions = gameWorldDimensions,
            UIElementPositions = uiElementPositions,
            UIElementSizes = uiElementSizes
        };

        return config;
    }
}
