let userProfiles = {};
let inactiveTimer;
const INACTIVE_DURATION = 30 * 24 * 60 * 60 * 1000; // 30 days

// Create, update and delete user profiles
app.all('/profiles/:id', async (req, res) => {
    const id = req.params.id;
    let profileData = userProfiles[id] || {};

    switch (req.method) {
        case 'GET':
            res.json(profileData);
            break;
        case 'PUT':
            Object.assign(profileData, req.body);
            // Versioning and merging concurrent updates
            profileData.version = profileData.version || 1;
            userProfiles[id] = profileData;
            break;
        case 'DELETE':
            delete userProfiles[id];
            res.status(204).send();
            break;
    }
});

// Auto-reset inactive profiles
inactiveTimer = setInterval(() => {
    for (const id in userProfiles) {
        const profile = userProfiles[id];
        if (!profile.lastActive || moment().diff(profile.lastActive) > INACTIVE_DURATION) {
            delete userProfiles[id];
        }
    }
}, INACTIVE_DURATION);
