using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;
using System.Linq;
using System.Threading.Tasks;
using System.Threading;

public class XPathHelper
{
    private readonly XmlNamespaceManager _namespaceManager;

    public XPathHelper(string defaultNamespaceUri)
    {
        _namespaceManager = new XmlNamespaceManager(new NameTable());
        _namespaceManager.AddNamespace("ns", defaultNamespaceUri);
    }

    public async Task<IEnumerable<XmlNode>> FindElementsAsync(XmlDocument document, string prefix, string localName)
    {
        using (var reader = XmlReader.Create(document))
        {
            var result = new List<XmlNode>();

            while (reader.Read())
            {
                if (reader.MoveToContent() == XmlNodeType.Element && _namespaceManager.LookupNamespace(prefix) == reader.LookupNamespace(prefix))
                {
                    if (reader.LocalName == localName)
                    {
                        result.Add(reader.ReadSubtree());
                    }
                }
            }

            return result;
        }
    }

    public XmlNode FindFirstElement(XmlDocument document, string prefix, string localName)
    {
        var nodes = FindElementsAsync(document, prefix, localName).Result;
        if (nodes.Count() > 0)
            return nodes.First();
        else
            return null;
    }
}
