const chalk = require('chalk');
const blueslip = require('blueslip'); // Assuming this is your mocking library

async function runModuleTests(moduleLabel, testLabel, testFunction, timeout = 10000) {
  try {
    const module = require(moduleLabel);
    console.log(`Testing module: ${chalk.bold(moduleLabel)}`);

    blueslip.reset();

    const testResult = await parallel((label) => task(() => {
      return new Promise((resolve, reject) => {
        try {
          console.log(`\tTest: ${chalk.bold(testLabel)}`);
          const start = Date.now();
          const result = testFunction();
          if (result === undefined) {
            resolve({ label, pass: true });
          } else if (typeof result === 'boolean') {
            resolve({ label, pass: result });
          } else {
            reject(new Error(`Test ${label} returned unexpected value`));
          }
          const duration = Date.now() - start;
          console.log(`\t\tTest duration: ${duration}ms`);
        })
      }).timeout(timeout).catch((err) => {
        console.error(`\tTest ${label}: FAIL - ${err.message}`);
        console.log(`\t\tTest duration: ${Date.now() - start}ms`);
        return { label, pass: false };
      });
    }, [testLabel]));

    blueslip.reset().catch((err) => console.error(err)); // Handle reset failure

    if (testResult.pass) {
      console.log(`\tTest ${testLabel}: PASS`);
    } else {
      console.log(`\tTest ${testLabel}: FAIL - Test function did not return a boolean result or failed to pass.`);
