const oldTestamentBooks = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', 'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms', 'Proverbs', 'Ecclesiastes', 'Song of Solomon', 'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'];
const bibleBookRegex = /(\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b)/gi;

function countBibleBooks(text) {
  if (!text || !text.length) throw new Error('Input text is empty or null');

  const normalizedText = unicodeNormalize(text);
  let bookCounts = {};

  // Use a loop and the global flag to search for all matches in the text
  let match;
  while ((match = bibleBookRegex.exec(normalizedText))) {
    const bookName = match[1].toLowerCase();
    if (oldTestamentBooks.includes(bookName)) {
      if (!bookCounts[bookName]) bookCounts[bookName] = 0;
      bookCounts[bookName]++;
    }
  }

  return bookCounts;
}
