["```javascript
async function loadModules(modules) {
  const head = document.getElementsByTagName('head')[0];
  const scripts = head.getElementsByTagName('script');
  const loadedModules = {};

  for (const module of modules) {
    if (!loadedModules[module.name]) {
      loadedModules[module.name] = module;
    } else if (module.version > loadedModules[module.name].version) {
      loadedModules[module.name] = module;
    }
  }

  const promises = [];

  for (const module of Object.values(loadedModules)) {
    let existingScript = null;

    for (let i = 0; i < scripts.length; i++) {
      if (scripts[i].src === module.src) {
        existingScript = scripts[i];
        break;
      }
    }

    if (!existingScript) {
      const newScript = document.createElement('script');
      newScript.src = module.src;
      head.appendChild(newScript);
      promises.push(new Promise((resolve) => {
        newScript.onload = resolve;
      }));
    } else {
      promises.push(Promise.resolve()); // If a script is already loaded, resolve immediately to skip it in the next iteration.
    }
  }

  return Promise.all(promises);
}
```"]

