    private ExecutorService executor = Executors.newCachedThreadPool();
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private AtomicLong totalBytesReceived = new AtomicLong();
    private AtomicLong totalBytesSent = new AtomicLong();
    private AtomicLong requestCount = new AtomicLong();
    private AtomicLong responseCount = new AtomicLong();

    public SelectorProvider selectorProvider;
    public ServerSocketChannel serverSocketChannel;
    public SelectionKey serverSelectionKey;
    public Map<SelectionKey, ManagedConnection> connections = new ConcurrentHashMap<>();

    public void start(int port) throws IOException {
        this.serverSocketChannel = ServerSocketChannel.open(this.selectorProvider);
        this.serverSocketChannel.socket().bind(new InetSocketAddress(port));
        this.serverSelectionKey = this.serverSocketChannel.register(this.selector, SelectionKey.OP_ACCEPT);
    }

    public void manageConnection(SelectionKey key) {
        if (key == this.serverSelectionKey) {
            SocketChannel socketChannel = this.serverSocketChannel.accept();
            socketChannel.configureBlocking(false);
            SelectionKey clientKey = socketChannel.register(this.selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
            ManagedConnection managedConnection = new ManagedConnection(socketChannel);
            this.connections.put(clientKey, managedConnection);
        } else {
            ManagedConnection managedConnection = this.connections.get(key);
            if (managedConnection == null) {
                LOGGER.error("ManagedConnection not found: {}", key);
                key.cancel();
                return;
            }
            managedConnection.processSelectionKey();
        }
    }

    public static class ManagedConnection {
        private final SocketChannel socketChannel;
        private final ByteBuffer readBuffer = ByteBuffer.allocateDirect(1024);
        private final ByteBuffer writeBuffer = ByteBuffer.allocateDirect(1024);

        public ManagedConnection(SocketChannel socketChannel) {
            this.socketChannel = socketChannel;
        }

        public void processSelectionKey() {
            if (this.socketChannel.isConnected()) {
                this.socketChannel.read(this.readBuffer);
                this.readBuffer.flip();
                while (this.readBuffer.hasRemaining()) {
                    // Process data here
                }
                this.readBuffer.compact();

                this.socketChannel.write(this.writeBuffer);
                this.writeBuffer.clear();
            } else {
                this.socketChannel.close();
                this.connections.remove(this.selectionKey);
            }
        }
    }

    private Runnable connectionStatisticLogger = () -> {
        long requestCountValue = this.requestCount.get();
        long responseCountValue = this.responseCount.get();
        long totalBytesReceivedValue = this.totalBytesReceived.get();
        long totalBytesSentValue = this.totalBytesSent.get();

        LOGGER.info("Connection statistics:\n\tRequest count: {}\n\tResponse count: {}\n\tTotal bytes received: {}\n\tTotal bytes sent: {}",
            requestCountValue, responseCountValue, totalBytesReceivedValue, totalBytesSentValue);
    };

    public void startConnectionStatisticsLogging(Consumer<Runnable> scheduler) {
        this.scheduler.scheduleAtFixedRate(this.connectionStatisticLogger, 10, 60, TimeUnit.SECONDS);
    }
}
