// Function to fetch and update JSON configuration file from remote server
async function fetchConfig() {
  let cachedConfig = await distributedCache.get('config');

  if (!cachedConfig || moment().diff(moment(cachedConfig.timestamp), 'minutes') > 60) { // cache invalidation based on timestamp (1 hour)
    try {
      const response = await axios.get('http://resource-server-url/config.json'); // replace with your resource server URL
      if (!response.error) {
        cachedConfig = response.data;
        await distributedCache.set('config', cachedConfig, 60 * 60); // cache for 1 hour
        fs.writeFileSync('./local-cache/config.json', JSON.stringify(cachedConfig)); // save to local file system
      }
    } catch (error) {
      if (!fs.existsSync('./local-cache/config.json')) { // check if local cache file doesn't exist yet
        await fetchConfig(); // try again, this time with the backup server if configured
      }
    }
  }

  return cachedConfig || fs.readFileSync('./local-cache/config.json');
}

// Function to configure default resource server or backup server if needed
function setupResourceServer() {
  let resourceServer = 'http://resource-server-url'; // replace with your resource server URL
  if (!fs.existsSync('./local-cache/config.json')) {
    resourceServer = configBackupServer;
  } else {
