import java.io.BufferedInputStream;
import java.io.File;
import java.io.IOException;
import java.io.UnsupportedEncodingException;
import java.math.BigInteger;
import java.name.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.FileHandler;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.logging.SimpleFormatter;

public class FileHasher {
    private static final Logger LOGGER = Logger.getLogger(FileHasher.class.getName());
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(5);
    private static final int BUFFER_SIZE = 8192;

    public void calculateMD5Hash(String filePathOrUrl, String logFilePath, String messagingSystemEndpoint) throws IOException {
        URL url;
        File file;
        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }

        if (filePathOrUrl.startsWith("http")) {
            url = new URL(filePathOrUrl);
            BufferedInputStream bis = new BufferedInputStream(url.openStream());
            try {
                LOGGER.log(Level.INFO, "Starting to process {0}", filePathOrUrl);
                byte[] buffer = new byte[BUFFER_SIZE];
                int read;
                while ((read = bis.read(buffer)) != -1) {
                    md.update(buffer, 0, read);
                }
            } finally {
                bis.close();
            }
        } else {
            file = new File(filePathOrUrl);
            try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(file))) {
                LOGGER.log(Level.INFO, "Starting to process {0}", file.getAbsoluteFile());
                byte[] buffer = new byte[BUFFER_SIZE];
                int read;
                while ((read = bis.read(buffer)) != -1) {
                    md.update(buffer, 0, read);
                }
            }
        }

        FileHandler fileHandler = new FileHandler(logFilePath, true);
        SimpleFormatter simpleFormatter = new SimpleFormatter();
        fileHandler.setFormatter(simpleFormatter);
        LOGGER.addHandler(fileHandler);

        LOGGER.log(Level.INFO, "Calculating MD5 hash...");
        byte[] digest = md.digest();
        BigInteger bigInt = new BigInteger(1, digest);
        String hashedData = bigInt.toString(16);
        while (hashedData.length() < 32) {
            hashedData = "0" + hashedData;
        }
        LOGGER.log(Level.INFO, "MD5 hash calculated: {0}", hashedData);

        // Simulate a random delay
        try {
            Thread.sleep((long) (Math.random() * 1000));
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }

        // Send message to messaging system when file processing is finished
        sendMessage(messagingSystemEndpoint, String.format("MD5 hash calculated for %s: %s", filePathOrUrl, Base64.getEncoder().encodeToString(digest)));

        LOGGER.log(Level.INFO, "Finished processing {0}", filePathOrUrl);
    }

    private void sendMessage(String messagingSystemEndpoint, String message) {
        // Implement your messaging system here
    }
}
