['```rust
use reqwest::{Client, header};
use serde_json as json;
use std::collections::HashMap;
use url::Url;
use futures::stream::StreamExt;
use tokio::task::spawn_blocking;
use reqwest::transport::{CertificateValidator, WebPkeyCertValider};
use reqwest::ClientBuilder;
use reqwest::http::Method;
use std::sync::Mutex;
use reqwest::r#async::Request;
use std::option::Option;
use tokio::runtime::Runtime;

pub struct CustomHttpClient {
    client: Mutex<Client>,
    auth_service_url: String,
    token: Option<String>,
    max_retries: u8,
}

impl CustomHttpClient {
    pub async fn new(auth_service_url: String, max_retries: u8) -> Self {
        let client = ClientBuilder::new()
            .connector(move |inner| {
                reqwest::Adapter::new(
                    reqwest::transport::ClientExecutor::new(inner, HttpConnector {
                        max_retries,
                        token: RwLock::new(None),
                        auth_service_url,
                    })
                )
            })
            .build()
            .await
            .expect("Failed to create http client");

        CustomHttpClient {
            client: Mutex::new(client),
            auth_service_url,
            max_retries,
            token: None,
        }
    }

    pub fn get(&self, url: &str) -> RequestBuilder {
        self.request_builder(Method::GET, url)
    }

    pub fn post<T>(&self, url: &str, headers: HashMap<String, String>, body: T) -> RequestBuilder
        where T: serde::Serialize + Send + Sync + 'static {
        let (json_body, header_map) = self.serialize_data(headers, body)?;
        self.request_builder(Method::POST, url).header("Content-Type", "application/json").body(json_body)
    }

    async fn request_builder<T>(&self, method: Method, url: &str) -> RequestBuilder<T> {
        let client = self.client.lock().await;
        let mut req_builder = client.request(url);
        if self.token.is_some() {
            req_builder = req_builder.header("Authorization", format!("Bearer {}", self.token.as_ref().unwrap()));
        }
        RequestBuilder {
            url: Url::parse(url).unwrap(),
            method,
            req_builder,
        }
    }

    async fn refresh_token(&self) -> Option<String> {
        let client = reqwest::Client::new();
        let token = client.post(&self.auth_service_url)
            .send()
            .await?
            .text()
            .await?;
        self.token = Some(token);
        self.token
    }

    fn serialize_data<T>(&self, headers: HashMap<String, String>, data: T) -> Result<(reqwest::Body, HashMap<String, String>) where T: serde::Serialize + Send + Sync + 'static {
        let serialized = json::to_string(&data)?;
        let mut header_map = headers;
        header_map.insert("Content-Type", "application/json".to_owned());
        Ok((reqwest::Body::from(serialized), header_map))
    }
}

struct HttpConnector {
    max_retries: u8,
    token: RwLock<Option<String>>,
    auth_service_url: String,
}

impl reqwest::transport::ClientConnector for HttpConnector {
    fn connect(&self, request: reqwest::request::Request<'_>) -> Box<dyn Future<Output = ()> + Send + Sync> {
        let mut connector = Box::new(move |executor| {
            executor.execute(reqwest::RequestBuilder::from_request(request)
                .builder()
                .cert(self.get_client_cert())
                .build()
                .map(|mut req| async move {
                    if self.token.read().await.is_none() && req.method() != Method::GET {
                        if let Some(ref token) = self.refresh_token().await {
                            req.headers_mut().insert("Authorization", header::HeaderValue::from_str(&format!("Bearer {}", token)).unwrap());
                        }
                    }
                    req.send().await?
                })
                .map_err(|e| {
                    if self.max_retries > 0 && e.is_transient() {
                        self.max_retries -= 1;
                        Box::pin(async move {
                            let rt = Runtime::new().expect("Failed to create a tokio runtime");
                            rt.block_on(async move {
                                connector(executor).await
                            })
                        })
                    } else {
                        return Err(e);
                    }
                })
            )
        });
        if let Some(ref token) = self.token.read().await {
            connector = Box::new(move |executor| {
                executor.execute(reqwest::RequestBuilder::from_request(request)
                    .header("Authorization", header::HeaderValue::from_str(&format!("Bearer {}", token)).unwrap())
                    .build()
                    .map(|mut req| async move {
                        req.send().await?
                    })
                    .map_err(|e| {
                        if self.max_retries > 0 && e.is_transient() {
                            self.max_retries -= 1;
                            Box::pin(async move {
                                let rt = Runtime::new().expect("Failed to create a tokio runtime");
                                rt.block_on(async move {
                                    connector(executor).await
                                })
                            })
                        } else {
                            return Err(e);
                        }
                    })
                )
            });
        }
        connector
    }

    fn get_client_cert(&self) -> Option<reqwest::cert::Certificate> {
        let mut cert = None;
        if let Ok(mut file) = std::fs::File::open("cert.pem") {
            let mut buf = vec![];
            file.read_to_end(&mut buf).unwrap();
            cert = Some(reqwest::cert::Certificate::from_pem(&buf[..]).unwrap());
        }
        cert
    }
}

struct RwLock<T> {
    data: Arc<Mutex<T>>,
}
```

