    private $cacheExpiry;
    private $cacheTable;

    public function __construct($apiKey, $cacheExpiry = 60 * 60, $cacheTable = 'weather_cache') {
        $this->apiKey = $apiKey;
        $this->cacheExpiry = $cacheExpiry;
        $this->cacheTable = $cacheTable;
    }

    public function getWeatherData($city) {
        $cacheKey = md5($city . time());
        $cachedData = $this->getFromCache($cacheKey);

        if ($cachedData && $cachedData['timestamp'] > (time() - $this->cacheExpiry)) {
            return [
                'success' => true,
                'message' => 'Weather data fetched from cache.',
                'data' => $cachedData
            ];
        }

        // Fetch weather data from third-party API and save to cache if fresh or update rate limit allowed.
