        $weatherData = [
            'temperature' => rand(-50, 50),
            'humidity' => rand(30, 90),
            'windSpeed' => rand(0, 100),
            'timestamp' => time()
        ];

        if (!$cachedData || $cachedData['timestamp'] < (time() - $this->cacheExpiry)) {
            $this->saveToCache($cacheKey, $weatherData);
        }

        return [
            'success' => true,
            'message' => 'Weather data fetched from API.',
            'data' => $weatherData
        ];
    }

    private function getFromCache($key) {
        global $db; // Assuming you have a global database connection object. Adapt this to your actual setup.

        $query = $db->prepare("SELECT * FROM {$this->cacheTable} WHERE key = ?");
        $query->execute([$key]);

        if ($row = $query->fetch(PDO::FETCH_ASSOC)) {
            return $row;
        }

        return false;
    }

    private function saveToCache($key, $data) {
        global $db; // Assuming you have a global database connection object. Adapt this to your actual setup.

        $query = $db->prepare("REPLACE INTO {$this->cacheTable} (key, temperature, humidity, windSpeed, timestamp) VALUES (?, ?, ?, ?, ?)");
        $query->execute([$key, $data['temperature'], $data['humidity'], $data['windSpeed'], $data['timestamp']]);
    }
}
