function updateUserPassword($userId, $newPassword) {
    // Validate password strength using a library or built-in function
    if (!password_validatesStrength($newPassword)) {
        throw new Exception("Invalid password format");
    }

    try {
        // Attempt to access the database directly
        $database = new Database();
        if ($database->isAvailable()) {
            // Hash the new password before storing it in the database
            $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

            // Update the user's password in the local database
            $database->execute("UPDATE users SET password = ? WHERE id = ?", [$hashedPassword, $userId]);
        } else {
            // Use fallback mechanism when direct database access is unavailable due to service outages
            $identityProvider = new IdentityProvider();
            if ($identityProvider->isAvailable()) {
                // Call the external identity provider's API to update the user's password
                $response = $identityProvider->updateUserPassword($userId, $newPassword);

                if ($response->success) {
                    return "Password updated successfully";
                } else {
                    throw new Exception("Error updating password through identity provider");
                }
            } else {
                throw new Exception("Both the local database and identity provider are unavailable");
            }
        }
    } catch (Exception $e) {
        // Log the error for further investigation
        error_log($e->getMessage());

        // Return a friendly error message to the user
        return "An error occurred while updating your password. Please try again later.";
    }
