#include <stdlib.h>
#include <stdio.h>

typedef struct FSA {
    int num_states;
    int *transitions;
    int start_state;
} FSA;

typedef struct State {
    int id;
    struct State *next;
} State;

State* create_state_list(int *initial_states, int num_initial_states, const FSA *fsa, State **last, int *total_states) {
    State *current = NULL;
    State *new_state = NULL;
    State *state_list = NULL;

    for (int i = 0; i < num_initial_states; ++i) {
        current = &initial_states[i];
        state_list = push_state(state_list, current, fsa);
        if (!state_list) return NULL;
        (*total_states)++;
    }

    while (current != NULL) {
        new_state = malloc(sizeof(State));
        if (!new_state) return NULL;

        new_state->id = current->id;
        new_state->next = NULL;

        int next_state = fsa->transitions[current->id];
        State *next_node = NULL;
        if (next_state != -1) {
            next_node = &fsa->transitions[next_state];
        } else {
            // Handle non-deterministic state or dead end
            printf("Error: Reached a non-deterministic state or dead end\n");
            return NULL;
        }

        if (next_node->next) {
            new_state->next = next_node->next;
            next_node->next = new_state;
        } else {
            next_node->next = new_state;
        }

        state_list = push_state(state_list, current, fsa);
        if (!state_list) return NULL;
        (*total_states)++;

        current = next_node;
    }

    *last = current;
    return state_list;
}

State* push_state(State *head, State *current, const FSA *fsa) {
    State *new_node = malloc(sizeof(State));
    if (!new_node) return NULL;

    new_node->id = current->id;
    new_node->next = head;
    return new_node;
}
