```cpp
#include <iostream>
#include <queue>
#include <unordered_map>
#include <deque>
#include <chrono>
#include <random>
#include <thread>
#include <boost/thread/mutex.hpp>

using namespace std;

struct Transaction {
    int id;
    chrono::system_clock::time_point timestamp;
    double amount, weight;
};

class TransactionSystem {
private:
    unordered_map<int, pair<double, int>> senders; // max_weighted_sum and transaction_id
    unordered_map<int, priority_queue<Transaction>> senderQueue; // sliding window
    unordered_map<int, chrono::system_clock::time_point> senderWindowStarts; // for rate limits
    mutex mtx;
    int windowSize = 100;
    double rateLimit = 1.0; // ratio of transactions per second

public:
    TransactionSystem(int w, double r) : windowSize(w), rateLimit(r) {}

    void processTransaction(const Transaction& transaction) {
        lock_guard<mutex> lck(mtx);
        auto it = senderQueue.find(transaction.id);
        if (it != senderQueue.end()) {
            it->second.push(transaction);
            while (it->second.size() > windowSize) {
                it->second.pop();
            }
            auto now = chrono::system_clock::now();
            double weightedSum = 0;
            double rateLimitTime = (1. / rateLimit);
            for (auto& t : it->second) {
                if ((now - t.timestamp.time_since_epoch()) > rateLimitTime) {
                    it->second.pop();
                    continue;
                }
                weightedSum += t.amount * t.weight;
            }
            senders[transaction.id] = make_pair(max(weightedSum, senders[transaction.id].first), transaction.id);
            if (now - senderWindowStarts[transaction.id].time_since_epoch() > chrono::seconds(3)) {
                senderWindowStarts[transaction.id] = now;
            }
        } else {
            senderQueue[transaction.id] = priority_queue<Transaction>();
            senderQueue[transaction.id].push(transaction);
            senders[transaction.id] = make_pair(transaction.amount * transaction.weight, transaction.id);
            senderWindowStarts[transaction.id] = chrono::system_clock::now();
        }
    }

    pair<double, int> getMaxWeightedSum(int sender) {
        lock_guard<mutex> lck(mtx);
        auto it = senders.find(sender);
        if (it != senders.end()) {
            return it->second;
        }
        return make_pair(0, 0);
    }
};
```

To use this class:

```cpp
int main() {
    TransactionSystem system(100, 0.01); // windowSize = 100, rateLimit = 1 transaction per 100 milliseconds
    auto generator = [&system]() -> Transaction {
        chrono::system_clock::time_point timestamp = chrono::system_clock::now();
        return { rand(), timestamp, (double)rand() / RAND_MAX * 100, (double)rand() / RAND_MAX };
    };

    auto threads = vector<thread>(10);
    for (int i = 0; i < threads.size(); ++i) {
        threads[i] = thread(processTransaction, ref(generator()), ref(system));
    }

    for (auto& t : threads) t.join();

    // ... process the results or display max weighted sums for each sender
}
```

This code demonstrates how to create a real-time transaction processing system with the given requirements, using concurrency and efficient data structures to handle large volumes of transactions."]

