Attack attacks[2]; // Initialize your attacks here
int currentEnergy = 0;
int maxEnergy = 0;
bool powerSourceOverload = false;
unsigned long lastEnergyUpdate = 0;
unsigned long lastAttack = 0;
std::mt19937 rng(static_cast<unsigned int>(std::time(0))); // Seed random number generator with current time

void selectAttack() {
    unsigned long now = std::chrono::system_clock::now().time_since_epoch().count();

    if (powerSourceOverload) {
        powerSourceOverload = false;
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate delay due to overload
    }

    unsigned long energyRegenerationTime = now - lastEnergyUpdate;
    if (energyRegenerationTime > 1) { // Energy regenerates every second
        currentEnergy += maxEnergy * (energyRegenerationTime / 1.0);
        powerSourceOverload |= (currentEnergy > maxEnergy);
        lastEnergyUpdate = now;
    }

    int energyNeeded = attacks[rand() % 2].energyCost;
    if (currentEnergy < energyNeeded) {
        std::cout << "Insufficient energy for attack. Current Energy: " << currentEnergy << ". Needed Energy: " << energyNeeded << "\n";
        return;
    }

    int elapsedTime = now - lastAttack;
    if (elapsedTime < attacks[rand() % 2].cooldown) {
        std::cout << "Cooldown period not yet expired for attack.\n";
        return;
    }

    currentEnergy -= energyNeeded;
    lastAttack = now;

    int selectedAttackIndex = rand() % 2;
    std::cout << "Selected Attack: " << selectedAttackIndex << ". Remaining Energy: " << currentEnergy << "\n";
}
