    private int _minValue;
    private float _maxValue;

    public CustomRandomGenerator(int minValue, int maxValue)
    {
        SetRange(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(_minValue, _maxValue);
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(_minValue, _maxValue);
    }

    public override string ToString()
    {
        if (typeof(int) == typeof(_minValue))
            return $"[{_minValue}, {_maxValue})";
        else
            return $"[{_minValue}, {_maxValue}]";
    }

    public void SetRange(int min, int max)
    {
        if (min >= max)
        {
            _minValue = 0;
            _maxValue = 0;
            return;
        }

        _minValue = min;
        _maxValue = max;
    }

    public (List<int>, List<float>) GenerateRandomValues(int iterations)
    {
        if (_minValue >= _maxValue)
            return (null, null);

        var intList = new List<int>();
        var floatList = new List<float>();

        for (int i = 0; i < iterations; i++)
        {
            intList.Add(GetRandomInt());
            floatList.Add(GetRandomFloat());
        }

        return (intList, floatList);
    }
}
