#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <libxml/parser.h>
#include <time.h>

typedef enum { JSON, XML } Format;

typedef struct ResourceBundleReport {
    Format format;
    char *path;
    int num_items;
    char **item_names;
    char **item_types;
} ResourceBundleReport;

ResourceBundleReport* load_resource_bundle(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Format format;
    char line[256];
    size_t line_len = 0;
    getline(&line, sizeof(line), file);
    if (strncmp(line, "<?xml", 5) == 0) {
        format = XML;
    } else if (strncmp(line, "[", 1) == 0) {
        format = JSON;
    } else {
        fprintf(stderr, "Unsupported file format: %s\n", line);
        fclose(file);
        return NULL;
    }

    ResourceBundleReport *report = malloc(sizeof(ResourceBundleReport));
    report->format = format;
    report->path = strdup(path);
    report->num_items = 0;

    if (format == JSON) {
        json_object *root;
        json_object *item;
        cJSON *json;
        size_t cap = 16, len;
        char **names = malloc(cap * sizeof(char*));
        char **types = malloc(cap * sizeof(char*));
        while ((json = json_tokener_get_object(file))) {
            root = json_object_get_child(json);
            if (root) {
                item = json_object_get_child_with_key(root, "name");
                if (!item) {
                    fprintf(stderr, "Invalid JSON format\n");
                    break;
                }
                names[report->num_items] = strdup(json_object_get_string(item));

                item = json_object_get_child_with_key(root, "type");
                if (!item) {
                    fprintf(stderr, "Invalid JSON format\n");
                    break;
                }
                types[report->num_items] = strdup(json_object_get_string(item));

                report->num_items++;

                if (report->num_items == cap) {
                    cap *= 2;
                    names = realloc(names, cap * sizeof(char*));
                    types = realloc(types, cap * sizeof(char*));
                }
            }
        }

        json_object_put(root);
        json_free_handler(&json_tokener, line);
    } else if (format == XML) {
        xmlDocPtr doc;
        xmlNodePtr root, cur, item;
        int num_items = 0;
        char **names = malloc(16 * sizeof(char*));
        char **types = malloc(16 * sizeof(char*));
        while ((doc = xmlReadFileToLocator(path, NULL, XML_PARSE_NONET | XML_PARSE_NOWARNINGS | XML_PARSE_HUGE)) != NULL) {
            root = xmlDocGetRootElement(doc);
            cur = root->children;
            while (cur) {
                if (xmlStrcmp(cur->name, "item")) {
                    cur = cur->next;
                    continue;
                }

                item = cur->xmlChildrenNode;
                names[num_items] = xmlGetProp(item, "name");
                types[num_items] = xmlGetProp(item, "type");
                num_items++;

                cur = cur->nextSibling;
            }

            xmlFreeDoc(doc);
            xmlCleanupParser();
        }
        report->num_items = num_items;
        names = realloc(names, num_items * sizeof(char*));
        types = realloc(types, num_items * sizeof(char*));
    }

    report->item_names = realloc(names, (report->num_items + 1) * sizeof(char*));
    report->item_types = realloc(types, (report->num_items + 1) * sizeof(char*));
    memcpy((void *)&report->item_names[report->num_items], (const void *)names, report->num_items * sizeof(char*));
    memcpy((void *)&report->item_types[report->num_items], (const void *)types, report->num_items * sizeof(char*));

    return report;
}
```

