#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

char* rename_extension(const char* original, const char* file_type) {
    size_t filename_length = strlen(original);
    if (filename_length > 150) return ""; // Handle filenames longer than 150 characters

    size_t vowel_count = 0;
    const char* vowels = "aeiouAEIOU";
    for (size_t i = 0; i < filename_length; ++i) {
        if (strchr(vowels, original[i]) != NULL)
            ++vowel_count;
    }

    size_t sequence_length = vowel_count > 3 ? vowel_count : 1;
    char sequence[sequence_length];
    for (size_t i = 0; i < sequence_length; ++i) {
        sequence[i] = vowel_count - i >= 10 ? (original[vowel_count - i] - 'a' + 10) : original[vowel_count - i];
    }

    size_t extension_start = filename_length;
    for (size_t i = filename_length - 1; i > 0 && isalnum(original[i]); --i) {} // Find the last alphanumeric character before the extension
    if (extension_start >= filename_length || !isalnum(original[extension_start]) || original[extension_start + 1] != '.') return original;

    char new_filename[256];
    size_t new_filename_length = 0;
    for (size_t i = 0; i < filename_length && new_filename_length < 255; ++i) {
        if (i >= extension_start && i <= extension_start + file_type_length(file_type)) continue; // Skip over the existing extension
        if (isspace(original[i]) || original[i] == '.' || original[i] == '/' || original[i] == '\\') continue; // Skip over whitespace, dots and path components

        new_filename[new_filename_length++] = original[i];
    }
    if (new_filename_length == 0) return original;

    strcat(new_filename + new_filename_length, sequence);
    strcat(new_filename + new_filename_length, file_type);

    return new_filename;
}

size_t file_type_length(const char* file_type) {
    size_t length = 0;
    while (file_type[length] && file_type[length] != '.') ++length;
    return length;
}
