2. Create a `cipher_algo_map` and `digest_algo_map` to map user-friendly aliases to their respective OpenSSL algorithms.

3. Implement a function that loads the configuration, creates the mapping dictionaries, and returns them.

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <unordered_map>

std::unordered_map<std::string, std::string> load_config(const char *filename) {
    std::unordered_map<std::string, std::string> cipher_algo_map;
    std::unordered_map<std::string, std::string> digest_algo_map;
    std::ifstream config_file(filename);

    if (!config_file.is_open()) {
        throw std::runtime_error("Configuration file not found.");
    }

    // Load cipher algorithms
    while (true) {
        std::string line;
        std::getline(config_file, line);
        if (line.empty()) break;

        if (line.find("[Ciphers]") != std::string::npos) continue; // Skip section header

        size_t pos = line.find('=');
        if (pos == std::string::npos) continue;

        auto cipher_pair = split(line, '=');
        if (cipher_algo_map.count(cipher_pair[0]) > 0) continue; // Skip duplicates

        cipher_algo_map[cipher_pair[0]] = cipher_pair[1];
    }

    // Load digest algorithms in the same manner as cipher algorithms.

    return {cipher_algo_map, digest_algo_map};
}
```

