void aes256_cbc_init(AES_KEY *key, const char *password, size_t password_len, const void *salt, size_t salt_len, unsigned int iterations) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char key_buf[AES_BLOCK_SIZE];
    unsigned char iv_buf[AES_BLOCK_SIZE];

    // Derive encryption key using PBKDF2
    size_t key_len = sizeof(key_buf);
    unsigned char pwdb[password_len + salt_len];
    memcpy(pwdb, password, password_len);
    memcpy(pwdb + password_len, salt, salt_len);
    int kdf_result = PKCS5_PBKDF2_HMAC((const EVP_CIPHER *)EVPaes_256_cbc(), iterations, pwdb, password_len + salt_len, key_len, key_buf);
    if (kdf_result <= 0) {
        fprintf(stderr, "Error deriving encryption key\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    // Copy the derived key to the AES_KEY structure
    AES_set_encrypt_key(key_buf, AES_KEYSIZE_256, key);

    // Generate new initialization vector (IV) for each encryption operation
    if (1 != RAND_bytes(iv_buf, sizeof(iv_buf))) {
        fprintf(stderr, "Error generating IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Initialize the cipher context with the derived key and IV
    ctx->cipher = AES_cfb128;
    ctx->init = 1;
    ctx->key_len = AES_KEYSIZE_256;
    ctx->iv = iv_buf;
    ctx->key = key_buf;

    // Support multiple encryption/decryption operations

    // Implement a mechanism to manage the lifetime of the cipher context, ensuring that resources are properly freed after usage.
    void (*aes256_cbc_deinit)(EVP_CIPHER_CTX *) = EVP_CIPHER_CTX_free;
}
