#include <fcntl.h>
#include <errno.h>

#define FFMPEG "ffmpeg"
#define PROGRESS_INTERVAL 10 // seconds

int encode_video(char *input, char *output, char *dest) {
    pid_t child_pid;
    int pipefd[2];
    char progress_str[256];
    int status;

    mkdir(dest, 0755); // Create destination directory if it doesn't exist

    pipe(pipefd);

    child_pid = fork();

    if (child_pid < 0) {
        perror("fork");
        return 1;
    } else if (child_pid == 0) { // Child process
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[0]);

        execl(FFMPEG, FFMPEG, "-i", input, "-c:v", "libvpx", "-c:a", "libopus", "-q:v", "30", "-q:a", "5", "-threads", "auto", "-s", "848x480", "-pix_fmt", "yuv420p", "-o", dest "/" output, NULL);
        perror("execl");
    } else { // Parent process
        close(pipefd[1]);

        while (waitpid(child_pid, &status, WNOHANG) != child_pid);

        while (read(pipefd[0], progress_str, sizeof(progress_str)) > 0) {
            printf("%s", progress_str);
            fflush(stdout);
            sleep(PROGRESS_INTERVAL);
        }

        close(pipefd[0]);

        return WEXITSTATUS(status);
    }
}
