#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <sys/time.h>
#include <limits.h>
#include <errno.h>

#define MAX_COMMANDS 10
#define TIMEOUT 5 /* seconds */

pid_t running_commands[MAX_COMMANDS];
struct timeval start_times[MAX_COMMANDS], end_times[MAX_COMMANDS];
int num_running = 0;
FILE *log_file;

void log_command(const char *cmd) {
    gettimeofday(&start_times[num_running], NULL);
    fprintf(log_file, "Start: %s\n", cmd);
}

void log_status(pid_t pid, int status, int wstatus) {
    gettimeofday(&end_times[num_running], NULL);
    fprintf(log_file, "End: %s (Exit Status: %d, WExit Status: %d)\n", strsignal(status), status, WEXITSTATUS(wstatus));
    if (WIFSIGNALED(wstatus)) {
        fprintf(log_file, "Signal: %d\n", WTERMSIG(wstatus));
    } else if (WIFSTOPPED(wstatus)) {
        fprintf(log_file, "Stopped by signal: %d\n", WSTOPSIG(wstatus));
    }
    if (WEXITSTATUS(wstatus) != 0) {
        fprintf(log_file, "Error: %s\n", strerror(errno));
    }
}

void check_and_exit() {
    if (num_running == MAX_COMMANDS || getrlimit(&rlimit, RLIMIT_NOFILE)->rlim_cur >= RLIMIT_NOFILE->rlim_max) {
        fprintf(log_file, "Resource constraint reached. Exiting.\n");
        exit(1);
    }
}

void handle_timeout(pid_t pid) {
    kill(pid, SIGTERM);
    waiting:
    int child_status;
    waitpid(pid, &child_status, 0);
    if (WIFEXITED(child_status)) {
        log_status(pid, WEXITSTATUS(child_status), child_status);
        num_running--;
    }
}

int run_commands(char **commands, FILE *log) {
    check_and_exit();
    log_file = log;

    for (int i = 0; commands[i] != NULL; ++i) {
        log_command(commands[i]);
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork failed");
            continue;
        } else if (pid == 0) {
            execl("/bin/bash", "/bin/bash", "-c", commands[i], NULL);
            perror("execl failed");
            exit(1);
        }
        running_commands[num_running++] = pid;
    }

    struct timeval timeout_tv;
    timeout_tv.tv_sec = TIMEOUT;
    timeout_tv.tv_usec = 0;

    fd_set fds;
    int maxfd = getpid();

    while (num_running > 0) {
        FD_ZERO(&fds);
        FD_SET(STDOUT_FILENO, &fds);
        for (int i = 0; i < num_running; ++i) {
            FD_SET(running_commands[i], &fds);
            if (FD_ISSET(running_commands[i], &fds)) {
                handle_timeout(running_commands[i]);
            }
        }
        maxfd = max(maxfd, STDOUT_FILENO);
        select((int)maxfd + 1, &fds, NULL, NULL, &timeout_tv);

        if (FD_ISSET(STDOUT_FILENO, &fds)) {
            // Handle output here
        }

        for (int i = 0; i < num_running; ++i) {
            if (FD_ISSET(running_commands[i], &fds)) {
                int child_status;
                waitpid(running_commands[i], &child_status, WNOHANG);
                if (WIFEXITED(child_status)) {
                    log_status(running_commands[i], WEXITSTATUS(child_status), child_status);
                    num_running--;
                } else if (WIFSIGNALED(child_status) || TIMER_EXPIRED == child_status) {
                    handle_timeout(running_commands[i]);
                }
            }
        }
    }

    return num_commands - num_running;
}
```

This code defines a `run_commands` function that takes an array of command strings and a log file as arguments. The function forks the processes, handles up to 10 concurrent command executions, logs detailed status updates, and gracefully handles resource constraints such as memory limits and file descriptor limits. If any command fails or exceeds the specified execution timeout, it terminates that specific command. The function returns 1 if all commands are successfully executed within the constraints and 0 if any command fails or times out.']

