public class CommandRunner {
    private static final int MAX_RETRIES = 3;
    private static final long TIMEOUT_MS = 1000L * 60 * 5; // 5 minutes

    private Properties config;
    private File logFile;

    public CommandRunner(Properties config) {
        this.config = config;
        this.logFile = new RotatingFileLogger(config.getProperty("log.file")).getLogFile();
    }

    public void runCommand(String command) throws IOException, InterruptedException {
        Process process = null;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                process = Runtime.getRuntime().exec(command, null, new File(config.getProperty("command.dir")));
                handleProcess(process, logFile);
                if (process.exitValue() == 0) {
                    return; // Successful execution, exit the loop
                }
            } catch (Exception e) {
                if (!isTransientError(e)) {
                    throw e;
                }
            }
            TimeUnit.MILLISECONDS.sleep(TimeUnit.SECONDS.toMillis(timeoutMs() / MAX_RETRIES));
        }
        // Persistent failure, notify administrator via email
        sendFailureNotification();
    }

    private void handleProcess(Process process, File logFile) {
        new Thread(() -> {
            try (
                    InputStream is = process.getErrorStream();
                    OutputStream os = process.getOutputStream();
                    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    PrintWriter writer = new PrintWriter(os);
            ) {
                Thread.currentThread().setName("Command Logging");
                String line;
                while ((line = reader.readLine()) != null) {
                    log(logFile, "Output: " + line);
                }
                writer.println(config.getProperty("command.input")); // Set command input if provided
                writer.flush();
            } catch (IOException e) {
                log(logFile, "Error: " + e.getMessage());
            }
        }).start();
    }

    private boolean isTransientError(Exception e) {
        // Implement a logic to determine if an exception is transient or not based on the error type and message.
        // For simplicity, let's assume that any IOException with "No such file or directory" in the message is transient.
        return e instanceof FileNotFoundException || e.getMessage().contains("No such file or directory");
    }

    private long timeoutMs() {
        return Long.parseLong(config.getProperty("command.timeout")) * 60 * 1000; // Convert minutes to milliseconds
    }

    private void sendFailureNotification() {
        // Implement the logic to send an email notification using an external API when the command fails persistently.
    }

    private void log(File logFile, String message) {
        try (PrintWriter writer = new PrintWriter(new FileWriter(logFile, true))) {
            SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            writer.printf("%s - %s%n", dateFormat.format(new Date()), message);
        } catch (IOException e) {
            // Handle logging exceptions gracefully
        }
    }
}
