#include <stdio.h>
#include <string.h>
#include <jsonschema/json-schema.h>
#include <json-c/json.h>
#include <inttypes.h>

typedef struct {
    const char *access_token;
    int64_t expires_in;
    const char *token_type;
    const char *refresh_token;
} oauth2_token;

static const jsmn_parser parser = { .max_depth = 10, .max_elements = JSON_OBJECT_MAX_ELEMENTS };

bool is_valid_oauth2_access_token(const char *json) {
    json_object *root;
    jsmn_obj obj;
    int tokens[JSON_OBJECT_MAX_ELEMENTS];
    int count = 0;
    int rc = jsmn_parse(json, strlen(json), tokens, &parser);

    if (rc < 1) {
        return false;
    }

    root = json_tokener_parse(json, 0);
    if (!root) {
        return false;
    }

    memset(&obj, 0, sizeof(jsmn_obj));
    obj.type = JSMN_OBJECT;
    obj.parent = NULL;
    obj.index = 0;

    jsmn_get_object(&obj, root, tokens[count++]);

    oauth2_token token;
    token.access_token = json_object_get_string(json_object_get_child(root, "access_token"));
    if (!token.access_token || !*token.access_token) {
        json_object_put(root);
        return false;
    }

    token.expires_in = json_object_get_int(json_object_get_child(root, "expires_in"));
    if (token.expires_in <= 0) {
        json_object_put(root);
        return false;
    }

    token.token_type = json_object_get_string(json_object_get_child(root, "token_type"));
    if (strcmp(token.token_type, "Bearer")) {
        json_object_put(root);
        return false;
    }

    token.refresh_token = json_object_get_string(json_object_get_child(root, "refresh_token"));

    while (count < rc) {
        jsmn_get_next(&obj, root, tokens[count++]);
        if (!obj.type) {
            break;
        }
        switch (obj.type) {
            case JSMN_STRING:
                // Ignore extra fields.
                break;
            default:
                // Not handling array or nested objects for simplicity.
                json_object_put(root);
                return false;
        }
    }

    json_object_put(root);
    return true;
}
```

This code uses the JSON-C library (https://github.com/json-c/json-c) to parse the JSON string. The `jsmn_parse()` function is used for fast, non-validating parsing that only handles top-level objects and arrays for simplicity. Extra fields or nested structures are ignored during validation in this example. The code also uses the json-schema library (https://github.com/json-schema/json-schema) to validate the expected structure of the JSON object. The `json_object_get_string()`, `json_object_get_int()` functions from json-c are used to extract values from the parsed JSON object.']

