using System.Net.Sockets;
using System.Net;
using Newtonsoft.Json;

public class DataServiceClient
{
    private readonly string _remoteServiceUrl;

    public DataServiceClient(string remoteServiceUrl)
    {
        _remoteServiceUrl = remoteServiceUrl;
    }

    public async Task<Stream> CompressAndSendAsync(byte[] data)
    {
        using (var memoryStream = new MemoryStream())
        {
            using (var lzmaOutputStream = new LZMALibrary.LZMAOutputStream(memoryStream))
            {
                try
                {
                    await lzmaOutputStream.WriteAsync(data, 0, data.Length);
                    await lzmaOutputStream.FinishAsync();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error during compression: {ex}");
                    throw;
                }
            }

            var compressedData = memoryStream.ToArray();

            var webRequest = WebRequest.CreateHttp(_remoteServiceUrl);
            webRequest.Method = "POST";
            webRequest.ContentType = "application/octet-stream";
            using (var requestStream = await webRequest.GetRequestStreamAsync())
            {
                await requestStream.WriteAsync(compressedData, 0, compressedData.Length);
            }

            var response = await webRequest.GetResponseAsync();
            using (var responseStream = response.GetResponseStream())
            {
                return new MemoryStream(await responseStream.ReadFullyAsync());
            }
        }
    }
}

public class DecompressedData
{
    public byte[] Data { get; set; }
}

public static async Task<DecompressedData> ReceiveAndDecompressAsync(Stream stream)
{
    var lzmaInputStream = new LZMALibrary.LZMAInputStream();
    var decompressedData = new MemoryStream();

    try
    {
        await lzmaInputStream.ReadStreamAsync(stream, null, -1);
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error during decompression: {ex}");
        throw;
    }

    var decompressedDataArray = decompressedData.ToArray();

    return new DecompressedData { Data = decompressedDataArray };
}
```
