#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    SimpleLogger::new().with_module_level(log::LevelFilter::Info).init().unwrap();

    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <directory>", args[0]);
        return Ok(());
    }

    let dir = &args[1];
    let config_path = format!("{}/config.json", dir);

    // Load the configuration file from the specified directory, handling potential errors such as missing or malformed files.
    match File::open(&config_path) {
        Ok(file) => match BufReader::new(file).lines().collect::<Result<Vec<String>, _>>() {
            Ok(lines) => match from_reader::<String>(BufReader::new(file)) {
                Ok(config) => {
                    let runtime = Runtime::new().unwrap();
                    for task in &config.tasks {
                        // Execute the tasks asynchronously within the Tokio runtime.
                        let handle = runtime.spawn(execute_task(&task));
                    }

                    // Wait for all tasks to complete and exit the program.
                    runtime.block_on(runtime.join_all(vec!{handle})).unwrap();
                }
                Err(err) => error!("Failed to deserialize configuration: {:?}", err),
            },
            Err(err) => error!("Failed to read the configuration file: {:?}", err),
        },
        Err(err) => error!("Failed to open the configuration file: {:?}", err),
    }

    Ok(())
}
