import java.util.Random;
import java.util.concurrent.ThreadLocalRandom;

public final class RandomNumberGeneratorPool {
    private static final ThreadLocalRandom[] pool = new ThreadLocalRandom[Runtime.getRuntime().availableProcessors()];

    static {
        for (int i = 0; i < pool.length; ++i)
            pool[i] = ThreadLocalRandom.current();
    }

    public static Random getInstance() {
        return new Random(next());
    }

    public static int nextInt() {
        return getInstance().nextInt();
    }

    public static long nextLong() {
        return getInstance().nextLong();
    }

    public static float nextFloat() {
        return getInstance().nextFloat();
    }

    public static double nextDouble() {
        return getInstance().nextDouble();
    }

    public static void reset() {
        for (ThreadLocalRandom threadLocal : pool)
            threadLocal.setSeed(System.currentTimeMillis());
    }
}
