#include <stdio.h>
#include <string.h>

char* modifyFileNameExtension(char* originalFileName) {
    int indexDot = -1; // assuming no extension in the filename initially

    // Find the dot separating the name and extension, if any
    for (int i = 0; originalFileName[i] != '\0'; ++i) {
        if (originalFileName[i] == '.') {
            indexDot = i;
            break;
        }
    }

    // If there's no dot, it means no extension exists in the filename
    if (indexDot < 0) {
        return originalFileName;
    }

    char* newFileName = malloc(strlen(originalFileName) + 16); // assuming maximum of 4 digits and 3 characters for file type
    strncpy(newFileName, originalFileName, indexDot);
    strcat(newFileName, "_v"); // versioning suffix
    strcat(newFileName, &originalFileName[indexDot + 1]); // appending the extension after versioning suffix

    return newFileName;
}
