<?php
namespace App\Classes;

class Security {
    private $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    private $hashAlgorithm = 'sha256';
    private $apiEndpoint;
    private $apiKey;

    public function __construct($charSet = null, $hashAlgorithm = null, $apiEndpoint = null, $apiKey = null) {
        if (!is_null($charSet)) $this->charSet = $charSet;
        if (!is_null($hashAlgorithm)) $this->hashAlgorithm = $hashAlgorithm;
        if (!is_null($apiEndpoint)) $this->apiEndpoint = $apiEndpoint;
        if (!is_null($apiKey)) $this->apiKey = $apiKey;
    }

    public function generateRandomString($length) {
        $randomString = '';
        $charSetLength = strlen($this->charSet);
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->charSet[rand(0, $charSetLength - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password) {
        return password_hash($password, PASSWORD_DEFAULT);
    }

    public function checkPassword($hashedPassword, $clearTextPassword) {
        return password_verify($clearTextPassword, $hashedPassword);
    }

    public function registerUser($username, $email, $password) {
        if ($this->apiEndpoint && $this->apiKey) {
            $response = $this->callApi('register', ['username' => $username, 'email' => $email, 'password' => $this->hashPassword($password)]);
            if (!$response || is_error($response)) throw new \Exception('API Error during registration');
        } else {
            // Handle no API configuration or missing credentials
        }
    }

    public function loginUser($username, $password) {
        if ($this->apiEndpoint && $this->apiKey) {
            $hashedPassword = $this->hashPassword($password);
            $response = $this->callApi('login', ['username' => $username, 'password' => $hashedPassword]);
            if (!$response || is_error($response)) throw new \Exception('API Error during login');
        } else {
            // Handle no API configuration or missing credentials
        }
    }

    private function callApi($action, $data) {
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $this->apiEndpoint . '/' . $action);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        if ($this->apiKey) {
            curl_setopt($ch, CURLOPT_HTTPHEADER, array('Content-Type: application/json', 'Authorization: Bearer ' . $this->apiKey));
        }
        $response = json_decode(curl_exec($ch), true);
        if (curl_errno($ch)) {
            throw new \Exception('Connection error during API call');
        }
        curl_close($ch);
        return $response;
    }
}
