    if (!file) {
        log_error("Failed to open input file.");
        return;
    }

    char buffer[1024];
    size_t lines_count = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        ++lines_count;
    }
    rewind(file);

    char **lines = (char **) malloc(lines_count * sizeof(char *));
    size_t line_index = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        lines[line_index] = (char *) malloc(strlen(buffer) + 1);
        strcpy(lines[line_index], buffer);
        ++line_index;
    }

    qsort(lines, lines_count, sizeof(char *), strcmp);
    sequence_number = atoi(lines[lines_count - 1]);

    // Cleanup and handle exceptions gracefully if needed
}
