    seg->payload_len = rand() % (max_payload_len - min_payload_len + 1) + min_payload_len;
    seg->payload_buf = mmap(NULL, seg->payload_len, PROT_READ | PROT_WRITE, MAP_PRIVATE, -1, 0);
    if (seg->payload_buf == MAP_FAILED) {
