[' Here is a simplified implementation of a dynamic thread pool manager in C, considering the given constraints. This code does not include the interaction with an external data source but demonstrates how to manage tasks and threads dynamically, handle errors, and ensure graceful shutdown.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>

typedef void (*TaskFunc)(void*);
struct task {
    TaskFunc func;
    void *arg;
};

// Semaphore for worker threads synchronization
sem_t workers_semaphore;
// Semaphore to limit the maximum number of worker threads
sem_t max_workers_semaphore;

// Thread pool structure
struct threadpool {
    sem_t *workers_count;
    sem_t *completion_semaphore;
    int min_threads, max_threads, idle_timeout;
    pthread_mutex_t threads_mutex;
    pthread_t **threads;
};

void worker(struct threadpool *tp) {
    for (;;) {
        struct task t;
        sem_wait(&tp->completion_semaphore);

        if (!tp->workers_count[0]) {
            // If there are no more tasks, we can exit the loop
            return;
        }

        pthread_mutex_lock(&tp->threads_mutex);
        int i = 0;
        for (; i < tp->max_threads && tp->threads[i]; ++i) {}

        if (i == tp->max_threads) {
            sem_post(&max_workers_semaphore); // Signal that a new worker can be created if needed
        }

        if (!tp->threads[i]) {
            tp->threads[i] = pthread_self();
            pthread_mutex_unlock(&tp->threads_mutex);

            t.func = get_next_task;
            t.arg = &t;
            (*t.func)(t.arg); // Execute the task
        } else {
            pthread_mutex_unlock(&tp->threads_mutex);
            sem_post(&workers_semaphore); // Signal a worker to pick up a new task when ready
        }
    }
}

void get_next_task(void* arg) {
    struct task *t = (struct task*)arg;
    (*t->func)(t->arg); // Execute the task
    sem_post(&workers_semaphore); // Signal that we finished a task, so a new one can be picked up
}

void add_task(struct threadpool *tp, TaskFunc func, void *arg) {
    struct task t;
    t.func = func;
    t.arg = arg;

    sem_wait(&max_workers_semaphore); // Block until a worker is available or the maximum number of workers is reached

    pthread_mutex_lock(&tp->threads_mutex);
    for (int i = 0; i < tp->max_threads; ++i) {
        if (!tp->threads[i]) {
            tp->threads[i] = pthread_self();
            break;
        }
    }
    pthread_mutex_unlock(&tp->threads_mutex);

    sem_post(&tp->completion_semaphore); // Signal a worker to pick up the new task
}

void threadpool_init(struct threadpool *tp, int min_workers, int max_workers, int idle_timeout) {
    tp->min_threads = min_workers;
    tp->max_threads = max_workers;
    tp->idle_timeout = idle_timeout;

    // Initialize semaphores and mutex
    if (sem_init(&workers_semaphore, 1, 0) != 0 ||
        sem_init(&max_workers_semaphore, 1, max_workers - min_workers) != 0 ||
        pthread_mutex_init(&tp->threads_mutex, NULL) != 0) {
        perror("Failed to initialize synchronization objects");
        exit(EXIT_FAILURE);
    }

    // Initialize thread array with sentinel values
    tp->threads = malloc((max_workers + 1) * sizeof(pthread_t*));
    for (int i = 0; i < max_workers + 1; ++i) {
        tp->threads[i] = NULL;
    }
}

void threadpool_destroy(struct threadpool *tp) {
    // Ensure that all tasks are completed before destroying the pool
    for (int i = 0; i < tp->max_threads; ++i) {
        add_task(tp, NULL, NULL);
    }

    pthread_mutex_destroy(&tp->threads_mutex);
    sem_destroy(&workers_semaphore);
    sem_destroy(&max_workers_semaphore);

    free(tp->threads);
}
```

This code demonstrates how to create a dynamic thread pool with support for adding tasks asynchronously, scaling based on current load (by creating and destroying worker threads), and graceful shutdown. The implementation makes use of semaphores for synchronization between the thread pool, worker threads, and new tasks. Error handling is not explicitly shown in this example but can be added by checking the return values of functions like `pthread_create` and `sem_init`.']

