            // Store the session token in the cache or database for later use
            // Handle the response from the API and set appropriate error messages
            if ($response['success']) {
                // Successfully registered, store the session token securely
                $this->cache->store($username, $sessionToken);
                return true;
            } else {
                throw new \Exception($response['message']);
            }
        } catch (\Exception $e) {
            // Handle exceptions and set appropriate error messages
            $this->log->error("Register failure: " . $e->getMessage());
            throw $e;
        }
    }

    public function login($username, $password) {
        try {
            $sessionToken = null;

            // Check the cache for a stored session token
            if ($this->cache->has($username)) {
                $sessionToken = $this->cache->get($username);
            } else {
                // If no token is found, try to authenticate through the API
                $response = $this->authApi->login([
                    'username' => $username,
                    'password' => $this->hashPassword($password),
                ]);

                if ($response['success']) {
                    // Successfully logged in, store the session token securely
                    $sessionToken = $this->generateRandomString(64);
                    $this->cache->store($username, $sessionToken);
                } else {
                    throw new \Exception($response['message']);
                }
            }

            if ($sessionToken) {
                return $sessionToken;
            } else {
                throw new \Exception("Unable to log in.");
            }
        } catch (\Exception $e) {
