                                         [this](const double& value) { return value < m_min || value > m_max; }) != m_data.end()) {
            throw std::invalid_argument("Invalid initial range.");
        }
        std::sort(m_data.begin(), m_data.end());
    }

    void AddDataPoint(double value) {
        if (value < m_min || value > m_max) {
            throw std::invalid_argument("Invalid data point.");
        }
        auto it = std::lower_bound(m_data.begin(), m_data.end(), value);
        m_data.insert(it, value);
    }

    double GetMean() const {
        return std::accumulate(m_data.cbegin(), m_data.cend(), 0.0) / m_data.size();
    }

    double GetMedian() const {
        size_t n = m_data.size();
        if (n == 0) return 0;
        auto it = std::next(m_data.cbegin(), n/2);
        return (*it + *(std::prev(it)) ) / 2.0;
    }

    double GetStandardDeviation() const {
        double mean = GetMean();
        double square_diff_sum = std::inner_product(m_data.cbegin(), m_data.cend(), m_data.cbegin(), 0, [](double a, double b) { return pow(a - b, 2); });
        return sqrt(square_diff_sum / (m_data.size() - 1));
    }

    friend std::ostream& operator<<(std::ostream& os, const DynamicDataAggregator& aggregator) {
        os << "Min: " << aggregator.m_min << ", Max: " << aggregator.m_max << "\n";
        auto it = aggregator.m_data.cbegin();
        std::advance(it, aggregator.m_data.size()/2);
        os << "Median: " << *it << "\n";
        os << "Mean: " << aggregator.GetMean() << ", Standard Deviation: " << aggregator.GetStandardDeviation();
        return os;
    }

    void SetRange(double min, double max) {
        if (min > m_max || max < m_min || std::find_if(m_data.begin(), m_data.end(),
                                         [this](const double& value) { return value < min || value > max; }) != m_data.end()) {
            throw std::invalid_argument("Invalid range.");
        }
        m_min = min;
        m_max = max;
    }

    void AggregateAndProcess(int iterations) {
        for (int i = 0; i < iterations; ++i) {
            double value = GetNextDataPoint(); // Implement a method that generates the next data point or reads it from a sensor.
            AddDataPoint(value);
        }
    }

    template<typename Archive>
    void serialize(Archive& ar, const unsigned int) {
        ar & BOOST_SERIALIZATION_NVP(m_data);
    }

private:
    std::vector<double> m_data;
    double m_min, m_max;

    double GetNextDataPoint() { // Implement a method that generates the next data point or reads it from a sensor. }
};

