public class TransactionSummary {
    private final ExecutorService parserPool;
    private final ConcurrentSkipListMap<String, TransactionCounter> userTransactions;
    private final HashMap<String, Integer> userCounts;

    public TransactionSummary() {
        this.parserPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.userTransactions = new ConcurrentSkipListMap<>();
        this.userCounts = new HashMap<>();
    }

    public void resetState() {
        userTransactions.clear();
        userCounts.clear();
    }

    public Summary parseAndAggregateCSV(String filePath) throws IOException {
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                CsvParser parser = new CsvParser();
                parserPool.submit(() -> parseRecord(parser, line));
            }
            parserPool.shutdown();
            parserPool.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

            Summary summary = new Summary();
            userTransactions.forEach((user, counter) -> {
                summary.totalTransactions += counter.getTotal();
                summary.averageTransactionValue += counter.getAverage();
                summary.transactionCountPerUser.put(user, counter.getCount());
            });
            return summary;
        } catch (InterruptedException | CsvFormatException e) {
            throw new RuntimeException(e);
        }
    }

    private void parseRecord(CsvParser parser, String line) throws CsvFormatException {
