        if (userId == null) return;

        TransactionCounter counter;
        if (userTransactions.computeIfAbsent(userId, k -> new TransactionCounter()) == null) {
            userCounts.put(userId, 1);
        } else {
            userCounts.merge(userId, 1, Integer::sum);
        }

        // Parse the transaction data from the record and update the counter for the given userId.
    }
}

