using System;
using System.Collections.Generic;
using System.Net;
using System.Text.RegularExpressions;
using System.IO;
using Newtonsoft.Json;

public class AdvancedDNSWeatherSimulation
{
    private double minTemp, maxTemp, minHumidity, maxHumidity, minWindSpeed, maxWindSpeed;
    private List<string> ipAddressList = new List<string>();

    public AdvancedDNSWeatherSimulation(double minTemp, double maxTemp, double minHumidity, double maxHumidity, double minWindSpeed, double maxWindSpeed, List<string> ipAddresses)
    {
        SetWeatherParameters(minTemp, maxTemp, minHumidity, maxHumidity, minWindSpeed, maxWindSpeed, ipAddresses);
    }

    private double GetRandomTemperature() => (double)((maxTemp - minTemp) * new Random().NextDouble()) + minTemp;
    private double GetRandomHumidity() => (double)((maxHumidity - minHumidity) * new Random().NextDouble()) + minHumidity;
    private double GetRandomWindSpeed() => (double)((maxWindSpeed - minWindSpeed) * new Random().NextDouble()) + minWindSpeed;
    private string GetRandomIP() => string.Format("{0}.{1}.{2}.{3}", new Random().Next(256), new Random().Next(256), new Random().Next(256), new Random().Next(256));

    public void SetWeatherParameters(double minTemp, double maxTemp, double minHumidity, double maxHumidity, double minWindSpeed, double maxWindSpeed, List<string> ipAddresses)
    {
        if (maxTemp <= minTemp || maxHumidity <= minHumidity || maxWindSpeed <= minWindSpeed)
            return;

        this.minTemp = minTemp;
        this.maxTemp = maxTemp;
        this.minHumidity = minHumidity;
        this.maxHumidity = maxHumidity;
        this.minWindSpeed = minWindSpeed;
        this.maxWindSpeed = maxWindSpeed;

        ipAddressList = new List<string>();
        foreach (var ip in ipAddresses)
            if (IsValidIP(ip))
                ipAddressList.Add(ip);
    }

    private bool IsValidIP(string input) => Regex.IsMatch(input, @"^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])$");

    public override string ToString()
    {
        var sb = new System.Text.StringBuilder();
        sb.AppendFormat("Min Temperature: {0} Max Temperature: {1}\n", minTemp, maxTemp);
        sb.AppendFormat("Min Humidity: {0} Max Humidity: {1}\n", minHumidity, maxHumidity);
        sb.AppendFormat("Min Wind Speed: {0} Max Wind Speed: {1}\n", minWindSpeed, maxWindSpeed);
        sb.AppendFormat("IP Addresses:\n");
        foreach (var ip in ipAddressList)
            sb.AppendLine(ip);
        return sb.ToString();
    }

    public Tuple<List<WeatherEvent>, List<string>> SimulateWeatherEvents(int iterations)
    {
        var weatherEvents = new List<WeatherEvent>();
        var resolvedIPs = new List<string>();

        for (var i = 0; i < iterations; i++)
        {
            try
            {
                var ip = GetRandomIP();
                resolvedIPs.Add(ip);
                IPAddress.TryParse(ip, out _);

                weatherEvents.Add(new WeatherEvent()
                {
                    Temperature = GetRandomTemperature(),
                    Humidity = GetRandomHumidity(),
                    WindSpeed = GetRandomWindSpeed(),
                    ResolvedIP = ip
                });
            }
            catch (Exception ex)
            {
                Console.WriteLine(ex);
            }
        }

        return new Tuple<List<WeatherEvent>, List<string>>(weatherEvents, resolvedIPs);
    }

    public void SaveWeatherData(string filename)
    {
        var data = new
        {
            minTemp = minTemp,
            maxTemp = maxTemp,
            minHumidity = minHumidity,
            maxHumidity = maxHumidity,
            minWindSpeed = minWindSpeed,
            maxWindSpeed = maxWindSpeed,
            ipAddressList = ipAddressList
        };

        var json = JsonConvert.SerializeObject(data);
        File.WriteAllText(filename, json);
    }
}
```

