        std::advance(it);
    }

    // Concatenate remaining arguments (except for the password) while respecting options and maximum string length
    if (it != end) {
        std::stringstream concatenatedArguments;
        bool append = false;
        for (; it != end; ++it) {
            if (*it == password.c_str()) continue; // Skip the password argument

            // Handle whitespace options
            if (append && !ignoreWhitespace) {
                concatenatedArguments << ' ';
            }

            std::stringstream ss(*it);
            std::string token;
            std::getline(ss, token, ':');
            concatenatedArguments << token.substr(1); // Remove leading colon
            append = true;
        }

        concatenatedArguments.seekg(0, std::ios::end);
        if (concatenatedArguments.tellp() > maxStringLength) {
            // Trim the concatenated string to the nearest valid length
            concatenatedArguments.seekp(maxStringLength);
            concatenatedArguments << std::string(concatenatedArguments.tellp(), ' ');
            concatenatedArguments.seekp(0, std::ios::end);
        }

        plaintext = concatenatedArguments.str();
    }

