                        }
                    }
                };
            }, array_values($this->apiEndpoints));

            foreach ($apiTasks as $task) {
                $task();
            }

            // Prioritize data integrity over speed, handle partial responses gracefully
            $data = array_filter($data);
            if (empty($data)) {
                // Fallback mechanism in case of incomplete data retrieval
                $this->logger->warning("Incomplete weather data for city: {$city}, using default values.");
                $data = [
