    stack->bandwidth_threshold = threshold;
}

void* mac_pdu_alloc() {
    MAC_PDU_T* pdu = mmap(NULL, sizeof(MAC_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pdu == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    pdu->payload = malloc(rand() % MAX_PAYLOAD_SIZE + MIN_PAYLOAD_SIZE);
    if (!pdu->payload) {
