        std::unique_lock<std::mutex> lock(tasksMutex);
        taskQueue.pop_wait(lock); // Waits until there is a new task in the queue

        Task currentTask = taskQueue.front();
        taskQueue.pop();

        // Process the task based on priority and status rules from the configuration file
        // ...
    }
    return nullptr;
}

void addTask(const Task& task) {
    std::unique_lock<std::mutex> lock(tasksMutex);

    if (tasks.find(task.id) != tasks.end()) {
        throw std::invalid_argument("Task with duplicate id found");
    }

    tasks[task.id] = task;
}

void removeTask(const TaskId& id) {
    std::unique_lock<std::mutex> lock(tasksMutex);
    auto it = tasks.find(id);
    if (it == tasks.end()) {
        throw std::invalid_argument("Task with given id not found");
    }

    tasks.erase(it);
}

