using System;
using System.Collections.Generic;
using System.Runtime.Serialization.Formatters.Binary;
using UnityEngine;

public class DynamicMACPDUInitializer
{
    private int minValue;
    private int maxValue;
    private BinaryFormatter serializer = new BinaryFormatter();

    public int MinValue { get => minValue; }
    public int MaxValue { get => maxValue; }

    public DynamicMACPDUInitializer(int min, int max)
    {
        SetRange(min, max);
    }

    private void SetRange(int min, int max)
    {
        if (max < min)
        {
            this.minValue = 0;
            this.maxValue = 0;
            return;
        }

        this.minValue = Mathf.Max(min, int.MinValue);
        this.maxValue = Mathf.Min(max, int.MaxValue);
    }

    public int GetRandomInt()
    {
        if (this.minValue >= this.maxValue) return 0;
        return UnityEngine.Random.Range(this.minValue, this.maxValue + 1);
    }

    public float GetRandomFloat()
    {
        if (this.minValue >= this.maxValue) return 0f;
        return UnityEngine.Random.Range(this.minValue, this.maxValue + 1f);
    }

    public override string ToString()
    {
        return $"[[{minValue}, {maxValue})]";
    }

    public List<int> GenerateRandomValues(int iterations)
    {
        var randomValues = new List<int>();

        for (int i = 0; i < iterations; ++i)
        {
            if (this.minValue >= this.maxValue) break;

            randomValues.Add(GetRandomInt());
        }

        return randomValues;
    }

