namespace bs = boost::serialization;

class DynamicDataAggregator {
public:
    explicit DynamicDataAggregator(size_t initialSize = 1024) : _data(initialSize) {
        resetRange(-std::numeric_limits<double>::max(), std::numeric_limits<double>::max());
    }

    void AddDataPoint(double value);
    double GetMean() const;
    double GetMedian() const;
    double GetStandardDeviation() const;
    void SetRange(double min, double max);
    void AggregateAndProcess(int iterations);
    friend std::ostream& operator<<(std::ostream&, const DynamicDataAggregator&);

    // Serialization/Deserialization
    static std::vector<uint8_t> SerializeToBinaryStream(const std::vector<double>& data);
    static std::vector<double> DeserializeFromBinaryStream(std::vector<double>& data, const std::vector<uint8_t>& bytes);

private:
    std::vector<double> _data;
    double _min, _max;

    BOOST_SERIALIZATION_SPLIT_MEMBER()

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & _data;
        ar & _min;
        ar & _max;
    }
};

void DynamicDataAggregator::AddDataPoint(double value) {
    if (value < _min)
        _min = value;
    else if (_max < value)
        _max = value;

    if (_data.size() == _data.capacity())
        _data.resize(_data.capacity() * 2);

    _data[_data.size() - 1] = value;
    std::sort(_data.begin(), _data.end());
}

double DynamicDataAggregator::GetMean() const {
    return std::accumulate(_data.cbegin(), _data.cend(), 0.0) / _data.size();
}

double DynamicDataAggregator::GetMedian() const {
    size_t n = _data.size();
    if (n == 0)
        return 0;

    auto it = std::next(_data.cbegin(), n / 2);
    return (*it + *(std::prev(it))) / 2;
}

double DynamicDataAggregator::GetStandardDeviation() const {
    double mean = GetMean();
    double m2 = 0;

    for (const auto& x : _data)
        m2 += pow(x - mean, 2);

    return sqrt(m2 / _data.size());
}

void DynamicDataAggregator::SetRange(double min, double max) {
    if (min > max)
        throw std::invalid_argument("Invalid range: min value should be smaller than max value.");

    std::vector<double> newData;

    for (const auto& x : _data) {
        if (x >= min && x <= max)
            newData.push_back(x);
    }

    _data = newData;
    _min = min;
    _max = max;
}

void DynamicDataAggregator::AggregateAndProcess(int iterations) {
    if (iterations <= 0)
        throw std::invalid_argument("Iterations should be a positive integer.");

    for (int i = 0; i < iterations; ++i) {
        double value = GenerateDataPoint(); // Replace this with actual data generation function.
        AddDataPoint(value);
    }
}

std::ostream& operator<<(std::ostream& os, const DynamicDataAggregator& agg) {
    os << "Min: " << agg._min << ", Max: " << agg._max << ", Mean: " << agg.GetMean() << ", Median: " << agg.GetMedian() << ", StdDev: " << agg.GetStandardDeviation();
    return os;
}

std::vector<uint8_t> DynamicDataAggregator::SerializeToBinaryStream(const std::vector<double>& data) {
    std::vector<uint8_t> buffer;
    bs::binary_oarchive oa(buffer);
    oa & boost::serialization::make_nvp("data", data);
    return buffer;
}

std::vector<double> DynamicDataAggregator::DeserializeFromBinaryStream(std::vector<double>& data, const std::vector<uint8_t>& bytes) {
    std::vector<uint8_t> buffer(bytes);
    bs::binary_iarchive ia(buffer);
    ia & boost::serialization::make_nvp("data", data);
    if (ia.is_open())
        ia.close();

    return data;
}
