public class AdvancedDNSWeatherSimulation
{
    private double _minTemp, _maxTemp, _minHumidity, _maxHumidity, _minWindSpeed, _maxWindSpeed;
    private List<string> _ipAddressList;
    private static Random _random = new Random();

    public AdvancedDNSWeatherSimulation(double minTemp, double maxTemp, double minHumidity, double maxHumidity, double minWindSpeed, double maxWindSpeed, List<string> ipAddresses)
    {
        SetWeatherParameters(minTemp, maxTemp, minHumidity, maxHumidity, minWindSpeed, maxWindSpeed, ipAddresses);
    }

    private void SetWeatherParameters(double minTemp, double maxTemp, double minHumidity, double maxHumidity, double minWindSpeed, double maxWindSpeed, List<string> ipAddresses)
    {
        if (minTemp >= maxTemp || minHumidity >= maxHumidity || minWindSpeed > maxWindSpeed)
            return;

        _minTemp = minTemp < -50 ? -50 : minTemp;
        _maxTemp = maxTemp > 50 ? 50 : maxTemp;
        _minHumidity = minHumidity < 0 ? 0 : minHumidity;
        _maxHumidity = maxHumidity > 100 ? 100 : maxHumidity;
        _minWindSpeed = minWindSpeed <= 0 ? 1 : minWindSpeed;
        _maxWindSpeed = maxWindSpeed > 100 ? 100 : maxWindSpeed;

        _ipAddressList = new List<string>();

        foreach (var ip in ipAddresses)
        {
            if (IsValidIP(ip))
                _ipAddressList.Add(ip);
        }
    }

    private bool IsValidIP(string input)
    {
        var parts = input.Split('.');

        if (parts.Length != 4 || int.TryParse(parts[0], out int octet1) && octet1 < 256 &&
            int.TryParse(parts[1], out int octet2) && octet2 < 256 &&
            int.TryParse(parts[2], out int octet3) && octet3 < 256 &&
            int.TryParse(parts[3], out int octet4) && octet4 < 256)
        {
            var sum = octet1 + octet2 + octet3 + octet4;
            return sum <= 224 && sum != 0;
        }

        return false;
    }

    private double GetRandomTemperature() => (_maxTemp - _minTemp) * _random.NextDouble() + _minTemp;

    private double GetRandomHumidity() => (_maxHumidity - _minHumidity) * _random.NextDouble() + _minHumidity;

    private int GetRandomWindSpeed() => _random.Next(1, (int)_maxWindSpeed + 1);

    private string GetRandomIP()
    {
        if (_ipAddressList.Count == 0)
            return null;

        var index = _random.Next(_ipAddressList.Count);
        return _ipAddressList[index];
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        sb.AppendLine($"Min Temperature: {_minTemp}");
        sb.AppendLine($"Max Temperature: {_maxTemp}");
        sb.AppendLine($"Min Humidity: {_minHumidity}%");
        sb.AppendLine($"Max Humidity: {_maxHumidity}%");
        sb.AppendLine($"Min Wind Speed: {_minWindSpeed}m/s");
        sb.AppendLine($"Max Wind Speed: {_maxWindSpeed}m/s");
        sb.AppendLine("IP Addresses:");
        foreach (var ip in _ipAddressList)
            sb.AppendLine(ip);
        return sb.ToString();
    }

    private void LogData()
    {
        var data = new StringBuilder();
        data.AppendLine($"Min Temperature: {_minTemp}");
        data.AppendLine($"Max Temperature: {_maxTemp}");
        data.AppendLine($"Min Humidity: {_minHumidity}%");
        data.AppendLine($"Max Humidity: {_maxHumidity}%");
        data.AppendLine($"Min Wind Speed: {_minWindSpeed}m/s");
        data.AppendLine($"Max Wind Speed: {_maxWindSpeed}m/s");
        data.AppendLine("IP Addresses:");
        foreach (var ip in _ipAddressList)
            data.AppendLine(ip);

        File.WriteAllText(@"C:\WeatherData.txt", data.ToString());
    }

    public Tuple<List<WeatherEvent>, List<string>> SimulateWeatherEvents(int iterations)
    {
        var weatherEvents = new List<WeatherEvent>();
        var resolvedIPs = new List<string>();

        for (var i = 0; i < iterations; i++)
        {
            var temperatureChange = GetRandomTemperature();
            var humidityChange = GetRandomHumidity();
            var windSpeedChange = GetRandomWindSpeed();

            var ip = GetRandomIP();

            if (ip == null)
                continue;

            resolvedIPs.Add(ip);

            weatherEvents.Add(new WeatherEvent
            {
                TimeStamp = DateTime.Now,
                TemperatureChange = temperatureChange,
                HumidityChange = humidityChange,
                WindSpeedChange = windSpeedChange
            });
        }

        LogData();

        return new Tuple<List<WeatherEvent>, List<string>>(weatherEvents, resolvedIPs);
    }
}

public class WeatherEvent
{
    public DateTime TimeStamp { get; set; }
    public double TemperatureChange { get; set; }
    public double HumidityChange { get; set; }
    public int WindSpeedChange { get; set; }
}
