        _fileList = new List<FileMetadata>();

        ValidateBucketNameAndCapacity(bucketName, totalCapacityGB);
    }

    private void ValidateBucketNameAndCapacity(string bucketName, int totalCapacityGB)
    {
        if (string.IsNullOrWhiteSpace(bucketName))
            throw new ArgumentException("Bucket name cannot be null or empty.");

        if (totalCapacityGB <= 0)
            throw new ArgumentOutOfRangeException(nameof(totalCapacityGB), totalCapacityGB, "Total capacity must be greater than zero.");

        if (bucketName.Length > 256) // Reasonable length limit for bucket names
            throw new ArgumentOutOfRangeException(nameof(bucketName), bucketName, $"Bucket name length exceeds the maximum allowed ({bucketName.Length} > 256).");
    }

    public void CalculateAvailableSpace()
    {
        _usedStorageGB = _fileList.Sum(f => f.FileSizeMB);

        if (_usedStorageGB > _totalCapacityGB)
            throw new Exception("Used storage exceeds the total capacity.");
    }

    public void AddFile(string fileName, int fileSizeMB)
    {
        if (fileSizeMB <= 0 || fileSizeMB > _totalCapacityGB - _usedStorageGB)
            throw new ArgumentOutOfRangeException(nameof(fileSizeMB), fileSizeMB, "Invalid file size.");

        var file = new FileMetadata { FileName = fileName, FileSizeMB = fileSizeMB };
        _fileList.Add(file);
        _usedStorageGB += fileSizeMB;
    }

    public void RemoveFile(string fileName)
    {
        var fileToRemove = _fileList.FirstOrDefault(f => f.FileName == fileName);

        if (fileToRemove != null)
        {
            _usedStorageGB -= fileToRemove.FileSizeMB;
            _fileList.Remove(fileToRemove);
        }
        else
            throw new FileNotFoundException("File not found.", fileName);
    }

    public void UpdateFileSize(string fileName, int newFileSizeMB)
    {
        var fileToUpdate = _fileList.FirstOrDefault(f => f.FileName == fileName);

        if (fileToUpdate != null)
        {
            if (newFileSizeMB <= 0 || newFileSizeMB > _totalCapacityGB - _usedStorageGB + fileToUpdate.FileSizeMB)
                throw new ArgumentOutOfRangeException(nameof(newFileSizeMB), newFileSizeMB, "Invalid new file size.");

            fileToUpdate.FileSizeMB = newFileSizeMB;
            _usedStorageGB += (fileToUpdate.FileSizeMB - fileToUpdate.OriginalFileSizeMB); // Adjust used storage based on the difference between the original and new sizes
        }
        else
            throw new FileNotFoundException("File not found.", fileName);
    }

