public:
    Parser() : maxLines(1000000), currentLines(0) {}

    void parseLogs(const std::string& filename) {
        std::ifstream inputFile(filename);
        if (!inputFile.is_open()) {
            throw std::runtime_error("Could not open file");
        }

        nlohmann::json j;
        Entry entry;
        boost::container::flat_map<std::uint64_t, size_t> uniqueIds;
        boost::container::flat_set<nlohmann::json> entries;
        std::vector<Entry> duplicates;
        size_t totalSize = 0;
        uintmax_t timestampLimit = std::numeric_limits<uintmax_t>::max(); // Adjust this according to your needs

        while (std::getline(inputFile, line)) {
            try {
                j = nlohmann::json::parse(line);
                if (!j.is_object()) {
                    throw std::runtime_error("Log entry is not a JSON object");
                }
                if (!j.contains("id")) {
                    throw std::runtime_error("Missing 'id' field in log entry");
                }

                entry.id = j["id"].get<uint64_t>();
                // Parse other fields as needed

                uniqueIds[entry.id]++;
                totalSize += sizeof(Entry); // Adjust this according to the size of your Entry structure

                if (entries.insert(j).second) {
                    entries.erase(std::begin(entries));
                }

                currentLines++;
                if (currentLines >= maxLines) {
                    std::cout << "Processed " << currentLines << " lines\n";
                    std::cout << "Average size of parsed entries: " << totalSize / currentLines << "\n";
                    std::cout << "Total number of unique identifiers: " << uniqueIds.size() << "\n";

                    for (const auto& [id, count] : uniqueIds) {
                        if (count > 1) {
                            duplicates.emplace_back(entry);
                            duplicates.back().id = id;
                        }
                    }

                    if (!duplicates.empty()) {
                        std::cout << "Duplicate entries:\n";
                        for (const auto& d : duplicates) {
                            std::ostringstream ss;
                            ss << d.id << ": " << duplicates.size();
                            std::cout << ss.str() << "\n";
                        }
                    }

                    // Reset counters
                    totalSize = 0;
                    currentLines = 0;
                    uniqueIds.clear();
                    entries.clear();
                }
            } catch (const nlohmann::json::exception& e) {
                std::cerr << "Error parsing log entry: " << e.what() << "\n";
            } catch (const std::exception& e) {
                std::cerr << "Unexpected error: " << e.what() << "\n";
            }
        }
    }

private:
    uint64_t maxLines;
    uint64_t currentLines;
};
