namespace RandomPool {
    struct ThreadSafeGenerator {
        std::mt19937 engine;
        std::uniform_int_distribution<int> intDist;
        std::uniform_real_distribution<float> floatDist;

        ThreadSafeGenerator() : engine(std::random_device{}()), intDist(*this), floatDist(*this) {}

        int nextInt() { return intDist(engine); }
        float nextFloat() { return floatDist(engine); }

        static std::vector<ThreadSafeGenerator> pool;
        static std::mutex mtx;
        static const int maxThreads = 10;
        static std::queue<std::unique_ptr<ThreadSafeGenerator>> freeGenPool;

        static void Reset() {
            for (auto& gen : pool) {
                gen.engine.seed(std::random_device{}());
            }
        }

    private:
        static ThreadSafeGenerator* GetFreeGenerator() {
            if (!freeGenPool.empty()) {
                auto gen = std::move(freeGenPool.front());
                freeGenPool.pop();
                return gen.get();
            }
            else {
                if (pool.size() < maxThreads) {
                    pool.emplace_back(ThreadSafeGenerator());
                    return &pool.back();
                }
                std::unique_ptr<ThreadSafeGenerator> newGen(new ThreadSafeGenerator());
                mtx.lock();
                freeGenPool.push(std::move(newGen));
                mtx.unlock();
                return freeGenPool.front().get();
            }
        }

        static void ReturnToPool(ThreadSafeGenerator* gen) {
            if (gen->engine.state() == std::mt19937::reset_state()) {
                mtx.lock();
                freeGenPool.push(std::unique_ptr<ThreadSafeGenerator>(gen));
                mtx.unlock();
            }
        }
    };

    std::vector<ThreadSafeGenerator> ThreadSafeGenerator::pool;
    std::mutex ThreadSafeGenerator::mtx;
    std::queue<std::unique_ptr<ThreadSafeGenerator>> ThreadSafeGenerator::freeGenPool;

