#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <inttypes.h>
#include <stdbool.h>

typedef struct {
    uint64_t ue_id;
    time_t timestamp;
    int cqi[12]; // CQI measurements for 12 cells
    int snr[12]; // SNR measurements for 12 cells
} report;

typedef struct hash_node {
    report data;
    struct hash_node *next;
} hash_node;

// Hash function for UE-ID
uint64_t hash(uint64_t key) {
    uint64_t hash = 5381;
    int c;

    while (key != 0 && isxdigit(key & 0xFF)) {
        c = (key & 0xFF);
        hash = ((hash << 5) + hash) + c;
        key >>= 8;
    }

    return hash % TABLE_SIZE;
}

// Allocate and initialize a new report
report* create_report() {
    report *r = malloc(sizeof(report));
    memset(r, 0, sizeof(report));
    return r;
}

// Add a report to the hash table
void add_report(hash_table *h, report *r) {
    uint64_t hash_idx = hash(r->ue_id);
    hash_node **slot = &h->slots[hash_idx];

    while (*slot != NULL) {
        if ((*slot)->data.ue_id == r->ue_id) return; // UE-ID already exists, ignore this report
        slot = &(*slot)->next;
    }

    *slot = malloc(sizeof(hash_node));
    (*slot)->data = *r;
    (*slot)->next = NULL;
}

