    [WebMethod]
    public string updateElementHTML(string sectionID, string elementID, string content)
    {
        if (string.IsNullOrWhiteSpace(sectionID) || string.IsNullOrWhiteSpace(elementID) || string.IsNullOrWhiteSpace(content))
            throw new ArgumentException("Invalid input parameters");

        Element element;
        if (_elements.TryGetValue(sectionID, out element))
        {
            if (element.TryGetValue(elementID, out var elementContent))
            {
                elementContent.Content = content;
                return "Refresh the page to see changes.";
            }
            else
            {
                throw new KeyNotFoundException("Element not found.");
            }
        }
        else
        {
            throw new KeyNotFoundException("Section not found.");
        }
    }
}
