struct priority_queue {
    pthread_mutex_t lock;
    int capacity, count;
    MAC_PDU_T** data;
};

void init_priority_queue(struct priority_queue* queue, int capacity) {
    queue->capacity = capacity;
    queue->count = 0;
    queue->data = malloc(capacity * sizeof(MAC_PDU_T*));
    pthread_mutex_init(&queue->lock, NULL);
}

void destroy_priority_queue(struct priority_queue* queue) {
    if (queue->data != NULL) {
        for (int i = 0; i < queue->capacity; ++i) {
            if (queue->data[i] != NULL)
                free(queue->data[i]->payload);
            free(queue->data[i]);
        }
        free(queue->data);
        pthread_mutex_destroy(&queue->lock);
    }
}

void enqueue(struct priority_queue* queue, MAC_PDU_T* pdu) {
    if (pthread_mutex_trylock(&queue->lock) != 0) return; // Try to lock the mutex. If it fails, we'll exit early without enqueuing the PDU.

    if (queue->count == queue->capacity) {
        pthread_mutex_unlock(&queue->lock); // If the queue is full, we unlock the mutex and exit. The caller will need to handle this case.
        return;
    }

    queue->data[queue->count++] = pdu;
    pthread_mutex_unlock(&queue->lock);
}

MAC_PDU_T* dequeue(struct priority_queue* queue) {
    if (pthread_mutex_trylock(&queue->lock) != 0) return NULL; // Try to lock the mutex. If it fails, we'll exit without dequeuing any PDU.

    MAC_PDU_T* pdu = NULL;
    if (queue->count > 0) {
        pdu = queue->data[0];
        memset(pdu->payload, 0, pdu->payload_len); // Zero out the payload to ensure data consistency before sending
        queue->data[0] = NULL;
        --queue->count;
    }
    pthread_mutex_unlock(&queue->lock);
    return pdu;
}

void init_pdu(MAC_PDU_T** pdu) {
    *pdu = malloc(sizeof(MAC_PDU_T));
