        *pdu = NULL;
        return; // Return early if memory allocation failed.
    }

    // Handle potential buffer overflows gracefully
    if (payload_len > INT16_MAX - sizeof(MAC_Header) - sizeof(MAC_Trailer)) {
        free((*pdu)->payload);
        free(*pdu);
        *pdu = NULL;
        return; // Return early if the generated payload length is too large.
