using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using Newtonsoft.Json;
using System.IO;
using System.Threading.Tasks;

public class LogService {
    private readonly Dictionary<ulong, LogEntry> logStore = new Dictionary<ulong, LogEntry>();
    private readonly object lockObj = new object();

    public async Task<bool> HandleLogEntryRequest(HttpRequest request) {
        try {
            var data = await request.ReadAsStringAsync();
            var entry = JsonConvert.DeserializeObject<LogEntry>(data);

            lock (lockObj) {
                if (!logStore.ContainsKey(entry.LogID)) {
                    logStore[entry.LogID] = entry;
                    return true;
                }
            }
        } catch (Exception e) {
            Console.WriteLine(e);
            return false;
        }

        return false;
    }
}
