typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

#define ARRAY_SIZE 10000
#define LOG_FILE "error_log.txt"

void md5_hash(const char *input, unsigned char output[MD5_DIGEST_LENGTH]) {
    if (!input) return;

    const EVP_MD *md = EVP_md5();
    EVP_MD_CTX *ctx = EVP_MD_CTX_create();

    int ret = EVP_DigestInit(ctx, md);
    if (ret != 1) {
        fprintf(stderr, "Failed to initialize the digest context\n");
        return;
    }

    ret = EVP_DigestUpdate(ctx, input, strlen(input));
    if (ret != 1) {
        fprintf(stderr, "Failed to update the digest context\n");
        return;
    }

    ret = EVP_DigestFinal(ctx, output, NULL);
    if (ret != 1) {
        fprintf(stderr, "Failed to finalize the digest context\n");
    }

    EVP_MD_CTX_free(ctx);
}

NFAPI_CRC_INDICATION_PDU_T* initializeNfaApiIndications() {
    static NFAPI_CRC_INDICATION_PDU_T buffer[ARRAY_SIZE];
    int *counter = calloc(2, sizeof(int)); // Successful and failed initializations counters
    int *log_fd = calloc(1, sizeof(int));

    if (!buffer || !counter || !log_fd) {
        fprintf(stderr, "Memory allocation failure\n");
        goto cleanup;
    }

    time_t rawtime;
    struct tm *timeinfo;

    *log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (*log_fd == -1) {
        perror("Failed to open log file");
        goto cleanup;
    }

    for (int i = 0; i < ARRAY_SIZE; ++i) {
        RX_UE_INFORMATION_TAG rx_ue_info = { .value = i };
        RNTI rnti = { .rntiValue = i + 100000 };
        CRC_INDICATION_REL8_TAG crc_ind;

        md5_hash("some-random-string", crc_ind.crc_flag);
        crc_ind.tag = CRCI_IND_REL8;

        buffer[i] = (NFAPI_CRC_INDICATION_PDU_T){rx_ue_info, rnti, crc_ind};

        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        fprintf(*log_fd, "%s - Initialization attempt: %d, Successful\n", asctime(timeinfo), i);
        ++counter[0];
    }

cleanup:
    if (buffer) free(buffer);
    if (counter) free(counter);
    if (*log_fd != -1) close(*log_fd);

    return buffer;
}
```

