void generateCRCIndicationPDUs(int N, NFAPI_CRCI_INDICATION_PDU_T **pdus) {
    *pdus = malloc(N * sizeof(NFAPI_CRCI_INDICATION_PDU_T));

    for (int i = 0; i < N; ++i) {
        NFAPI_CRCI_INDICATION_PDU_T *pdu = &((*pdus)[i]);

