        pdu->crc_indication_rel8_tag.crcf_flag = rand() % 2;

        // Compute MD5 hash of a provided string parameter
        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, "your-string", strlen("your-string"));
        MD5_Final(md5, &ctx);

        // Copy the MD5 hash into the CRC field of the pdu structure
        memcpy(pdu->crc, md5, MD5_DIGEST_LENGTH);
    }
}
