    pthread_t hash_thread, flag_thread;
    unsigned char md5[MD5_DIGEST_LENGTH];
    unsigned long unique_id;
    NFAPI_CRC_INDICATION_PDU_T *result = malloc(1);

    input = fopen(input_file, "rb");
    if (!input) {
        perror("Error opening input file");
        return NULL;
    }

    fseek(input, 0, SEEK_END);
    N = ftell(input);
    rewind(input);

    if (N <= 0) {
        fclose(input);
        return result;
    }

    buffer = malloc(N);
    if (!buffer) {
        perror("Memory allocation error");
        fclose(input);
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, N, input);
    if (bytes_read != N) {
