    fclose(input);

    pthread_create(&hash_thread, NULL, compute_md5_hash, &seed, buffer);
    pthread_create(&flag_thread, NULL, generate_random_flag, &seed);

    result = malloc((N + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        perror("Memory allocation error");
        free(buffer);
        pthread_cancel(hash_thread);
        pthread_cancel(flag_thread);
        return NULL;
    }

    unique_id = time_in_milliseconds();

    for (size_t i = 0; i < N; ++i) {
        result[i].RX_UE_INFORMATION_TAG = (uint8_t)(unique_id >> 56);
        result[i].RNTI = (uint16_t)((unique_id & 0x00FF0000) >> 16);
        result[i].CRC_INDICATION_REL8_TAG = unique_id;
        result[i].CRCFLAG = 0; // Initialize to zero, wait for flag generation thread to set it

        unique_id++;
    }

    output = fopen(output_file, "wb");
    if (!output) {
        perror("Error opening output file");
        free(buffer);
        pthread_cancel(hash_thread);
        pthread_cancel(flag_thread);
        free(result);
        return NULL;
    }

    fwrite(buffer, 1, N, output);
    fclose(output);

    void* hash_res = NULL;
    void* flag_res = NULL;

    pthread_join(hash_thread, &hash_res);
    pthread_join(flag_thread, &flag_res);

    if (hash_res && flag_res) {
        memcpy(md5, hash_res, MD5_DIGEST_LENGTH);
        result[0].CRCFLAG = *(uint32_t*)flag_res;
    }

    free(buffer);
    free(result);

    return result;
}

unsigned long time_in_milliseconds() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long)((double)ts.tv_sec * 1000.0 + (double)ts.tv_nsec / 1000000.0);
}

