    off_t file_size = st.st_size;
    if (file_size < 0) {
        perror("fstat");
        exit(1);
    }

    if (file_size <= 0) {
        fprintf(stderr, "Input file is empty or negative size.\n");
        close(fd_input);
        exit(1);
    }

    void* mapped_memory = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd_input, 0);
    if (mapped_memory == MAP_FAILED) {
        perror("mmap");
        close(fd_input);
        exit(1);
    }

