    if (!pdu_array) {
        perror("malloc");
        munmap(mapped_memory, file_size);
        close(fd_input);
        exit(1);
    }

    int current_id = 0;
    off_t offset = 0;
    while (offset < file_size) {
        // Parse the contents based on the transformation rules.
        // Generate a unique identifier for each PDU and set CRCFLAG using the provided seed.
        // Handle edge cases such as memory allocation errors appropriately.

        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current_id++;
        pdu_array = realloc(pdu_array, current_id * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_array) {
            perror("realloc");
            munmap(mapped_memory, file_size);
            close(fd_input);
            exit(1);
        }
    }

    pthread_join(hash_thread, (void**)&md5_hash);

    munmap(mapped_memory, file_size);
    close(fd_input);

    int fd_output = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd_output == -1) {
        perror("open");
        exit(1);
    }

    write(fd_output, pdu_array, current_id * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    close(fd_output);

    return pdu_array;
}
