#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    uint32_t UE_ID;
    uint32_t RNTI;
    uint16_t ServingCellID;
    bool RB_ALLOC_FLAG;
    time_t creation_time;
} NF_API_UE_CONTEXT;

typedef struct {
    NF_API_UE_CONTEXT* contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} UE_CONTEXT_MANAGER;

void init_ue_context(NF_API_UE_CONTEXT* context) {
    memset(context, 0, sizeof(NF_API_UE_CONTEXT));
}

UE_CONTEXT_MANAGER* ue_context_manager_init(size_t capacity) {
    UE_CONTEXT_MANAGER* manager = malloc(sizeof(UE_CONTEXT_MANAGER));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }

    manager->capacity = capacity;
    manager->count = 0;
    manager->contexts = calloc(capacity, sizeof(NF_API_UE_CONTEXT));
    if (!manager->contexts) {
        perror("Failed to allocate memory for contexts");
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);

    return manager;
}

NF_API_UE_CONTEXT* ue_context_manager_get(UE_CONTEXT_MANAGER* manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count < manager->capacity) {
        NF_API_UE_CONTEXT* context = &manager->contexts[manager->count];
        init_ue_context(context);
        manager->count++;
        pthread_mutex_unlock(&manager->mutex);
        return context;
    }
    pthread_mutex_unlock(&manager->mutex);

    // Cache search for existing context
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->contexts[i].RB_ALLOC_FLAG) {
            manager->contexts[i].UE_ID = rand();
            manager->contexts[i].RNTI = rand();
            manager->contexts[i].ServingCellID = rand() % 65536; // Valid range for ServingCellID
            manager->contexts[i].RB_ALLOC_FLAG = (rand() < RAND_MAX / 4);
            manager->contexts[i].creation_time = time(NULL);
            return &manager->contexts[i];
        }
    }

    // Resize if necessary
    if (manager->count >= manager->capacity) {
        UE_CONTEXT_MANAGER temp;
        temp.capacity *= 2;
        temp.count = manager->count;
        temp.contexts = realloc(manager->contexts, temp.capacity * sizeof(NF_API_UE_CONTEXT));
        if (!temp.contexts) {
            perror("Failed to resize context array");
            return NULL;
        }

        memcpy(temp.contexts + manager->count, manager->contexts, manager->capacity * sizeof(NF_API_UE_CONTEXT));
        free(manager);
        manager = &temp;
    }

    // Allocate new context
    NF_API_UE_CONTEXT* context = &manager->contexts[manager->count];
    init_ue_context(context);
    manager->count++;

    return context;
}

void ue_context_manager_destroy(UE_CONTEXT_MANAGER* manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}

