void* allocate_subscription(void* arg) {
    struct subscription_manager* manager = arg;
    NF_API_SUBSCRIPTION* sub;

    if (manager->num_subscriptions < manager->max_subscriptions) {
        sub = &manager->list[manager->num_subscriptions];
        init_subscription(sub);
        ++manager->num_subscriptions;
        return sub;
    }

    return NULL; // Failed to allocate subscription due to max limit reached
}

void* find_cached_subscription(void* arg) {
    struct subscription_cache* cache = arg;
    NF_API_SUBSCRIPTION* sub;

    pthread_mutex_lock(&cache->mutex);

    if (cache->count > 0) {
        sub = &cache->cache[cache->count - 1];
        --cache->count;
    } else {
        pthread_mutex_unlock(&cache->mutex);
        return NULL; // No cached subscription available
    }

    pthread_mutex_unlock(&cache->mutex);

    memset(sub, 0, sizeof(*sub)); // Initialize the found subscription with default values
    init_subscription(sub);

    return sub;
}

void manage_subscriptions(struct subscription_manager* manager) {
    pthread_t allocation_thread, cache_thread;
    pthread_attr_t attr;

    // Initialize mutex for the subscription cache
    pthread_mutex_init(&manager->cache.mutex, NULL);

    // Configure attributes for the allocation and cache threads
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Create allocation thread
    pthread_create(&allocation_thread, &attr, allocate_subscription, manager);

    // Create cache thread
    pthread_create(&cache_thread, &attr, find_cached_subscription, &manager->cache);

    // Wait for both threads to finish execution and join their results
    pthread_join(allocation_thread, NULL);
    pthread_join(cache_thread, NULL);

    // Cleanup attributes and mutexes
    pthread_mutex_destroy(&manager->cache.mutex);
    pthread_attr_destroy(&attr);
}
