pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
int log_fd = -1;

time_t current_time() {
    return time(NULL);
}

void *mmaped_memory(size_t size) {
    int fd = open("/dev/zero", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    off_t offset = 0;
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, fd, offset);
    close(fd);
    return ptr;
}

void log(const char *message) {
    pthread_mutex_lock(&log_lock);
    if (log_index == max_log_entries) {
        rewind(log_fd);
        log_index = 0;
    }

    struct tm *tm = localtime(&current_time());
    char timestr[32];
    strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", tm);
    log_buffer[log_index].timestamp = current_time();
    log_buffer[log_index].type = SUCCESS;
    snprintf(log_buffer[log_index].type_str, sizeof(log_buffer[log_index].type_str), "%s", message);
    log_index++;
    fseek(log_fd, 0, SEEK_SET);
    fwrite(log_buffer, sizeof(LogEntry), log_index, log_fd);

    pthread_mutex_unlock(&log_lock);
}

void log_error(const char *message) {
    log("ERROR: ");
    log(message);
}

bool within_one_year(time_t date) {
    return current_time() - date <= 31536000; // One year in seconds
}

struct NF_API_SUBSCRIPTION *get_subscription_from_cache(unsigned long user_id, unsigned long plan_id) {
    pthread_mutex_lock(&cache_lock);
    if (subscription_cache.size > 0 && subscription_cache.memory != NULL) {
        struct NF_API_SUBSCRIPTION *subscription = subscription_cache.memory;
        size_t index = (user_id + plan_id) % subscription_cache.size;

        if (subscription[index].USER_ID == user_id && subscription[index].PLAN_ID == plan_id && subscription[index].ACTIVE_STATUS != 0) {
            pthread_mutex_unlock(&cache_lock);
            return &subscription[index];
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void put_subscription_to_cache(struct NF_API_SUBSCRIPTION *subscription) {
    pthread_mutex_lock(&cache_lock);
    // Cache management logic goes here
    pthread_mutex_unlock(&cache_lock);
}

void manage_subscriptions(unsigned int num_subscriptions) {
    if (num_subscriptions > MAX_SUBSCRIPTIONS) {
        log_error("Requested number of subscriptions exceeds maximum allowed");
        return;
    }

    struct NF_API_SUBSCRIPTION *subscriptions = mmaped_memory(num_subscriptions * SUBSCRIPTION_SIZE);
    subscription_cache.memory = subscriptions;
    subscription_cache.size = num_subscriptions;

    for (unsigned int i = 0; i < num_subscriptions; ++i) {
        struct NF_API_SUBSCRIPTION *subscription = &subscriptions[i];
        subscription->USER_ID = rand() % 1000000 + 1; // Generate valid user IDs
        subscription->PLAN_ID = (i / 10) % 10 + 1; // Assign plan based on index
        subscription->ACTIVE_STATUS = current_time();
        subscription->PLAN_EXPIRY_DATE = current_time() + rand() % 31536000 + 2592000; // Generate future expiry dates within one year range
    }
}

void* worker(void *arg) {
    manage_subscriptions(*(unsigned int *)arg);
    return NULL;
}

int main() {
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR)) == -1) {
        log_error("Failed to create log file");
        return 1;
    }

    unsigned int num_workers = MAX_SUBSCRIPTIONS / 10 + 1;
    pthread_t workers[num_workers];
    unsigned int workloads[num_workers];

    for (unsigned int i = 0; i < num_workers; ++i) {
        workloads[i] = MAX_SUBSCRIPTIONS / num_workers;
        if ((i + 1) * workloads[i] >= MAX_SUBSCRIPTIONS) {
            workloads[i] += 1;
        }
    }

    for (unsigned int i = 0; i < num_workers; ++i) {
        pthread_create(&workers[i], NULL, worker, &workloads[i]);
    }

    for (unsigned int i = 0; i < num_workers; ++i) {
        pthread_join(workers[i], NULL);
    }

    return 0;
}
