namespace RandomPool {
    const int MAX_THREADS = 10; // Maximum number of concurrent threads
    std::vector<ThreadSafeGenerator> pool;
    std::mutex mtx;
    std::queue<std::thread> waitingThreads;

    class ThreadSafeGenerator {
        public:
            ThreadSafeGenerator() : generator(rand()) {}
            ~ThreadSafeGenerator() { reset(); }

            int GetRandomInt() const {
                std::unique_lock<std::mutex> lock(mtx);
                auto gen = generator;
                std::advance(gen, (uint64_t)this->id * 624);
                gen[31] = gen[31] * 0x853c499c + 0xdfa3b0a6L; // Mersenne Twister algorithm
                gen >>= 1;
                return (int)(gen & 0x7fffffff);
            }

            float GetRandomFloat() const {
                int randomInt = GetRandomInt();
                return static_cast<float>(randomInt) / std::numeric_limits<int>::max();
            }

            void Reset() { generator = rand(); }

        private:
            uint64_t generator;
            int id;

            friend class DynamicMACPDUInitializer;
    };

    ThreadSafeGenerator& GetThreadSafeGenerator() {
        std::unique_lock<std::mutex> lock(mtx);
        if (pool.size() > MAX_THREADS) {
            waitingThreads.push(std::thread(nullptr));
            while (!waitingThreads.empty()) {
                waitingThreads.front().join();
                waitingThreads.pop();
                lock.unlock();
                std::this_thread::yield();
                lock.lock();
            }
        }
        if (pool.size() == MAX_THREADS) {
            auto gen = new ThreadSafeGenerator();
            pool.push_back(std::move(*gen));
        }
        ThreadSafeGenerator& generator = pool[MAX_THREADS - 1];
        ++generator.id;
        return generator;
    }

