// Thread-safe implementation of a semaphore as a buffer with head and tail indices
void sem_init(sem_t *sem, int value) {
    sem->head = value;
    sem->tail = 0;
}

int sem_trywait(sem_t *sem) {
    if (atomic_compare_exchange_weak(&sem->head, &sem->tail, sem->tail + 1)) {
        return 1;
    }
    return 0;
}

void sem_post(sem_t *sem) {
    atomic_compare_exchange_weak(&sem->head, &sem->tail, sem->head - 1);
