    if (pdu == MAP_FAILED) {
        handle_failure("Memory allocation failed");
        return NULL;
    }
    sem_wait(&mutex);
    processed_structures++;
    sem_post(&mutex);

    pdu->header = mmap(NULL, sizeof(void*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pdu->header == MAP_FAILED) {
        handle_failure("Header allocation failed");
        munmap(pdu, sizeof(ENCODING_INDICATION_PDU_T));
        return NULL;
    }
    pdu->trailer = mmap(NULL, sizeof(void*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pdu->trailer == MAP_FAILED) {
        handle_failure("Trailer allocation failed");
        munmap(pdu->header, sizeof(void*));
        munmap(pdu, sizeof(ENCODING_INDICATION_PDU_T));
        return NULL;
    }

    pdu->payload = generate_payload(MIN_PAYLOAD_SIZE, MAX_PAYLOAD_SIZE);
    if (!pdu->payload) {
        handle_failure("Payload generation failed");
        munmap(pdu->header, sizeof(void*));
        munmap(pdu->trailer, sizeof(void*));
        munmap(pdu, sizeof(ENCODING_INDICATION_PDU_T));
        return NULL;
    }
    pdu->payload_len = (size_t)(MAX_PAYLOAD_SIZE * pow(PAYLOAD_GROWTH_FACTOR, ((double)processed_structures / MAX_STRUCTURES)));

    sem_wait(&mutex);
    successful_allocations++;
    if (processed_structures % 100 == 0 && log_detailed) {
        validate(pdu);
