    munmap(pdu, sizeof(ENCODING_INDICATION_PDU_T));
}

void run_task() {
    sem_init(&mutex, 0, 1);
    char* payload_range = getenv(ENV_PAYLOAD_RANGE);
    if (payload_range) {
        sscanf(payload_range, "%u-%u", &MIN_PAYLOAD_SIZE, &MAX_PAYLOAD_SIZE);
    }
    char* concurrency = getenv(ENV_CONCURRENCY);
    if (concurrency) {
        concurrent_limit = atoi(concurrency);
        if (concurrent_limit > MAX_STRUCTURES / 10) {
            concurrent_limit = MAX_STRUCTURES / 10;
        }
    }
    char* logging_verbosity = getenv(ENV_LOGGING_VERBOSITY);
    if (logging_verbosity && strcmp(logging_verbosity, "detailed") == 0) {
        log_detailed = true;
    }

    pthread_t threads[concurrent_limit];
    ENCODING_INDICATION_PDU_T* pdus[MAX_STRUCTURES];
    MEDIA_ENCODER_T encoder;
    DECODER_T decoder;

    // Initialize media encoding and decoding libraries here

    for (unsigned int i = 0; i < MAX_STRUCTURES && processed_structures < MAX_STRUCTURES; ++i) {
