    }

    for (unsigned int i = 0; i < concurrent_limit && processed_structures < MAX_STRUCTURES; ++i) {
        pthread_create(&threads[i], NULL, process_structures, pdus);
    }

    for (unsigned int i = 0; i < concurrent_limit; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Implementation of health check function here

    log_statistics();
}

void* process_structures(void* data) {
    ENCODING_INDICATION_PDU_T* pdus = data;
    DECODER_T decoder;
    for (unsigned int i = 0; i < MAX_STRUCTURES && processed_structures < MAX_STRUCTURES; ++i) {
        if (!pdus[i]) continue;
        ENCODING_INDICATION_PDU_T* pdu = pdus[i];
        sem_wait(&mutex);
        bool decode_success = decode_pdu(pdu, &decoder);
        sem_post(&mutex);
        if (decode_success) {
            // Implementation of post-processing function here
        }
        cleanup(pdu);
    }
    return NULL;
}
