['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    char id[33]; // Session ID (256 bits, SHA-256 digest length + null terminator)
    bool authenticated;
    int num_connections;
    pthread_mutex_t session_mutex;
} SessionInfo;

// List of session structures, managed with a doubly linked list for efficient insertion and removal.
typedef struct Node {
    SessionInfo session;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL; // The first node in the list

void hash_log(const char* id, FILE* file) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;

    // Initialize the context for SHA-256 calculation.
    SHA256_Init(&ctx);

    // Hash the input and store the result in the digest array.
    SHA256_Update(&ctx, id, strlen(id));
    SHA256_Final(digest, &ctx);

    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        fprintf(file, "%02x", digest[i]);
    }
    fprintf(file, "\n");
}

void session_add(SessionInfo* session) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node.");
        exit(EXIT_FAILURE);
    }

    memcpy(&new_node->session, session, sizeof(SessionInfo));
    pthread_mutex_init(&new_node->session.session_mutex, NULL);

    if (!head) {
        head = new_node;
        head->next = head;
        head->prev = head;
    } else {
        Node* last = head->prev;
        new_node->next = head;
        new_node->prev = last;

        last->next = new_node;
        head->prev = new_node;
    }
}

void session_remove(const char* id) {
    Node* current = head;

    while (current != head) {
        if (strcmp(current->session.id, id) == 0) {
            Node* next_node = current->next;
            Node* prev_node = current->prev;

            if (next_node == head) {
                head = prev_node;
                free(current);
            } else {
                prev_node->next = next_node;
                next_node->prev = prev_node;
                free(current);
            }

            return;
        }

        current = current->next;
    }
}

SessionInfo* session_get(const char* id) {
    Node* current = head;

    while (current != head) {
        if (strcmp(current->session.id, id) == 0) {
            return &current->session;
        }

        current = current->next;
    }

    return NULL;
}
