import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class StateLoader {
    private static final ConcurrentHashMap<String, MoSTState> LOADED_STATES = new ConcurrentHashMap<>();
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(10);

    public static MoSTState loadAndValidateStateObject(String fileName) {
        MoSTState state = LOADED_STATES.get(fileName);
        if (state != null) return state;

        Runnable task = () -> {
            try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(fileName))) {
                Object obj = in.readObject();
                if (obj instanceof MoSTState) {
                    MoSTState loadedState = (MoSTState) obj;
                    validateState(loadedState);
                    LOADED_STATES.putIfAbsent(fileName, loadedState);
                    return loadedState;
                }
            } catch (IOException | ClassNotFoundException e) {
                handleError(e);
            }
            return null;
        };

        state = EXECUTOR.submit(task).get();
        return state;
    }

    private static void validateState(MoSTState state) throws StateLoadException {
        // Perform integrity validation on the loaded state object
        if (!isValidState(state)) throw new StateLoadException("Invalid state");
    }

    private static boolean isValidState(MoSTState state) {
        // Implement your custom state validation logic here
        return true;
    }

    private static void handleError(Throwable e) {
        System.err.println("Error loading state: " + e.getMessage());
        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(fileName))) {
            in.close();
        } catch (IOException ignore) {}
    }
}
