    Character() : energy(MAX_ENERGY), systemLoadPercentage(0) {}

    void updateSystemLoad(int players, int attacksFrequency) {
        float load = (players + attacksFrequency) * SYSTEM_LOAD_FACTOR;
        if (load > 100)
            load = 100;
        systemLoadPercentage = static_cast<int>(load);
    }

    int regenerateEnergy() {
        float regenRate = ENERGY_REGEN_BASE / static_cast<float>(systemLoadPercentage);
        energy += static_cast<int>(regenRate);
        if (energy > MAX_ENERGY)
            energy = MAX_ENERGY;
        return energy;
    }

