        std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now();
        int attackIndex, remainingEnergy;
        float probability[3] = { 0.4f, 0.35f, 0.25f }; // bias towards less frequently used attacks
        float cumulativeProbability[3] = { 0.0f, 0.4f, 0.75f };
        int r = std::rand() % static_cast<int>(std::numeric_limits<float>::digits10);

        for (int i = 0; i < 3; ++i) {
            if (now - lastAttack[i] > std::chrono::milliseconds(attackCooldown[i])) {
                if (cumulativeProbability[i] <= static_cast<float>(r)) {
                    attackIndex = i;
                    break;
                }
                cumulativeProbability[i + 1] += probability[i];
            }
        }

        remainingEnergy = regenerateEnergy() - ATTACK_COSTS[attackIndex];

        std::cout << "Selected attack: " << attackIndex << ", Remaining energy: " << remainingEnergy << ", System load percentage: " << systemLoadPercentage << std::endl;

        lastAttack[attackIndex] = now;
        return attackIndex;
    }
private:
    std::map<int, int> ATTACK_COSTS = { { 1, ATTACK1_COST }, { 2, ATTACK2_COST }, { 3, ATTACK3_COST } };
};
