    int available;
    bool sourceAvailable = true;
    std::mutex mtx;
};

std::queue<Attack> cooldownQueue;
EnergyStatus energyStatus;
CURL* apiHandle = nullptr; // External API handle
bool networkConnected = true;

// Energy regeneration function with potential delays due to system overload
void regenerateEnergy() {
    std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate energy regeneration delay
    int regenAmount = std::min(5, energyStatus.available);
    {
        std::lock_guard<std::mutex> lock(energyStatus.mtx);
        energyStatus.available += regenAmount;
    }
}

// Function to select attack and handle external dependencies
Attack selectAttack() {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> distrib(0, 2);

    Attack* attacks[] = {&attacks[0], &attacks[1], &attacks[2]};
    int attackIndex;

    // Check for energy availability and source status
    std::lock_guard<std::mutex> lock(energyStatus.mtx);
    while (!energyStatus.sourceAvailable && !networkConnected) {
        std::this_thread::sleep_for(std::chrono::milliseconds(50)); // Simulate network recovery delay
        if (apiHandle) curl_easy_cleanup(apiHandle);
        apiHandle = callAPIForStatus();
    }

    int energyRequired = 0;
    for (auto attack : attacks) {
        energyRequired += attack->energyCost;
        if (energyRequired > energyStatus.available) break;
    }

    int remainingEnergy = energyStatus.available - energyRequired;

    if (!remainingEnergy) return nullptr; // No available energy, can't perform an action

    regenerateEnergy(); // Regenerate some energy before selecting the attack

    Attack selectedAttack(attacks[distrib(gen)]);

    std::lock_guard<std::mutex> lock(cooldownQueue.mtx);
    if (cooldownQueue.empty() || std::chrono::system_clock::now() > cooldownQueue.front().cooldownEnd) {
        cooldownQueue.push({selectedAttack->id, std::chrono::system_clock::now() + std::chrono::seconds(selectedAttack->duration), selectedAttack});
    } else {
        selectedAttack = cooldownQueue.front().attack; // Use the next available attack instead
    }

    return selectedAttack;
}

