import java.io.*;
import java.security.*;
import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileLoader {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileLoader.class);

    public MoSTState loadStateFromFile(Path file) throws IOException, ClassNotFoundException {
        try (MessageDigest messageDigest = MessageDigest.getInstance("SHA-256")) {
            byte[] fileDigest;

            // Previous digest value stored in the file
            String prevDigest = Files.readString(file).trim();
            if (prevDigest.isEmpty()) {
                throw new IllegalStateException("No previous digest found.");
            }

            byte[] fileBytes = Files.readAllBytes(file);
            messageDigest.update(fileBytes);
            fileDigest = messageDigest.digest();

            // Compare the calculated and stored digests.
            if (!Arrays.equals(Hex.decode(prevDigest), fileDigest)) {
                LOGGER.warn("File integrity has been compromised.");
                Files.deleteIfExists(file);
                return null;
            }
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file.toFile()))) {
            Object obj = ois.readObject();

            if (!(obj instanceof MoSTState)) {
                return null;
            }

            return (MoSTState) obj;
        } catch (ClassNotFoundException | IOException e) {
            throw new RuntimeException(e);
        }
    }
}
```
