import java.io.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.ArrayDeque;
import java.util.ConcurrentLinkedQueue;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Queue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import com.google.common.primitives.Booleans;
import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVParser;
import org.apache.commons.lang3.math.NumberUtils;

public class NfaApiIndications {
    private static final int MAX_PARSERS = 100;
    private static final int PARSER_POOL_THREADS = Runtime.getRuntime().availableProcessors() * 2;
    private static final int CPU_THRESHOLD = 75; // percentage

    private Map<String, NFAPI_CRC_INDICATION_PDU_T[]> userTransactions;
    private ExecutorService parserPool;
    private long totalTransactions;
    private double averageTransactionValue;

    public void initializeNfaApiIndications(String filePath) {
        userTransactions = new HashMap<>();
        parserPool = Executors.newFixedThreadPool(PARSER_POOL_THREADS);

        try (CSVParser csvParser = new CSVParser(Files.newBufferedReader(Paths.get(filePath)), CSVFormat.DEFAULT);) {
            int lineCount = 0;
            for (CSVRecord record : csvParser) {
                if (++lineCount == 1) continue; // skip header row
                if (!isValidRecord(record)) continue;

                String userId = record.get("user_id");
                NFAPI_CRC_INDICATION_PDU_T[] userTransactions = userTransications.computeIfAbsent(userId, k -> new NFAPI_CRC_INDICATION_PDU_T[10_000]);
                generateAndInitializeStructures(userTransactions);

                double transactionValue = NumberUtils.createDouble(record.get("transaction_value"));
                totalTransactions++;
                averageTransactionValue += transactionValue;
            }
        } catch (IOException e) {
            // Handle IO exceptions gracefully and log errors if necessary
        }

        this.averageTransactionValue /= totalTransactions;
    }

    private boolean isValidRecord(CSVRecord record) {
        return record.size() > 3 && NumberUtils.isCreatable(record.get("transaction_value"));
    }

    private void generateAndInitializeStructures(NFAPI_CRC_INDICATION_PDU_T[] userTransactions) {
        for (NFAPI_CRC_INDICATION_PDU_T structure : userTransactions) {
            structure.rxUEInformationTag = (byte) Math.round(Math.random() * 0xFF);
            structure.rnti = (short) Math.round(Math.random() * Short.MAX_VALUE);
            structure.crcIndicationRel8Tag = new CRC_INDICATION_REL8_TAG();
            structure.crcIndicationRel8Tag.crcflag = Booleans.fromBoolean((Math.random() < 0.5));
        }
    }

    private static class CRC_INDICATION_REL8_TAG {
        boolean crcflag;
    }

    private static NFAPI_CRC_INDICATION_PDU_T md5Hash(String input) {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("MD5");
            if (Objects.nonNull(input)) {
                md.update(input.getBytes());
            }
        } catch (Exception e) {
            // Handle exceptions and log errors if necessary
        }
        return md != null ? new NFAPI_CRC_INDICATION_PDU_T(md.digest()) : null;
    }

    // Thread-safe parser class for fuzzy matching user identifiers using Levenshtein distance
    private static class FuzzyParser implements Runnable {
        private final String userId;
        private final Queue<String> inputQueue;
        private final ArrayDeque<NFAPI_CRC_INDICATION_PDU_T[]> userTransactionsQueue;

        public FuzyParser(String userId, Queue<String> inputQueue, ArrayDeque<NFAPI_CRC_INDICATION_PDU_T[]> userTransactionsQueue) {
            this.userId = userId;
            this.inputQueue = inputQueue;
            this.userTransactionsQueue = userTransactionsQueue;
        }

        @Override
        public void run() {
            while (!inputQueue.isEmpty()) {
                String record = inputQueue.poll();
                String userIdFromRecord = record.get("user_id");
                if (LevenshteinDistance(userId, userIdFromRecord) <= 2) {
                    userTransactionsQueue.add(record.getNfaApiCrcIndications());
                }
            }
        }

        private int LevenshteinDistance(String text1, String text2) {
            if (Objects.isNull(text1) || Objects.isNull(text2)) return 0;

            int[] costs = new int[text2.length() + 1];

            for (int i = 0; i <= text2.length(); i++) {
                costs[i] = i;
            }

            for (int j = 0; j < text1.length(); j++) {
                costs[(int) text2.charAt(0)] = Math.min(costs[(int) text2.charAt(0)] + 1, costs[j + 1] + 1);

                for (int k = 1; k < text2.length(); k++) {
                    costs[k] = Math.min(costs[k], costs[k - 1] + 1);
                    costs[(int) text2.charAt(k)] = Math.min(costs[(int) text2.charAt(k)], costs[j] + (text1.charAt(j) != text2.charAt(k)) ? 1 : 0);
                }
            }

            return costs[text2.length()];
        }
    }

    // Method to perform fuzzy matching and aggregate transactions based on a specified threshold
    public Map<String, List<NFAPI_CRC_INDICATION_PDU_T>> getMatchedTransactions(String userId, double similarityThreshold) {
        ArrayDeque<NFAPI_CRC_INDICATION_PDU_T[]> userTransactionsQueue = new ArrayDeque<>();

        for (NFAPI_CRC_INDICATION_PDU_T[] userTransactions : userTransactions.values()) {
            userTransactionsQueue.add(userTransactions);
        }

        Queue<String> inputQueue = new ConcurrentLinkedQueue<>();
        inputQueue.addAll(userTransactions.keySet());

        parserPool.submit(new FuzzyParser(userId, inputQueue, userTransactionsQueue));

        List<NFAPI_CRC_INDICATION_PDU_T> matchedTransactions = userTransactionsQueue.stream()
            .flatMap(Arrays::stream)
            .filter(t -> LevenshteinDistance(userId, t.getUserId()) <= (int) (similarityThreshold * 2))
            .collect(Collectors.toList());

        return Collections.singletonMap(userId, matchedTransactions);
    }

    public void resetParserPool() {
        parserPool.shutdown();
        try {
            parserPool.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            // Handle exceptions and log errors if necessary
        }

        parserPool = Executors.newFixedThreadPool(PARSER_POOL_THREADS);
    }
}
