#include <stdlib.h>
#define MAX_SESSIONS 1000000
#define CHAR_SET "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

struct SessionInfo {
    char id[16];
    int authenticated;
    // ... (list of active connections and associated metadata)
};

struct SessionList {
    struct SessionInfo sessions[MAX_SESSIONS];
    pthread_mutex_t mutex;
    int num_sessions;
    char log_file[256];
};

void init_session_list(struct SessionList *list, const char *log_file) {
    strcpy(list->log_file, log_file);
    pthread_mutex_init(&list->mutex, NULL);
    list->num_sessions = 0;
}

void add_session(struct SessionList *list, const char *id, int authenticated) {
    if (strlen(id) != 16 || strspn(id, CHAR_SET) != strlen(id)) {
        return; // Invalid session ID
    }

    pthread_mutex_lock(&list->mutex);
    if (list->num_sessions < MAX_SESSIONS) {
        strcpy(list->sessions[list->num_sessions].id, id);
        list->sessions[list->num_sessions].authenticated = authenticated;
        list->num_sessions++;
    }
    pthread_mutex_unlock(&list->mutex);
}

void* hash_and_log(void *arg) {
    struct SessionList *list = arg;
    int i;

    while (true) {
        pthread_mutex_lock(&list->mutex);
        for (i = 0; i < list->num_sessions && !list->sessions[i].authenticated; ++i);

        if (i == list->num_sessions) {
            pthread_mutex_unlock(&list->mutex);
            usleep(1000); // Backoff
            continue;
        }

        char hash[65];
        SHA256((unsigned char*)list->sessions[i].id, 16, (unsigned char*)hash);

        int fd = open(list->log_file, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (fd < 0) {
            pthread_mutex_unlock(&list->mutex);
            usleep(1000 * pow(2, i % 4)); // Exponential backoff
            continue;
        }

        write(fd, hash, 64);
        close(fd);
        pthread_mutex_unlock(&list->mutex);
    }

    return NULL;
}
