    class ThreadSafeGenerator {
    private:
        static std::mutex mtx;
        static std::vector<ThreadSafeGenerator> pool;
        MersenneTwister engine;

    public:
        ThreadSafeGenerator() : engine(static_cast<unsigned long>(std::random_device{}()) ) {}
        ~ThreadSafeGenerator() = default;

        static ThreadSafeGenerator& getInstance() {
            std::unique_lock<std::mutex> lock(mtx);
            if (pool.empty()) {
                pool.reserve(100); // Reserve some memory for efficiency
                for(size_t i = 0; i < 100; ++i)
                    pool.emplace_back();
            }
            ThreadSafeGenerator& generator = pool[pool.size() - 1];
            pool.pop_back(); // Reuse instances as they are freed to conserve memory
            return generator;
        }

        int getInt(int min, int max) {
            return min + engine() % (max - min + 1);
