typedef struct {
    NFAPI_RX_FRAME_HEADER header;
    uint16_t pci;
    uint8_t srs_indication_tag;
    bool crc_check_flag; // randomly set to either true or false with 95% probability of true
} RX_FRAME_T;

typedef struct ListNode {
    RX_FRAME_T frame;
    struct ListNode *next;
} ListNode;

void log_allocation(const char* message) {
    // Replace this with your desired callback function that logs the given message
    printf("%s\n", message);
}

ListNode* populate_frames(size_t num_frames) {
    if (num_frames > 5000) return NULL;

    ListNode *head = NULL, *current = NULL;
    srand(time(NULL));

    for (size_t i = 0; i < num_frames; ++i) {
        RX_FRAME_T* frame = malloc(sizeof(RX_FRAME_T));
        if (!frame) return NULL;

        memset(frame, 0, sizeof(RX_FRAME_T));
        frame->crc_check_flag = (rand() < RAND_MAX * 5 / 100);

        ListNode* node = malloc(sizeof(ListNode));
        if (!node) {
            free(frame);
            return NULL;
        }

        node->frame = *frame;
        node->next = NULL;

        if (!head) {
            head = current = node;
        } else {
            current->next = node;
            current = node;
        }
    }

    return head;
}

void serialize(const char* filename, ListNode* list) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    size_t num_frames = 0;
    ListNode* current = list;
    while (current) {
        ++num_frames;
        current = current->next;
    }

    fwrite(&num_frames, sizeof(size_t), 1, file);
    current = list;
    while (current) {
        fwrite(&current->frame, sizeof(RX_FRAME_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserialize(const char* filename, ListNode** list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t num_frames;
    fread(&num_frames, sizeof(size_t), 1, file);

    *list = NULL;
    ListNode* current = NULL;
    while (num_frames--) {
        RX_FRAME_T frame;
        fread(&frame, sizeof(RX_FRAME_T), 1, file);

        ListNode* node = malloc(sizeof(ListNode));
        if (!node) break;

        node->frame = frame;
        node->next = NULL;

        if (!current) {
            *list = current = node;
        } else {
            current->next = node;
            current = node;
        }
    }

    fclose(file);
    log_allocation("Deserialized frames successfully.");
}
