```cpp
#include <random>
#include <cmath>

namespace RandomPool {

ThreadSafeGenerator::ThreadSafeGenerator()
    : rng((std::random_device())()) {
    if (pool.size() >= MAX_THREADS) {
        threads.push(std::thread([]{ while(true){ ThreadSafeGenerator::GetInstance().NextInt(); } });
    }
}

ThreadSafeGenerator::~ThreadSafeGenerator() {
    std::scoped_lock lock(generatorMutex);
    for (auto& gen : pool) {
        if (&gen != this)
            gen.rng.~mt19937();
    }
}

int ThreadSafeGenerator::NextInt() {
    std::uniform_int_distribution<> dist(0, INT32_MAX);
    return dist(rng);
}

float ThreadSafeGenerator::NextFloat() {
    std::uniform_real_distribution<> dist(0.0f, 1.0f);
    return dist(rng);
}

void ThreadSafeGenerator::ResetAll() {
    std::scoped_lock lock(generatorMutex);
    for (auto& gen : pool) {
        gen.rng.discard(INT32_MAX * 100);
    }
}

ThreadSafeGenerator& ThreadSafeGenerator::GetInstance() {
    static ThreadSafeGenerator instance;
    std::scoped_lock lock(mtx);
    if (pool.size() >= MAX_THREADS && !threads.empty()) {
        threads.front().join();
        threads.pop();
    }
    return instance;
}

DynamicMACPDUInitializer::DynamicMACPDUInitializer(int min, int max)
    : min_(min), max_(max) {}

int DynamicMACPDUInitializer::GetRandomInt() {
    if (min_ > max_)
        std::swap(min_, max_);
    return static_cast<int>(std::uniform_real_distribution<>(min_, max_ + 1.0f)(generator));
}

float DynamicMACPDUInitializer::GetRandomFloat() {
    if (min_ > max_)
        std::swap(min_, max_);
    return static_cast<float>(std::uniform_real_distribution<>(min_, max_ + 1.0f)(generator));
}

const std::string DynamicMACPDUInitializer::ToString() const {
    return "DynamicMACPDUInitializer[" + std::to_string(min_) + ", " + std::to_string(max_) + "]";
}

void DynamicMACPDUInitializer::SetRange(int newMin, int newMax) {
    if (newMin > newMax)
        std::swap(newMin, newMax);
    min_ = newMin;
    max_ = newMax;
}

