    printf("[STATS] Cache hit rate: %f\n", (double)num_cache_hits / (num_cache_misses + num_cache_hits));
}

struct cache_node* find_context(uint64_t UE_ID) {
    struct cache_node *node = cache_head;
    while (node != NULL) {
        if (node->context.UE_ID == UE_ID) {
            return node;
        }
        node = node->next;
    }
    return NULL;
}

void inc_cache_misses() {
    static int misses = 0;
    misses++;
    if (misses % LOG_INTERVAL == 0) {
        log_stats();
    }
}

void inc_cache_hits() {
    static int hits = 0;
    hits++;
    if (hits % LOG_INTERVAL == 0) {
        log_stats();
    }
}

NF_API_UE_CONTEXT* get_context(uint64_t UE_ID) {
    struct cache_node *node = find_context(UE_ID);
    if (node != NULL) {
        inc_cache_hits();
        return &node->context;
    }
    inc_cache_misses();
    return NULL;
}

void put_context(NF_API_UE_CONTEXT context) {
    struct cache_node *node = (struct cache_node *) malloc(sizeof(*node));
    if (node == NULL) {
        log_error("Failed to allocate cache node");
        return;
    }
    memcpy(&node->context, &context, sizeof(context));
    node->next = cache_head;
    cache_head = node;
}

void* create_and_allocate_contexts(void* arg) {
    int index = *(int*)arg;
    for (size_t i = index; i < MAX_CONTEXTS && num_allocated_contexts < MAX_CONTEXTS; i += CACHE_SIZE) {
        NF_API_UE_CONTEXT context;
        init_context(&context);
        context.UE_ID = i + 1;
        context.RNTI = rand() % 65535;
        context.ServingCellID = rand() % 65535;
        context.RB_ALLOC_FLAG = (rand() % 10) < 8 ? true : false;

        NF_API_UE_CONTEXT* allocated_context = get_context(context.UE_ID);
        if (allocated_context == NULL) {
            pthread_mutex_lock(&list_lock);
            if (num_allocated_contexts < MAX_CONTEXTS) {
                allocated_context = get_context(context.UE_ID);
                if (allocated_context == NULL) {
                    memcpy(allocated_context, &context, sizeof(context));
                    num_allocated_contexts++;
                    pthread_cond_signal(&list_notempty);
                }
            }
            pthread_mutex_unlock(&list_lock);
        }
        if (allocated_context != NULL) {
            put_context(context);
        }
    }
    return NULL;
}

void manage_contexts() {
    int thread_count = MAX_CONTEXTS / CACHE_SIZE + (MAX_CONTEXTS % CACHE_SIZE != 0 ? 1 : 0);
    pthread_t threads[thread_count];
    for (int i = 0; i < thread_count; ++i) {
        struct thread_data* data = malloc(sizeof(*data));
        data->index = i * CACHE_SIZE;
        if (pthread_create(&threads[i], NULL, create_and_allocate_contexts, data)) {
            log_error("Failed to create thread");
        }
    }
    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}
