class UEContext {
public:
    int UE_ID;
    int RNTI;
    int ServingCellID;
    bool RB_ALLOC_FLAG;

    // Default constructor initializes all members to zero
    UEContext() : UE_ID(0), RNTI(0), ServingCellID(0), RB_ALLOC_FLAG(false) {}
};

std::mutex contexts_mutex;
std::deque<UEContext> context_pool;
std::unordered_map<int, UEContext*> cache;

const int MAX_CONTEXTS = 10000;
double cache_hit_ratio_target = 0.95; // Target cache hit ratio
int num_successfully_allocated = 0;

void generate_contexts(int num) {
    std::default_random_engine gen;
    std::uniform_int_distribution<> dist(0, MAX_CONTEXTS - 1);

    for (int i = 0; i < num; ++i) {
        UEContext* context = &context_pool.front();
        context->UE_ID = i;
        context->RNTI = i + 1;
        context->ServingCellID = i * 3 % MAX_CONTEXTS;
        context->RB_ALLOC_FLAG = gen() < 0.8; // 80% chance of allocation

        if (context_pool.size() == 1) {
            context_pool.pop_back();
        }

        std::lock_guard<std::mutex> lock(contexts_mutex);
        auto it = cache.find(context->UE_ID);
        if (it != cache.end()) {
            num_successfully_allocated++;
            it->second = context;
        } else {
            cache[context->UE_ID] = context;
        }
    }
}

UEContext* get_or_create_context(int UE_ID) {
    std::lock_guard<std::mutex> lock(contexts_mutex);
    auto it = cache.find(UE_ID);
    if (it != cache.end()) {
        return it->second;
    }

    if (context_pool.empty()) {
        generate_contexts(MAX_CONTEXTS - context_pool.size());
    }

    UEContext* context = &context_pool.front();
    context->UE_ID = UE_ID;
    context->RNTI = UE_ID + 1;
    context->ServingCellID = UE_ID * 3 % MAX_CONTEXTS;
    context->RB_ALLOC_FLAG = random() < RAND_MAX / 5; // 20% chance of allocation in get_or_create_context

    if (context_pool.size() == 1) {
        context_pool.pop_back();
    }

    it = cache.find(UE_ID);
    if (it != cache.end()) {
        num_successfully_allocated++;
        it->second = context;
    } else {
        cache[UE_ID] = context;
    }

    return context;
}
