struct ConfigProfile {
    int freqBand;
    int bandwidth;
    char *modulationScheme;
    int modulationOrder;
    double bandwidthEfficiency;
    int uniqueId;
    // ... other fields ...
};

typedef struct ConfigProfile ConfigProfile;

// Mutex and Semaphore for thread safety
pthread_mutex_t configProfilesMutex = PTHREAD_MUTEX_INITIALIZER;
sem_t numConfigProfilesAvailable;

int allocateConfigProfiles(int N) {
    if (N <= 0 || N > MAX_CONFIGURATIONS) {
        return -1; // Invalid or out of range value for N
    }

    ConfigProfile *configProfiles = malloc(sizeof(ConfigProfile) * N);
    if (!configProfiles) {
        return -2; // Failed to allocate memory for configuration profiles
    }

    sem_init(&numConfigProfilesAvailable, 0, N);

    int allocatedConfigs = 0;
    for (int i = 0; i < N; ++i) {
        memset(&configProfiles[i], 0, sizeof(ConfigProfile));
        configProfiles[i].uniqueId = i + 1;
        allocatedConfigs++;
    }

    return allocatedConfigs;
}

void updateConfigProfile(int index, ConfigProfile updates) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&configProfilesMutex);

    sem_wait(&numConfigProfilesAvailable); // Decrease the count of available profiles

    if (index > 0 && index <= sem_value(&numConfigProfilesAvailable)) {
        ConfigProfile *profile = &configProfiles[index - 1];

        profile->freqBand = updates.freqBand;
        profile->bandwidth = updates.bandwidth;
        free(profile->modulationScheme); // Free old modulation scheme memory before updating
        profile->modulationScheme = strdup(updates.modulationScheme);
        profile->modulationOrder = updates.modulationOrder;
        profile->bandwidthEfficiency = updates.bandwidthEfficiency;
    }

    // Release the mutex after updating
    pthread_mutex_unlock(&configProfilesMutex);
}

void deallocateConfigProfiles() {
    ConfigProfile *configProfiles = NULL;

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&configProfilesMutex);

    sem_destroy(&numConfigProfilesAvailable);
    configProfiles = malloc(sizeof(ConfigProfile) * sem_value(&numConfigProfilesAvailable));
    memcpy(configProfiles, configProfiles, sizeof(ConfigProfile) * sem_value(&numConfigProfilesAvailable));

    for (int i = 0; i < sem_value(&numConfigProfilesAvailable); ++i) {
        free(configProfiles[i].modulationScheme);
        free(configProfiles + i);
    }

    free(configProfiles);

    // Release the mutex after deallocating
    pthread_mutex_unlock(&configProfilesMutex);
}

// Function to retrieve the list of successfully allocated configuration profiles
ConfigProfile *getAllocatedConfigProfiles() {
    ConfigProfile *configProfiles = NULL;

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&configProfilesMutex);

    configProfiles = malloc(sizeof(ConfigProfile) * sem_value(&numConfigProfilesAvailable));
    memcpy(configProfiles, configProfiles, sizeof(ConfigProfile) * sem_value(&numConfigProfilesAvailable));

    // Release the mutex after retrieving
    pthread_mutex_unlock(&configProfilesMutex);

    return configProfiles;
}
