```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <stdexcept>
#include <cstdlib>
#include <algorithm>

class NetworkConfig {
public:
    unsigned int id;
    std::string frequency_band;
    std::string bandwidth;
    std::string modulation_scheme;
    int modulation_order;
    double bandwidth_efficiency;
};

std::mutex g_configs_mutex;
std::vector<std::shared_ptr<NetworkConfig>> g_configs;
unsigned int g_total_allocated = 0;

int init_network_configs(size_t N) {
    if (N == 0 || N > std::numeric_limits<size_t>::max() / sizeof(NetworkConfig)) {
        std::cerr << "Invalid number of configurations provided." << std::endl;
        return -1;
    }

    g_configs.resize(N);

    for (auto& config : g_configs) {
        config = std::make_shared<NetworkConfig>();
        // Set default values here, e.g., config->id = 0; ...
        if (!config) {
            std::cerr << "Failed to allocate configuration profile." << std::endl;
            clear_network_configs();
            return -1;
        }
    }

    g_total_allocated = N;
    return 0;
}

void clear_network_configs() {
    std::for_each(g_configs.begin(), g_configs.end(), [](auto& config) { config.reset(); });
    g_configs.clear();
    g_total_allocated = 0;
}

int update_network_config(size_t id, const NetworkConfig& new_config) {
    std::unique_lock<std::mutex> lock(g_configs_mutex);

    auto it = std::find_if(g_configs.begin(), g_configs.end(),
                           [&](const auto& config) { return config->id == id; });

    if (it == g_configs.end()) {
        lock.unlock();
        std::cerr << "Configuration ID not found." << std::endl;
        return -1;
    }

    (*it)->frequency_band = new_config.frequency_band;
    (*it)->bandwidth = new_config.bandwidth;
    (*it)->modulation_scheme = new_config->modulation_scheme;
    (*it)->modulation_order = new_config.modulation_order;
    (*it)->bandwidth_efficiency = new_config.bandwidth_efficiency;

    return 0;
}

const std::vector<NetworkConfig*>& get_network_configs() {
    std::unique_lock<std::mutex> lock(g_configs_mutex);
    return g_configs;
}
```

