typedef struct TCP_CONNECTION_RECORD {
    int connection_id;
    sockaddr_in remote_address;
    sockaddr_in local_address;
    enum { ESTABLISHED, TIME_WAIT, CLOSE_WAIT } status;
    struct TCP_CONNECTION_RECORD *next;
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD* create_connection_record(int connection_id,
                                               const sockaddr_in* remote_address,
                                               const sockaddr_in* local_address,
                                               enum state status) {
    TCP_CONNECTION_RECORD *new_node = malloc(sizeof(TCP_CONNECTION_RECORD));
    if (!new_node) return NULL;

    memcpy(&new_node->remote_address, remote_address, sizeof(sockaddr_in));
    memcpy(&new_node->local_address, local_address, sizeof(sockaddr_in));
    new_node->connection_id = connection_id;
    new_node->status = status;
    new_node->next = NULL;

    return new_node;
}

void append_connection(TCP_CONNECTION_RECORD **head, TCP_CONNECTION_RECORD *new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }

    TCP_CONNECTION_RECORD *current = *head;
    while (current->next) current = current->next;

    current->next = new_node;
}

