    SHA256_Update(&sha256_ctx, data, len);
}

void sha256_final(unsigned char* result) {
    SHA256_Final(hash, &sha256_ctx);
    memcpy(result, hash, SHA256_DIGEST_LENGTH);
}

TCP_CONNECTION_RECORD* create_connection_list() {
    TCP_CONNECTION_RECORD *head = NULL;

