AES_KEY secureEncryptDecrypt(int operation, const std::initializer_list<std::string>& args) {
    log4cpp::Category& logger = log4cpp::Category::getRoot();

    std::vector<unsigned char> data;
    for (const auto& arg : args) {
        if (!arg.empty()) {
            data.insert(data.end(), trimWhitespace(arg).begin(), trimWhitespace(arg).end());
        }
    }

    if (data.size() > MAX_STRING_LENGTH) {
        data.resize(MAX_STRING_LENGTH);
    }

    std::vector<unsigned char> hashedData = md5(data);

    // Derive encryption key securely using PBKDF2
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
    int keyLength;
    PBKDF2_Hmac_EVP( operation == ENCRYPT ? EVP_sha256() : EVP_sha256(), data.size(), salt, PBKDF2_ITERATIONS, hashedData.data(), key, sizeof(key), &keyLength);
    RAND_bytes(iv, AES_BLOCK_SIZE);

    AES_KEY ctx;
    AES_set_encrypt_key(key, keyLength, &ctx);
    AES_cbc_encrypt(NULL, data.data(), data.size(), &ctx, iv, operation == ENCRYPT ? AES_ENCRYPT : AES_DECRYPT);

    logOperation(logger, (operation == ENCRYPT ? "Encrypt" : "Decrypt"), key, iv, data);

    if (operation == EXPORT) {
        return exportKeyIV(ctx);
    }

    return std::vector<unsigned char>(data.begin(), data.end());
}
