    let mut hasher = Sha256::new();
    let mut file_size = 0;
    const CHUNK_SIZE: usize = 1048576; // 1MB

    tokio::task::spawn(async move {
        while let Some(chunk) = file.by_ref().take(CHUNK_SIZE).await {
            hasher.update(&chunk);
            file_size += chunk.len() as u64;
