#include <iostream>
#include <fstream>
#include <vector>
#include <deque>
#include <thread>
#include <mutex>
#include <atomic>
#include <algorithm>
#include <numeric>
#include <sstream>
#include <execution>
#include <parallel/algorithm>
#include <sys/resource.h>
#include <cmath>
#include <boost/asio/connect.hpp>
#include <boost/beast/http.hpp>
#include "gsl/gsl_stats.h"
#include "boost/circular_buffer.hpp"
#include "boost/lockfree/queue.hpp"

std::mutex mtx;
std::atomic<int> num_threads(std::thread::hardware_concurrency());
std::deque<std::string> inputQueue(num_threads * 2);
boost::lockfree::queue<std::vector<double>> outputQueue;
std::vector<std::thread> workerThreads;

double sum, avg, stddev;
boost::circular_buffer<double> cb(10'000'000); // buffer for 10GB of data

void worker() {
    while (true) {
        auto record = inputQueue.pop_front();
        if (record.empty()) break;

        std::istringstream iss(record);
        std::vector<double> fields(std::execution::par, std::istream_iterator<double>(iss), {});

        // Calculate sum of the last five fields
        std::copy_n(std::end(fields) - 5, 5, std::back_inserter(sum));
        // Calculate average of the first ten fields
        auto it = std::next(std::begin(fields), 10);
        avg = std::accumulate(std::begin(it), it, 0.0) / 10.0;
        // Calculate standard deviation of all fields
        gsl_stats_double sumsq = gsl_stats_double_variance(fields.data(), static_cast<size_t>(fields.size()));
        stddev = sqrt(sumsq);
    }
}

void monitorMemory() {
    rlimit memLimit;
    if (getrlimit(RLIMIT_DATA, &memLimit))
        throw std::runtime_error("Failed to get memory limit");

    double currentUsage = 0.0;
    while (true) {
        currentUsage += cb.capacity() + outputQueue.size() * sizeof(std::vector<double>);
        if (currentUsage > memLimit.rlim_cur * 0.6) {
            num_threads--;
            std::cout << "Reducing number of worker threads to " << num_threads << std::endl;
        }
        std::this_thread::sleep_for(std::chrono::seconds(10));
    }
}

int main() {
    // Load file and process records concurrently
    std::ifstream inputFile("large_text_file.txt");
    if (!inputFile) {
        std::cerr << "Failed to open input file" << std::endl;
        return 1;
    }

    // Read and queue records for worker threads
    std::string record;
    while (std::getline(inputFile, record)) {
        mtx.lock();
        inputQueue.push_back(record);
        mtx.unlock();
    }

    for (int i = 0; i < num_threads; ++i) {
        workerThreads.emplace_back(worker);
    }

    // Monitor memory usage and adjust the number of worker threads accordingly
    std::thread memMonitor(monitorMemory);

    // Process any remaining records in the queue after all worker threads have finished
    for (auto& thread : workerThreads) {
        thread.join();
    }

    // Asynchronously process and queue each record for downstream components
    boost::asio::io_context ioContext;
    boost::beast::http::async_server<boost::beast::tcp_STREAM> server(ioContext);
    server.set_option(boost::asio::socket_base::accept_connector(ioContext),
                      boost::beast::bind_front_handler(&handleRequest, std::ref(outputQueue)));
    server.listen(8080);
    ioContext.run();

    return 0;
}
```

