    int socket = socket(AF_INET, SOCK_DGRAM, 0);
    char buf[IF_NAMESIZE];
    char *iface_name;

    getifaddrs(&ifaddr, NULL);
    int num_interfaces = 0;

    if (!ifaddr) {
        perror("getifaddrs");
        exit(EXIT_FAILURE);
    }

    for (ifa = ifaddr; ifa != NULL; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == NULL || ifa->ifa_addr->sa_family != AF_INET)
            continue;
        strncpy(buf, ifa->ifa_name, IF_NAMESIZE);
        buf[IF_NAMESIZE-1] = '\0'; // ensure null termination
        iface_name = strdup(buf);
