    struct timespec time_diff;

    double total_rx_bytes = 0.0;
    double total_tx_bytes = 0.0;
    uint64_t total_rx_packets = 0;
    uint64_t total_tx_packets = 0;

    clock_gettime(CLOCK_MONOTONIC, &last_sample);

    for (int index = 0; index < num_interfaces; ++index) {
        interfaces[index].packet_loss = 0.0;
        interfaces[index].throughput = 0.0;
        interfaces[index].latency = 0.0;
    }

    while (num_interfaces > 0) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        time_diff.tv_sec = current_time - last_sample;
        time_diff.tv_nsec = (current_time - last_sample) * 1e9;

        double sample_interval = time_diff.tv_sec + time_diff.tv_nsec / 1e9;
        double rx_bytes = 0.0;
        double tx_bytes = 0.0;
        uint64_t rx_packets = 0;
        uint64_t tx_packets = 0;

        for (int index = 0; index < num_interfaces && sample_interval > 0; ++index) {
            // Simulate traffic data here
            rx_bytes += rand() % 100 + 50;
            tx_bytes += rx_bytes * 2.0;
            rx_packets++;
            tx_packets++;
            sample_interval -= 0.000001; // Adjust the sample interval based on the desired granularity
        }

        total_rx_bytes += rx_bytes;
        total_tx_bytes += tx_bytes;
        total_rx_packets += rx_packets;
        total_tx_packets += tx_packets;

        for (int index = 0; index < num_interfaces && sample_interval > 0; ++index) {
            interfaces[index].rx_bytes += rx_bytes;
            interfaces[index].tx_bytes += tx_bytes;
            interfaces[index].rx_packets += rx_packets;
            interfaces[index].tx_packets += tx_packets;
            sample_interval -= 0.000001; // Adjust the sample interval based on the desired granularity
        }

        last_sample = current_time;
        num_interfaces--;
    }

    for (int index = 0; index < num_interfaces; ++index) {
        interfaces[index].throughput = (interfaces[index].tx_bytes - total_tx_bytes / num_interfaces) / sample_interval * 8.0 / (1024.0 * 1024.0); // Convert bytes to Mbps
        interfaces[index].latency = sqrt(sample_interval * DBL_EPSILON); // Approximate latency based on the sample interval
        interfaces[index].packet_loss = (1 - interfaces[index].tx_packets / total_rx_packets) * 100.0;
    }
}
