public:
    CustomRandomGenerator(int min, int max) : _minValue(min), _maxValue(max) {}

    int GetRandomInt() const {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(_minValue, _maxValue - 1);
        return dis(gen);
    }

    float GetRandomFloat() const {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(_minValue, _maxValue);
        return dis(gen);
    }

    const std::string ToString() const {
        std::ostringstream os;
        if (std::is_integral<decltype(_minValue)>::value) {
            os << '[' << _minValue << ', ' << _maxValue << ')';
        } else {
            os << '[' << _minValue << ', ' << _maxValue << ']';
        }
        return os.str();
    }

    void SetRange(int min, int max) {
        if (min >= max) {
            throw std::invalid_argument("New range is not valid.");
        }
        _minValue = min;
        _maxValue = max;
    }

    static CustomRandomGenerator* LoadMoSTStateFromFile(std::string filePath) {
        std::ifstream inputFile(filePath, std::ios::binary);
        if (!inputFile.is_open()) {
            throw std::runtime_error("Failed to open or access the specified file.");
        }
        std::unique_ptr<std::istream> inputStream(new std::ifstream(filePath, std::ios::binary));
        try {
            inputStream->exync(); // Ensure the ObjectInputStream is synchronized
            auto state = dynamic_cast<CustomRandomGenerator*>(std::make_unique<std::object_input_archive>(*inputStream).deserialize(nullptr));
            if (state) return state.release();
        } catch (const std::exception& e) {
            std::cerr << "Failed to load state from file: " << e.what() << std::endl;
        }
        inputFile.close();
        return nullptr;
    }

private:
    int _minValue, _maxValue;
};

// Function for initializing an array of NFAPI_CRC_INDICATION_PDU_T structures.
void InitializeStructures(int N, const CustomRandomGenerator& randomGenerator) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> structures;
    std::mutex mtx;

    auto allocateAndFill = [&](NFAPI_CRC_INDICATION_PDU_T* structure) {
        structure->RX_UE_INFORMATION_TAG = randomGenerator.GetRandomInt() % MAX_TAG_VALUE + MIN_TAG_VALUE;
        structure->RNTI = randomGenerator.GetRandomInt() % MAX_RNTI_VALUE + MIN_RNTI_VALUE;
        structure->CRCFLAG = (randomGenerator.GetRandomInt() & 1) == 0 ? true : false;
    };

    auto allocateAndLock = [&](NFAPI_CRC_INDICATION_PDU_T* structure, size_t index) {
        std::unique_lock<std::mutex> lock(mtx);
        if (index >= structures.size()) {
            structures.resize(index + 1);
            allocateAndFill(&structures[index]);
        } else {
            allocateAndFill(&structures[index]);
        }
        lock.unlock();
    };

    std::vector<std::future<void>> tasks;
    for (int i = 0; i < N; ++i) {
        tasks.emplace_back(std::async(allocateAndLock, std::addressof(structures[i]), i));
    }

    for (auto& task : tasks) {
        task.wait();
    }
}
