typedef struct {
    int64_t timestamp;
    int id;
    double weight;
} Transaction;

typedef struct {
    int64_t packet_loss;
    int64_t throughput;
    int64_t latency;
    size_t capacity;
    size_t current_count;
    Transaction* data;
} InterfaceStatistics;

void init_interface(InterfaceStatistics* stats, size_t capacity) {
    stats->capacity = capacity;
    stats->packet_loss = 0;
    stats->throughput = 0;
    stats->latency = 0;
    stats->current_count = 0;
    stats->data = malloc(stats->capacity * sizeof(Transaction));
}

int64_t calculate_metrics(InterfaceStatistics* stats, double current_time) {
    double elapsed_time = (double)(current_time - stats->data[stats->current_count - 1].timestamp);
    stats->throughput += (elapsed_time * stats->current_count / CLOCKS_PER_SEC);
    stats->latency = (stats->latency * stats->current_count + elapsed_time) / (stats->current_count + 1);
    return stats->packet_loss;
}

int filter_transactions(InterfaceStatistics* stats, double current_time, int age_threshold, int transaction_threshold, double weighted_sum_threshold) {
    double max_weighted_sum = 0.0;
    int max_transaction_id = -1;
    for (size_t i = stats->current_count - 1; i >= 0 && stats->current_count > transaction_threshold; --i) {
        double elapsed_time = (double)(current_time - stats->data[i].timestamp);
        if (elapsed_time < age_threshold) {
            double weighted_sum = stats->data[i].weight + (elapsed_time * stats->throughput / CLOCKS_PER_SEC);
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_transaction_id = stats->data[i].id;
            }
        }
    }
    return max_transaction_id;
}

void log_error(const char* message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

void collect_statistics(InterfaceStatistics* stats, double current_time) {
    if (stats->current_count >= stats->capacity) {
        log_error("Overflow in the interface statistics buffer");
        return;
    }

    int packet_loss = filter_transactions(stats, current_time, 3.0, 3, 10.0);
    int64_t metrics = calculate_metrics(stats, current_time);
    stats->packet_loss += packet_loss;
}
