};

std::mutex CustomRandomGenerator::_rngMutex;

void NFAPI_CRC_INDICATION_PDU_T::init(int n, const CustomRandomGenerator& rng) {
    if (n <= 0) {
        throw std::invalid_argument("Invalid number of structures");
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;
    pdus.reserve(n);

    std::unique_ptr<std::uniform_int_distribution<>> distRXUEIT(new std::uniform_int_distribution<>{1, RX_UE_INFORMATION_TAG_MAX});
    std::unique_ptr<std::uniform_int_distribution<>> distRNTI(new std::uniform_int_distribution<>{1, RNTI_MAX});

    std::unique_lock<std::mutex> rngLock(_rngMutex);
    rng._rng.seed(rng._seed); // seed the random number generator with a fixed value for reproducibility

    std::uniform_int_distribution<> distCRCFLAG; // generate a single instance of the distribution, no need to manage it across calls since it's not cached

    for (int i = 0; i < n; ++i) {
        int rxUeInformationTag = distRXUEIT->operator()(rng._rng);
        int rnti = distRNTI->operator()(rng._rng);

        if (rxUeInformationTag <= 0 || rxUeInformationTag > RX_UE_INFORMATION_TAG_MAX ||
            rnti <= 0 || rnti > RNTI_MAX) {
            std::cerr << "Invalid UE Information Tag or RNTI: " << rxUeInformationTag << ", " << rnti << std::endl;
            continue;
        }

        pdus.emplace_back(rxUeInformationTag, rnti, CRCFLAG ? rng._rng() : 0); // use the non-cached distribution for CRCFLAG to avoid caching issues
    }

    _pdus = std::move(pdus);
}
