NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&(pdu->lock), &attr);

    pdu->rx_ue_info = (RX_UE_INFORMATION_TAG) { .tag = RX_UE_INFORMATION_TAG__value };
    pdu->rnti = rand();
    pdu->crc_indication.tag = CRC_INDICATION_REL8_TAG__value;
    pdu->crc_indication.crcflag = (rand() % 2) == 0 ? 1 : 0;

    return pdu;
}

void handle_pdu(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t *pdus_count, size_t max_pdus) {
    if (*pdus_count >= max_pdus) {
        printf("Warning: Maximum number of PDUs reached. Dropping new PDUs.\n");
        return;
    }

