typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct priority_queue {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T **data;
    size_t capacity;
    size_t head, tail;
};

void push(struct priority_queue *q, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&q->lock);
    if (++q->tail == q->capacity) q->tail = 0;
    if (q->head != q->tail) {
        q->data[q->head] = pdu;
        ++q->head;
    } else {
        size_t i;
        for (i = q->capacity - 1; i != q->tail; --i) q->data[i] = q->data[i + 1];
        q->data[q->tail] = pdu;
    }
    pthread_mutex_unlock(&q->lock);
}

NFAPI_CRC_INDICATION_PDU_T *pop(struct priority_queue *q) {
    pthread_mutex_lock(&q->lock);
    NFAPI_CRC_INDICATION_PDU_T *res;
    if (q->head != q->tail) {
        res = q->data[q->head];
        if (++q->head == q->capacity) q->head = 0;
    } else
        res = NULL;
    pthread_mutex_unlock(&q->lock);
    return res;
}

struct priority_queue* create_priority_queue(size_t capacity) {
    struct priority_queue *q = malloc(sizeof(*q));
    q->capacity = capacity;
    q->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void free_priority_queue(struct priority_queue *q) {
    free(q->data);
    pthread_mutex_destroy(&q->lock);
    free(q);
}

void crc_indication_generator(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t count, struct priority_queue *pq) {
    for (size_t i = 0; i < count; ++i) {
        pdus[i]->rx_ue_information.tag = RX_UE_INFORMATION_TAG_VALUE;
        pdus[i]->rnti = rand() % UINT16_MAX;
        pdus[i]->crc_indication.tag = CRC_INDICATION_REL8_TAG_VALUE;
        pdus[i]->crc_indication.crcflag = (rand() % 2) == 0 ? 1 : 0;
        push(pq, pdus[i]);
    }
}

void process_ue_data(struct priority_queue *pq, void (*process)(NFAPI_CRC_INDICATION_PDU_T*)) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = pop(pq);
        if (!pdu) break;
        process(pdu);
    }
}

void log_metrics(const char *file, const struct timespec *start, const struct timespec *end, double data_rate, double latency) {
    FILE *f = fopen(file, "a");
    if (!f) return;
    fprintf(f, "[%lu.%06lu] Data rate: %.2f Mbps, Latency: %.3fs\n",
            (unsigned long)end->tv_sec, (unsigned long)(end->tv_nsec / 1_000_000), data_rate * 8 / 1e6, latency);
    fclose(f);
}

void process_and_log(struct priority_queue *pq, void (*process)(NFAPI_CRC_INDICATION_PDU_T*), const char *file) {
