    double data_rate = (double)(end.tv_sec - start.tv_sec) * 1e6 + (double)(end.tv_nsec - start.tv_nsec) / 1_000_000;
    double latency = (end.tv_sec - start.tv_sec + (end.tv_nsec - start.tv_nsec) / 1_000_000);
    log_metrics(file, &start, &end, data_rate, latency);
}

