bool read_csv(const char *filename, size_t *num_rows, struct NFAPI_CRC_INDICATION_PDU_T **data) {
    FILE *file = fopen(filename, "r");
    if (!file) return false;

    size_t row_count = 0;
    size_t capacity = 16; // initial guess for memory allocation
    struct NFAPI_CRC_INDICATION_PDU_T *data_array = malloc(capacity * sizeof(*data_array));
    if (!data_array) {
        fclose(file);
        return false;
    }

    bool row_read = true;
    char line[4096];
    while (row_read && (row_count < capacity)) {
        size_t len = fgets(line, sizeof(line), file);
        if (len <= 0) break; // EOF or error, stop reading rows

        row_read = true;
        char *token = strtok(line, ",");
        if (!token) continue; // empty line, skip it

        struct NFAPI_CRC_INDICATION_PDU_T *row = &data_array[row_count];
        row->RX_UE_INFORMATION_TAG = (uint32_t)strtol(token, NULL, 10);

        token = strtok(NULL, ",");
        if (!token) {
            free(data_array);
            fclose(file);
            return false; // malformed row, stop processing data
        }
        row->RNTI = (uint16_t)strtol(token, NULL, 10);

        token = strtok(NULL, ",");
        if (!token) {
            free(data_array);
            fclose(file);
            return false; // malformed row, stop processing data
        }
        row->CRC_INDICATION_REL8_TAG = (uint8_t)(*token == '1' ? 0x01 : 0x00);

        row_count++;
        if (row_count >= capacity) {
            capacity *= 2; // double the memory allocation
            data_array = realloc(data_array, capacity * sizeof(*data_array));
            if (!data_array) {
                free(data_array);
                fclose(file);
                return false; // out of memory, stop processing data
            }
        }
    }

    if (row_count > 0) *num_rows = row_count;
    *data = data_array;
    fclose(file);
    return true;
}

uint32_t calculate_checksum(const char *filename, size_t num_rows, const struct NFAPI_CRC_INDICATION_PDU_T *data) {
