    uint32_t checksum = 0;
    char line[4096];
    size_t row_index = 0;
    bool first_line = true;
    while (fgets(line, sizeof(line), file)) {
        if (!first_line && row_index < num_rows) {
            checksum ^= ((uint32_t)strtol(line, NULL, 10) << (4 * (row_index % 4)));
        }
        first_line = false;
        row_index++;
    }

    fclose(file);
    return checksum;
}

void free_data(size_t num_rows, struct NFAPI_CRC_INDICATION_PDU_T *data) {
