#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int cqi;
    int pmi;
    int ri;
} report_t;

typedef struct lte_cell {
    size_t user_count;
    report_t** reports;

    void (*free)(struct lte_cell*);
    report_t* (*allocate)(struct lte_cell*, size_t index);
} lte_cell_t;

void lte_cell_destroy(lte_cell_t* cell) {
    if (!cell || !cell->reports) return;

    for (size_t i = 0; i < cell->user_count; ++i) {
        free(cell->reports[i]);
    }

    free(cell->reports);
    free(cell);
}

report_t* lte_cell_allocate(lte_cell_t* cell, size_t index) {
    if (!index < cell->user_count) return NULL;

    report_t** reports = cell->reports;
    if (!reports) {
        size_t users = cell->user_count ? cell->user_count : 1;
        reports = malloc(users * sizeof(report_t*));
        if (!reports) return NULL;
        cell->reports = reports;
    }

    reports[index] = malloc(sizeof(report_t));
    if (!reports[index]) {
        lte_cell_destroy(cell);
        return NULL;
    }

    return reports[index];
}

void lte_cell_init(lte_cell_t* cell, size_t user_count) {
    if (!cell) return;

    cell->user_count = user_count;
    cell->reports = NULL;
    cell->free = &lte_cell_destroy;
    cell->allocate = &lte_cell_allocate;
}

void generate_data(report_t* report) {
    // Populate the report with simulated data
    report->cqi = rand() % 15 + 1;
    report->pmi = rand() % 16;
    report->ri = rand() % 8 + 1;
}

int main() {
    lte_cell_t cell;
    lte_cell_init(&cell, 10);

    for (size_t i = 0; i < cell.user_count; ++i) {
        report_t* report = cell.allocate(&cell, i);
        if (!report) goto error;

        generate_data(report);
    }

    // Use the reports here...

    cell.free(&cell);
    return 0;

error:
    fprintf(stderr, "Error allocating memory\n");
    cell.free(&cell);
    return 1;
}
