    char UE_IDENTIFIER[32];
    time_t TIMESTAMP;
    char LOG_MESSAGE[256];
} UE_LOGGING_RECORD;

UE_LOGGING_RECORD* readCSVFileToLogRecords(const char *filename, time_t startTime, time_t endTime, int minLogLevel) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    size_t recordsCapacity = 0;
    size_t recordsCount = 0;
    UE_LOGGING_RECORD *records = NULL;

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        if (!token) continue; // blank or invalid line

        UE_LOGGING_RECORD *record = records + recordsCount;
        record->TIMESTAMP = (time_t)strtol(token, NULL, 10);
        token = strtok(NULL, ",");
        if (!token) {
            free(records);
            fclose(file);
            return NULL;
        }
        strncpy(record->UE_IDENTIFIER, token, sizeof(record->UE_IDENTIFIER) - 1);
        record->UE_IDENTIFIER[sizeof(record->UE_IDENTIFIER) - 1] = '\0';
        token = strtok(NULL, ",");
        if (!token) {
            free(records);
            fclose(file);
            return NULL;
        }
        strncpy(record->LOG_MESSAGE, token, sizeof(record->LOG_MESSAGE) - 1);
        record->LOG_MESSAGE[sizeof(record->LOG_MESSAGE) - 1] = '\0';

        if (record->TIMESTAMP >= startTime && record->TIMESTAMP <= endTime && record->LOG_LEVEL >= minLogLevel) {
            recordsCapacity += sizeof(UE_LOGGING_RECORD);
            if (recordsCount == recordsCapacity) {
                records = realloc(records, recordsCapacity * 2);
                if (!records) {
                    free(records);
                    fclose(file);
                    return NULL;
                }
            }
            record->LOG_LEVEL = convertLogMessageToLevel(record->LOG_MESSAGE);
        }

        recordsCount++;
    }

    if (feof(file)) {
        fclose(file);
    } else {
        perror("Unexpected end of file");
        free(records);
        return NULL;
    }

    return records;
}

int convertLogMessageToLevel(const char *logMessage) {
    // implement your custom logic here to convert log message string to enum LOG_LEVEL
    // for example, consider the first three words in the log message
    if (strcmp(logMessage, "Information") == 0 || strcmp(logMessage, "Info") == 0) return INFO;
    if (strcmp(logMessage, "Warning") == 0) return WARNING;
    if (strcmp(logMessage, "Error") == 0) return ERROR;
    // or any other custom logic you might need
    return -1; // invalid log message
}
