} report_t;

struct dynamic_array {
    report_t* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void log(const char* message) {
    // Implement logging mechanism here, e.g., writing to a file or sending to a log server
}

static void resize(struct dynamic_array* array, size_t new_capacity) {
    if (new_capacity <= array->size) return;

    report_t* new_data = realloc(array->data, new_capacity * sizeof(report_t));
    if (!new_data) {
        log("Memory allocation failure");
        return;
    }

    array->data = new_data;
    array->capacity = new_capacity;
}

static void check_capacity(struct dynamic_array* array) {
    if (array->size + 1 >= array->capacity) {
        resize(array, array->capacity * 2);
    }
}

void add_report(struct dynamic_array* array, const report_t* new_report) {
    pthread_mutex_lock(&array->mutex);
    check_capacity(array);
    array->data[array->size++] = *new_report;
    pthread_mutex_unlock(&array->mutex);
}

report_t* get_report_by_id(struct dynamic_array* array, int user_id) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].user_id == user_id) {
            report_t* result = &array->data[i];
            pthread_mutex_unlock(&array->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

struct dynamic_array* create_dynamic_array(size_t initial_capacity) {
    struct dynamic_array* array = malloc(sizeof(struct dynamic_array));
    if (!array) {
        log("Memory allocation failure");
        return NULL;
    }

    array->data = malloc(initial_capacity * sizeof(report_t));
    if (!array->data) {
        free(array);
        log("Memory allocation failure");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}
