typedef struct LogEntry {
    char message[512];
    int retry_count;
    time_t timestamp;
} LogEntry;

static LogEntry queue[100];
static int head = 0, tail = 0;
static pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t queue_not_full = PTHREAD_COND_INITIALIZER;
static pthread_cond_t queue_not_empty = PTHREAD_COND_INITIALIZER;

static int service_available = 1;

void log_message(const char *format, ...) {
    va_list args;
    LogEntry entry;

    if (!service_available) {
        va_start(args, format);
        vsnprintf(entry.message, sizeof(entry.message), format, args);
        va_end(args);

        pthread_mutex_lock(&queue_mutex);
        if (tail - head < 100) {
            strcpy(queue[tail], entry.message);
            tail++;
            pthread_cond_signal(&queue_not_full);
        } else {
            pthread_cond_wait(&queue_not_empty, &queue_mutex);
            if (head != tail) {
                strcpy(queue[head], entry.message);
                head++;
            }
        }
        pthread_mutex_unlock(&queue_mutex);
    } else {
        va_start(args, format);
        vsnprintf(entry.message, sizeof(entry.message), format, args);
        va_end(args);

        // Your distributed logging system call here
    }
}

void log_service_recovered() {
    service_available = 1;
    pthread_mutex_lock(&queue_mutex);

    while (head != tail) {
        LogEntry entry = queue[head];
        head++;

        // Your distributed logging system call here with updated retry count, timestamp, and message
    }

    pthread_cond_broadcast(&queue_not_empty);
    pthread_mutex_unlock(&queue_mutex);
}
```

