// Define the struct for LTE PHY layer measurement reports
typedef struct {
    time_t timestamp;
    int user_id;
    int signal_strength;
    unsigned char *CQI; // Variable size array of CQIs
    unsigned char *PMI; // Variable size array of PMIs
    int RI; // Rank Indicator
    void *custom_metadata; // Pointer to custom metadata
} lte_report_t;

// Global variables for configuration
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t full = PTHREAD_COND_INITIALIZER, empty = PTHREAD_COND_INITIALIZER;
int reports_capacity = 10000;
int reports_count = 0;

// Function to handle a new report
void store_report(lte_report_t *report) {
    pthread_mutex_lock(&mutex);

    // Check if the array is full
    if (reports_count >= reports_capacity) {
        // If full, double the capacity and resize the array
        int new_capacity = reports_capacity * 2;
        lte_report_t *new_array = realloc(reports, new_capacity * sizeof(lte_report_t));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        reports = new_array;
