EVP_CIPHER *cipher_init(const char *mode, const char *encryption_key) {
    EVP_CIPHER_CTX *ctx;
    EVP_CIPHER *cipher = EVP_get_cipherbyname((const EVP_CIPHER *)mode);

    if (!cipher) return NULL;

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, cipher, NULL, (void*)encryption_key, NULL);

    return ctx;
}

int is_revoked(token_data *td, CURL *curl) {
    int retries = 3;
    char *response = NULL;
    int status_code;

    while (retries--) {
        CURLcode res = curl_easy_setopt(curl, CURLOPT_URL, "https://revocation.example.com/api/isRevoked");
        if (res != CURLE_OK) return 1;

        res = curl_easy_setopt(curl, CURLOPT_POSTFIELDS, td->access_token);
        if (res != CURLE_OK) return 1;

        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
            if (res == CURLE_OK && status_code == 200) {
                size_t len;
                res = curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_REMAIN, &len);
                if (res != CURLE_OK || len != sizeof("revoked" - 1)) return 0;

                response = malloc(len + 1);
                res = curl_easy_getinfo(curl, CURLINFO_READDATA, &response);
                if (res == CURLE_OK) {
                    if (!strncmp(response, "revoked", len)) return 1;
                    free(response);
                }
            }
        }
        sleep(pow(2, retries));
    }

    log_event("Exceeded revocation service request limit");
    return 0;
}

// Function for token validation and cipher construction
EVP_CIPHER *validate_token(const char *json_string, const char *encryption_key, const char *cipher_mode) {
    json_t *root, *access_token, *expires_in, *token_type;
    int error = 0;

    root = json_loads(json_string, 0, NULL);
    if (!root) return NULL;

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");

    if (!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) error = 1;
    else {
        const char *at_str = json_string_value(access_token);
        int exi_val = json_integer_value(expires_in);
        const char *tt_str = json_string_value(token_type);

        if (strcmp(tt_str, "Bearer") != 0 || exi_val <= 0) error = 1;
        else {
            time_t expiration = td->current_time + exi_val;
            struct tm exp_tm = *localtime(&expiration);

            if (td->current_time > expiration) error = 1;
            else if (is_revoked(td, curl)) error = 1;
        }
    }

    if (error || !refresh_token || json_object_get(root, "refresh_token")) return NULL;

    EVP_CIPHER *cipher = cipher_init(cipher_mode, encryption_key);
    if (!cipher) return NULL;

    // Perform null encryption logic here if required

    free(json_string);
    json_decref(root);
    return cipher;
}
