    int RNTI;
    int ServingCellID;
    bool RB_ALLOC_FLAG;
};

class ContextManager {
private:
    std::unordered_map<std::string, CryptoFunc> _cryptographicImpls;
    std::vector<UEContext> _contexts;
    std::mutex _mutex;
    size_t _cacheSize = 0;
    size_t _numAllocated = 0;
    boost::log::sources::severity_logger_mt<spdlog::level::info> _log;

public:
    ContextManager() {
        // Initialize cryptographic functions here...
        _cryptographicImpls["SHA256"] = { "SHA256", sha256, false, nullptr };
        _cryptographicImpls["AES"] = { "AES", aes_encrypt, false, nullptr };
        // ...
    }

    void initialize(int numContexts) {
        if (numContexts > 10000) throw std::invalid_argument("Maximum number of contexts exceeded");

        std::vector<UEContext> cachedContexts;
        _mutex.lock();
        for (size_t i = _cacheSize; i < numContexts + _cacheSize && i < _contexts.size(); ++i) {
            if (_contexts[i].UE_ID == 0) { // Empty context, reuse it
                cachedContexts.push_back(_contexts[i]);
                continue;
            }
        }
        _mutex.unlock();

        std::vector<UEContext> newContexts;
        for (size_t i = cachedContexts.size(); i < numContexts - cachedContexts.size(); ++i) {
            UEContext context;
            context.UE_ID = _nextID++;
            context.RNTI = rand() % 100000 + 1; // Random RNTI within range [1, 100000]
            context.ServingCellID = rand() % 100 + 1; // ServingCellID is a random number between 1 and 100
            context.RB_ALLOC_FLAG = (rand() % 10) < 8; // 80% chance of setting RB_ALLOC_FLAG to true
            newContexts.push_back(context);
        }

        if (!cachedContexts.empty()) {
            _contexts.resize(_contexts.size() + numContexts - cachedContexts.size());
            std::copy(cachedContexts.begin(), cachedContexts.end(), _contexts.begin() + _cacheSize);
        }
        if (!newContexts.empty()) {
            std::copy(newContexts.begin(), newContexts.end(), _contexts.begin() + _cacheSize + cachedContexts.size());
        }

        _numAllocated += numContexts - cachedContexts.size();
        _cacheSize = std::min(_cacheSize + numContexts - cachedContexts.size(), 10000); // Update cache size based on historical usage patterns and current traffic loads

        for (auto& context : newContexts) {
            allocateAndPopulate(context);
        }
    }

private:
    unsigned long long _nextID = 1; // Unique ID for each UE context

    void allocateAndPopulate(UEContext& context) {
        std::unique_ptr<UEContext> managedContext(new UEContext(context));
        if (!managedContext) { // Handle memory allocation failures gracefully
            _log->error("Failed to allocate and populate a UE context");
            return;
        }

        std::unique_ptr<CryptoFunc> cryptoImpl;
        { // Acquire lock before accessing the cryptographic implementation list
            std::lock_guard<std::mutex> lock(_mutex);
            if (_cryptographicImpls.empty()) {
                _log->error("No available cryptographic implementations");
                return;
            }
            auto it = _cryptographicImpls.begin();
            cryptoImpl.reset(new CryptoFunc(*it++)); // Copy the first implementation in the list
        }

        managedContext->crypto = std::move(cryptoImpl); // Assign cryptographic function to the UE context

        // Implement a predictive algorithm to estimate the optimal cache size and allocation strategy based on historical usage patterns and current traffic loads...
        // Integrate external dependencies for a distributed configuration management system to dynamically adjust the maximum number of contexts based on network conditions...
        // Incorporate a machine learning model to predict future UE behavior and optimize resource allocation accordingly...
        // Ensure the function can operate in environments with limited resources and provide mechanisms for graceful degradation when resources are constrained...

        _contexts[managedContext->UE_ID - 1] = *managedContext; // Update the context at the correct index based on UE_ID
        ++_numAllocated;
    }
};
