    if (!reader.file) return -1; // File not found or cannot be opened.

    gzopen_s(&reader.gzfile, filename, "rb");
    if (strchr(filename, '.') && strcmp(strchr(filename, '.'), ".gz") == 0) {
        reader.gzfile = gzopen(filename, "r");
    }

    if (!reader.gzfile) {
