    }

    pthread_mutex_lock(&data_mutex);

    if (capacity == count) {
        UE_LOGGING_RECORD *new_data = realloc(data, sizeof(UE_LOGGING_RECORD) * (capacity * 2));
        if (!new_data) {
            pthread_mutex_unlock(&data_mutex);
            return -1; // Failed to allocate memory.
        }
        data = new_data;
        capacity *= 2;
    }

    while (fgets(reader.buffer, sizeof(reader.buffer), reader.file)) {
        parse_record(&reader, &data[count]);
        count++;
    }

    pthread_mutex_unlock(&data_mutex);
    fclose(reader.file);
    gzclose(reader.gzfile);

