import { Router } from 'express';
import { UserProfile, ProfileUpdate, ArchiveUserParams } from './models'; // Define your models here
import jwt from 'jsonwebtoken';
import redis from 'redis';
import bluebird from 'bluebird';
const client = redis.createClient();

const apiRouter = Router();

// Middleware to authenticate requests using an external authentication service (e.g. OAuth)
function authenticate(req, res, next) {
  // Extract the authorization header and validate the token
  const token = req.header('Authorization');
  if (!token) return res.status(401).send('Unauthorized');

  jwt.verify(token, process.env.AUTH_SECRET, (err, decoded) => {
    if (err) return res.status(401).send('Unauthorized');
    req.user = decoded; // Store the decoded user data in the request object for further use
    next();
  });
}

// Function to get the latest version of a user profile, merging concurrent updates if necessary
async function getLatestProfile(userId: number): Promise<UserProfile> {
  const versionKey = `profile:${userId}:version`;
  const latestVersion = await client.getAsync(versionKey);

  let profiles: UserProfile[] = [];
  let currentVersion = Number(latestVersion) || 0;
  do {
    profiles = await UserProfile.find({ where: { userId, version: currentVersion } });
    if (profiles.length === 0) break;
    currentVersion++;
  } while (true);

  // Merge the profiles to get the latest version
  return profiles.reduce((acc, profile) => ({ ...acc, ...profile }), {});
}

// Function to update a user profile, handling concurrent updates gracefully by merging changes
async function updateProfile(userId: number, update: ProfileUpdate): Promise<UserProfile> {
  const version = await getLatestProfile(userId).then((p) => p.version);
  const updatedProfile = await UserProfile.update({ ...update }, { where: { userId, version } });
  if (updatedProfile[0] === 1) {
    // Increment the version number of the updated profile
    await client.incrby(updateKey, 1);
  }
  return updatedProfile[1];
}

// Function to create a new user profile or update an existing one if it already exists
async function manageUserProfile(userId: number, requestBody: UserProfile): Promise<UserProfile> {
  const existingProfile = await getLatestProfile(userId);
  if (existingProfile) {
    return updateProfile(userId, requestBody);
  } else {
    // Create a new profile with the initial version set to 1
    const createdProfile = await UserProfile.create({ ...requestBody, version: 1 });
    // Increment the version number of the newly created profile
    await client.incrby(updateKey, 1);
    return createdProfile;
  }
}

// Function to archive or permanently delete inactive user profiles
async function manageInactivity(userId: number, action: 'archive' | 'delete'): Promise<void> {
  const userProfile = await UserProfile.findOne({ where: { userId } });
  if (!userProfile) return; // If the user doesn't exist, do nothing

  // Determine the current time and check if the user is inactive based on the specified period
  const now = new Date();
  const inactivePeriod = process.env.INACTIVE_PERIOD || '24h'; // Set the default period to 1 day
  const inactivityCheckFunction = (duration: string) => {
    const parts = duration.split(' ');
    const unit = parts[parts.length - 1].toLowerCase();
    const amount = Number(parts.slice(0, -1).join(' '));

    switch (unit) {
      case 'hours': return now - userProfile.lastActive > new Date(now.getTime() - amount * 60 * 60 * 1000);
      case 'days': return now - userProfile.lastActive > new Date(now.getTime() - amount * 24 * 60 * 60 * 1000);
      default: throw new Error(`Invalid unit "${unit}" for inactive period`);
    }
  };

  if (inactivityCheckFunction(inactivePeriod)) {
    if (action === 'archive') {
      await userProfile.update({ archived: true });
    } else if (action === 'delete') {
      await userProfile.destroy();
    }
  }
}

// Define the API endpoints for managing user profiles
apiRouter.post('/', authenticate, async (req, res) => {
  const userId = req.user.id;
  try {
    const profileData = req.body;
    await manageUserProfile(userId, profileData);
    res.status(201).send('Created user profile');
  } catch (err) {
    console.error(err);
    res.status(500).send('Error creating user profile');
  }
});

apiRouter.put('/', authenticate, async (req, res) => {
  const userId = req.user.id;
  try {
    const profileData = req.body;
    await manageUserProfile(userId, profileData);
    res.status(200).send('Updated user profile');
  } catch (err) {
    console.error(err);
    res.status(500).send('Error updating user profile');
  }
});

apiRouter.delete('/:userId', authenticate, async (req, res) => {
  const userId = req.params.userId;
  try {
    await manageInactivity(userId, 'delete');
    res.status(204).send('Deleted user profile');
  } catch (err) {
    console.error(err);
    res.status(500).send('Error deleting user profile');
  }
});

apiRouter.put('/:userId/archive', authenticate, async (req, res) => {
  const userId = req.params.userId;
  try {
    await manageInactivity(userId, 'archive');
    res.status(204).send('Archived user profile');
  } catch (err) {
    console.error(err);
    res.status(500).send('Error archiving user profile');
  }
});
```

