const promises = [];

async function readFiles(directory, extension) {
    const files = await fs.readdir(directory);
    files.forEach((file) => {
        if (path.extname(file) === `.${extension}`) {
            const filePath = path.join(directory, file);
            promises.push(fs.readFile(filePath, 'utf8'));
        }
    });
