const newTestamentBooks = /(mathew|mark|luke|john|acts|romans|1\s+corinthians|2\s+corinthians|galatians|ephhesians|philippians|colossians|1\s+thessalonians|2\s+thessalonians|1\s+timothy|2\s+timothy|titus|philemon|hebrews|james|1\s+peter|2\s+peter|1\s+john|2\s+john|3\s+john|jude|revelation)/gi;

function countBookOccurrences(text) {
  if (!text || !text.length) return {};

  const bible = { old: [], new: [] };
  let match;

  textProcessingLibrary.streamText(text, (chunk) => {
    chunk.split(/\s+/).forEach((word) => {
      word = word.toLowerCase().replace(/[^\w\s]/g, ''); // Remove punctuation and special characters

      if ((match = oldTestamentBooks.exec(word))) bible.old.push(match[0]);
      else if ((match = newTestamentBooks.exec(word))) bible.new.push(match[0]);
    });
  }, (error) => {
    console.error(error);
  });

  return bible.old.reduce((acc, book) => {
    acc[book] = (acc[book] || 0) + 1;
    return acc;
  }, {}) + bible.new.reduce((acc, book) => {
    acc[book] = (acc[book] || 0) + 1;
    return acc;
  }, {});
}

