["```javascript
const storage = require('distributed-storage'); // Replace with your actual distributed storage system library
const { v4: uuidv4 } = require('uuid');
const log = require('winston'); // Replace with your actual logging library

let graph = new Map();
let timer;
let paused = false;

function addVertex(vertexProps) {
  const vertexId = uuidv4();
  const vertex = Object.assign({ id: vertexId }, vertexProps);
  graph.set(vertexId, vertex);
  return vertexId;
}

function addEdge(sourceId, targetId, edgeProps) {
  if (!graph.has(sourceId)) throw new Error('Source vertex does not exist');
  if (!graph.has(targetId)) throw new Error('Target vertex does not exist');

  const edge = Object.assign({ source: sourceId, target: targetId }, edgeProps);
  const existingEdges = graph.get(sourceId).edges || [];
  graph.get(sourceId).edges = [...existingEdges, edge];
}

function processData(data) {
  // Randomly set properties on vertices and edges created from data
  const vertexProps = { ...data };
  Object.keys(vertexProps).forEach(key => vertexProps[key] = Math.random());
  const sourceId = addVertex(vertexProps);
  const edgeProps = { ...data, weight: Math.random() };
  addEdge(sourceId, uuidv4(), edgeProps);
}

function saveData() {
  if (paused) return;

  try {
    storage.save(Array.from(graph.entries()), () => log.info('Data saved'));
    timer = setTimeout(saveData, 60000); // Save every minute
  } catch (err) {
    log.error(`Error saving data: ${err}`);
  }
}

function pause() {
  if (paused) return;
  paused = true;
  clearTimeout(timer);
}

function resume() {
  if (!paused) return;
  paused = false;
  saveData();
}

module.exports = {
  processData,
  pause,
  resume,
};
```"]

