typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateAndInitializePDUs(size_t count) {
    if (count == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for PDUs\n");
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    for (size_t i = 0; i < count; ++i) {
        uint16_t tag = rand() % 256 + 1; // Valid range is [1, 256]
        pdus[i].RX_UE_INFORMATION_TAG = (tag > UINT16_MAX - NFAPI_CRC_INDICATION_PDU_T) ? (tag - UINT16_MAX + NFAPI_CRC_INDICATION_PDU_T + 1) : tag;
        pdus[i].RNTI = i + 1; // Valid range is [1, count]
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Valid range is [0, 255]
        pdus[i].CRCFLAG = (rand() & 1) ? true : false;
    }

    return pdus;
}
