```javascript
function copyData(dataChunks, start, end, destinationBuffer) {
    if (!Array.isArray(dataChunks)) throw new Error('dataChunks must be an array');
    if (start < 0 || end < 0 || start >= dataChunks.length || end >= dataChunks.length) throw new Error('Invalid dataChunks index range');

    const chunkLength = Math.min(end - start + 1, dataChunks[start].byteLength);
    const chunk = Buffer.concat(dataChunks.slice(start, end + 1));

    if (chunkLength > destinationBuffer.length) throw new Error('Destination buffer is too small');

    destinationBuffer.write(chunk, destinationBuffer.length);
}
