const fs = require('fs-extra');
const crypto = require('crypto');
const axios = require('axios');
const { promisify } = require('util');
const readFile = promisify(fs.readFile);
const writeFile = promisify(fs.writeFile);
const appendFile = promisify(fs.appendFile);
const logStream = appendFile('./logfile.txt', '\n');

async function copyDataChunks(dataChunks, byteCount, log) {
  let copiedData = Buffer.alloc(byteCount);
  let readIndex = 0;
  let writeIndex = 0;

  for (const chunk of dataChunks) {
    const endIndex = Math.min(readIndex + byteCount, chunk.length);
    copiedData.slice(writeIndex, writeIndex + endIndex - readIndex)
      .set(chunk.slice(readIndex, endIndex), 'utf8');
    readIndex += endIndex - readIndex > byteCount ? byteCount : endIndex;
    writeIndex += endIndex - readIndex > byteCount ? byteCount : endIndex;

    if (readIndex === chunk.length) {
      readIndex = 0;
      // Simulate a random delay between chunks
      await new Promise(resolve => setTimeout(resolve, Math.random() * 100));
    }
  }

  return copiedData;
}

