  constructor(storage) {
    this.storage = storage;
  }

  log(message) {
    this.storage.push(message);
  }
}

// Aggregation function with exponential backoff retry mechanism
async function asyncAggregate(data, initialValue, callback, retries = 3) {
  let accumulator = initialValue;

  try {
    for (let i = 0; i < data.length; ++i) {
      accumulator = await callback(accumulator, data[i]);

      if (!Array.isArray(data) || i + 1 === data.length) {
        return accumulator;
      }
    }
  } catch (error) {
    if (retries <= 0) {
      throw error;
    }

    const backoff = moment.duration(moment.random() * Math.pow(2, retries - 1), 'milliseconds');
    console.log(`Retrying operation in ${backoff.asMilliseconds()}ms`);
    await new Promise((resolve) => setTimeout(resolve, backoff.asMilliseconds()));
    return asyncAggregate(data, initialValue, callback, --retries);
  }
}

