  try {
    const data = req.body;
    if (!Array.isArray(data)) {
      throw new Error('Invalid data format');
    }

    const result = await asyncAggregate(data, 0, (acc, num) => acc + num);
    res.json({result});
  } catch (error) {
    res.status(500).json({error: error.message});
  }
});

