    const result1 = await asyncAggregate(sampleData, 0, (acc, num) => acc + num);
    console.log(`Result for sequential execution: ${result1}`);

    // Simulate network latency with Promise.resolve and Promise.reject
    const result2 = await asyncAggregate([...Array(10000).keys()].map(n => n + 1), 0, (acc, num) => acc + num, 3);
    console.log(`Result for asynchronous execution with latency: ${result2}`);

    // Simulate an unexpected data format
    const result3 = await asyncAggregate(["not a number"], 0, (acc, num) => acc + num);
    console.log(`Result for unexpected data format: ${result3}`);
