#include <stdlib.h>
#include <string.h>
#include <pthread.h>

static pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;

char* append_slash_if_possible(const char* str, size_t limit, char* buffer, status_t* status) {
    size_t len = strlen(str);
    if (len > (limit / 2)) {
        *status = STATUS_FAILURE;
        return NULL;
    }

    if ((len + 1) <= limit) {
        strcat(buffer, "/");
        *status = STATUS_SUCCESS;
        return buffer;
    }

    size_t new_size = (len + 1 > limit ? limit * 2 : len + 1);
    char* new_buf = realloc(buffer, new_size);
    if (!new_buf) {
        *status = STATUS_MEMORY_FAILURE;
        return NULL;
    }

    // Add the lock to ensure thread safety during memory allocation
    pthread_mutex_lock(&mem_lock);

    strcat(new_buf, "/");
    if ((len + 1) < new_size)
        memmove(new_buf + 1, buffer, len + 1);
    else
        memcpy(new_buf + 1, buffer, limit - (len + 1));

    pthread_mutex_unlock(&mem_lock);

    *status = STATUS_SUCCESS;
    return new_buf;
}
```

