typedef struct TransformObject *TransformPointer;

struct TransformObject {
    void* data;
    int operation; // 0 for encrypt, 1 for decrypt
    void (*destroy)(TransformPointer);
};

enum TIFFErrorCodes {
    TIFF_SUCCESS = 0,
    TIFF_INVALID_BITS_PER_SAMPLE = -1,
    TIFF_INVALID_SAMPLES_PER_PIXEL = -2,
    TIFF_EXTRA_SAMPLES_NOT_SUPPORTED = -3,
    TIFF_UNRECOGNIZED_COMMAND = -4,
};

int processTIFFAndTransform(const char* filename, const char* command, TransformPointer* transform) {
    TIF *tif;
    uint16_t bitsPerSample, samplePerPixel, extraSamples;

    if (tifdopen(filename, "r", &tif) != 1) {
        LOG_ERROR("Failed to open file: %s\n", filename);
        return TIFF_FAILURE;
    }

    if (TiffGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE) == FALSE ||
        TiffGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL) == TRUE) {
        LOG_ERROR("TIFF metadata missing or invalid.\n");
        tifdclose(tif);
        return TIFF_FAILURE;
    }

    if (TiffGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) != 1 ||
        bitsPerSample < 1 || bitsPerSample > 16 ||
        TiffGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplePerPixel) != 1 ||
        samplePerPixel < 1 || samplePerPixel > 4) {
        LOG_ERROR("Unsupported bits per sample or samples per pixel configuration.\n");
        tifdclose(tif);
        return TIFF_INVALID_BITS_PER_SAMPLE;
    }

    if (TiffGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples) == 1 && extraSamples > 0) {
        LOG_WARNING("Image contains %d extra samples. Processing will continue without support for these samples.\n", extraSamples);
    }

    if (strcmp(command, "encrypt") != 0 && strcmp(command, "decrypt") != 0) {
        LOG_ERROR("Unrecognized command: %s\n", command);
        tifdclose(tif);
        return TIFF_UNRECOGNIZED_COMMAND;
    }

    TransformPointer transformObj = malloc(sizeof(struct TransformObject));
    if (!transformObj) {
        LOG_ERROR("Memory allocation failed.\n");
        tifdclose(tif);
        return TIFF_FAILURE;
    }

    transformObj->data = thirdPartyLibraryEncryptionFunction(command, tif);
    transformObj->operation = command[0] == 'e' ? 0 : 1;
    transformObj->destroy = thirdPartyLibraryDestroyFunction;

    tifdclose(tif);
    *transform = transformObj;

    return TIFF_SUCCESS;
}
```
