#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>

#define MAX_LOGGING_LEVEL 4 // debug, info, warning, error
struct directory {
    char path[256];
    unsigned int num_files;
    struct directory *next;
};

struct directory *directories = NULL;

void log(int level, const char *message) {
    if (level > MAX_LOGGING_LEVEL) return;
    printf("[Level %d] %s\n", level, message);
}

unsigned int count_vowels(const char *str) {
    unsigned int count = 0;
    while (*str) {
        if (islower(*str++) && strchr("aeiou", *--str)) ++count;
    }
    return count;
}

char* create_new_filename(const char *original, const char *file_type) {
    int vowel_count = count_vowels(original);
    int digit_count = vowel_count > 3 ? vowel_count : 1;
    size_t new_name_len = strlen(original) + digit_count + strlen(file_type) + 1; // +1 for the extension separator
    if (new_name_len > 255) return NULL;

    char *new_name = malloc(new_name_len);
    strncpy(new_name, original, strlen(original));

    int pos = strlen(original);
    for (int i = 0; i < digit_count; ++i) {
        sprintf(&new_name[pos++], "%d", vowel_count - i);
    }

    if (!strchr(file_type, '.')) strcat(new_name, ".");
    strcat(new_name, file_type);

    return new_name;
}

struct directory* find_suitable_directory() {
    struct directory *current = directories;
    while (current) {
        if (current->num_files < 10000 - num_files_in_dir(current->path)) {
            return current;
        }
        current = current->next;
    }

    struct directory *new_dir = malloc(sizeof(struct directory));
    strcpy(new_dir->path, "."); // current directory
    new_dir->num_files = 0;
    new_dir->next = directories;
    directories = new_dir;

    return new_dir;
}

void update_directory_count(const char *path) {
    struct directory *current = directories;
    while (current) {
        if (!strcmp(current->path, path)) {
            current->num_files++;
            return;
        }
        current = current->next;
    }
}

void update_directory_count_recursively(const char *path, int depth) {
    struct directent entry;
    DIR *dir = opendir(".");

    if (!dir) return;
    while (readdir_r(dir, &entry, &current)) {
        if (entry.d_type == DT_DIR && !strcmp(entry.d_name, ".") && depth > 1 || entry.d_type != DT_DIR) {
            char full_path[256];
            snprintf(full_path, sizeof(full_path), "%s/%s", path, entry.d_name);
            update_directory_count_recursively(full_path, depth + 1);
        } else if (entry.d_type == DT_DIR && !strcmp(entry.d_name, "..")) continue; // skip parent directory
        else {
            char full_path[256];
            snprintf(full_path, sizeof(full_path), "%s/%s", path, entry.d_name);
            update_directory_count(full_path);
        }
    }
    closedir(dir);
}

unsigned int num_files_in_dir(const char *path) {
    if (!path || !*path) return 0;

    struct directory *current = directories;
    while (current) {
        if (!strcmp(current->path, path)) return current->num_files;
        current = current->next;
    }

    update_directory_count_recursively(path, 1);
    return 0; // should never reach here
}

char* rename_file_and_log(const char *original, const char *new_filename) {
    log(INFO, "Renaming file from %s to %s", original, new_filename);
    int fd = open(original, O_RDWR | O_EXCL);

    if (fd == -1 && errno != EEXIST) {
        perror("Failed to open the file");
        return NULL;
    }

    if (fd != -1) {
        close(fd);
        rename(original, new_filename);
        log(INFO, "File renamed successfully.");
    } else {
        log(WARNING, "File already exists. Skipping...");
    }

    return new_filename;
}

char* process_file(const char *filename) {
    if (!filename || !strlen(filename)) return NULL;

    char *file_type = strrchr(filename, '.');
    if (!file_type) file_type = ".txt"; // default extension

    char *new_filename = create_new_filename(filename, file_type);
    if (!new_filename) return NULL;

    struct directory *suitable_dir = find_suitable_directory();

    char full_path[256];
    snprintf(full_path, sizeof(full_path), "%s/%s", suitable_dir->path, new_filename);
    if (rename_file_and_log(filename, full_path)) {
        free(new_filename);
        return full_path;
    }

    log(ERROR, "Failed to rename the file.");
    free(new_filename);
    return NULL;
}

char* process_batch(const char *filenames[], size_t num_files) {
    if (!filenames || !num_files) return NULL;

    for (size_t i = 0; i < num_files; ++i) {
        process_file(filenames[i]);
    }

    return NULL; // return NULL to indicate success when processing a batch
}
```

