// Function to load a plugin and create a MediaObject instance
MediaObject* loadPlugin(const char* libName) {
    void* handle = dlopen(libName, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        return nullptr;
    }
    // Get the function pointer for the main processing function using dlsym()
    typedef MediaObject*(ProcessMediaFunc)(void*);
    ProcessMediaFunc processMedia = reinterpret_cast<ProcessMediaFunc>(dlsym(handle, "processMedia"));
    if (!processMedia) {
        fprintf(stderr, "Failed to get the processMedia function\n");
        dlclose(handle);
        return nullptr;
    }
    // Call the library's main processing function and store the result in a new MediaObject instance
    MediaObject* obj = processMedia(nullptr);
    if (!obj) {
        fprintf(stderr, "Failed to create a MediaObject instance\n");
        dlclose(handle);
        return nullptr;
    }
    // Add any required data members or custom functions here based on the library's implementation
    obj->libHandle = handle;
    return obj;
}

// Function to clean up and unload a plugin when it's no longer needed
void freePlugin(MediaObject* obj) {
    if (obj && obj->libHandle) {
        dlclose(obj->libHandle);
        free(obj);
    }
}

// Main function to process media with support for multiple codecs
void processMedia(const char* codecName, ...) {
