int encodeVideo(char *inputFileName, char *outputDirectory, char *outputFile, double maxDuration) {
    const char *logFile = "encoding.log";

    // Initialize logging mechanism
    log_initialize(logFile);

    WebMEncoderContext encoderContext;
    memset(&encoderContext, 0, sizeof(WebMEncoderContext));

    // Open the input file
    int inputFile = open(inputFileName, O_RDONLY);
    if (inputFile < 0) {
        log_error("Could not open input file: %s", inputFileName);
        return -1;
    }

    // Initialize the video context
    avformat_alloc_context3(&encoderContext.pFormatCtx);
    encoderContext.pFormatCtx->pb = NULL;
    encoderContext.pFormatCtx->avfile = NULL;

    if (avformat_open_input(&encoderContext.pFormatCtx, inputFileName, NULL, NULL) != 0) {
        log_error("Could not open input file: %s", inputFileName);
        close(inputFile);
        return -1;
    }

    if (avformat_find_stream_info(encoderContext.pFormatCtx, NULL) < 0) {
        log_error("Failed to find stream information");
        close(inputFile);
        return -1;
    }

    // Find the first video stream and create output context for WebM format
    AVStream *videoStream = encoderContext.pFormatCtx->streams[0];
    if (videoStream == NULL) {
        log_error("No valid video stream found");
        close(inputFile);
        return -1;
    }

    encoderContext.pCodecCtx = avcodec_alloc_context3(videoStream->codecpar);
    avcodec_parameters_to_context(encoderContext.pCodecCtx, videoStream->codecpar);

    // Set the output file destination directory and name
    char dir[256], fileName[256];
    sprintf(dir, "%s", outputDirectory);
    sprintf(fileName, "%s/%s", dir, outputFile);
    encoderContext.pFormatCtx->oformat = av_guess_format("webm", NULL, NULL);
    encoderContext.pFormatCtx->filename = fileName;

    if (avio_open(&encoderContext.pFormatCtx->pb, fileName, AVIO_FLAG_WRITE, NULL, NULL) < 0) {
        log_error("Could not open output file: %s", fileName);
        close(inputFile);
        return -1;
    }

    if (avformat_write_header(encoderContext.pFormatCtx, NULL) < 0) {
        log_error("Failed to write header for output file");
        close(inputFile);
        return -1;
    }

    // Find the appropriate video encoder and open it
    AVCodec *codec = avcodec_find_encoder(videoStream->codecpar->codec_id);
    if (!codec) {
        log_error("Could not find a suitable video encoder");
        close(inputFile);
        return -1;
    }
    encoderContext.pCodec = codec;
    encoderContext.pCodecCtx->pix_fmt = AV_PIX_FMT_YUV420P;

    if (avcodec_open2(encoderContext.pCodecCtx, encoderContext.pCodec, NULL) < 0) {
        log_error("Could not open video codec");
        close(inputFile);
        return -1;
    }

    // Open the output file for writing YUV frames (if necessary)
    encoderContext.yuvFile = fopen("temp_output.yuv", "wb");
    if (!encoderContext.yuvFile) {
        log_error("Could not open temporary YUV file");
        close(inputFile);
        return -1;
    }
    encoderContext.yuvFileIsOpen = 1;

    // Create the write thread for writing frames to output file
    pthread_create(&encoderContext.writeThreadId, NULL, encodeWriteThread, &encoderContext);

    // Read input frames and encode them until the allowed duration is reached or an error occurs
    encoderContext.startTime = time(NULL);
    double totalDuration = 0;
    while (totalDuration < maxDuration) {
        AVPacket packet;
        int ret = av_read_frame(encoderContext.pFormatCtx, &packet);
        if (ret < 0) {
            log_error("Error reading frame: %s", av_err2str(ret));
            close(inputFile);
            return -1;
        }

        // Encode the packet and write it to the output file
        ret = avcodec_encode_video2(encoderContext.pCodecCtx, &packet, NULL);
        if (ret < 0) {
            log_error("Error encoding frame: %s", av_err2str(ret));
            close(inputFile);
            return -1;
        }

        AVFrame *frame = av_frame_alloc();
        frame->data = packet.data;
        frame->linesize = packet.linesize;
        av_frame_unref(&packet.data);

        ret = avcodec_send_frame(encoderContext.pCodecCtx, frame);
        if (ret < 0) {
            log_error("Error sending frame for encoding: %s", av_err2str(ret));
            close(inputFile);
            return -1;
        }

        totalDuration += AV_TIME_BASE_Q(encoderContext.pFormatCtx->streams[0]->time_base)
                              .num / packet.duration * 0.001;
    }

    // Stop the write thread and wait for it to finish
    encoderContext.frameFinished = 1;
    pthread_join(encoderContext.writeThreadId, NULL);

    // Finalize the output file and close resources
    if (encoderContext.yuvFileIsOpen) {
        fclose(encoderContext.yuvFile);
        encoderContext.yuvFileIsOpen = 0;
    }
    avcodec_close(encoderContext.pCodecCtx);
    av_write_trailer(encoderContext.pFormatCtx);
    close(inputFile);

    // Log the duration of the encoding process and return success
    double elapsedTime = difftime(time(NULL), encoderContext.startTime);
    log_info("Encoding completed in %.2f seconds", elapsedTime);
    return 0;
}

