        if (pid > 0) {
            end_time[i] = time(NULL);

            if (WIFEXITED(status)) {
                int exit_status = WEXITSTATUS(status);
                if (exit_status == timeout) {
                    fprintf(stderr, "Command %d timed out.\n", i);
                } else {
                    fprintf(log_file, "Command %d started at: %s\n", i, ctime(&start_time[i]));
                    fprintf(log_file, "Command %d finished at: %s with exit status: %d\n", i, ctime(&end_time[i]), WEXITSTATUS(status));
                }
            } else if (WIFSIGNALED(status)) {
                int signum = WTERMSIG(status);
                fprintf(stderr, "Command %d terminated by signal: %d\n", i, signum);
            } else {
                perror("waitpid");
            }

            running[i] = false;
        }

        if (pid == pids[i]) continue;
        if (i < 9) i++;
