#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

int safe_background(char *command) {
    pid_t child_pid;
    int pipefd[2];

    // create a pipe to send the exit status from child to parent process
    if (pipe(pipefd) == -1) {
        perror("Pipe failed");
        return 0;
    }

    child_pid = fork();
    if (child_pid == -1) {
        perror("Fork failed");
        return 0;
    }

    // In child process, we exec the given command and pass the exit status through pipe
    if (!child_pid) {
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[1]);

        if (execl("/bin/bash", "/bin/bash", "-c", command, NULL) == -1) {
            perror("Command execution failed");
            _exit(EXIT_FAILURE);
        }
    }

    // In parent process, we close the write-end of the pipe and wait for child to finish
    close(pipefd[1]);
    if (child_pid == 0) {
        // The command is executed synchronously. It's not in background yet.
        return 0;
    }

    // Set up signal handlers for catching and waiting on child processes.
    sigset_t mask, oldmask;
    sigfillset(&mask);
    sigprocmask(SIG_BLOCK, &mask, &oldmask);

    if (tcgetpgrp(STDIN_FILENO) != getpgid(child_pid)) {
        if (setpgid(child_pid, 0) == -1) {
            perror("Setpgid failed");
            sigprocmask(SIG_SETMASK, &oldmask, NULL);
            return 0;
        }
    }

    // Ignore SIGCHLD so that we can safely handle multiple child processes.
    signal(SIGCHLD, SIG_IGN);

    int status = 0;
    if (waitpid(child_pid, &status, WNOHANG) <= 0 && errno != EINTR) {
        perror("Waitpid failed");
        sigprocmask(SIG_SETMASK, &oldmask, NULL);
        return 0;
    }

    // Check if the child exited with a non-zero status.
    if (WIFEXITED(status)) {
        if (WEXITSTATUS(status) != 0) {
            printf("Command failed with exit code %d\n", WEXITSTATUS(status));
        }
    } else {
        perror("Child process terminated unexpectedly");
    }

    sigprocmask(SIG_SETMASK, &oldmask, NULL);
    close(pipefd[0]); // no need for it anymore

    return (WIFEXITED(status) && WEXITSTATUS(status) == 0) ? 1 : 0;
}
