using Microsoft.AspNetCore.WebHost;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using System.Threading.Tasks;

namespace WebsiteManager
{
    public class IISHelper
    {
        private readonly IWebHostBuilder _webHostBuilder;
        private readonly ILogger<IISHelper> _logger;

        public IISHelper(IWebHostBuilder webHostBuilder, ILogger<IISHelper> logger)
        {
            _webHostBuilder = webHostBuilder;
            _logger = logger;
        }

        public async Task AddAndStartWebsite(string directoryPath, string siteName)
        {
            var webConfigFile = Path.Combine(directoryPath, "web.config");

            if (!File.Exists(webConfigFile))
            {
                _logger.LogInformation($"{webConfigFile} is missing. Generating default configuration...");
                await GenerateDefaultWebConfigAsync(webConfigFile);
            }

            try
            {
                var webHost = _webHostBuilder
                    .UseContentRoot(directoryPath)
                    .UseStartup<Startup>()
                    .Build();

                await using (var serviceScope = webHost.Services.CreateScope())
                {
                    var services = serviceScope.ServiceProvider;
                    var iisManager = services.GetRequiredService<IWebHostEnvironment>();
                    var siteCollection = iisManager.ApplicationHost.GetSiteCollection();

                    var newSite = siteCollection.AddWebSite(siteName, directoryPath);
                    newSite.Start();

                    _logger.LogInformation($"Added and started website: {siteName}");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error adding and starting website: {siteName}");
                throw;
            }
        }

        private async Task GenerateDefaultWebConfigAsync(string webConfigFile)
        {
            var defaultWebConfig = File.ReadAllText("DefaultWebConfig.xml");
            await File.WriteAllTextAsync(webConfigFile, defaultWebConfig);
        }
    }
}
