    public Process executeCommand(String commandFile) throws IOException, InterruptedException {
        File configFile = new File(commandFile);
        if (!configFile.exists()) {
            throw new FileNotFoundException(commandFile);
        }

        Properties commandProps = new Properties();
        try (InputStream inputStream = new FileInputStream(configFile)) {
            commandProps.load(inputStream);
        }

        String cmd = commandProps.getProperty("cmd");
        File workingDirectory = new File(commandProps.getProperty("workingDirectory"));
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Runnable logRedirect = createLogRedirector(commandProps);
        ProcessBuilder pb = new ProcessBuilder(cmd).directory(workingDirectory);
        Process process = pb.start();

        process.getInputStream().forEach((byteBuf) -> {
            executor.execute(() -> logRedirect.runWith(process.getInputStream()));
        });

        process.getErrorStream().forEach((byteBuf) -> {
            executor.execute(() -> logRedirect.runWith(process.getErrorStream()));
        });

        Thread mainThread = Thread.currentThread();
        executor.submit(() -> {
            try {
                process.waitFor(Long.parseLong(configProps.getProperty("commandTimeout")), TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                logger.log(Level.WARNING, "Command execution interrupted.");
            } finally {
                process.destroy();
            }
        });

        mainThread.join();
        executor.shutdownNow();

        return process;
    }

    // Implement remaining methods here based on task requirements...

    private Runnable createLogRedirector(Properties commandProps) {
        String logFile = commandProps.getProperty("logFile");
        RotatingFileLogger loggerInstance = new RotatingFileLogger(new File(logDirectory, dateFormat.format(new Date()) + "_" + logFile), true, LOG_ROTATION_SIZE);
        AtomicLong requestId = new AtomicLong();

        return (InputStream is) -> {
            try (PrintStream loggerStream = new PrintStream(System.out, true)) {
                loggerStream.printf("Request ID: %d%n", requestId.getAndIncrement());
                loggerInstance.log(Level.INFO, String.format("Command output: %s", is));
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error redirecting command output.", e);
            }
        };
    }

