#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <inttypes.h>
#include <regex.h>
#include <jansson.h>

typedef struct {
    const char *issuer;
    const char *subject;
    const char *audience[]; // Array of audience identifiers
    uint64_t expiration;
    uint64_t issuance;
    uint64_t not_before; // Optional field, set to 0 if not present
} Config;

Config config = {
    .issuer = "https://example.com",
    .subject = "",
    .audience = {},
    .expiration = 0,
    .issuance = 0,
    .not_before = 0
};

bool jwt_validate(const char *jwt) {
    json_t *root, *claims;
    int rc;

    root = json_loads(jwt, 0, NULL);
    if (!root || !json_is_object(root)) {
        return false;
    }

    claims = json_object_get(root, "claims");
    if (!claims || !json_is_object(claims)) {
        json_decref(root);
        return false;
    }

    // Validate required fields
    const char *iss = json_object_get_string_field(claims, "iss");
    if (!iss) {
        json_decref(root);
        return false;
    }
    if (strchr(iss, '\0') || !regexec((regmatch_t *)NULL, iss, strlen(iss), (const char *)iss, 0)) {
        json_decref(root);
        return false;
    }

    const char *sub = json_object_get_string_field(claims, "sub");
    if (!sub || !*sub) {
        json_decref(root);
        return false;
    }

    const char **audience_it;
    for (audience_it = config.audience; *audience_it; ++audience_it) {
        const char *cur_aud = *audience_it;
        const char *cur_aud_claim = json_object_get_string_field(claims, cur_aud);
        if (!cur_aud_claim || !*cur_aud_claim || strchr(cur_aud_claim, '\0') || !regexec((regmatch_t *)NULL, cur_aud, strlen(cur_aud), (const char *)cur_aud_claim, 0)) {
            goto next_audience;
        }
    }
    // All audiences are valid
    json_decref(root);
    return true;

next_audience: {}
    const char *exp = json_object_get_string_field(claims, "exp");
    if (!exp || !*exp) {
        json_decref(root);
        return false;
    }
    rc = strtoll(exp, NULL, 10);
    if (rc < 0 || ((time_t)rc > INT64_MAX)) {
        json_decref(root);
        return false;
    }

    const char *iat = json_object_get_string_field(claims, "iat");
    if (!iat || !*iat) {
        json_decref(root);
        return false;
    }
    rc = strtoll(iat, NULL, 10);
    if (rc < 0 || ((time_t)rc > INT64_MAX)) {
        json_decref(root);
        return false;
    }

    const char *nbf = json_object_get_string_field(claims, "nbf");
    if (nbf && !*nbf) {
        goto validate_expiration;
    }
    if (nbf && strchr(nbf, '\0')) {
        json_decref(root);
        return false;
    }
    rc = strtoll(nbf, NULL, 10);
    if (rc < 0 || ((time_t)rc > INT64_MAX)) {
        json_decref(root);
        return false;
    }

validate_expiration:
    time_t now = time(NULL);
    uint64_t exp_ts = (uint64_t)now + config.expiration * NANOSECOND;
    uint64_t iat_ts = (uint64_t)now + config.issuance * NANOSECOND;
    uint64_t nbf_ts = 0;
    if (config.not_before) {
        nbf_ts = (uint64_t)now + config.not_before * NANOSECOND;
    }

    // Compare timestamps and ensure they are in the correct order
    if ((exp_ts <= iat_ts && nbf_ts && nbf_ts > iat_ts) || (nbf_ts && exp_ts < nbf_ts)) {
        json_decref(root);
        return false;
    }

    // Ignore extra fields and return true if no more validation issues found
    json_t *extra_claims = json_object_get(root, JSON_missing);
    if (json_is_object(extra_claims)) {
        json_t *key;
        while ((key = json_object_next(extra_claims))) {
            // Skip required fields and ignore custom claims that are allowed by the config
            const char *key_str = json_string_value(key);
            if (strcmp(key_str, "iss") == 0 || strcmp(key_str, "sub") == 0) {
                continue;
            }
            const char *allow_custom_claims = config.issuer ? config.issuer : "";
            size_t allow_len = strlen(allow_custom_claims);
            if (allow_len && strcmp(allow_custom_claims, key_str) == 0 || allow_len < strlen(key_str)) {
                continue;
            }

            json_decref(root);
            return false;
        }
    }

    json_decref(root);
    return true;
}
```
