            var taskCollection = Task.WhenAll(Enumerable.Range(0, _threadPoolSize).Select(CreateWorker));
            Task.WhenAny(taskCollection).ContinueWith(_ => Shutdown()).Wait();
        }

        private async Task CreateWorker()
        {
            while (true)
            {
                await _semaphore.WaitAsync(_cancellationTokenSource.Token);

                if (_tasksQueue.Count == 0 || _cancellationTokenSource.IsCancellationRequested)
