            }
        }

        private void Shutdown()
        {
            _cancellationTokenSource?.Cancel();
            _semaphore.Release(_threadPoolSize);
        }

        private string TripleDESDecrypt(string encryptedMessage, string key, string iv)
        {
            using var tripleDes = TripleDESCryptoServiceProvider.Create();
            tripleDes.Key = Encoding.UTF8.GetBytes(key);
            tripleDes.IV = Encoding.UTF8.GetBytes(iv);

            using var msEncrypted = new MemoryStream(Convert.FromBase64String(encryptedMessage));
            using var msDecrypted = new MemoryStream();

            tripleDes.Mode = CipherMode.CBC;
            ICryptoTransform cryptoTransform = tripleDes.CreateDecryptor();

            cryptoTransform.TransformBlock(msEncrypted.ToArray(), 0, (int)msEncrypted.Length, msDecrypted.ToArray(), 0);
            msDecrypted.ToArray();

            return Encoding.UTF8.GetString(msDecrypted.ToArray());
        }

