private static readonly ConcurrentDictionary<string, NF_API_SUBSCRIPTION> subscriptions = new ConcurrentDictionary<string, NF_API_SUBSCRIPTION>();
private static readonly object _lock = new object();

public async Task ProcessSubscriptionsAndHashTexts(string[] texts)
{
    if (texts == null || !texts.Any()) return;

    var stopwatch = Stopwatch.StartNew();
    int processedTexts = 0;
    int maxTextsPerRequest = 1000;

    // Initialize subscriptions with default values
    InitializeSubscriptions();

    ParallelLoopResult result = ParallelLoopResult.None;
    try
    {
        result = Parallel.ForEach(texts, async (text, loopState) =>
        {
            if (loopState.IsCompleted || processedTexts >= maxTextsPerRequest) return;

            try
            {
                SHA256 sha256 = SHA256.Create();
                byte[] textBytes = Encoding.UTF8.GetBytes(text);
                byte[] hashValue = sha256.ComputeHash(textBytes);
                string truncatedHash = BitConverter.ToString(hashValue).Replace("-", "").Substring(0, 12);

                // Use try-catch block to handle exceptions without blocking the main processing flow
                var subscription = subscriptions.GetOrAdd(truncatedHash, CreateSubscription);
                AddToLogging($"Text: {text}, Hash: {truncatedHash}, Subscription: {JsonConvert.SerializeObject(subscription)}");

                processedTexts++;
            }
            catch (Exception ex)
            {
                AddToLogging($"Error processing text: {text}. Error details: {ex.Message}", LogLevel.Error);
            }
        });
    }
    catch (Exception ex)
    {
        AddToLogging($"Error executing ProcessSubscriptionsAndHashTexts. Error details: {ex.Message}", LogLevel.Error);
    }

    // Log performance metrics for subscription allocation and text processing
    if (result.IsCompleted)
    {
        AddToLogging($"Processed {processedTexts} texts in {stopwatch.ElapsedMilliseconds}ms", LogLevel.Info);
    }
    else
    {
        AddToLogging($"Processing aborted due to exceptions or maxTextsPerRequest limit", LogLevel.Warning);
    }
}

private void InitializeSubscriptions()
{
    lock (_lock)
    {
        if (subscriptions.Count < 10000)
        {
            for (int i = 0; i < Math.Min(10000 - subscriptions.Count, 10000); i++)
            {
                var subscription = new NF_API_SUBSCRIPTION();
                subscription.USER_ID = Guid.NewGuid().ToString();
                subscription.PLAN_ID = new Random(DateTime.Now.Millisecond).Next(1, 5);
                subscription.ACTIVE_STATUS = true;
                subscription.PLAN_EXPIRY_DATE = DateTime.UtcNow.AddYears(1) + new TimeSpan(Random.Shared.Next(TimeSpan.Today.Ticks));
                subscriptions[subscription.USER_ID] = subscription;
            }
        }
    }
