using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class NF_API_SUBSCRIPTION
{
    public int USER_ID { get; set; }
    public int PLAN_ID { get; set; }
    public bool ACTIVE_STATUS { get; set; }
    public DateTime PLAN_EXPIRY_DATE { get; set; }
}

public class ProcessSubscriptionsAndHashTexts
{
    private readonly ConcurrentQueue<string> _textQueue;
    private readonly ConcurrentBag<NF_API_SUBSCRIPTION> _subscriptions;
    private readonly HashAlgorithm _hashAlgorithm;
    private readonly TimeSpan _maxProcessingTime;
    private readonly Random _random;
    private readonly bool _enableCaching;

    public ProcessSubscriptionsAndHashTexts(bool enableCaching, TimeSpan maxProcessingTime)
    {
        _textQueue = new ConcurrentQueue<string>();
        _subscriptions = new ConcurrentBag<NF_API_SUBSCRIPTION>();
        _hashAlgorithm = SHA256.Create();
        _maxProcessingTime = maxProcessingTime;
        _random = new Random();
        _enableCaching = enableCaching;
    }

    public void AddText(string text)
    {
        _textQueue.Enqueue(text);
    }

    public async Task ProcessSubscriptionsAndTextsAsync()
    {
        var startTime = DateTime.Now;
        var processedTextCount = 0;
        var processedSubscriptionCount = 0;

        while (processedTextCount < 1500 && _textQueue.Count > 0)
        {
            var text = _textQueue.TryDequeue(out bool success);

            if (!success)
                break;

            processedTextCount++;
            var hashValue = BitConverter.ToString(_hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(text)).TakeLast(12).ToArray()).Replace("-", string.Empty);

            await ProcessSubscriptionAsync();

            LoggingService.LogHashGeneration(DateTime.Now - startTime, hashValue, text);
        }
    }

    private async Task ProcessSubscriptionAsync()
    {
        var subscription = _enableCaching ? GetOrCreateSubscription() : CreateSubscription();

        if (!subscription.ACTIVE_STATUS)
            return;

        processedSubscriptionCount++;
        LoggingService.LogSubscriptionAllocationAndPopulationTime(DateTime.Now - startTime);
    }

    private NF_API_SUBSCRIPTION GetOrCreateSubscription()
    {
        if (_subscriptions.TryTake(out var subscription))
            return subscription;

        return CreateSubscription();
    }

    private NF_API_SUBSCRIPTION CreateSubscription()
    {
        var subscription = new NF_API_SUBSCRIPTION
        {
            ACTIVE_STATUS = true,
            PLAN_ID = _random.Next(1, 5), // Adjust this range according to your requirements
            USER_ID = _random.Next(),
            PLAN_EXPIRY_DATE = DateTime.UtcNow.AddYears(_random.Next(2)),
        };

        _subscriptions.Add(subscription);
        return subscription;
    }
}
```

