using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

public class HashGenerator
{
    private readonly ILogger<HashGenerator> _logger;
    private readonly IDatabase _redisDatabase;
    private const int MaxBatchSize = 1000;
    private const int MaxRequestsPerMinute = 10000;
    private const int MaxRetries = 3;
    private const int HashLength = 12;
    private static readonly TimeSpan RetryInterval = TimeSpan.FromSeconds(5);

    public HashGenerator(ILogger<HashGenerator> logger, IDatabase redisDatabase)
    {
        _logger = logger;
        _redisDatabase = redisDatabase;
    }

    public async Task ProcessHashesAsync(IEnumerable<string> inputs)
    {
        var batchInputs = inputs.Chunk(MaxBatchSize);
        var successfulHashes = new List<string>();
        var failedHashes = new List<string>();

        var stopwatch = Stopwatch.StartNew();
        var currentRequests = 0;

        await Task.WhenAll(batchInputs.Select(async batch =>
        {
            var hashBatch = await ProcessBatchAsync(batch);
            successfulHashes.AddRange(hashBatch.successfulHashes);
            failedHashes.AddRange(hashBatch.failedHashes);

            currentRequests += hashBatch.successfulHashes.Count() + hashBatch.failedHashes.Count();
            if (currentRequests >= MaxRequestsPerMinute)
            {
                await Task.Delay(TimeSpan.FromMinutes(1));
                currentRequests = 0;
            }
        }));

        await FlushLogsAsync();

        _logger.LogInformation($"Generated {successfulHashes.Count} successful hashes and {failedHashes.Count} failed hashes in {stopwatch.ElapsedMilliseconds} ms.");
    }

    private async Task<(IEnumerable<string>, IEnumerable<string>)> ProcessBatchAsync(IEnumerable<string> inputs)
    {
        var successfulHashes = new List<string>();
        var failedHashes = new List<string>();

        using (var hasher = SHA256.Create())
        {
            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
            await Parallel.ForEachAsync(inputs, options, async input =>
            {
                try
                {
                    var hash = BitConverter.ToString(hasher.ComputeHash(Encoding.UTF8.GetBytes(input)).Take(HashLength).ToArray()).Replace("-", "").ToLower();
                    _redisDatabase.StringSet($"hash:{hash}", input);
                    successfulHashes.Add(hash);
                }
                catch (Exception ex)
                {
                    failedHashes.Add(input + ":Error:" + ex.Message);

                    if (_logger.IsEnabled(LogLevel.Debug)) _logger.LogDebug($"Failed to generate hash for input: {input}. Error: {ex.Message}");

                    await Retry(failedHashes, ex);
                }
            });
        }

        return (successfulHashes, failedHashes);
    }

    private async Task Retry(IList<string> failedHashes, Exception exception)
    {
        for (int i = 0; i < MaxRetries && !failedHashes.Any(); i++)
        {
            await Task.Delay(RetryInterval);

            try
            {
                var retryBatch = failedHashes.Take(MaxBatchSize);
                await ProcessBatchAsync(retryBatch);
            }
            catch (Exception ex)
            {
                if (_logger.IsEnabled(LogLevel.Debug)) _logger.LogDebug($"Retry for hash generation failed: {exception.Message}. New error: {ex.Message}");
            }
        }
    }

    private async Task FlushLogsAsync()
    {
        var logs = new List<KeyValuePair<DateTime, LogEntry>>();

        while (true)
        {
            try
            {
                using (var connectionMultiplexer = ConnectionMultiplexer.Connect("localhost"))
                {
                    var logger = connectionMultiplexer.GetDatabase().CreateSubscriber<LogEntry>();

                    await Task.WhenAll(logger.GetMessagesAsync());

                    if (!logger.HasMessages) break;

                    logs.AddRange(logger.GetMessages().ToList());
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to connect to logging service: {ex.Message}");
            }
        }

        if (!logs.Any()) return;

        var logFile = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "logs", $"{DateTime.UtcNow:yyyy-MM-dd}.log");

        using (var writer = new StreamWriter(logFile, append: true))
        {
            foreach (var log in logs)
            {
                await writer.WriteAsync($"{log.Key}: {log.Value}\n");
            }
        }
    }
}

public struct LogEntry
{
    public DateTime Timestamp { get; set; }
    public string Message { get; set; }
}
