                var key = await RetrieveKeyAsync();
                var iv = await RetrieveIVAsync();

                using (var msKey = new MemoryStream(key))
                    using (var msIv = new MemoryStream(iv))
                        aes.Key = msKey.ToArray();
                        aes.IV = msIv.ToArray();

                // Handle multi-part messages by slicing the ciphertext and decrypting each part individually.
                var chunkSize = 1024;
                var parts = Enumerable.Range(0, ciphertext.Length / chunkSize + 1)
                    .Select(i => new ArraySegment<byte>(ciphertext, i * chunkSize, chunkSize))
                    .ToList();

                var plaintextParts = new List<ArraySegment<byte>>();
                foreach (var part in parts)
                {
                    using (var memoryStream = new MemoryStream())
                    {
                        using (var cryptoTransform = aes.CreateDecryptor(aes.Key, aes.IV))
                            using (var cs = new CryptoStream(part, cryptoTransform, CryptoStreamMode.Read))
                                cs.CopyTo(memoryStream);

                        plaintextParts.Add(new ArraySegment<byte>(memoryStream.ToArray()));
                    }
                }

                return string.Concat(plaintextParts);
            }
        }
        catch (Exception ex)
        {
            Log.Error("Decryption failed.", ex);
            throw;
        }
    }
