async function getFileContent(filePath) {
  if (/^https?:\/\//.test(filePath)) { // Remote file
    const response = await axios.get(filePath, { responseType: 'arraybuffer' });
    return response.data;
  } else {
    const promise = new Promise((resolve, reject) => {
      fs.readFile(filePath, (err, data) => {
        if (err) reject(err);
        resolve(data);
      });
    });
    return promise;
  }
}

async function computeMD5Hash(buffer) {
  const hash = crypto.createHash('md5');
  hash.update(buffer);
  return hash.digest('hex');
}

function validateHash(computedHash, expectedHash) {
  if (computedHash === expectedHash) return true;

  // Retry up to three times if hashes do not match
  for (let i = 1; i < 4; ++i) {
    logger.warn(`MD5 hash validation failed (${i}/3). Computed: ${computedHash}, Expected: ${expectedHash}`);
    if (computeMD5Hash(buffer) === expectedHash) return true;
  }

  logger.error(`MD5 hash validation repeatedly failed. Aborting processing for this file.`);
  return false;
}

async function processFile(filePath, expectedHash, logFile, messageSystemInstance, batchProcessorInstance) {
  try {
    const buffer = await getFileContent(filePath);
    const computedHash = await computeMD5Hash(buffer);

    if (validateHash(computedHash, expectedHash)) {
      logger.info(`Successfully processed file "${filePath}" with MD5 hash ${computedHash}.`);
      messageSystemInstance.sendMessage(`File "${filePath}" hashed successfully. MD5 Hash: ${computedHash}`);
    } else {
      throw new Error('MD5 hash validation failed');
    }
  } catch (err) {
    logger.error(`Error processing file "${filePath}": ${err.message}`);
    messageSystemInstance.sendMessage(`Error while hashing file "${filePath}". Error: ${err.message}`);
  } finally {
    batchProcessorInstance.decrementCounter();
  }
}

async function run() {
  let startTime = moment().valueOf();
  const filesToProcess = ['/path/to/local/file1.txt', 'https://example.com/remote-file.txt']; // Replace with the actual list of files to process
  batchProcessorInstance.processBatch(filesToProcess, async (filePath, logFile) => {
