      await processFile(filePath, '', logFile, messageSystemInstance, batchProcessorInstance);
    } catch (err) {
      logger.error(`Error processing file "${filePath}": ${err.message}`);
    }
  });

  // Simulate random delay before shutting down
  await new Promise(resolve => setTimeout(() => resolve(), Math.random() * 1000));

  const endTime = moment().valueOf();
  logger.info(`Finished processing all files in ${endTime - startTime}ms`);
  messageSystemInstance.sendMessage(`All files have been processed. Total execution time: ${endTime - startTime}ms`);
}

