use std::env;
use std::fs::{self, File, OpenOptions};
use std::io::{BufReader, Write};
use std::path::Path;
use rand::Rng;
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug)]
struct Record {
    key: i32,
}

fn main() {
    let config_dir = env::var("CONFIG_DIR").unwrap_or_else(|_| ".".to_string());
    let config_path = Path::new(&config_dir).join("config.toml");

    if !fs::metadata(config_path).is_ok() {
        fs::create_dir_all(config_dir)?;
        let mut file = OpenOptions::new()
            .write(true)
            .create(true)
            .open(config_path)?;
        write!(file, "[configuration]").unwrap();
    }

    let mut buf = Vec::new();
    {
        let file = BufReader::new(File::open(config_path).unwrap());
        file.read_to_end(&mut buf).unwrap();
    }

    let config: Configuration = toml::from_slice(&buf).unwrap();

    let offsets_len = config.offsets_size;
    let keys_len = config.keys_size;

    let mut offsets: Vec<i64> = vec![0; offsets_len];
    let mut keys: Vec<i32> = vec![0; keys_len];
    let mut records: Vec<Record> = vec![Record { key: 0 }; keys_len];

    let rng = rand::thread_rng();
    for i in 0..keys_len {
        records[i].key = rng.gen_range(1, 100);
    }

    // Save the updated configuration to disk.
    let mut file = OpenOptions::new()
        .write(true)
        .create(false)
        .open(config_path)?;
    toml::to_writer_pretty(&mut file, &Configuration {
        offsets: offsets.as_slice(),
        keys: keys.as_slice(),
        records,
    })
    .unwrap();
}

#[derive(Serialize, Deserialize)]
struct Configuration {
    offsets: Vec<i64>,
    keys: Vec<i32>,
    records: Vec<Record>,
}
