void initializeNfaApiIndications(size_t num_pdus) {
    if (num_pdus > 10000 || num_pdus == 0) {
        fprintf(stderr, "Error: Invalid number of PDUs. Support up to 10,000 structures.\n");
        return;
    }

    // Allocate the buffer if it's not already initialized or the requested size exceeds the current buffer size
    if (buffer_size < num_pdus) {
        void* new_buffer = realloc(pdu_buffer, num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) {
            fprintf(stderr, "Error: Failed to allocate memory for %zu PDUs. Current heap usage: %f MB\n", num_pdus, get_current_heap_usage() / (1024 * 1024));
            return;
