```java
import java.util.*;
import java.time.Instant;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class FileSystemUtil {
    public static List<FileInfo> generateFiles(int count, ExecutorService executor) {
        AtomicInteger idCounter = new AtomicInteger();
        List<Future<FileInfo>> tasks = new ArrayList<>();
        Callable<FileInfo> taskFactory = () -> {
            FileInfo fileInfo = new FileInfo(idCounter.getAndIncrement(), "file" + idCounter, Instant.now());
            fileInfo.setFileSize(calculateFileSize(fileInfo.getFileName()));
            return fileInfo;
        };

        for (int i = 0; i < count && tasks.size() < executor.getMaximumPoolSize(); ++i) {
            tasks.add(executor.submit(taskFactory));
        }

        List<FileInfo> results = new ArrayList<>();
        for (Future<FileInfo> task : tasks) {
            try {
                FileInfo fileInfo = task.get();
                if (fileInfo != null) {
                    results.add(fileInfo);
                }
            } catch (ExecutionException | InterruptedException e) {
                // Handle exceptions gracefully, like logging or retrying
            }
        }
        return results;
    }

    private static int calculateFileSize(String fileName) {
        return Math.max((int) (fileName.length() * 0.1), 20);
    }

    static class FileInfo {
        private final AtomicInteger fileID;
        private String fileName;
        private Instant lastModifiedTime;
        private int fileSize;

        public FileInfo(int fileID, String fileName, Instant lastModifiedTime) {
            this.fileID = new AtomicInteger(fileID);
            this.fileName = fileName;
            this.lastModifiedTime = lastModifiedTime;
        }

        // Setters and Getters for each field...
    }
}
```

