```c
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>

NFAPI_CRAC_INDICATION_PDU_T* load_and_deserialize(const char* filename, size_t* out_num_elements) {
    int fd = open(filename, O_RDONLY);
    struct stat st;
    fstat(fd, &st);
    size_t file_size = st.st_size;

    void* mapped_memory = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd, 0);

    if (mapped_memory == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    size_t num_elements = file_size / sizeof(NFAPI_CRAC_INDICATION_PDU_T);

    NFAPI_CRAC_INDICATION_PDU_T* array = malloc(num_elements * sizeof(NFAPI_CRAC_INDICATION_PDU_T));
    if (!array) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    memcpy(array, mapped_memory, num_elements * sizeof(NFAPI_CRAC_INDICATION_PDU_T));

    munmap(mapped_memory, file_size);
    close(fd);

    *out_num_elements = num_elements;
    return array;
}
```

