#include <time.h>

typedef struct {
    time_t timestamp;
    char interface[32];
    unsigned long long incoming_bytes;
    unsigned long long outgoing_bytes;
    float packet_loss;
} NetworkStat;

void log_error(const char *message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

unsigned long long total_byte_count(NetworkStat stats[], unsigned int size) {
    unsigned long long sum = 0;
    for (unsigned int i = 0; i < size; ++i) {
        sum += stats[i].incoming_bytes + stats[i].outgoing_bytes;
    }
    return sum;
}

int initialize_stats(NetworkStat stats[], unsigned int size, unsigned long long limit, FILE *log_file) {
    srand(time(NULL));
    for (unsigned int i = 0; i < size; ++i) {
        stats[i].timestamp = time(NULL);
        snprintf(stats[i].interface, sizeof(stats[i].interface), "%31s", rand_r(&i) % 26 + 'a');
        stats[i].incoming_bytes = rand() % (limit / size + 1);
        stats[i].outgoing_bytes = rand() % (limit / size + 1);
        stats[i].packet_loss = (float)(rand() % 101) / 100.0;
    }

    unsigned long long total = total_byte_count(stats, size);
    if (total > limit) {
        log_error("Exceeded specified byte count limit.");
        return -1;
    }
    return 0;
}
