#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
};

static struct node* head = NULL;
static unsigned int count = 0;
static const unsigned int max_structures = M;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void create_and_populate_list(unsigned int N) {
    if (N > max_structures) {
        N = max_structures;
    }

    pthread_mutex_lock(&list_mutex);
    struct node *current = head;
    unsigned int i;

    for (i = count; i < count + N; ++i) {
        if (!current) {
            current = malloc(sizeof(struct node));
            current->data.RX_UE_INFORMATION_TAG = i;
            current->data.RNTI = rand() % 10000 + 1; // RNTI should be within a reasonable range
            current->data.CRCFLAG = (rand() % 2 == 0) ? true : false;
            current->next = head;
            head = current;
        } else {
            for (struct node *prev = NULL, *temp = current; temp != NULL && i < count + N; prev = temp, temp = temp->next) {
                if (!prev || prev->data.RNTI != temp->data.RNTI) {
                    continue;
                }
                free(temp);
                current = prev;
                --i;
            }

            if (i == count + N) {
                struct node *new_node = malloc(sizeof(struct node));
                new_node->data.RX_UE_INFORMATION_TAG = i;
                new_node->data.RNTI = rand() % 10000 + 1; // RNTI should be within a reasonable range
                new_node->data.CRCFLAG = (rand() % 2 == 0) ? true : false;
                new_node->next = current->next;
                current->next = new_node;
            }
        }
    }

    pthread_mutex_unlock(&list_mutex);
}
```

