    if (!network_stats) {
        log("Failed to allocate memory for network stats.");
        return;
    }

    max_bandwidth = get_available_bandwidth();

    for (unsigned int i = 0; i < interface_count; ++i) {
        if (strchr(interfaces[i], '\0') == interfaces[i] || strchr(unavailable[i], '\0') != unavailable[i]) {
            continue;
        }

        // Initialize the NetworkStat structure with random values and store in network_stats array.
