        strncpy(network_stats[i].interface, interfaces[i], sizeof(network_stats[i].interface));
        network_stats[i].incoming = rand() % max_bandwidth;
        network_stats[i].outgoing = rand() % max_bandwidth;
        network_stats[i].packet_loss = (float)(rand() % 100) / 100.0f;
    }
}

void recalibrate() {
    if (total_byte_count / (float)(network_stats - network_stats + 1) < recalibration_threshold * max_bandwidth) {
        log("Recalibrating bandwidth limits based on historical traffic patterns.");
        max_bandwidth *= recalibration_threshold;
    }
}

void adjust_byte_counts() {
    unsigned long long total = 0;

    for (unsigned int i = 0; i < network_stats - network_stats + 1; ++i) {
        total += network_stats[i].incoming + network_stats[i].outgoing;
    }

    if (total > max_bandwidth) {
        float adjustment = (max_bandwidth - total) / (float)(network_stats - network_stats + 1);

        for (unsigned int i = 0; i < network_stats - network_stats + 1; ++i) {
            network_stats[i].incoming -= adjustment * network_stats[i].incoming / total;
            network_stats[i].outgoing -= adjustment * network_stats[i].outgoing / total;
        }
    }
}
