#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned int FLD;
    unsigned int protocol_version;
    time_t timestamp;
} packet_descriptor;

typedef struct queue_node {
    packet_descriptor data;
    struct queue_node* next;
} queue_node;

struct queue {
    unsigned int capacity;
    unsigned int count;
    queue_node *head;
    queue_node *tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full; // not full condition variable
    pthread_cond_t cond_not_empty; // not empty condition variable
};

void enqueue(struct queue* q, packet_descriptor data) {
    queue_node *new_node = (queue_node*)malloc(sizeof(queue_node));

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&q->mutex);

    if (q->count == q->capacity) { // queue is full, so drop the oldest packet
        queue_node *temp = q->head;
        while (q->count > 1 && temp->next != NULL) {
            q->head = temp = temp->next;
            free(temp->prev);
            --q->count;
        }
    }

    if (q->head == NULL) { // queue is empty
        q->head = q->tail = new_node;
    } else {
        q->tail->next = new_node;
        q->tail = new_node;
    }

    ++q->count;

    if (pthread_cond_signal(&q->cond_not_full) != 0) {
        perror("pthread_cond_signal");
    }
    pthread_mutex_unlock(&q->mutex);
}

int dequeue(struct queue* q, packet_descriptor* data) {
    if (q->count <= 0) return -1; // queue is empty

    pthread_mutex_lock(&q->mutex);

    *data = q->head->data;
    queue_node *temp = q->head;
    q->head = q->head->next;
    free(temp);

    --q->count;

    if (pthread_cond_signal(&q->cond_not_empty) != 0) {
        perror("pthread_cond_signal");
    }
    pthread_mutex_unlock(&q->mutex);

    return 0;
}

void queue_init(struct queue* q, unsigned int capacity) {
    q->capacity = capacity;
    q->count = 0;
    q->head = NULL;
    q->tail = NULL;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond_not_full, NULL);
    pthread_cond_init(&q->cond_not_empty, NULL);
}
```

This code defines a queue data structure and a function to initialize the queue. The enqueue function manages the concurrent access by locking the mutex before adding or removing elements from the queue. It also dynamically resizes the queue based on the specified capacity, dropping the oldest packet if necessary. The dequeue function retrieves the head of the queue and removes it.']

