    stat->outgoing = rand() % MAX_BYTE_COUNT;
    stat->packet_loss = (double)rand() / RAND_MAX * 100.0;
    stat->status = rand() % 2;

    if (stat->incoming + stat->outgoing > MAX_BYTE_COUNT) {
        log(LOG_ERROR, "Byte count limit exceeded: incoming=%lld outgoing=%lld", stat->incoming, stat->outgoing);
        return NULL;
    }

    // Adjust byte count distribution based on user preference (not implemented)

    return stat;
}

int init_stats(NetworkStat* stats, size_t count, size_t thread_count, long MAX_BYTE_COUNT) {
    pthread_t threads[thread_count];
    NetworkStat *stat;

    for (size_t i = 0; i < count; ++i)
        stats[i].incoming = stats[i].outgoing = 0;

    for (size_t t = 0; t < thread_count; ++t) {
        stat = &stats[(unsigned int)(t * (count / thread_count))];
        pthread_create(&threads[t], NULL, init_stat, stat);
    }

    for (size_t t = 0; t < thread_count; ++t) {
        pthread_join(threads[t], (void **)&stat);
        if (!stat) return -1; // Indicates byte count limit exceeded

        stats[stat->timestamp]->incoming += stat->incoming;
        stats[stat->timestamp]->outgoing += stat->outgoing;
    }

    return 0;
}
