        pdu = (LTE_PDCP_PDU_T*)realloc(pdu, sizeof(LTE_PDCP_PDU_T) * (i + 1));
        if (!pdu) {
            list_foreach_entry(&ctx->pdus, LTE_PDCP_PDU_T*, node)
                list_remove_entry(list_find(&ctx->pdus, LTE_PDCP_PDU_T*, node));
            free(pdu);
            EVP_CIPHER_CTX_free(cipher_context);
            dlclose(cipher_handle);
            free(ctx);
            perror("Error while reallocating memory for PDCP PDU");
            return NULL;
        }
        pdu->content = create_pdcp_pdu_content(); // Replace this with your own implementation to populate the content
    }

    if (i < K) {
