}

int init_sessions() {
    int i, max = config.max_sessions;

    if (!(sessions = malloc(sizeof(struct session) * max))) {
        perror("malloc");
        return 1;
    }

    for (i = 0; i < max; ++i) {
        sessions[i].duration = INT_MAX; // Set initial session duration to MAX_INT
    }

    return 0;
}

void free_sessions() {
    free(sessions);
    sessions = NULL;
}

int add_session(struct session* sess) {
    pthread_mutex_lock(&sessions_lock);

    // Check if max sessions limit is exceeded and handle the error condition
    if (get_num_active_sessions() >= config.max_sessions) {
        syslog(config.log_level, "ERROR: Maximum number of active sessions reached");
        pthread_mutex_unlock(&sessions_lock);
        return 1;
    }

    // Copy the session to the array and update its status
    memcpy(&sessions[get_num_active_sessions()], sess, sizeof(struct session));
    sessions[get_num_active_sessions()].status = true;
    pthread_mutex_unlock(&sessions_lock);

    return 0;
}

int update_session(int index, struct session* sess) {
    if (index >= config.max_sessions || index < 0)
        return 1;

    pthread_mutex_lock(&sessions_lock);
    memcpy(&sessions[index], sess, sizeof(struct session));
    pthread_mutex_unlock(&sessions_lock);

    return 0;
}

int remove_session(int index) {
    if (index >= config.max_sessions || index < 0)
        return 1;

    struct session* to_remove = &sessions[index];

    pthread_mutex_lock(&sessions_lock);
    memmove(&to_remove[index], &to_remove[index + 1], (config.max_sessions - index - 1) * sizeof(struct session));
    --config.max_sessions;
    pthread_mutex_unlock(&sessions_lock);

    free(to_remove);
    return 0;
}

int get_num_active_sessions() {
    int i, count = 0;

    for (i = 0; i < config.max_sessions; ++i)
        if (sessions[i].status)
            ++count;

    return count;
}
