import java.security.MessageDigest;
import java.util.Arrays;
import java.util.Concurrent.ThreadPoolExecutor;
import java.util.LinkedBlockingQueue;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.nio.charset.StandardCharsets;
import okhttp3.*;

public class Pokemon {
    private final String name;
    private final String type;

    public Pokemon(String name, String type) {
        this.name = name;
        this.type = type;
    }

    // getters for name and type
}

public class WeaknessService {
    private static ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newCachedThreadPool();
    private static OkHttpClient client = new OkHttpClient();

    public static String getWeaknessesForPokemon(Pokemon pokemon) {
        String url = "https://api.pokedex.com/weaknesses/" + pokemon.getType();
        Request request = new Request.Builder().url(url).build();

        Call call = client.newCall(request);
        Future<Response> future = executor.submit(() -> call.execute());

        try {
            Response response = future.get(10, TimeUnit.SECONDS);
            if (!response.isSuccessful()) {
                throw new IOException("Unexpected code " + response);
            }
            String body = response.body().string();
            Map<String, List<String>> weaknesses = JsonParser.parse(body).getAsJsonObject().getAsJsonArray("weaknesses").stream()
                    .collect(Collectors.toMap(JsonParser::getString, JsonParser::getListOfStrings));

            StringBuilder sb = new StringBuilder();
            for (String weakness : weaknesses.getOrDefault("critical", Collections.emptyList())) {
                sb.append(weakness).append(", ");
            }
            for (String weakness : weaknesses.getOrDefault("non-critical", Collections.emptyList())) {
                sb.append(weakness).append(", ");
            }
            return sb.substring(0, sb.length() - 2);
        } catch (ExecutionException | InterruptedException | IOException e) {
            // log error details for debugging purposes
            throw new RuntimeException("Failed to fetch weaknesses", e);
        }
    }

    private static String md5(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            digest.update(input.getBytes(StandardCharsets.UTF_8));
            byte[] hash = digest.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 not supported", e);
        }
    }
}
