    pq->lock = PTHREAD_MUTEX_INITIALIZER;
    pq->not_empty = PTHREAD_COND_INITIALIZER;
    pq->sem_capacity = sem_init(0, 1, capacity);
    if (pq->sem_capacity == SEM_FAILED) {
