public class IoTDataStreamingPlatform {
    private static final int MAX_DEVICES = 10000;
    private static final double ACCURACY_RATE = 0.75;
    private static final Random RANDOM = new Random();
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final ConcurrentHashMap<String, TemperatureData> cache = new ConcurrentHashMap<>();

    public static void main(String[] args) {
