        int count = Math.min(MAX_DEVICES, Runtime.getRuntime().availableProcessors());
        List<TemperatureData> dataList = new ArrayList<>(count);
        AtomicInteger successCount = new AtomicInteger();
        AtomicInteger failureCount = new AtomicInteger();

        Runnable worker = () -> {
            while (true) {
                TemperatureData tempData = new TemperatureData(generateSensorID(), generateTemperature(), new Date());
                if (cache.putIfAbsent(tempData.getSensorID(), tempData) == null) {
                    successCount.incrementAndGet();
                    // Kafka producer publish (omitted for brevity)
                } else {
                    failureCount.incrementAndGet();
                }
            }
        };

        for (int i = 0; i < count; i++) {
            executor.submit(worker);
        }

        // Wait for workers to finish (graceful shutdown)
        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.HOURS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Successfully created and populated " + successCount + " temperature data objects.");
        System.out.println("Failed to create or populate " + failureCount + " temperature data objects.");
    }

    private static String generateSensorID() {
        // Implement unique sensor ID generation (omitted for brevity)
    }

    private static double generateTemperature() {
        double temp = RANDOM.nextDouble();
        return (temp <= ACCURACY_RATE) ? (RANDOM.nextInt(50) + 25) : RANDOM.nextInt(100);
    }
}

