            exit(1);
        }
        size_t read = fread(line + line_size, 1, 4096, file);
        if (read > 0) {
            line_size += read;
            data[fgetc(file) % num_threads].line = line;
            data[fgetc(file) % num_threads].line_len = line_size;
        }
    }

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_line, &data[i])) {
            perror("Error creating thread");
            exit(1);
