#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>
#include <openssl/sha.h>

typedef struct {
    char *name;
    char types[2];
    int stats[10]; // Variable length, can be adjusted as needed
} Pokemon;

typedef struct {
    void (*process_func)(Pokemon*);
    FILE *file;
    size_t entry_size;
    pthread_mutex_t lock;
} ProcessData;

void process_pokemon(Pokemon *pokemon) {
    int sum = 0;
    for (int i = pokemon->stats + 5; i < pokemon->stats + 10; ++i)
        sum += *(int *)i;

    printf("%s: Type: %c%c, Average Stats: %d\n", pokemon->name, pokemon->types[0], pokemon->types[1], sum / 5);
}

void *load_pokemon(void *arg) {
    ProcessData *data = arg;
    char *buffer = mmap(NULL, data->entry_size, PROT_READ, MAP_PRIVATE, fileno(data->file), 0);

    if (!buffer) {
        perror("mmap");
        return NULL;
    }

    Pokemon *pokemon = malloc(sizeof(Pokemon));
    pokemon->name = strndup((char *)buffer, data->entry_size - offsetof(Pokemon, stats));
    memcpy(pokemon->types, buffer + strlen(pokemon->name), 2);
    memcpy((void *)(pokemon->stats), buffer + offsetof(Pokemon, types) + 2, (data->entry_size - offsetof(Pokemon, stats)) - sizeof(pokemon->types));

    pthread_mutex_lock(&data->lock);
    data->process_func(pokemon);
    free(pokemon->name);
    free(pokemon);
    munmap(buffer, data->entry_size);
    pthread_mutex_unlock(&data->lock);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <binary_file>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "rb");
    if (!file) {
        perror("fopen");
        return 1;
    }

    fseek(file, 0, SEEK_END);
    size_t entry_size = ftell(file);
    rewind(file);

    ProcessData data = { .process_func = process_pokemon, .file = file, .entry_size = entry_size };
    pthread_mutex_init(&data.lock, NULL);

    size_t num_threads = sysconf(_SC_NPROCESSORS_ONLN);
    pthread_t threads[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, &load_pokemon, &data)) {
            perror("pthread_create");
            return 1;
        }
    }

    for (size_t i = 0; i < num_threads; ++i)
        if (pthread_join(threads[i], NULL)) {
            perror("pthread_join");
            return 1;
        }

    fclose(file);
    pthread_mutex_destroy(&data.lock);
    return 0;
}
