    uint64_t in_bytes, out_bytes;
    double packet_loss;
} NetStat;

struct sys_data {
    uint64_t bandwidth_limit;
    pthread_mutex_t lock;
    semaphore_t mem_alloc_sem; // Semaphore to control memory usage
};

void init_sys_data(struct sys_data *sys_data, uint64_t bandwidth_limit) {
    pthread_mutex_init(&sys_data->lock, NULL);
    sem_init(&sys_data->mem_alloc_sem, 0, 1); // Allow one allocation at a time
    sys_data->bandwidth_limit = bandwidth_limit;
}

NetStat* create_netstat() {
    NetStat *ns = malloc(sizeof(NetStat));
    if (!ns) return NULL;
    memset(ns, 0, sizeof(NetStat));
    return ns;
}

void destroy_netstat(NetStat **ns) {
    free(*ns);
    *ns = NULL;
}

uint64_t get_total_bytes(NetStat** stats, size_t len) {
    uint64_t total_in = 0, total_out = 0;
    for (size_t i = 0; i < len; ++i) {
        total_in += ((NetStat*)stats[i])->in_bytes;
        total_out += ((NetStat*)stats[i])->out_bytes;
    }
    return total_in + total_out;
}

void populate_netstats(NetStat** stats, size_t len, struct sys_data *sys_data) {
    uint64_t total_limit = sys_data->bandwidth_limit * len;
    sem_wait(&sys_data->mem_alloc_sem); // Lock memory allocation
    for (size_t i = 0; i < len; ++i) {
        time_t timestamp = time(NULL);
        if (!getifaddrs_r(getifindex("eth"[i % 10]), &((*stats)[i]), sizeof(((NetStat*)0)->interface), RTAX_NAME)) {
            strncpy(((NetStat*)(*stats)[i])->interface, ((struct ifaddrs *)((*stats)[i]))->ifa_name, IF_NAMESIZE - 1);
        }

        ((NetStat*)(*stats)[i])->timestamp = timestamp;

        // Generate random byte counts within specified ranges
        ((NetStat*)(*stats)[i])->in_bytes = rand() % (50 + 5 * i) + 50;
        ((NetStat*)(*stats)[i])->out_bytes = rand() % (75 + 5 * i) + 75;

        // Calculate packet loss percentage based on simulated network conditions
        int connections = rand() % (i+1);
        double load = (double)(connections + rand() % (10 * i)) / (100 * (i+1));
        ((NetStat*)(*stats)[i])->packet_loss = 5 * (load > 0.8 ? 1 : load) * connections;

        // Check if the total byte count across all interfaces does not exceed the predefined bandwidth limit
        if (get_total_bytes(stats, len) > total_limit) {
            printf("Error: Bandwidth limit exceeded. Notifying administrator.\n");
            sys_data->notify_admin(); // Callback function to notify system administrator
            sem_post(&sys_data->mem_alloc_sem); // Unlock memory allocation
            return;
        }
    }
    sem_post(&sys_data->mem_alloc_sem); // Unlock memory allocation
}

