["```javascript
const fs = require('fs-extra');
const path = require('path');
const writeTextFileSync = require('fs-extra').writeFileSync;

const processLimit = 100; // Limit the number of files processed in a single run
let currentProcessCount = 0;

function readFiles(dirPath, fileExtension, logFile) {
    const results = [];
    const files = fs.readdirSync(dirPath);

    files.forEach((file) => {
        if (currentProcessCount >= processLimit) return; // Limit the number of files processed in a single run

        currentProcessCount++;
        const filePath = path.join(dirPath, file);
        const stats = fs.lstatSync(filePath);

        if (stats.isDirectory()) {
            readFiles(filePath, fileExtension, logFile); // Recursively process directories
        } else if (path.extname(filePath) === `.\${fileExtension}`) {
            results.push(file);
        }

        currentProcessCount--;
    });

    // Handle potential errors and log them to the errorLog.txt file
    files.forEach((file) => {
        try {
            const filePath = path.join(dirPath, file);
            const stats = fs.lstatSync(filePath);

            if (stats.isDirectory()) {
                readFiles(filePath, fileExtension, logFile);
            } else if (path.extname(filePath) !== `.\${fileExtension}`) {
                // Log error to the errorLog.txt file
                const errorMessage = `${new Date().toISOString()} - Invalid file extension for ${filePath}\n`;
                writeTextFileSync(logFile, errorMessage, { flag: 'a' });
            }
        } catch (error) {
            // Log error to the errorLog.txt file
            const errorMessage = `${new Date().toISOString()} - ${filePath}: ${error}\n`;
            writeTextFileSync(logFile, errorMessage, { flag: 'a' });
        }
    });

    return results;
}

module.exports = readFiles;
```

In this example, the `readFiles()` function takes a directory path, a file extension, and an error log file as parameters. It reads all files in the specified directory (including subdirectories) synchronously using the `fs-extra` library's `readdirSync()` method.

The function limits the number of files processed concurrently by keeping track of the current number of files being processed and only processing additional files when the count is below the defined limit. This prevents resource exhaustion when dealing with large directories containing thousands of files.

Errors encountered during the process, such as invalid file extensions or other file system errors, are caught and logged to a separate `errorLog.txt` file for further investigation."]

