  if (cache.get(cacheKey)) return cache.get(cacheKey);

  let metadata;
  try {
    // Call the metadata service API with rate limiting and fallback strategy
    metadata = await callMetadataService(filePath);
    // Store the metadata in cache for future use
    cache.set(cacheKey, metadata);
