  const cacheKey = `metadata:${filePath}`;
  if (cache.get(cacheKey)) return cache.get(cacheKey);

  let metadata;
  const startTime = Date.now();
  let attempts = config.apiRateLimit;

  while (attempts > 0) {
    try {
      const response = await axios.get(`${config.apiUrl}/file/${encodeURIComponent(filePath)}`);
      metadata = response.data;
      break;
    } catch (error) {
      if (error.response && error.response.status === 429) { // Rate limit exceeded
        await new Promise((resolve) => setTimeout(resolve, attempts * 1000));
        attempts -= 1;
      } else {
        throw error;
      }
    }
    attempts--;
  }

  if (!metadata) metadata = getLocalMetadata(filePath); // Fallback to local metadata when service is unavailable

  logger.debug(`Fetched metadata from metadata service: ${JSON.stringify(metadata)}\nTime elapsed: ${Date.now() - startTime}ms`);
  return metadata;
}

