        await config.backoffStrategy();
        return processContent(fileData);
      } else {
        console.error(`Failed to process file ${fileData.filePath}:`, error);
      }
    }
  };

  const readFilesInParallel = eachLimit(processFile, config.concurrency);
  const contentWithPaths = await series(readFilesInParallel, parallel(processContent));

  // Batch processing of results
  const batchedResults = _.chunk(contentWithPaths, Math.ceil(contentWithPaths.length / 100));

  // Return the final results
  return Promise.all(batchedResults.map((batch) =>
    fs.writeFile(`results-${Date.now()}.json`, JSON.stringify(_.map(batch, 'content')))
  ));
}

