        if (strcmp(action, "create") == 0 || strcmp(action, "update") == 0) {
            if (!Validate(request)) {
                response = CreateResponse("Invalid request", 1);
            } else {
                response = Save(request) ? CreateResponse("Success", 0) : CreateResponse("Database error", 2);
            }
        } else if (strcmp(action, "delete") == 0) {
            // Implement delete user account logic here
            response = CreateResponse("Deleted", 3);
        }

        // Handle errors and report performance metrics
        if (!response) {
            logError("Failed to process request");
            continue;
        }

        json_object* metrics = collectMetrics();
        logMetrics(metrics);

        // Dispatch the response back to the client
