long long total_bytes = 0;
int num_interfaces, bandwidth_limit, sample_freq, log_interval, flush_interval;
pthread_mutex_t stats_mutex;
time_t last_log, last_flush;

// Function to initialize array and start data collection
void init_network_stats() {
    // Calculate number of interfaces based on bandwidth limit and sample frequency
    num_interfaces = (bandwidth_limit * 8) / sample_freq; // Assuming 8 bits per byte

    // Allocate memory for the array and initialize other variables
    stats = malloc(num_interfaces * sizeof(NetworkStat));
    if (!stats) {
        printf("Error: Failed to allocate memory for network statistics.\n");
        exit(1);
    }
    pthread_mutex_init(&stats_mutex, NULL);
    last_log = last_flush = 0;
}

// Function to collect data from network interfaces
void collect_network_data() {
    // Simulate real-time data collection and adjust byte counts gracefully
    static long long total_bytes_prev = 0;
    for (int i = 0; i < num_interfaces; ++i) {
        // Collect sample data (replace with actual network APIs or functions as needed)
        NetworkStat *stat = &stats[i];
        stat->timestamp = time(NULL);
        snprintf(stat->interface, sizeof(stat->interface), "Interface%d", i + 1);
        stat->incoming_bytes = rand() % bandwidth_limit / 8;
        stat->outgoing_bytes = rand() % bandwidth_limit / 8;
        stat->packet_loss = (float)rand() / RAND_MAX * 0.01; // Simulate packet loss

        total_bytes += stat->incoming_bytes + stat->outgoing_bytes;

        // Adjust byte counts to fit within the bandwidth limit
        if (total_bytes > bandwidth_limit) {
            long long adjustment = total_bytes - bandwidth_limit;
            for (int j = i; j >= 0; --j) {
                NetworkStat *adj_stat = &stats[j];
                adj_stat->incoming_bytes -= adjustment / num_interfaces;
                adj_stat->outgoing_bytes -= adjustment / num_interfaces;
                total_bytes -= 2 * adjustment / num_interfaces;
            }
        }
    }
}

// Function to handle logging and data flushing
void handle_data() {
    time_t current_time = time(NULL);
    if (current_time - last_log >= log_interval) {
        printf("Log: Bandwidth limit: %lld, Sampling frequency: %d, Total bytes: %lld\n",
