/* Define structure for network statistics */
struct net_stats {
    time_t timestamp;
    char interface[32];
    long long incoming_bytes;
    long long outgoing_bytes;
    float packet_loss;
};

/* Global variables */
#define MAX_INTERFACES 10
struct net_stats interfaces[MAX_INTERFACES];
long long total_bytes = 0;
long long bandwidth_limit;
pthread_mutex_t bandwidth_lock;

void adjust_byte_counts(long long *incoming, long long *outgoing) {
    double scale = (double)bandwidth_limit / total_bytes;
    *incoming *= scale;
    *outgoing *= scale;
}

/* Function to simulate real-time data collection */
void collect_data(int index) {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    long load = (long)(usage.ru_utime.tv_sec + usage.ru_stime.tv_sec);
    if (load > 80) return; // Adjust sampling frequency based on system load

    struct net_stats *stat = &interfaces[index];
    time_t now = time(NULL);
    stat->timestamp = now;
    sprintf(stat->interface, "iface%d", index);

    /* Simulate network activity */
    static unsigned seed = 123456789;
    long long byte_counts[2] = { (rand_r(&seed) % 100 + 100), (rand_r(&seed) % 100 + 100) };
    total_bytes += byte_counts[0] + byte_counts[1];
    pthread_mutex_lock(&bandwidth_lock);
    adjust_byte_counts(byte_counts, byte_counts + 1);
    total_bytes -= byte_counts[0] + byte_counts[1];
    pthread_mutex_unlock(&bandwidth_lock);

    stat->incoming_bytes = byte_counts[0];
    stat->outgoing_bytes = byte_counts[1];
    stat->packet_loss = (rand_r(&seed) % 5 + 5) / 10.0;

    /* Integrate with logging framework */
    log_network_stat(stat);
}

/* Main function to initialize and populate network statistics array */
void init_network_stats() {
    srand(time(NULL));
    bandwidth_limit = 1000000; // Set initial bandwidth limit (bytes)
    pthread_mutex_init(&bandwidth_lock, NULL);

    for (int i = 0; i < MAX_INTERFACES; ++i) {
        collect_data(i);
    }
}

