#include <ethtools/eth.h> // Include necessary Ethernet header structure

typedef struct {
    eth_addr_t dest_mac;
    eth_addr_t src_mac;
    uint16_t ethertype;
    uint8_t *data;
    size_t data_len;
} MAC_PACKET_T;

struct buffer {
    MAC_PACKET_T **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

MAC_PACKET_T* generate_packet(void) {
    MAC_PACKET_T *packet = malloc(sizeof(MAC_PACKET_T));
    if (!packet) return NULL;

    eth_addr_random(&packet->dest_mac);
    eth_addr_copy(&packet->src_mac, &eth_broadcast());
    packet->ethertype = htons(0x89ab); // Replace with your desired ethertype value
    packet->data = calloc(1, 4096); // Adjust buffer size as needed
    if (!packet->data) {
        free(packet);
        return NULL;
    }

    // Implement verification of the integrity of the packet headers here

    packet->data_len = 4096; // Set an initial payload length
    return packet;
}

struct buffer* generate_packets(size_t num_packets) {
    struct buffer *buffer = malloc(sizeof(struct buffer));
    if (!buffer) return NULL;

    buffer->packets = calloc(num_packets, sizeof(MAC_PACKET_T *));
    if (!buffer->packets) {
        free(buffer);
        return NULL;
    }

    buffer->capacity = num_packets;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);

    for (size_t i = 0; i < num_packets && generate_packet(); ++i) {
        buffer->packets[i] = generate_packet();
        if (!buffer->packets[i]) break;
        pthread_mutex_lock(&buffer->mutex);
        buffer->count++;
        pthread_mutex_unlock(&buffer->mutex);
    }

    return buffer;
}

struct buffer* generate_safe_packets(size_t num_packets, size_t *error_count) {
    struct buffer *buffer = generate_packets(num_packets);
    if (!buffer) return NULL;

    size_t total_success = 0;
    for (size_t i = 0; i < num_packets; ++i) {
        if (buffer->packets[i]) total_success++;
        else ++*error_count;
    }

    if (*error_count == num_packets) {
        free(buffer);
        return NULL;
    }

    return buffer;
}
