// Global variables for synchronization
pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t num_records = 0;
DATA_RECORD_T* data_array = NULL;

int generate_data_array(size_t max_records, size_t* out_num_records) {
    // Allocate memory for the array and synchronize access with a mutex
    if (data_array != NULL) pthread_mutex_destroy(&array_mutex);
    data_array = malloc(max_records * sizeof(DATA_RECORD_T));
    if (data_array == NULL) {
        perror("Failed to allocate memory");
        return 1;
    }
    pthread_mutex_init(&array_mutex, NULL);

    // Create a thread pool to generate data concurrently
    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    if (threads == NULL) {
        free(data_array);
        perror("Failed to allocate memory for threads");
        return 1;
    }

    // Launch worker threads and pass in the maximum number of records as an argument
    size_t num_threads = sysconf(_SC_NPROCESSORS_CONF);
    for (size_t i = 0; i < num_threads; ++i) {
        int err = pthread_create(&threads[i], NULL, worker_thread, (void*)max_records);
        if (err != 0) {
            perror("Failed to create thread");
            free(data_array);
            free(threads);
            return 1;
        }
    }

    // Wait for all threads to finish and count the number of records generated
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    *out_num_records = num_records;
    free(threads);
    return 0;
}

void* worker_thread(void* arg) {
    size_t max_records = *(size_t*)arg;
    for (size_t i = 0; i < max_records; ++i) {
        DATA_RECORD_T* record = &data_array[num_records++];
        // Generate a unique ID, timestamp, event type, and processing status
        snprintf(record->id, sizeof(record->id), "%lu", time(NULL));
        record->timestamp = time(NULL);
        record->event_type = (enum { EVENT_TYPE_A, EVENT_TYPE_B, EVENT_TYPE_C })rand() % 3;
        record->processing_status = PROCESSING_STATUS_IDLE;

        // Fetch and process payload data from an external database or API
        void* payload = fetch_payload();
        if (payload == NULL) continue;

        // Verify the integrity of the payload data before storing it
        if (!validate_payload(payload)) {
            free(payload);
            continue;
        }

        // Compress the payload for efficient storage and transmission
        unsigned long compressed_length;
        char* compressed_payload = compress2((Bytef*)payload, strlen((char*)payload), &compressed_length, Z_DEFAULT_COMPRESSION);

        // Store the compressed payload in the data record
        record->payload = malloc(compressed_length + 1);
        memcpy(record->payload, compressed_payload, compressed_length);
        ((char*)record->payload)[compressed_length] = '\0';

        // Lock the array and update the number of records generated
        pthread_mutex_lock(&array_mutex);
        num_records++;
        pthread_mutex_unlock(&array_mutex);
    }
    return NULL;
}

