typedef struct PHY_FRAME_INFO_T {
    uint32_t frame_index;
} PHY_FRAME_INFO_T;

typedef struct PHY_STATS_T {
    int signal_strength; // Range: -100 to 50 (dBm)
    float error_rate;   // Range: 0.0 to 1.0
} PHY_STATS_T;

typedef struct LTE_PHY_FRAME_BUFFER_T {
    PHY_FRAME_INFO_T phy_frame_info;
    PHY_STATS_T phy_stats;
} LTE_PHY_FRAME_BUFFER_T;

int initialize_lte_phy_buffer(LTE_PHY_FRAME_BUFFER_T **buffer, size_t N) {
    if (!buffer || N <= 0) {
        return -1; // Invalid input
    }

    *buffer = (LTE_PHY_FRAME_BUFFER_T*) malloc(N * sizeof(LTE_PHY_FRAME_BUFFER_T));
    if (!*buffer) {
        return -2; // Allocation failure
    }

    srand(time(NULL));

    bool *used = calloc(N, sizeof(bool));
    if (!used) {
        free(*buffer);
        return -2; // Allocation failure for used array
    }

    int i = 0;
    for (size_t n = 0; n < N; ++n) {
        while (used[i]) {
            ++i;
            if (i >= N) {
                i = 0;
            }
        }
        used[i] = true;

        LTE_PHY_FRAME_BUFFER_T *buf = &(*buffer)[n];
        buf->phy_frame_info.frame_index = ++i;

        buf->phy_stats.signal_strength = (rand() % 101) - 50;
        buf->phy_stats.error_rate = ((float)(rand() % 100)) / 100.0f;
    }

    free(used);

    // Verify integrity of allocated memory
    for (size_t n = 0; n < N; ++n) {
        LTE_PHY_FRAME_BUFFER_T *buf = &(*buffer)[n];
        if (!buf || !buf->phy_frame_info.frame_index || used[buf->phy_frame_info.frame_index - 1]) {
            free(*buffer);
            return -3; // Memory integrity failure
        }
    }

    return 0;
}
