    if (!valid) {
        pthread_mutex_unlock(&list->mutex);
        return ERROR_CODE_INVALID_INPUT;
    }

    list->data[list->size] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *list->data[list->size] = *data;
    // Generate a random CRCFLAG for this structure here
    (*list->data[list->size]).CRC_INDICATION_REL8_TAG.crcFlag = rand() % 2;

    qsort(list->data, list->size + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*), compare_rnti);
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return ERROR_CODE_SUCCESS;
}

void resize_list(crc_list* list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T** new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (new_data == NULL) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    list->capacity = new_capacity;
    list->data = new_data;
}
