#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTIS (1 << 16) // Maximum possible RNTI value

// Generate pseudo-random CRCFLAG
uint8_t generate_pseudo_random(uint32_t seed) {
    uint32_t x = seed + time(NULL);
    return (x >> 16) ^ (x & 0xFFFF);
}

// Function to checksum validation
int validate_checksum(NFAPI_CRC_INDICATION_PDU_T* buffer, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; ++i)
        sum += buffer[i].crcflag + buffer[i].rnti + buffer[i].tag + buffer[i].crc_indication;
    return (sum & 0xFF) == 0;
}

// Caching mechanism using a hashmap
typedef struct hashmap {
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T** data;
    pthread_mutex_t lock;
} HashMap;

HashMap* new_hashmap(size_t size) {
    HashMap* map = malloc(sizeof(HashMap));
    map->size = size;
    map->data = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    map->lock = PTHREAD_MUTEX_INITIALIZER;
    return map;
}

void free_hashmap(HashMap* map) {
    for (size_t i = 0; i < map->size; ++i)
        free(map->data[i]);
    free(map->data);
    free(map);
}

// Hash function using RNTI value as key
size_t hash(uint32_t rnti) {
    return rnti % map->size;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_hashmap(HashMap* map, uint32_t rnti) {
    pthread_mutex_lock(&map->lock);
    for (size_t i = 0; i < map->size; ++i) {
        if (map->data[hash(rnti + i)] && map->data[hash(rnti + i)]->rnti == rnti) {
            pthread_mutex_unlock(&map->lock);
            return map->data[hash(rnti + i)];
        }
    }
    pthread_mutex_unlock(&map->lock);
    return NULL;
}

void put_in_hashmap(HashMap* map, uint32_t rnti, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&map->lock);
    size_t index = hash(rnti);
    if (!map->data[index])
        map->data[index] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    map->data[index]->rnti = rnti;
    map->data[index] = data;
    pthread_mutex_unlock(&map->lock);
}

// Function to allocate and populate the array of structures
NFAPI_CRC_INDICATION_PDU_T* create_pdus(HashMap* cache, size_t N, uint32_t seed) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus)
        return NULL;

    for (size_t i = 0; i < N; ++i) {
        uint32_t rnti = i + 1; // Ensure unique RNTI values
        pdus[i].tag.value = i % MAX_RNTIS;
        pdus[i].rnti = rnti;
        pdus[i].crc_indication.value = (i / MAX_RNTIS) % MAX_RNTIS;
        pdus[i].crcflag = generate_pseudo_random(seed + rnti);

        NFAPI_CRC_INDICATION_PDU_T* cached_data = get_from_hashmap(cache, rnti);
        if (cached_data) { // Update cached data instead of creating a new one
            *pdus[i] = *cached_data;
            put_in_hashmap(cache, rnti, &pdus[i]);
        } else {
            // Create and cache the data if it doesn't exist in the hashmap
            put_in_hashmap(cache, rnti, &pdus[i]);
        }
    }

    return pdus;
}
