```cpp
#include <openssl/evp.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>
#include <iostream>
#include <vector>
#include <string>
#include <cstddef>
#include <cstring>
#include <memory>
#include <functional>

namespace aes {

class AESEncryptor {
public:
    // Constructor, initializes EVP_CIPHER_CTX, PBKDF2 context and sets the number of iterations.
    explicit AESEncryptor(int iterations) : iterations_(iterations), key_(nullptr), iv_(nullptr), ctx_(nullptr) {}

    // Destructor frees resources allocated by the cipher context.
    ~AESEncryptor() {
        if (ctx_) EVP_CIPHER_CTX_free(ctx_);
        if (key_) EVP_cleanup();
    }

    // Initializes the encryptor with a user-provided password, derives a key and generates a new IV.
    bool init(const std::string& passwd) {
        if (!deriveKey(passwd)) return false;
        if (!generateIV()) return false;
        ctx_ = EVP_CIPHER_CTX_new();
        if (!ctx_) return false;
        return true;
    }

    // Encrypts a single message and appends the resulting ciphertext to 'ciphertext'.
    bool encrypt(const std::string& msg, std::vector<uint8_t>& ciphertext) const {
        if (!ctx_) return false;
        int len = msg.length();
        if (len <= 0) return true;

        EVP_EncryptInit_ex(ctx_, EVP_aes_256_cbc(), key_.get(), iv_.data());
        EVP_EncryptUpdate(ctx_, ciphertext.data(), &ciphertext.size(), reinterpret_cast<const uint8_t*>(msg.c_str()), len);
        ciphertext.resize(EVP_CIPHER_CTX_ctrl(ctx_, EVP_CTRL_CC_GET_OUTPUT_LEN, 0));
        EVP_EncryptFinal_ex(ctx_, nullptr, nullptr);
        EVP_EncryptUpdate(ctx_, ciphertext.data() + EVP_CIPHER_CTX_ctrl(ctx_, EVP_CTRL_CC_GET_OUTPUT_LEN, 0), &ciphertext.size() - (ciphertext.data() + EVP_CIPHER_CTX_ctrl(ctx_, EVP_CTRL_CC_GET_OUTPUT_LEN, 0) - ciphertext.data()));
        return true;
    }

    // Decrypts a single message and appends the resulting plaintext to 'plaintext'.
    bool decrypt(const std::vector<uint8_t>& ciphertext, std::string& plaintext) const {
        if (!ctx_) return false;
        int len = ciphertext.size();
        if (len <= 0) return true;

        EVP_DecryptInit_ex(ctx_, EVP_aes_256_cbc(), key_.get(), iv_.data());
        EVP_DecryptUpdate(ctx_, nullptr, nullptr, ciphertext.data(), len);
        plaintext.resize(EVP_CIPHER_CTX_ctrl(ctx_, EVP_CTRL_CC_GET_OUTPUT_LEN, 0));
        EVP_DecryptFinal_ex(ctx_, reinterpret_cast<uint8_t*>(plaintext.data()), nullptr);
        plaintext.resize(EVP_CIPHER_CTX_ctrl(ctx_, EVP_CTRL_CC_GET_OUTPUT_LEN, 0));
        return true;
    }

private:
    int iterations_;
    std::unique_ptr<uint8_t[]> key_;
    std::unique_ptr<uint8_t[]> iv_;
    EVP_CIPHER_CTX* ctx_;

    // Derives a strong encryption key from a user-provided password using PBKDF2.
    bool deriveKey(const std::string& passwd) {
        auto pass = reinterpret_cast<const char*>(passwd.c_str());
        unsigned char hash[EVP_MAX_MD_SIZE];
        size_t len;
        if (PBKDF2_HMAC((ENGINE*)NULL, pass, passwd.length(), iterations_, EVP_sha512(), hash, sizeof(hash), &len) <= 0) return false;
        key_.reset(new uint8_t[len]);
        std::memcpy(key_.get(), hash, len);
        return true;
    }

    // Generates a new, random initialization vector (IV) for each encryption operation.
    bool generateIV() {
        if (RAND_bytes(iv_.release(), EVP_CIPHER_CTX_block_size(EVP_aes_256_cbc())) <= 0) return false;
        return true;
    }
};
} // namespace aes
```

