};

// Memory pool structure definition
struct MEMORY_POOL_T {
    void* memory_block;
    size_t allocated_size;
    struct MEMORY_POOL_T* next;
};

// Global variables for memory and lock management
pthread_mutex_t mem_pool_lock = PTHREAD_MUTEX_INITIALIZER;
struct MEMORY_POOL_T* free_memory_list = NULL;
size_t memory_block_size = sizeof(struct VIDEO_STREAM_FRAME_T);

// Function prototype for generating frames
struct VIDEO_STREAM_FRAME_T* generate_frame(void);

// Function to handle frame creation, data population, and checksum calculation
struct VIDEO_STREAM_FRAME_T* create_frame() {
    struct VIDEO_STREAM_FRAME_T* frame = (struct VIDEO_STREAM_FRAME_T*) mmap(NULL, memory_block_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!frame) {
        // Handle out-of-memory error here
    }

    sem_init(&frame->checksum_sem, 0, 1);
    frame->checksum = calculate_checksum(frame);

    return frame;
}

// Function to manage memory pool by reusing memory blocks from the free list
void* get_memory() {
    pthread_mutex_lock(&mem_pool_lock);
    struct MEMORY_POOL_T* mem = free_memory_list;
    if (mem) {
        free_memory_list = mem->next;
    } else {
        // Allocate new memory block here
    }
    void* data = mem ? mem->memory_block : mmap(NULL, memory_block_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!data) {
        // Handle out-of-memory error here
    }

    pthread_mutex_unlock(&mem_pool_lock);

    return data;
}

// Function to return memory block back to the pool
void free_memory(void* data) {
    pthread_mutex_lock(&mem_pool_lock);
    struct MEMORY_POOL_T* mem = (struct MEMORY_POOL_T*)data;
    mem->memory_block = data;
    mem->allocated_size = memory_block_size;
    mem->next = free_memory_list;
    free_memory_list = mem;
    pthread_mutex_unlock(&mem_pool_lock);
}
