void process_packets(packet_t *packets, size_t count) {
    qsort(packets, count, sizeof(packet_t), (int (*)(const void *, const void *)) compare_packets);

    for (size_t i = 0; i < count; ++i) {
        if (packets[i].prioritized) {
            send_packet(/* Your socket file descriptor */, &packets[i]);
        } else {
            queue_packet(packets, count, &packets[i]);
        }
    }
}

int compare_packets(const void *a, const void *b) {
