#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <semaphore.h>

typedef struct {
    sockaddr_in dest;
    uint16_t protocol;
    uint16_t payload_size;
    time_t timestamp;
    int priority;
    bool prioritized;
    bool transmitted;
} Packet;

struct NetworkInterface {
    Packet* packets;
    size_t capacity;
    size_t read_idx;
    size_t write_idx;
    sem_t queue_sem;
    pthread_mutex_t lock;
};

void init_network_interface(struct NetworkInterface* ni, size_t initial_capacity) {
    ni->packets = malloc(initial_capacity * sizeof(Packet));
    if (!ni->packets) {
        perror("Memory allocation error");
        exit(1);
    }
    ni->capacity = initial_capacity;
    ni->read_idx = 0;
    ni->write_idx = 0;
    sem_init(&ni->queue_sem, 0, 0);
    pthread_mutex_init(&ni->lock, NULL);
}

void send_packet(struct NetworkInterface* ni, const Packet* packet) {
    // Integrate with network stack API to send packets here
}

void enqueue_packet(struct NetworkInterface* ni, const Packet* packet) {
    pthread_mutex_lock(&ni->lock);
    while (sem_wait(&ni->queue_sem) < 0 && errno != EINTR) {
        perror("Semaphore wait error");
        exit(1);
    }
    if (ni->write_idx == ni->read_idx) {
        // Handle capacity overflow here, e.g., by increasing capacity or dropping old packets
    }
    ni->packets[ni->write_idx] = *packet;
    ni->write_idx = (ni->write_idx + 1) % ni->capacity;
    sem_post(&ni->queue_sem);
    pthread_mutex_unlock(&ni->lock);
}

void dequeue_packet(struct NetworkInterface* ni, Packet* packet) {
    pthread_mutex_lock(&ni->lock);
    if (ni->read_idx == ni->write_idx) {
        // Handle capacity underflow here, e.g., by waiting for more packets or discarding empty queues
    }
    *packet = ni->packets[ni->read_idx];
    ni->read_idx = (ni->read_idx + 1) % ni->capacity;
    pthread_mutex_unlock(&ni->lock);
}
