```java
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Random;
import java.util.function.Supplier;

public class TemperatureDataGenerator {
    private final int maxDevices;
    private final double minTemp;
    private final double maxTemp;
    private final AtomicInteger allocatedObjects = new AtomicInteger(0);
    private final Random random = new Random();

    public TemperatureDataGenerator(int maxDevices, double minTemp, double maxTemp) {
        this.maxDevices = maxDevices;
        this.minTemp = minTemp;
        this.maxTemp = maxTemp;
    }

    public List<TemperatureData> generateTemperatureData(int numObjects) {
        ExecutorService executor = Executors.newFixedThreadPool(maxDevices);
        List<Supplier<TemperatureData>> dataProducers = new ArrayList<>();

        for (int i = 0; i < maxDevices; i++) {
            dataProducers.add(() -> createTemperatureData((long) i, minTemp, maxTemp));
        }

        List<TemperatureData> result = new ArrayList<>();
        for (int i = 0; i < numObjects && allocatedObjects.get() < maxDevices; i++) {
            TemperatureData data = executor.submit(dataProducers.get((int) (random.nextInt(maxDevices)))).get();
            if (data != null) {
                result.add(data);
                allocatedObjects.incrementAndGet();
            }
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            // Handle the exception as needed
        }

        return result;
    }

    private TemperatureData createTemperatureData(long sensorID, double minTemp, double maxTemp) {
        double temperature = getRandomTemperature(minTemp, maxTemp);
        long timestamp = Instant.now().toEpochMilli();
        return new TemperatureData(sensorID, temperature, timestamp);
    }

    private double getRandomTemperature(double minTemp, double maxTemp) {
        double randomValue = random.nextDouble() * (maxTemp - minTemp) + minTemp;
        if (Math.abs(randomValue - minTemp) > (maxTemp - minTemp) / 4.0) {
            return getRandomTemperature(minTemp, maxTemp); // Retry to ensure 75% accuracy within the specified range
        }
        return randomValue;
    }
}
```

