  level: process.env.LOG_LEVEL || 'info',
  format: format.combine(
    format.timestamp(),
    format.label(),
    format.printf(({ label, timestamp, level, message }) => `${timestamp} [${label}] ${level}: ${message}`)
  ),
  transports: [
