  ]
});

// Function to process files asynchronously and in parallel
async function processFiles(directory, filterFn = _.identity) {
  const queue = async.queue((file, callback) => {
    fs.stat(file)
      .then((stats) => {
        if (filterFn(stats)) {
          fs.readFile(file, 'utf8')
            .then((content) => {
              customCache.get(file, (cachedContent) => {
                if (!cachedContent) {
                  // Process content here, and add it to the cache
                  processContent(content)
                    .then(() => {
                      customCache.set(file, content);
                      callback(null, content);
                    })
                    .catch((error) => {
                      logger.error(`Error processing file ${file}:`, error);
                      callback(error);
                    });
                } else {
                  // Cache hit! Return the cached content
                  callback(null, cachedContent);
                }
              });
            })
            .catch((error) => {
              logger.error(`Error reading file ${file}:`, error);
              callback(error);
            });
        } else {
          // Filter function excluded this file, do nothing and move on to the next one
          callback();
        }
      })
      .catch((error) => {
        logger.error(`Error getting stats for file ${file}:`, error);
        callback(error);
      });
  }, async (concurrencyLimit))

  // Start processing files
  queue.push(path.join(directory, '**/*'));
  await queue.drain();
}

