#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <arpa/inet.h>
#include <pthread.h>

typedef struct {
    in_addr_t src_ip;
    in_addr_t dest_ip;
    uint16_t protocol;
    size_t payload_size;
    time_t timestamp;
    unsigned char priority;
    uint32_t sequence_number;
    bool prioritized;
    uint8_t *payload;
} Packet;

struct NetworkInterface {
    Packet *packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

void init_network_interface(struct NetworkInterface *ni, size_t initial_capacity) {
    if (!(ni->packets = malloc((initial_capacity + 1) * sizeof(Packet)))) {
        fprintf(stderr, "Error: Failed to allocate memory for packet array.\n");
        exit(EXIT_FAILURE);
    }

    ni->capacity = initial_capacity;
    ni->count = 0;
    pthread_mutex_init(&ni->lock, NULL);
}

Packet *get_next_packet(struct NetworkInterface *ni) {
    Packet *packet;

    // Lock the network interface to prevent concurrent access
    pthread_mutex_lock(&ni->lock);

    if (ni->count < ni->capacity) {
        packet = &ni->packets[ni->count];
        ni->count++;
    } else {
        // Overflow handling
        fprintf(stderr, "Error: Packet array overflow.\n");
        pthread_mutex_unlock(&ni->lock);
        return NULL;
    }

    packet->src_ip = htonl(rand());
    packet->dest_ip = htonl(rand());
    packet->protocol = rand() % 256;
    packet->payload_size = rand() % MAX_PAYLOAD_SIZE + 1;
    packet->timestamp = time(NULL);
    packet->priority = rand() % NUM_PRIORITIES;
    packet->sequence_number = ni->count;
    packet->prioritized = rand() % 2 == 0 ? true : false;
    packet->payload = calloc(packet->payload_size, sizeof(uint8_t));

    if (!packet->payload) {
        // Memory allocation error handling
        fprintf(stderr, "Error: Failed to allocate memory for packet payload.\n");
        free(packet);
        pthread_mutex_unlock(&ni->lock);
        return NULL;
    }

    pthread_mutex_unlock(&ni->lock);
    return packet;
}

void send_packet(struct NetworkInterface *ni, Packet *packet, void (*network_stack_send)(Packet *)) {
    if (network_stack_send(packet)) {
        // Queue the packet for later transmission if network congestion occurs
        pthread_mutex_lock(&ni->lock);

        // Handle potential underflow when removing a packet from the array
        if (ni->count > 0 && ni->count == ni->packets[ni->count - 1].sequence_number + 1) {
            ni->count--;
        } else {
            fprintf(stderr, "Error: Packet underflow.\n");
        }

        free(packet->payload);
        free(packet);

        pthread_mutex_unlock(&ni->lock);
    } else {
        // Add the packet to the queued packets if it cannot be sent immediately
        pthread_mutex_lock(&ni->lock);

        // Handle potential underflow when adding a packet to the array
        if (ni->count < ni->capacity) {
            memcpy(&ni->packets[ni->count], packet, sizeof(Packet));
            ni->count++;
        } else {
            fprintf(stderr, "Error: Packet queue overflow.\n");
        }

        pthread_mutex_unlock(&ni->lock);
    }
}

void deallocate_network_interface(struct NetworkInterface *ni) {
    if (ni->packets) {
        for (size_t i = 0; i < ni->count; ++i) {
            free(ni->packets[i].payload);
        }
        free(ni->packets);
    }

    pthread_mutex_destroy(&ni->lock);
}
```

