    }

    public void Init() {
        if (root == null) Initialize();
    }

    public float GetRandomFloat() {
        return root.GetRandomNumber();
    }

    public int GetRandomInt(int min, int max) {
        float rand = GetRandomFloat();
        int level = numLevels - 1;
        int rangeSize = (int)(max - min + 1);
        int position = Math.Min((int)((rand - root.minValue) / ((root.maxValue - root.minValue) / rangeSize)), rangeSize - 1);
        return min + position;
    }
}

public class Node {
    public float minValue, maxValue;
    public Node[] children;
    public int level;

    public void Init(float min, float max) {
        minValue = min;
        maxValue = max;
        level = 0;
        children = new Node[8];
        for (int i = 0; i < children.Length; i++) {
            children[i] = null;
        }
    }

    public float GetRandomNumber() {
        if (children == null) return minValue + (maxValue - minValue) * Random.Shared.NextDouble();

        float rand = Random.Shared.NextDouble();
        int position = (int)((rand / (1.0f / 8)) % children.Length);
        Node node = children[position];
        if (node == null) return minValue + ((maxValue - minValue) * RandFloat(0, 1));
        return node.GetRandomNumber();
    }
}

public static float RandFloat(float min, float max) {
    Random rand = new Random((int)(DateTime.Now.Ticks >> (32 * 4)));
    return min + (max - min) * rand.NextDouble();
}
