#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <sys/mman.h>

typedef enum { NORMAL, CRITICAL } RequestType;
typedef struct {
    char *buf;
    size_t len;
    RequestType type;
    int urgency;
    int retry_count;
    time_t timestamp;
} Request;

static pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t queue_notempty = PTHREAD_COND_INITIALIZER;
static pthread_cond_t queue_notfull = PTHREAD_COND_INITIALIZER;
static Request *queue = NULL;
static size_t queue_size = 0;
static size_t queue_max = 256;

void process_request(Request *req) {
    // Critical section for accessing shared data (request metadata)
    pthread_mutex_lock(&queue_lock);

    // Handle edge cases: malformed input or insufficient buffer space
    if (!req->buf || req->len > 4096 || !req->type || !req->urgency) {
        free(req->buf);
        req->buf = NULL;
        req->len = 0;
        // Default processing behavior
        process_default(req);
    } else {
        // Process request based on priority
        if (req->type == CRITICAL && req->urgency > 3) {
            process_critical(req);
        } else {
            process_normal(req);
        }
    }

    // Update retry count and timestamp for retries
    if (req->retry_count < 5) {
        req->retry_count++;
        req->timestamp = time(NULL);
    }

    // Unlock critical section
    pthread_mutex_unlock(&queue_lock);
}

void enqueue_request(Request *req) {
    // Critical section for accessing shared data (queue metadata)
    pthread_mutex_lock(&queue_lock);

    if ((queue_size + 1) >= queue_max) {
        // Queue is full, wait for a spot to become available
        pthread_cond_wait(&queue_notempty, &queue_lock);
    }

    // Insert request into the queue and update queue size
    req->next = queue;
    queue = req;
    queue_size++;

    // Signal that the queue is not empty (if a thread was waiting)
    pthread_cond_signal(&queue_notfull);

    // Unlock critical section
    pthread_mutex_unlock(&queue_lock);
}

void dequeue_request(Request **req) {
    // Critical section for accessing shared data (queue metadata)
    pthread_mutex_lock(&queue_lock);

    if (queue_size == 0) {
        // Queue is empty, wait for a request to be enqueued
        pthread_cond_wait(&queue_notfull, &queue_lock);
    }

    *req = queue;
    Request *temp = queue->next;
    free(queue);
    queue = temp;
    queue_size--;

    // Signal that the queue is not full (if a thread was waiting)
    pthread_cond_signal(&queue_notempty);

    // Unlock critical section
    pthread_mutex_unlock(&queue_lock);
}

// Implement process_default, process_critical, process_normal functions here...

void initialize_queue(size_t max) {
    queue = malloc(max * sizeof(Request));
    if (!queue) {
        perror("Failed to allocate memory for request queue");
        exit(EXIT_FAILURE);
    }
    queue_max = max;
    memset(queue, 0, queue_max * sizeof(Request));
}
```

