MemoryPool memPool; // Global memory pool variable

void initMemoryPool(size_t initialCapacity, size_t blockSize) {
    memPool.capacity = initialCapacity;
    memPool.count = 0;
    memPool.items = malloc(initialCapacity * blockSize);
    memPool.blockSize = blockSize;
}

PoolItem allocateFromPool() {
    if (memPool.count < memPool.capacity)
        return memPool.items + memPool.count++;
    else {
        size_t newCapacity = 2 * memPool.capacity;
        PoolItem* newItems = realloc(memPool.items, newCapacity * memPool.blockSize);
        if (newItems == NULL) {
            fprintf(stderr, "Out of memory!\n");
            exit(1);
