void initDataArray(size_t initialSize) {
    if (dataArray != nullptr) return;

    dataArray = new std::vector<NFAPI_RX_FRAME_INFO>(initialSize);
    totalAllocated += initialSize;
    maxSize = initialSize;

    pthread_mutex_init(&mutex, NULL);
}

void resizeDataArray(size_t newSize) {
    if (newSize <= maxSize) return;

    std::vector<NFAPI_RX_FRAME_INFO>* temp = new std::vector<NFAPI_RX_FRAME_INFO>(newSize);

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < totalAllocated && i < newSize; ++i) {
        temp[i] = dataArray->at(i);
    }

    delete[] dataArray;
    dataArray = temp;
    maxSize = newSize;
    totalAllocated += (newSize - maxSize);

    pthread_mutex_unlock(&mutex);
}

NFAPI_RX_FRAME_INFO& getDataAt(size_t index) {
    if (index >= totalAllocated) resizeDataArray(totalAllocated * 2 + 1);

    pthread_mutex_lock(&mutex);

    while (dataArray->size() <= index) dataArray->push_back({}); // Populate with default values

    auto& result = dataArray->at(index);
    result.crcIndication = boost::random::uniform_int_distribution<>()((unsigned int)index);

    pthread_mutex_unlock(&mutex);

    return result;
}
