struct Attack {
    std::string type;
    int energyCost;
    int cooldownDuration;
};
```

Next, we create a MemoryPool class to manage dynamic memory allocation:

```cpp
template <typename T>
class MemoryPool {
public:
    MemoryPool(size_t initialCapacity) : data_(initialCapacity), freeList_(data_.begin(), data_.end()) {}

    std::unique_ptr<T> allocate() {
        if (freeList_.empty()) {
            // Expand memory pool if necessary
            expand();
        }
        auto it = freeList_.back();
        freeList_.pop_back();
        return std::unique_ptr<T>(it);
    }

    void deallocate(std::unique_ptr<T> ptr) {
        ptr->~T();  // Destroy the object
        new (ptr.release()) T;  // Construct a new one in the memory pool
        freeList_.push_back(ptr.release());
    }

private:
    void expand() {
        // Implement dynamic expansion strategy based on current workload patterns
        // For simplicity, I'll assume that we simply double the capacity when it runs out
        auto newCapacity = data_.size() * 2;
        std::vector<T> newData(newCapacity);
        std::copy(data_.begin(), data_.end(), newData.begin());
        freeList_ = newData.begin(), newData.end();
    }

    std::vector<T> data_;
    std::list<T*> freeList_;
};
```

Now, let's define a function to initialize and populate the Attack structures:

```cpp
