Finally, let's define the dynamic attack selection function:

```cpp
Attack selectAttack(const std::vector<std::unique_ptr<Attack>>& attacks, float systemLoad) {
    // Implement a weighted random selection strategy based on the system load and the desired bias
    auto totalWeight = 0.f;
    for (auto& attack : attacks) {
        const int energyCost = attack->energyCost;
        const int cooldownDuration = attack->cooldownDuration;
        float weight = 1.f / (energyCost + systemLoad * cooldownDuration);
        totalWeight += weight;
    }

    float biasSum = 0.f;
    std::uniform_real_distribution<> distribution(0.f, totalWeight);
    std::mt19937 generator;  // Use a thread-safe random number generator for concurrency
    auto rnd = [&]() { return distribution(generator); };

    float cumulativeWeight = 0.f;
    int selectedIndex = -1;
    for (size_t i = 0, n = attacks.size(); i < n; ++i) {
        auto weight = static_cast<float>(attacks[i]->energyCost + systemLoad * attacks[i]->cooldownDuration);
        cumulativeWeight += weight;

        if (rnd() <= cumulativeWeight && rnd() > cumulativeWeight - weight) {
            selectedIndex = i;
            break;
        }
    }

    return *attacks[selectedIndex];
}
