using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MersenneTwister;

public class DynamicRandomGeneratorPool
{
    private readonly int _minValue;
    private readonly float _maxValue;
    private readonly MT19937[] _randomGenerators;

    public DynamicRandomGeneratorPool(int min, int max)
    {
        SetRange(min, max);
        _randomGenerators = Enumerable.Range(0, Environment.ProcessorCount).Select(_ => new MT19937()).ToArray();
    }

    public int GetRandomInt() => _randomGenerators[Thread.CurrentThread.ManagedThreadId % _randomGenerators.Length].Next(_minValue, _maxValue + 1);

    public float GetRandomFloat() => (float)(_randomGenerators[Thread.CurrentThread.ManagedThreadId % _randomGenerators.Length].NextDouble() * (_maxValue - _minValue) + _minValue);

    public override string ToString() => $"[{_minValue}, {_maxValue})";

    public void SetRange(int min, int max)
    {
        if (max < min) throw new ArgumentException("Maximum value must be greater than the minimum value.", nameof(max));
        _minValue = min;
        _maxValue = max;
    }

    public static RandomState LoadStateFromFile(string filePath)
    {
        if (File.Exists(filePath))
        {
            using var stream = File.OpenRead(filePath);
            return SerializationHelper.Deserialize<RandomState>(stream);
        }

        throw new FileNotFoundException("The specified file does not exist.", filePath);
    }

    public async Task ResetAsync()
    {
        var tasks = _randomGenerators.Select(generator => Task.Run(() => generator.Reset()));
        await Task.WhenAll(tasks);
    }
}

[Serializable]
public class RandomState
{
    public int MinValue { get; set; }
    public int MaxValue { get; set; }
}
