DataPacket* initDynamicArray(size_t size) {
    DataPacket* packets = (DataPacket*)malloc(sizeof(DataPacket) * size);

    if (!packets) {
        perror("Memory allocation failed for DataPacket array");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        packets[i].packet_id = i + 1;
        packets[i].payload = calloc(packets[i].packet_id, sizeof(char));

        if (!packets[i].payload) {
            perror("Memory allocation failed for Payload");
            free(packets);
            exit(EXIT_FAILURE);
        }

        packets[i].timestamp = time(NULL);
    }

    return packets;
}

void destroyDynamicArray(DataPacket* packets, size_t size) {
    if (!packets) {
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        free(packets[i].payload);
    }

    free(packets);
