#include <openssl/evp.h>

#ifdef _WIN32
#define RAND_bytes rand_bytes
#endif

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateCrcListAndEncryptString(int N, const char* input) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; ++i) {
        list[i].tag.present = RX_UE_INFORMATION_TAG_PR_RNTI;
        list[i].rnti.value = i + 1;
        list[i].crc_indication.crcflag = (unsigned char)(rand() & 0x1);
    }

    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    unsigned char *key, *iv, encrypted_data;
    int key_len, iv_len;

    if ((cipher = EVP_get_cipherbyname("AES-256-CFB")) == NULL) {
        fprintf(stderr, "Failed to find AES-256-CFB cipher\n");
        exit(EXIT_FAILURE);
    }

    if (EVP_CIPHER_init(&ctx, cipher, NULL, key, iv) <= 0) {
        fprintf(stderr, "Failed to initialize AES-256-CFB cipher\n");
        exit(EXIT_FAILURE);
    }

    if (N == 1) { // If only one element in the list, encrypt input directly
        key = (unsigned char *)malloc(EVP_CIPHER_key_length(cipher));
        RAND_bytes(key, EVP_CIPHER_key_length(cipher));
        iv = (unsigned char *)malloc(EVP_CIPHER_iv_length(cipher));
        RAND_bytes(iv, EVP_CIPHER_iv_length(cipher));

        int plaintext_len = strlen(input);
        unsigned char *plaintext = (unsigned char *)malloc(plaintext_len + 1);
        strcpy((char *)plaintext, input);

        while ((plaintext_len % EVP_CIPHER_block_size(cipher)) != 0) {
            plaintext_len++;
            plaintext = realloc(plaintext, plaintext_len + 1);
            plaintext[plaintext_len - 1] = '\0';
        }

        int encrypted_len = plaintext_len;
        unsigned char *encrypted = (unsigned char *)malloc(encrypted_len + EVP_CIPHER_block_size(cipher));

        EVP_CIPHER_update(&ctx, NULL, &encrypted_data, &encrypted_len, plaintext, plaintext_len);
        encrypted[encrypted_len] = '\0';

        free(key);
        free(iv);
        free(plaintext);

        list[0].crc_indication.crc_indication_rel8.present = CRCI_PR_CRC16;
        list[0].crc_indication.crc_indication_rel8.crc16 = crc16(encrypted, encrypted_len);

        free(encrypted);
    } else { // Encrypt each part of the input separately and combine them
        int chunk_size = strlen(input) / N;
        unsigned char *chunk = (unsigned char *)malloc(chunk_size + 1);
        strncpy((char *)chunk, input, chunk_size);
        chunk[chunk_size] = '\0';

        unsigned char *encrypted = (unsigned char *)malloc(N * (EVP_CIPHER_block_size(cipher) + chunk_size));
        int offset = 0;

        for (int i = 0; i < N; ++i) {
            EVP_CIPHER_update(&ctx, NULL, &encrypted_data, &encrypted_len, chunk, chunk_size);
            encrypted[offset] = encrypted_data;
            offset += encrypted_len;

            if (i < N - 1) {
                memset(chunk, '\0', chunk_size + 1);
                strncpy((char *)chunk, ((i + 1) % strlen(input)) == 0 ? input : "", strlen(input) / N);
            }
        }

        list[0].crc_indication.crc_indication_rel8.present = CRCI_PR_CRC16;
        list[0].crc_indication.crc_indication_rel8.crc16 = crc16(encrypted, offset);

        free(chunk);
        free(encrypted);
    }

    return list;
}
