namespace RandomPool {
    class ThreadSafeGenerator {
        static std::mutex mtx;
        static std::map<std::thread::id, std::mt19937> generators;

        public:
            ThreadSafeGenerator() : gen(*generators[std::this_thread::get_id()]) {}
            ~ThreadSafeGenerator() { generators.erase(std::this_thread::get_id()); }

            int nextInt() { return gen() % INT32_MAX; }
            float nextFloat() { return static_cast<float>(gen()) / std::randmax(); }

            static void resetAll() {
