void request_queue_push(Request *req) {
    sem_wait(&queue_mutex);

    if (sem_trywait(&queue_not_full)) {
        queue_enqueue(request_queue, req);
        sem_post(&queue_not_empty);
    } else {
        // Handle edge case: queue is full
        printf("Error: Request queue is full.\n");
        free(req);
    }

    sem_post(&queue_mutex);
}

Request* request_queue_pop() {
    sem_wait(&queue_mutex);

    Request *req = NULL;

    if (sem_trywait(&queue_not_empty)) {
        req = queue_dequeue(request_queue);
        sem_post(&queue_not_full);
    } else {
        // Handle edge case: queue is empty
        printf("Error: Request queue is empty.\n");
    }

    sem_post(&queue_mutex);

    return req;
}

void oauth_request_thread(void* arg) {
    while (true) {
        Request *req = request_queue_pop();

        if (req != NULL) {
            handle_request(req);
        }
    }
