#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

#pragma pack(push, 1) /* Pack struct members at byte boundaries */
struct RX_UE_INFORMATION_TAG {
    uint32_t tag;
};

struct RNTI {
    uint32_t value;
};

struct CRC_INDICATION_REL8_TAG {
    uint8_t crcflag;
};
#pragma pack(pop) /* Revert to system's default struct packing */

int validate_rnti(const NFAPI_CRC_INDICATION_PDU_T *pdu, const size_t index) {
    return pdu[index].rnti.value > 0 && pdu[index].rnti.value <= UINT32_MAX;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(const size_t N) {
    if (N == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Calloc failure");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pdus[i].rx_ue.tag = RX_UE_INFORMATION_TAG_CRC_INDICATION;
        pdus[i].rnti.value = (i % 128) + 1; // Valid range: 1 to 128
        pdus[i].crc_ind.crcflag = rand() % 2;
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, const size_t N) {
    if (!pdus || !N) return;

    free(pdus);
}

