#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

CRC_INDICATION_REL8_TAG generate_tag() {
    return (CRC_INDICATION_REL8_TAG){.crcflag = rand() % 2};
}

int validate_rnti(RNTI rnti) {
    if (rnti < 0 || rnti > RNTI_MAX)
        return -1;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(unsigned int N, unsigned int index) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    pthread_mutex_lock(&mutex);

    if (N > 0 && index < N) {
        pdus = realloc(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

        if (!pdus) {
            perror("realloc failed");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    } else {
        fprintf(stderr, "Invalid size or index\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    RNTI rnti = index + 1; // Assuming RNTI starts from 1
    int error = validate_rnti(rnti);

    if (error) {
        free(pdus);
        fprintf(stderr, "Invalid RNTI: %d\n", rnti);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    pdus[index].rx_ue = (RX_UE_INFORMATION_TAG){.tag = 1}; // Assuming a specific tag for RX_UE_INFORMATION_TAG
    pdus[index].rnti = rnti;
    pdus[index].crc_ind = generate_tag();

    pthread_mutex_unlock(&mutex);
    return pdus;
}

void destroy_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, unsigned int size) {
    if (pdus && size > 0) {
        free(pdus);
        pdus = NULL;
    }
}

