void free_dynamic_stream_list(DYNAMIC_STREAM_LIST* list) {
    for (int i = 0; i < list->max_streams; ++i) {
        if (list->stream_list[i]) {
            free(list->stream_list[i]->api_context);
            pthread_mutex_destroy(&list->stream_list[i]->ctx_lock);
            sem_destroy(&list->stream_list[i]->cache_sem);
            free(list->stream_list[i]);
        }
    }
    free(list->stream_list);
    free(list);
}

NF_API_STREAM_CONTEXT* alloc_context(DYNAMIC_STREAM_LIST* list) {
    sem_wait(&list->stream_sem);
    int index = list->num_streams;
    if (index == list->max_streams) {
        log_error("No more available contexts. Consider increasing the max number of contexts or implementing a fallback strategy.");
        return NULL;
    }
    NF_API_STREAM_CONTEXT* ctx = list->stream_list[index];
