    ctx->ServingCellID = 1234; // Placeholder Serving Cell ID
    ctx->RB_ALLOC_FLAG = rand() % 2; // Randomly set RB Alloc Flag
    list->num_streams++;
    sem_post(&list->stream_sem);
    return ctx;
}

void free_context(DYNAMIC_STREAM_LIST* list, NF_API_STREAM_CONTEXT* ctx) {
    sem_wait(&ctx->cache_sem);
    sem_post(&ctx->cache_sem);
    memset(ctx, 0, sizeof(*ctx));
    list->num_streams--;
}

