#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>

void* mmap_aligned(size_t size, size_t alignment) {
    void* ptr = mmap(NULL, size + (alignment - 1), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED)
        return NULL;

    size_t offset = alignment - (size_t)(uintptr_t)ptr % alignment;
    return (void*)((uintptr_t)ptr + offset);
}

NFAPI_CRCI_PDU_T* create_linked_list(int N, bool ordered, sem_t* mem_semaphore, log_func_t log_callback) {
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
    NODE* head = NULL;
    NODE* tail = NULL;
    size_t node_size = sizeof(NFAPI_CRCI_PDU_T) + 2 * sizeof(NODE*);

    for (int i = 0; i < N; ++i) {
        NODE* new_node = (NODE*)mmap_aligned(node_size, 64);
        if (!new_node) {
            sem_post(mem_semaphore);
            log_callback("Memory allocation failed.");
            return NULL;
        }

        NFAPI_CRCI_PDU_T* new_pdu = (NFAPI_CRCI_PDU_T*)((uintptr_t)new_node + sizeof(NODE*));
        // Fill in the required fields for each PDU instance

        pthread_mutex_lock(&list_lock);
        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
        pthread_mutex_unlock(&list_lock);
    }

    if (ordered) {
        sort_by_RNTI(head, N);
    }

    return head->data;
}
