        return;
    }

    NFAPI_CRCI_PDU_T* new_pdu_ptr = (NFAPI_CRCI_PDU_T*)((uintptr_t)new_node + sizeof(NODE*));
    *new_pdu_ptr = *new_pdu;
    new_node->data = new_pdu_ptr;

    if (!*head) {
        *head = new_node;
    } else {
        (*tail)->next = new_node;
        new_node->prev = tail;
        tail = new_node;
    }
    pthread_mutex_unlock(head);
}

void remove_pdu(NFAPI_CRCI_PDU_T* pdu, NODE** head) {
    pthread_mutex_lock(head);
    NODE* curr = *head;
    while (curr != NULL && curr->data->RNTI != pdu->RNTI) {
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(head);
        return;
    }

    if (curr->prev) {
        curr->prev->next = curr->next;
    } else {
        *head = curr->next;
    }

    if (curr->next) {
        curr->next->prev = curr->prev;
    } else {
        tail = curr->prev;
    }

    free(curr);
    pthread_mutex_unlock(head);
}

void sort_by_RNTI(NODE* head, int N) {
    if (N <= 1)
        return;

    NODE* sentinel = (NODE*)malloc(sizeof(NODE));
    sentinel->data = NULL;
    NODE* curr = head;
    NODE* right_min = NULL;
    NODE* next_right_min = NULL;

    pthread_mutex_lock(&list_lock);
    while (curr != tail) {
        int min_index = -1;
        for (int i = 0; i < N; ++i) {
            if (i == curr->RNTI || curr->data->RNTI > i)
                continue;
            if (min_index == -1 || curr->data->RNTI > head[i].data->RNTI) {
                min_index = i;
                right_min = &head[i];
                next_right_min = right_min->next;
            }
        }

        if (min_index == -1) {
            curr = curr->next;
            continue;
        }

        NODE* temp = right_min->data;
        right_min->data = curr->data;
        curr->data = temp;

        pthread_mutex_lock(&right_min->data->prev);
        if (right_min->data->prev) {
            right_min->data->prev->next = right_min;
        } else {
            head = right_min;
        }

        pthread_mutex_unlock(&right_min->data->prev);

        pthread_mutex_lock(head);
        right_min->next = curr;
        curr->prev = right_min;
        pthread_mutex_unlock(head);

        curr = right_min->next;
    }
    pthread_mutex_unlock(&list_lock);
}
