void applyCompression(unsigned char *data, int len) {
    unsigned long zlen;
    char *dest = (char *) malloc(len + 26);

    if (inflateInit2(&dest, Z_SYNC_FLUSH) == Z_OK) {
        if (inflate(zlib_inflate, FD_STORED, data, len, Z_FINISH) == Z_STREAM_END) {
            zlen = dest - (char *)data;
            memcpy(data, dest, zlen);
        }
        inflateEnd(&dest);
        free(dest);
    }
}

void generateEncryptionKey() {
    RAND_bytes((unsigned char *)&encryptionKey, AES_BLOCK_SIZE);
