        for (i = 0; i < N; ++i)
            applyCompression((unsigned char *)dataList[i].payload, strlen(dataList[i].payload));
    }

    generateEncryptionKey();

    AES_encrypt(dataList[0].payload, dataList[0].payload, &encryptionKey, AES_ENCRYPT);

