namespace RandomPool {
    class BaseGenerator {
    public:
        virtual int generateInt() = 0;
        virtual float generateFloat() = 0;
    };

    class Generator : public BaseGenerator {
        friend class RandomPool;
        private:
            static std::mutex mtx;
            static std::vector<Generator*> pool;
            static int maxGenerators;
            static std::deque<Generator*> queuedGenerators;
            std::mt19937_64 rng;

            Generator(uint64_t seed) : rng(seed) {}
            ~Generator() {
                std::cout << "Generator destroyed: " << this << std::endl;
            }

            int generateInt() { return rng(); }
            float generateFloat() { return static_cast<float>(rng()) / std::numeric_limits<uint64_t>::max(); }
    };

    std::mutex Generator::mtx;
    std::vector<Generator*> RandomPool::Generator::pool;
    std::deque<Generator*> RandomPool::QueuedGenerator;
    int RandomPool::maxGenerators = 10; // Maximum number of generators in the pool

    class GeneratorManager {
        public:
            static void initialize(int maxGenerators) { RandomPool::maxGenerators = maxGenerators; }
            static Generator* getGenerator() {
                std::unique_lock<std::mutex> lock(mtx);
                if (pool.size() < maxGenerators) {
                    auto newGen = new Generator(getSeed());
                    pool.push_back(newGen);
                    return newGen;
                } else {
                    if (!queuedGenerators.empty()) {
                        lock.unlock();
                        queuedGenerators.front()->use();
                        return queuedGenerators.front();
                    } else {
                        lock.unlock();
                        std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Sleep to avoid contention
                        return getGenerator();
                    }
                }
            }

            static void reset() {
                std::unique_lock<std::mutex> lock(mtx);
                for (auto gen : pool) {
                    if (!gen->isUsed()) {
                        gen->reset();
                    }
                }
            }

            static void monitor() {
                std::unique_lock<std::mutex> lock(mtx);
                std::cout << "Active Generators: " << pool.size() << std::endl;
            }

            static uint64_t getSeed() {
                auto seed = std::getenv("RANDOM_SEED");
                if (!seed) {
                    seed = std::to_string(time(nullptr));
                }
                return std::stoull(seed);
            }

            static void setMaxGenerators(int maxGenerators) { RandomPool::maxGenerators = maxGenerators; }

    private:
        class GeneratorUsageCounter {
            friend class Generator;
            public:
                bool isUsed() const { return used; }
                void use() { used = true; }
                void reset() { used = false; }

            private:
                bool used = false;
        };

        static std::map<Generator*, GeneratorUsageCounter> usageCounters;
    };
}

