void populateArray(NFAPI_CRC_INDICATION_PDU_T **array, uint32_t size) {
    if (!array || size <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T*) calloc(size, sizeof(**array));
    if (!*array) {
