        return;
    }

    pthread_t threads[size];
    for (uint32_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &((*array)[i]);
        pthread_create(&threads[i], NULL, generate_random, pdu);
    }

    for (uint32_t i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void freeArray(NFAPI_CRC_INDICATION_PDU_T **array, uint32_t size) {
