// Thread-safe RNG function using atomic operations for multi-threaded access
uint32_t get_random(void) {
    static thread_local unsigned long rng = 0xdeadbeef;

    // Using xorshift128+ to generate pseudo-random numbers with good distribution and low correlation
    const uint64_t mag01 = 0x04c9c3f7a2ca85a2ULL;
    const uint64_t mag03 = 0x5b9seed5dbellULL;
    const uint64_t mag1p = 0x9e3779b97f4a7c15ULL;

    rng ^= (rng << 32);
    rng ^= (rng >> 5) ^ (rng << 4);
    rng ^= (rng << 31) | (rng >> 1);
    rng *= mag01;
    rng += mag03;
    rng *= mag01;
    rng += mag1p;
    rng *= mag01;

    return (uint32_t)(rng >> 16) & ((1 << 32) - 1);
}

// Deallocate dynamically allocated memory for LTE_PHY_TX_BUFFER_T array
void free_lte_buffers(LTE_PHY_TX_BUFFER_T* buffers, size_t num_buffers) {
    if (buffers) free(buffers);
