void populate_buffer(LTE_PHY_RX_BUFFER_T** buffer, size_t* num_buffers, size_t max_num_buffers) {
    if (!buffer || !num_bufflers)
        return;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    size_t num_filled_buffers = 0;
    *num_bufflers = 0;

    void* buffer_mem = malloc(max_num_buffers * sizeof(LTE_PHY_RX_BUFFER_T));
    if (!buffer_mem) {
        // Handle memory allocation error
        return;
    }

    LTE_PHY_RX_BUFFER_T* current_buffer = buffer_mem;
    for (size_t i = 0; i < max_num_buffers; ++i) {
        current_buffer[i].SEQUENCE_NUMBER = rand();
        current_buffer[i].SNR = rand() / RAND_MAX * 100.0f;
        current_buffer[i].RF_CHAIN = rand() % 4;

        current_buffer[i].rlc_am_pdu = generate_rlc_am_pdu();
        current_buffer[i].rlc_ps_pdu = generate_rlc_ps_pdu();
        current_buffer[i].pdcp_pdu = generate_pdcp_pdu();

        ++num_filled_buffers;
        if (num_filled_buffers >= *num_bufflers) {
            // Notify the main thread that buffers are ready
            pthread_mutex_lock(&mutex);
            *num_bufflers = num_filled_buffers;
            pthread_cond_signal(&cond);
            pthread_mutex_unlock(&mutex);
            break;
        }
    }

    free(buffer_mem);

    // Wait for the main thread to process all filled buffers before exiting
    while (*num_bufflers < num_filled_buffers) {
        pthread_mutex_lock(&mutex);
        pthread_cond_wait(&cond, &mutex);
        pthread_mutex_unlock(&mutex);
    }
}
