void processAndPopulatePDUArray(size_t num_structures, unsigned char *key, unsigned char *iv, const NFAPI_CRC_INDICATION_PDU_T **pudu_array) {
    if (!key || !iv || !pudu_array) {
        perror("Invalid parameters");
        return;
    }

    *pudu_array = malloc(num_structures * sizeof(NFAPI_CRU_INDICATION_PDU_T));
    if (!*pudu_array) {
        perror("Memory allocation failed");
        return;
    }

    AES_KEY aes_ctx;
    AES_set_encrypt_key(key, 128, &aes_ctx);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*pudu_array)[i];

        pthread_mutex_lock(&mutex);

        // Generate random padding and ciphertext
        unsigned char *ciphertext = malloc(AES_BLOCK_SIZE + rand() % AES_BLOCK_SIZE);
        if (!ciphertext) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            continue;
        }

        memset(ciphertext, 0, AES_BLOCK_SIZE + rand() % AES_BLOCK_SIZE);

        // Perform encryption
        unsigned char encrypted[AES_BLOCK_SIZE];
        AES_cbc_encrypt(ciphertext, encrypted, AES_BLOCK_SIZE, &aes_ctx, iv, AES_ENCRYPT);

        // Set tags and CRCFLAG
        pdu->tag = RX_UE_INFORMATION_TAG(); // Use a macro or function to generate the tag
        pdu->rnti = GENERATE_RNTI(); // Use a function to generate the rnti
        pdu->crc_indication.tag = CRC_INDICATION_REL8_TAG(); // Use a macro or function to generate the tag
        pdu->crc_indication.crcflag = rand() % 2; // Set randomly

        // Add padding and store the decrypted data
        unsigned char *decrypted = malloc(encrypted - ciphertext + 1);
        if (!decrypted) {
            perror("Memory allocation failed");
            free(ciphertext);
            pthread_mutex_unlock(&mutex);
            continue;
        }

        memcpy(decrypted, encrypted, encrypted - ciphertext);
        decrypted[encrypted - ciphertext] = 0;

        // Add the PDU to the array
        pthread_mutex_unlock(&mutex);
    }
}
