// Function to populate PDU array with valid structures
void generate_pdus(int size) {
    if (!rnti_to_pdu || !size) return;

    rnti_to_pdu = realloc(rnti_to_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    num_pdus = size;

    for (int i = 0; i < size; ++i) {
        RX_UE_INFORMATION_TAG tag = (RX_UE_INFORMATION_TAG)(i % 16); // Valid tags from 0 to 15
        RNTI rnti = get_rnti(tag); // Get RNTI based on UE information tag
        if (!rnti) continue; // If no RNTI available, skip this structure

        CRC_INDICATION_REL8_TAG crc_indication = (CRC_INDICATION_REL8_TAG)(rand() % 4); // Valid tags from 0 to 3
