        rnti_to_pdu[i].crc_indication = crc_indication;
        rnti_to_pdu[i].crcflag = crcflag;
    }
}

// Data source function running in a separate thread, refreshing PDUs as needed
void data_source() {
    while (1) {
        sem_wait(&data_source_mutex);
        sem_post(&data_source_cond);
        sem_timedwait(&data_source_cond, DATA_SOURCE_REFRESH_INTERVAL);
        generate_pdus(num_pdus);
        sem_post(&data_source_mutex);
    }
}

// Function to dynamically populate the PDU array with valid structures
void create_pdus(int* size) {
    if (!size || !rnti_to_pdu) return;

    generate_pdus(*size);

    sem_init(&data_source_mutex, 0, 1);
    pthread_create(&data_source_thread, NULL, data_source, NULL);
}
