void loadConfig(const std::string& filename, Config& config) {
    namespace pt = boost::property_tree;
    pt::ptree tree;
    try {
        read_xml(filename, tree);

        if (!get<int>(tree.get<pt::ptree>("config.tagCount"), config.tagCount)) {
            std::cerr << "Error: Invalid tag count" << std::endl;
            return;
