            return;
        }

        if (!get(tree.get<pt::ptree>("config.maxRetries"), config.maxRetries)) {
            std::cerr << "Error: Invalid maxRetries" << std::endl;
            return;
        }

        if (!get(tree.get<pt::ptree>("config.backoffFactor"), config.backoffFactor)) {
