void init_random(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crc_ind_rel8_tag.crcflag = (rand() % 100 < 5) ? true : false;
    pdu->rx_ue_info_tag = rand();
    pdu->rnti = rand();
    pdu->srs_tag.crc_check_flag = (rand() % 100 < 95) ? true : false;
