bool add_pdu(RNTI rnti) {
    if (num_allocated + sizeof(NFAPI_CRC_INDICATION_PDU_T) > 5000 * 64) return false;
    list_node_t *new_node = malloc(sizeof(list_node_t));
    if (!new_node) return false;

