    new_node->data->rnti = rnti;

    pthread_mutex_lock(&list_mutex);
    new_node->next = head;
    head = new_node;
    num_allocated += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&list_mutex);

    if (log_callback) log_callback("Allocated and populated a new PDU");
    ++num_populated;
    return true;
}

bool remove_pdu(RNTI rnti) {
    pthread_mutex_lock(&list_mutex);
    list_node_t *current = head, *prev = NULL;

    while (current != NULL) {
        if (current->data->rnti == rnti) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current->data);
            free(current);

            num_allocated -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            --num_populated;

            if (log_callback) log_callback("Removed PDU with RNTI");
            pthread_mutex_unlock(&list_mutex);
            return true;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
    return false;
}

