    newNode->next = NULL;

    sem_wait(&list->garbageCollectSemaphore);
    sem_wait(&list->mutex);

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }

    sem_post(&list->mutex);
    sem_post(&list->framesAddedSemaphore);
}

