        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        sem_post(&list->mutex);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    sem_post(&list->mutex);
}

void frameListGarbageCollect(struct frameList* list) {
