bool addDynamicContextToList(dynamic_list_t* list, dynamic_context_t* context) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        resizeDynamicList(list, list->capacity * 2);
    }

    // Handle cases where the number of contexts exceeds available memory

    list->contexts[list->count] = *context;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

void resizeDynamicList(dynamic_list_t* list, size_t new_capacity) {
    dynamic_context_t* new_contexts = realloc(list->contexts, new_capacity * sizeof(dynamic_context_t));
    if (!new_contexts) {
