struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class Populator {
public:
    explicit Populator(const json& config) : maxRetries_(config["max_retries"].get<int>()), backoff_(1), log_(spdlog::get("populator")) {}

    void populate(vector<unique_ptr<NFAPI_CRC_INDICATION_PDU_T>>& data, int numStructures) {
        if (!data) {
            throw invalid_argument{"Data vector cannot be null"};
        }
        unique_lock lock(mtx_);
        tagDefs_ = config["tag_definitions"];
        for (int i = 0; i < numStructures; ++i) {
            auto pdu = make_unique<NFAPI_CRC_INDICATION_PDU_T>();
            if (!populateStructure(*pdu)) {
                lock.unlock();
                if (--retries_ <= 0) {
                    log_->error("Failed to populate structure after {} retries", maxRetries_);
                    throw runtime_error{"Failed to populate structure after retries"};
                }
                this_thread::sleep_for(chrono::milliseconds(backoff_ * backoff_));
                backoff_ *= 2;
                lock.lock();
            }
            data->push_back(move(pdu));
        }
    }

private:
    bool populateStructure(NFAPI_CRC_INDICATION_PDU_T& pdu) {
        if (!tagDefs_.empty()) {
            auto it = tagDefs_.begin();
            pdu.RX_UE_INFORMATION_TAG = it->second["RX_UE_INFORMATION_TAG"].get<uint16_t>();
            pdu.RNTI = it->second["RNTI"].get<uint16_t>();
            pdu.CRC_INDICATION_REL8_TAG = it->second["CRC_INDICATION_REL8_TAG"].get<uint32_t>();
            pdu.CRCFLAG = static_cast<bool>(rand() % 2);
            ++it;
        } else {
            return false;
        }
        if (it != tagDefs_.end()) {
            tagDefs_.erase(begin(tagDefs_));
        }
        return true;
