    total_memory += MAX_RECORDS * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Populate arrays with random data and synchronize access using mutex to avoid race conditions
    pthread_mutex_init(&mutex, NULL);
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
