    }

    unsigned int current_RNTI = 0;
    for (unsigned int i = 0; i < n && unique_RTNIs < MAX_RTNIS_COUNT; ++i) {
        bool found_match = false;
        for (unsigned int j = i - 1; j >= 0 && !found_match; --j) {
            if (list[j].RNTI == current_RNTI) {
                found_match = true;
            }
        }

        if (!found_match) {
            list[i].RX_UE_INFORMATION_TAG = i + 1;
            list[i].RNTI = current_RNTI++;
            if (current_RNTI > MAX_RTNIS) {
                current_RNTI = 1;
                ++unique_RTNIs;
            }
            list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        } else {
            --i;
        }
    }

    return list;
}
```

