void init_network(struct Network* net, size_t interfaces_count, size_t bandwidth_limit) {
    net->interfaces_count = interfaces_count;
    net->bandwidth_limit = bandwidth_limit;
    net->interfaces = malloc(sizeof(Statistic) * interfaces_count);
    if (!net->interfaces) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    net->lock = PTHREAD_MUTEX_INITIALIZER;
}

void populate_statistics(struct Network* net) {
    for (size_t i = 0; i < net->interfaces_count; ++i) {
        Statistic* stat = &net->interfaces[i];
        time_t now = time(NULL);
        snprintf(stat->interface, sizeof(stat->interface), "if%zu", i);
        stat->timestamp = now;
        stat->CRCFLAG = rand() % 2 == 0;
        stat->incoming = rand() % (net->bandwidth_limit / net->interfaces_count);
        stat->outgoing = rand() % (net->bandwidth_limit / net->interfaces_count);
    }
}

void update_network(struct Network* net, bool adjust_limits) {
    pthread_mutex_lock(&net->lock);
    uint64_t total = 0;
    for (size_t i = 0; i < net->interfaces_count; ++i) {
        Statistic* stat = &net->interfaces[i];
        if (!stat->CRCFLAG && adjust_limits) { // Adjust byte count when necessary and prioritize high-traffic interfaces
            float traffic_priority = (float)(stat->incoming + stat->outgoing) / net->bandwidth_limit;
            if (traffic_priority > 0.8f) {
                stat->incoming -= rand() % ((stat->incoming - total) * traffic_priority / 10);
                stat->outgoing -= rand() % ((stat->outgoing - total) * traffic_priority / 10);
            }
        }
        total += stat->incoming + stat->outgoing;
    }
    pthread_mutex_unlock(&net->lock);
}

int main(void) {
