#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LENGTH 256 // Maximum length of the filename
#define EXT_DIGITS 4 // Number of digits in the extension

typedef struct {
    char *filename;
    size_t len;
} FileData;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random(char *str, int length) {
    for (int i = 0; i < length; ++i) {
        str[i] = (i % 36 < 10 ? '0' + (i % 10) : 'a' + (i % 26 - 10)) + ((i % 36 > 9) * (i / 36));
    }
}

char* rename_file(const char *filename) {
    FileData data = { .filename = strdup(filename), .len = strlen(filename) };

    if (data.len + EXT_DIGITS > MAX_LENGTH) {
        free(data.filename);
        return NULL;
    }

    size_t ext_start = data.len - 1;
    while (ext_start > 0 && filename[ext_start] != '.') ext_start--;

    if (ext_start == 0) { // No extension found, add .txt by default
        strcat(data.filename, ".txt");
        data.len += 5;
    } else {
        data.len -= ext_start + 1;
    }

    pthread_mutex_lock(&mutex);
    time_t timestamp = time(NULL);
    char timestr[20];
    strftime(timestr, sizeof(timestr), "%Y%m%d_%H%M%S", localtime(&timestamp));

    generate_random(data.filename + data.len, EXT_DIGITS);
    sprintf(data.filename + data.len + EXT_DIGITS, ".%s%ld", timestr, (long)pthread_self());

    if (data.len + strlen(data.filename + data.len + EXT_DIGITS) > MAX_LENGTH) {
        free(data.filename);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    pthread_mutex_unlock(&mutex);

    return data.filename;
}
