        if (strchr(&filename[pos_dot + num_digits], allowed_chars[i][0])) {
            strcpy(&ext[num_digits], allowed_chars[i]);
            break;
        }
    }

    int new_len = pos_dot != -1 ? len + num_digits + strlen(ext) : len + num_digits + strlen(allowed_chars[0]);
    if (new_len > max_len) return; // Return if the new filename is too long

    sprintf(filename, "%.*s%*.*%s", pos_dot != -1 ? pos_dot : len, filename, num_digits, num_digits, ext);

    log_info("Renamed %s to %s", filename, filename + pos_dot + 1);
}
