#include <string.h>

struct aes_gcm_ctx {
    AES_KEY aes_key;
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char tag[AES_GCM_TAG_LENGTH];
};

void aes_gcm_init(struct aes_gcm_ctx *ctx, const char *password, size_t iterations, const unsigned char *salt, size_t salt_len) {
    EVP_CIPHER_CTX *evp_ctx = EVP_AES_256_GCM_ctx_new();
    EVP_CIPHER_CTX *derivation_ctx = EVP_PBE_keygen_init();

    // Derive key and tag from password using PBKDF2
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char tag[AES_GCM_TAG_LENGTH];
    size_t key_len = sizeof(key);
    size_t tag_len = sizeof(tag);
    EVP_CIPHER_CTX_ctrl(derivation_ctx, EVP_CTRL_PBKDF2_HMAC, EVP_sha256(), iterations, salt, salt_len, key_len, (const unsigned char *)password, strlen((const char *)password));
    EVP_PBE_CIPHER_init_derived(derivation_ctx, NULL, key, tag);
    EVP_CIPHER_CTX_get_tcipher(derivation_ctx, &ctx->aes_key.ctx);
    EVP_CIPHER_CTX_ctrl(derivation_ctx, EVP_CTRL_GCM_GET_TAG, tag_len, ctx->tag);

    // Generate a new IV for each encryption operation
    RAND_bytes(ctx->iv, sizeof(ctx->iv));

    // Store the derived key and tag in the context structure
    memcpy(ctx->aes_key.key, key, AES_BLOCK_SIZE);
    ctx->aes_key.iv = ctx->iv;

    // Cleanup resources
    EVP_CIPHER_CTX_free(derivation_ctx);
    EVP_AES_256_GCM_set_encrypt(evp_ctx, &ctx->aes_key, ctx->iv, ctx->tag);
}

int aes_gcm_encrypt(struct aes_gcm_ctx *ctx, unsigned char *out, size_t outlen, const unsigned char *in, size_t inlen) {
    int len;
    AES_GCM_encrypt(out, &len, in, inlen, ctx->iv, ctx->tag, &ctx->aes_key);
    if (out + len > out + outlen) return 0; // Buffer overflow
    outlen = len;
    return 1;
}

int aes_gcm_decrypt(struct aes_gcm_ctx *ctx, unsigned char *out, size_t outlen, const unsigned char *in, size_t inlen) {
    int len;
    AES_GCM_decrypt(out, &len, in, inlen, ctx->iv, ctx->tag, &ctx->aes_key);
    if (out + len > out + outlen) return 0; // Buffer overflow
    outlen = len;
    return 1;
}
```

