    if (g_log_enabled || !log_path) return;
    g_log_enabled = 1;
    g_log_file = fopen(log_path, "w");
}

void log_data(NFAPI_LTE_PDU_T* data) {
    if (!g_log_enabled || !g_log_file) return;
    fprintf(g_log_file, "[%d] [%02x %02x %02x %02x] %hu\n",
            data->TX_UE_INFORMATION_TAG,
            data->PREAMBLE_SEQUENCE[0], data->PREAMBLE_SEQUENCE[1],
            data->PREAMBLE_SEQUENCE[2], data->PREAMBLE_SEQUENCE[3],
            data->CELL_ID);
}

void* memory_pool_malloc(size_t size) {
    void* ptr = malloc(alignof(NFAPI_LTE_PDU_T) * size + sizeof(struct memory_block));
    if (!ptr) return NULL;
    struct memory_block* mem_block = (struct memory_block*)ptr;
    memset(mem_block, 0, sizeof(*mem_block));
    mem_block->data = (NFAPI_LTE_PDU_T*)((uintptr_t)mem_block + alignof(struct memory_block));
    mem_block->num_elements = size;
    mem_block->capacity = size;
    return mem_block->data;
}

void* get_memory(size_t num_elements) {
    void* ptr = memory_pool_malloc(num_elements);
    if (!ptr) return NULL;
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_LTE_PDU_T* elem = ptr + i;
        elem->TX_UE_INFORMATION_TAG = rand();
        for (size_t j = 0; j < sizeof(elem->PREAMBLE_SEQUENCE); ++j) {
            elem->PREAMBLE_SEQUENCE[j] = rand() % 256;
        }
        elem->CELL_ID = rand();
    }
    pthread_mutex_unlock(&mutex);
    return ptr;
}

void free_memory(void* mem) {
    if (!mem) return;
    struct memory_block* mem_block = (struct memory_block*)((uintptr_t)mem - sizeof(struct memory_block));
    pthread_mutex_lock(&mutex);
    memset(mem_block->data, 0, mem_block->num_elements * sizeof(NFAPI_LTE_PDU_T));
    mem_block->num_elements = 0;
    pthread_mutex_unlock(&mutex);
}

void reset_memory() {
    if (!g_log_file) return;
    fseek(g_log_file, 0, SEEK_SET);
    fprintf(g_log_file, "");
}

int main(int argc, char** argv) {
    size_t num_elements = atoi(argv[1]);
    int seed = atoi(argv[2]);
    if (argc < 3 || num_elements <= 0) return ERROR;
