typedef struct {
    time_t timestamp;
    enum { DEBUG, INFO, WARN, ERROR } log_level;
    size_t message_len;
    char *message;
} NFAPI_LOG_PDU_T;

#define MAX_MESSAGE_LEN 256

static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_LOG_PDU_T *pool = NULL;
static size_t pool_capacity = 0, pool_size = 0;

NFAPI_LOG_PDU_T* create_log_entry() {
    NFAPI_LOG_PDU_T *entry = malloc(sizeof(NFAPI_LOG_PDU_T));
    if (!entry) return NULL;
    entry->timestamp = time(NULL);
    entry->log_level = DEBUG; // Set default log level to DEBUG, update as needed
    entry->message_len = 0;
    entry->message = NULL;
    return entry;
}

void destroy_log_entry(NFAPI_LOG_PDU_T *entry) {
    if (entry && entry->message) free(entry->message);
    free(entry);
}

NFAPI_LOG_PDU_T* get_log_entry() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_size < pool_capacity) {
        NFAPI_LOG_PDU_T *entry = pool + pool_size++;
        entry->message_len = 0;
        entry->message = NULL;
        pthread_mutex_unlock(&pool_mutex);
        return entry;
    }
    pthread_mutex_unlock(&pool_mutex);

    NFAPI_LOG_PDU_T *entry = create_log_entry();
    if (!entry) {
        fprintf(stderr, "Failed to allocate log entry\n");
        return NULL;
    }
    return entry;
}

void put_log_entry(NFAPI_LOG_PDU_T *entry) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_size > pool_capacity) {
        // Reallocate the pool if it's full, assuming a factor of 2 for growth
        NFAPI_LOG_PDU_T *new_pool = realloc(pool, sizeof(NFAPI_LOG_PDU_T) * (pool_capacity * 2));
        if (!new_pool) {
            fprintf(stderr, "Failed to reallocate pool\n");
            destroy_log_entry(entry);
            pthread_mutex_unlock(&pool_mutex);
            return;
        }
        pool = new_pool;
        pool_capacity *= 2;
    }
    pool[pool_size - 1] = *entry;
    destroy_log_entry(entry);
    pthread_mutex_unlock(&pool_mutex);
}

void log_message(const char* message, enum { DEBUG, INFO, WARN, ERROR } log_level) {
    size_t len = strlen(message);
    if (len > MAX_MESSAGE_LEN) return;

    NFAPI_LOG_PDU_T *entry = get_log_entry();
    if (!entry) return;

    entry->message_len = len;
    entry->message = strdup(message);
    entry->log_level = log_level;

    printf("[%ld] [%s] [%s]: %s\n", entry->timestamp, log_level == DEBUG ? "DEBUG" : (log_level == INFO ? "INFO" : (log_level == WARN ? "WARN" : "ERROR")), ctime(&entry->timestamp), message);
    put_log_entry(entry);
}
```

