#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_MSG_LEN 256
#define LOG_LEVEL_MAX 4
#define GROWTH_FACTOR 2

typedef struct NFAPI_LOG_PDU_T {
    time_t timestamp;
    enum {DEBUG, INFO, WARN, ERROR} level;
    char message[MAX_MSG_LEN];
    struct NFAPI_LOG_PDU_T *next;
} LogEntry;

static LogEntry *pool = NULL, *head = NULL, *tail = NULL, count = 0;
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t pool_notempty = PTHREAD_COND_INITIALIZER;

void log_init(size_t N) {
    if (N == 0) return;
    LogEntry *entry, **ppool = &pool;
    size_t i;

    for (i = 0; i < N; ++i) {
        if (!(*ppool = malloc(sizeof(LogEntry))) ||
            !((*ppool)->next = malloc(sizeof(LogEntry)))) {
                free_pool();
                return;
        }
        (*ppool)->timestamp = time(NULL);
        (*ppool)->level = INFO;
        (*ppool)->message[0] = '\0';
        (*ppool)->next = NULL;
    }
}

void log_create(const char *msg, enum log_level level) {
    LogEntry *entry, **ppool = &pool;

    if (!msg || !*msg || strlen(msg) >= MAX_MSG_LEN) return;

    pthread_mutex_lock(&pool_mutex);
    while (count == 0 || head == tail) {
        pthread_cond_wait(&pool_notempty, &pool_mutex);
    }
    entry = head;
    head = entry->next;
    count--;
    if (head) tail = head;
    entry->level = level;
    strncpy(entry->message, msg, MAX_MSG_LEN - 1);
    entry->timestamp = time(NULL);
    pthread_mutex_unlock(&pool_mutex);
}

void log_print() {
    LogEntry *cur = head;
    while (cur) {
        printf("[%s] [%s] %s\n", asctime(localtime(&cur->timestamp)),
            level_str[cur->level], cur->message);
        cur = cur->next;
    }
}

void free_pool() {
    LogEntry *cur, *next;

    pthread_mutex_lock(&pool_mutex);
    for (cur = pool; pool; cur = next) {
        next = cur->next;
        free(cur);
    }
    pool = head = tail = NULL;
    count = 0;
    pthread_cond_destroy(&pool_notempty);
    pthread_mutex_unlock(&pool_mutex);
}

char* level_str[LOG_LEVEL_MAX] = { "DEBUG", "INFO", "WARN", "ERROR" };
```

