// Custom error codes
enum class ErrorCode { SUCCESS, INSUFFICIENT_MEMORY, LOG_FILE_ERROR, FILE_OPEN_ERROR };

struct NFAPI_LTE_PDU_T {
    uint32_t TX_UE_INFORMATION_TAG;
    std::array<uint8_t, 8> PREAMBLE_SEQUENCE;
    uint16_t CELL_ID;
};

class MemoryPool {
private:
    std::vector<NFAPI_LTE_PDU_T*> pool;
    std::mutex mtx;

public:
    NFAPI_LTE_PDU_T* allocate() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!pool.empty()) {
            auto result = pool.back();
            pool.pop_back();
            return result;
        }
        return new NFAPI_LTE_PDU_T();
    }

    void deallocate(NFAPI_LTE_PDU_T* pdu) {
        std::lock_guard<std::mutex> lock(mtx);
        pool.push_back(pdu);
    }
};

MemoryPool memoryPool;

ErrorCode createStructures(size_t M, uint32_t seed, const char* logFile) {
    if (M == 0) return ErrorCode::LOG_FILE_ERROR; // Handle edge case: zero input

    std::vector<NFAPI_LTE_PDU_T*> structures(M);
    for (auto& pdu : structures) {
        pdu = memoryPool.allocate();
        if (!pdu) return ErrorCode::INSUFFICIENT_MEMORY;
    }

    std::srand(seed);
    std::uniform_int_distribution<uint32_t> distTxUeInformationTag(0, std::numeric_limits<uint32_t>::max());
    std::uniform_int_distribution<uint16_t> distCellId(0, 65535);

    for (size_t i = 0; i < M; ++i) {
        structures[i]->TX_UE_INFORMATION_TAG = distTxUeInformationTag(std::random_device{}());
        std::fill(structures[i]->PREAMBLE_SEQUENCE.begin(), structures[i]->PREAMBLE_SEQUENCE.end(), 0);
        structures[i]->CELL_ID = distCellId(std::random_device{});
    }

    if (logFile) {
        std::ofstream log;
        log.open(logFile);
        if (log.is_open()) {
            for (const auto& pdu : structures) {
                log << "Tag: " << pdu->TX_UE_INFORMATION_TAG << ", PREAMBLE_SEQUENCE: "
                   << std::to_string(pdu->PREAMBLE_SEQUENCE[0]) + "," +
                   std::to_string(pdu->PREAMBLE_SEQUENCE[1]) + "," +
                   std::to_string(pdu->PREAMBLE_SEQUENCE[2]) + "," +
                   std::to_string(pdu->PREAMBLE_SEQUENCE[3]) + "," +
                   std::to_string(pdu->PREAMBLE_SEQUENCE[4]) + "," +
                   std::to_string(pdu->PREAMBLE_SEQUENCE[5]) + "," +
                   std::to_string(pdu->PREAMBLE_SEQUENCE[6]) + "," +
                   std::to_string(pdu->PREAMBLE_SEQUENCE[7]) << ", CELL_ID: " << pdu->CELL_ID << '\n';
            }
        } else {
            return ErrorCode::FILE_OPEN_ERROR;
        }
    }

    // Performance monitoring
    auto start = std::chrono::high_resolution_clock::now();

    // Use the dynamically allocated structures here...

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<double>(end - start).count();
    // Log the time taken for allocation and populating the structures.

    for (auto& pdu : structures) {
        memoryPool.deallocate(pdu);
    }

    return ErrorCode::SUCCESS;
}

ErrorCode reinitialize() {
    std::fill(memoryPool.pool.begin(), memoryPool.pool.end(), nullptr);
    return ErrorCode::SUCCESS;
}
