    return true;
}

bool populateAndSerializeNFAPDUList(NODE** head, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = i + 1;
        data.RNTI = rand() % 65536;
        while (!isUniqueRNTI(data, head)) {
            data.RNTI = rand() % 65536;
        }
        data.CRC_INDICATION_REL8_TAG[0] = (i + 1) / 256;
        data.CRC_INDICATION_REL8_TAG[1] = (i + 1) % 256;
        data.CRC_INDICATION_REL8_TAG[2] = (data.RNTI >> 8) & 0xFF;
        data.CRC_INDICATION_REL8_TAG[3] = data.RNTI & 0xFF;
        NODE* newNode = createNode(data);
        if (!newNode) return false;
        appendToList(head, newNode);
    }
    return true;
}

