```c
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

NFAPI_CRC_INDICATION_PDU* createNode(uint32_t rxTag, uint16_t rnti, uint8_t crcFlag) {
    NFAPI_CRC_INDICATION_PDU *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!node) return NULL;

    node->RX_UE_INFORMATION_TAG = rxTag;
    node->RNTI = rnti;
    node->CRC_INDICATION_REL8_TAG = crcFlag;
    node->prev = NULL;
    node->next = NULL;

    return node;
}

bool addNode(NFAPI_CRC_INDICATION_PDU** head, NFAPI_CRC_INDICATION_PDU* newNode) {
    if (!head || !newNode) return false;

    if (*head == NULL) {
        *head = newNode;
        return true;
    }

    NFAPI_CRC_INDICATION_PDU* current = *head;
    while (current->next != NULL) {
        if (current->RNTI == newNode->RNTI) return false;  // Ensure RNTI uniqueness
        current = current->next;
    }

    newNode->prev = current;
    newNode->next = current->next;
    current->next = newNode;
    if (newNode->next) newNode->next->prev = newNode;

    return true;
}

void populateAndSerializeNFAPDUList(const int size, NFAPI_CRC_INDICATION_PDU** head) {
    // Populate the doubly linked list with unique RNTI values and initialize CRCFLAG randomly.
    for (int i = 0; i < size; ++i) {
        addNode(head, createNode(i, i, rand() % 2));
    }
}

