void init_mutex(sem_t* mutex) {
    sem_init(mutex, 1, 1);
}

struct dynamic_linked_list* create_node(LTE_RRC_ProtocolConfig config) {
    struct dynamic_linked_list* node = (struct dynamic_linked_list*)malloc(sizeof(struct dynamic_linked_list));
    node->data = malloc(sizeof(LTE_RRC_ProtocolConfig));
    *node->data = config;
    init_mutex(&node->data->sib_mutex);
    node->next = NULL;
    return node;
}

void free_node(struct dynamic_linked_list* node) {
    if (node == NULL)
        return;
    free(node->data);
    free(node);
}

void insert_at_head(struct dynamic_linked_list** head, LTE_RRC_ProtocolConfig config) {
    struct dynamic_linked_list* node = create_node(config);
    node->next = *head;
    *head = node;
}

struct dynamic_linked_list* find_by_id(struct dynamic_linked_list** head, unsigned long id) {
    struct dynamic_linked_list* current = *head;
    while (current != NULL) {
        if (current->data->id == id)
            return current;
        current = current->next;
    }
    return NULL;
}

void adjust_sibs(struct dynamic_linked_list* node, unsigned char* new_sibs, unsigned int new_sibs_len) {
    sem_wait(&node->data->sib_mutex);
    free(node->data->configured_sibs);
    node->data->configured_sibs = malloc(new_sibs_len * sizeof(unsigned char));
    memcpy(node->data->configured_sibs, new_sibs, new_sibs_len * sizeof(unsigned char));
    node->data->configured_sibs_len = new_sibs_len;
    sem_post(&node->data->sib_mutex);
}
