typedef struct TileConfiguration {
    int tileID;
    int width, height;
    time_t lastModified;
    struct WorldConfig *worlds;
    size_t numWorlds;
} TileConfiguration;

struct ThreadSafeList {
    TileConfiguration **tiles;
    size_t capacity;
    size_t count;
    sem_t lock;
};

void initThreadSafeList(struct ThreadSafeList *list, size_t initialCapacity) {
    list->capacity = initialCapacity;
    list->count = 0;
    list->tiles = mmap(NULL, sizeof(TileConfiguration*) * initialCapacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list->tiles == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    list->lock = sem_init(Sem_UNBOUNDED, TRUE, 1);
}

void destroyThreadSafeList(struct ThreadSafeList *list) {
    for (size_t i = 0; i < list->count; ++i)
        free(list->tiles[i]);
    munmap(list->tiles, sizeof(TileConfiguration*) * list->capacity);
    sem_destroy(&list->lock);
}

void addTile(struct ThreadSafeList *list, TileConfiguration tile) {
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        TileConfiguration **newTiles = realloc(list->tiles, sizeof(TileConfiguration*) * newCapacity);
        if (!newTiles) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        list->tiles = newTiles;
        list->capacity = newCapacity;
    }
    sem_wait(&list->lock);
    list->tiles[list->count++] = malloc(sizeof(TileConfiguration));
    memcpy(list->tiles[list->count - 1], &tile, sizeof(TileConfiguration));
    sem_post(&list->lock);
}

void removeTile(struct ThreadSafeList *list, int tileID) {
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (list->tiles[i]->tileID == tileID) {
            sem_wait(&list->lock);
            TileConfiguration *toDelete = list->tiles[i];
            memmove(list->tiles + i, list->tiles + i + 1, --list->count - i);
            free(toDelete);
            sem_post(&list->lock);
            break;
        }
    }
}

