#include "TileConfiguration.h"

class TileList {
private:
    std::list<TileConfiguration> tileConfigs;
    std::mutex mtx;
    semaphore_t lock; // Used to enforce thread safety during list manipulation
    size_t capacity;
    std::unordered_map<TileID, TileConfiguration*> cache;
    std::atomic<size_t> readCounter;
    std::atomic<size_t> writeCounter;

public:
    TileList(size_t initialCapacity) : capacity(initialCapacity), lock(capacity), readCounter(0), writeCounter(0) {}

    void addTileConfig(const TileConfiguration& config);
    TileConfiguration* getTileConfigById(TileID id);
    void updateTileConfigById(TileID id, const TileConfiguration& newConfig);
    void removeTileConfigById(TileID id);
};

void TileList::addTileConfig(const TileConfiguration& config) {
    pthread_mutex_lock(&lock);
    tileConfigs.push_back(config);
    cache[config.getTileID()] = &tileConfigs.back();
    pthread_mutex_unlock(&lock);
}

TileConfiguration* TileList::getTileConfigById(TileID id) {
    pthread_mutex_lock(&lock);
    auto it = cache.find(id);
    if (it != cache.end()) {
        readCounter++;
        return it->second;
    }
    pthread_mutex_unlock(&lock);

    std::unique_lock<std::mutex> lck(mtx); // Lock to synchronize thread-safe access within the function
    it = cache.find(id);
    if (it != cache.end()) {
        readCounter++;
        return it->second;
    }

    for (auto& tile : tileConfigs) {
        if (tile.getTileID() == id) {
            cache[id] = &tile;
            readCounter++;
            return &tile;
        }
    }

    pthread_mutex_unlock(&lock); // Unlock mutex since no matching configuration was found in the first lock

    lck.unlock(); // Unlock mutex to allow other threads to proceed

    // Retry logic and fallback strategies (e.g., exponential backoff, timeout, etc.) can be implemented here if needed

    return nullptr;
}

void TileList::updateTileConfigById(TileID id, const TileConfiguration& newConfig) {
    pthread_mutex_lock(&lock);
    auto it = cache.find(id);
    if (it != cache.end()) {
        writeCounter++;
        *it->second = newConfig;
        pthread_mutex_unlock(&lock);
        return;
    }
    pthread_mutex_unlock(&lock);

    std::unique_lock<std::mutex> lck(mtx); // Lock to synchronize thread-safe access within the function
    it = cache.find(id);
    if (it != cache.end()) {
        writeCounter++;
        *it->second = newConfig;
        pthread_mutex_unlock(&mtx);
        return;
    }

    for (auto& tile : tileConfigs) {
        if (tile.getTileID() == id) {
            cache[id] = &tile;
            writeCounter++;
            memcpy(const_cast<TileConfiguration*>(&tile), &newConfig, sizeof(TileConfiguration));
            pthread_mutex_unlock(&mtx);
            return;
        }
    }

    pthread_mutex_unlock(&lock); // Unlock mutex since no matching configuration was found in the first lock

    lck.unlock(); // Unlock mutex to allow other threads to proceed

    // Retry logic and fallback strategies (e.g., exponential backoff, timeout, etc.) can be implemented here if needed
}

void TileList::removeTileConfigById(TileID id) {
    pthread_mutex_lock(&lock);
    auto it = cache.find(id);
    if (it != cache.end()) {
        writeCounter++;
        tileConfigs.erase(it->second);
        cache.erase(it);
        pthread_mutex_unlock(&lock);
        return;
    }
    pthread_mutex_unlock(&lock);

    std::unique_lock<std::mutex> lck(mtx); // Lock to synchronize thread-safe access within the function
    it = cache.find(id);
    if (it != cache.end()) {
        writeCounter++;
        tileConfigs.erase(it->second);
        cache.erase(it);
        pthread_mutex_unlock(&mtx);
        return;
    }
}
