typedef struct {
    time_t timestamp;
    double frequency_offset;
    double phase_noise;
    double snr;
    double ssi[10];
    double csi_rs[10];
} rf_measurement;

#define BUFFER_SIZE 500
#define SAMPLING_INTERVAL 100000 // ns

rf_measurement measurements[BUFFER_SIZE];
int head = 0, tail = 0;
sem_t lock;

void initialize() {
    sem_init(&lock, 0, 1);
}

void enqueue(rf_measurement measurement) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    measurement.timestamp = ts.tv_sec;

    sem_wait(&lock);

    measurements[head] = measurement;
    head = (head + 1) % BUFFER_SIZE;

    sem_post(&lock);
}

rf_measurement dequeue() {
    rf_measurement measurement = measurements[tail];
    tail = (tail + 1) % BUFFER_SIZE;

    return measurement;
}
