        logEntries = new ConcurrentLinkedQueue<>();
        sourceLogs = new HashMap<>();
        severityLogs = new HashMap<>();
        scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(() -> processLogEntries(), 0, 1, TimeUnit.SECONDS);
    }

