            throw new IllegalArgumentException("Error loading configuration file: " + CONFIG_FILE);
        }
    }

    public void addLogEntry(LogEntry entry) {
        if (entry == null) {
            throw new NullPointerException("Log entry cannot be null.");
        }

        synchronized (logEntries) {
            while (logEntries.size() >= maxEntries) {
                LogEntry oldest = logEntries.poll();
                removeFromLogMaps(oldest);
            }

            if (!logEntries.add(entry)) {
                throw new IllegalStateException("Attempted to add duplicate timestamp.");
