['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct NFAPI_CRC_INDICATION_PDU_T *next, *prev;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

void add_head(NFAPI_CRC_INDICATION_PDU_T **list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    if (!new_node) return;

    if (*list) {
        new_node->next = *list;
        (*list)->prev = new_node;
    }

    *list = new_node;
}

void add_tail(NFAPI_CRC_INDICATION_PDU_T **list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    if (!new_node) return;

    if (*list == NULL) {
        *list = new_node;
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = *list;
    while (current->next != NULL) current = current->next;

    current->next = new_node;
    new_node->prev = current;
    new_node->next = NULL;
}

