#define LOCK_COUNT 32

pthread_mutex_t rnti_lock[LOCK_COUNT];
unsigned int used_rntis[MAX_RNTIs] = { 0 };

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
};

struct list {
    struct list_node* head;
    unsigned int num_elements;
    pthread_mutex_t lock;
};

void init_list(struct list* list) {
    list->head = NULL;
    list->num_elements = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(struct list* list) {
    struct list_node *current, *next;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->num_elements = 0;
    pthread_mutex_unlock(&list->lock);
}

struct list_node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    struct list_node *new_node = (struct list_node*)malloc(sizeof(struct list_node));
    if (!new_node) return NULL;
    new_node->data = *data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    struct list_node *new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        struct list_node *current = list->head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }
    list->num_elements++;
    pthread_mutex_unlock(&list->lock);
}

void remove_node(struct list* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);
    struct list_node *current = list->head;
    struct list_node *prev = NULL;
    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    list->num_elements--;
    pthread_mutex_unlock(&list->lock);
}

unsigned int find_free_rnti() {
    for (int i = 0; i < MAX_RNTIS; ++i) {
        if (!used_rntis[i]) {
            used_rntis[i] = 1;
            return i;
        }
    }
    // If no free RNTI is found, find a used one to recycle
    for (int i = 0; i < MAX_RNTIS; ++i) {
        if (used_rntis[i]) {
            pthread_mutex_lock(&rnti_lock[i % LOCK_COUNT]);
            if (!used_rntis[i]) {
                used_rnti[i] = 1;
                pthread_mutex_unlock(&rnti_lock[i % LOCK_COUNT]);
                return i;
            }
            pthread_mutex_unlock(&rnti_lock[i % LOCK_COUNT]);
        }
    }
    // If no free RNTIs are available, handle the situation gracefully (e.g., return an error code)
}

void populate_data(NFAPI_CRC_INDICATION_PDU_T* data) {
    data->rx_ue_information_tag = rand() % 0xFFFF;
    data->crc_indication_r8_tag = rand() % 2;
    data->timestamp = time(NULL);
