```c
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct Node {
    NFAPI_LTE_DOWNLINK_FRAME_PDU_T data;
    struct Node *prev, *next;
    pthread_mutex_t lock;
} Node;

Node* create_node(const NFAPI_LTE_DOWNLINK_FRAME_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = *data;
    node->prev = node->next = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void add_head(Node** head, Node* new_node) {
    if (!new_node || !head) return;

    new_node->next = *head;
    if (*head) (*head)->prev = new_node;
    *head = new_node;
}

void add_tail(Node** head, Node* new_node) {
    if (!new_node || !head) return;

    if (!*head) {
        *head = new_node;
        return;
    }

    Node* last = *head;
    while (last->next) last = last->next;

    last->next = new_node;
    new_node->prev = last;
}

Node* find_by_RNTI(const Node** head, uint32_t rnti) {
    if (!head || !*head) return NULL;

    Node* current = *head;
    while (current) {
        if (current->data.RNTI == rnti) break;
        current = current->next;
    }

    return current;
}

void update_stats(Node** node, const DL_FRAME_STATS* stats) {
    pthread_mutex_lock(&(*node)->lock);
    // Update the node's DL_FRAME_STATS with the provided stats.
    // ...
    pthread_mutex_unlock(&(*node)->lock);
}

void destroy(Node** head) {
    if (!head || !*head) return;

    Node* current = *head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}
```

