typedef struct {
    size_t capacity;
    size_t count;
    LTE_PHY_PDU_T* array;
} LTE_PHY_PDU_MANAGER_T;

void lte_phy_pdu_manager_init(LTE_PHY_PDU_MANAGER_T *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->array = malloc(initial_capacity * sizeof(LTE_PHY_PDU_T));
}

void lte_phy_pdu_manager_resize(LTE_PHY_PDU_MANAGER_T *manager, size_t new_capacity) {
    if (new_capacity <= manager->capacity || !manager->array) return;

    LTE_PHY_PDU_T* tmp = realloc(manager->array, new_capacity * sizeof(LTE_PHY_PDU_T));
    if (!tmp) {
        fprintf(stderr, "Failed to resize PHY PDU manager\n");
        return;
    }

    manager->array = tmp;
    manager->capacity = new_capacity;
}

void lte_phy_pdu_manager_free(LTE_PHY_PDU_MANAGER_T *manager) {
    if (!manager->array) return;
    free(manager->array);
    manager->count = 0;
    manager->capacity = 0;
}

LTE_PHY_PDU_T* lte_phy_pdu_manager_get(LTE_PHY_PDU_MANAGER_T *manager) {
    if (manager->count >= manager->capacity) lte_phy_pdu_manager_resize(manager, manager->capacity * 2);
    return &manager->array[manager->count++];
}
