    size_t total_size = MAX_NUM_TC * sizeof(LTE_PHY_PDU_T) + (MAX_NUM_TC - 1) * sizeof(unsigned char);
    transport_channel_pool = malloc(total_size);
    memset(transport_channel_pool, 0, total_size);
    num_free_tc = MAX_NUM_TC;
}

LTE_PHY_PDU_T* get_transport_channel() {
    pthread_mutex_lock(&tc_pool_mutex);
    if (num_free_tc > 0) {
        LTE_PHY_PDU_T* tc = &transport_channel_pool[--num_free_tc];
        return tc;
    }
    pthread_mutex_unlock(&tc_pool_mutex);
    // Return NULL if no free transport channel is available
    return NULL;
}

void put_transport_channel(LTE_PHY_PDU_T* tc) {
    pthread_mutex_lock(&tc_pool_mutex);
    if (num_free_tc < MAX_NUM_TC) {
        transport_channel_pool[num_free_tc++] = *tc;
    }
    pthread_mutex_unlock(&tc_pool_mutex);
}

void reset_transport_channels() {
    pthread_mutex_lock(&tc_pool_mutex);
    num_free_tc = 0;
    memset(transport_channel_pool, 0, sizeof(LTE_PHY_PDU_T) * MAX_NUM_TC);
    pthread_mutex_unlock(&tc_pool_mutex);
}
