    if (allocated_pdus) free(allocated_pdus);
    max_allocated_pdus = num_pdus;
    allocated_pdus = malloc(max_allocated_pdus * sizeof(LTE_PHY_PDU_T));

    pthread_mutex_unlock(&memory_pool_mutex);
}

LTE_PHY_PDU_T* get_free_pdu() {
    LTE_PHY_PDU_T* free_pdu;

