        free_pdu = NULL;
    } else {
        free_pdu = &allocated_pdus[--max_allocated_pdus];
        free(free_pdu->data.data_payload);
        free_pdu->data.is_corrupted = false;
        free_pdu->data.payload_size = 0;
    }
    pthread_mutex_unlock(&memory_pool_mutex);

    return free_pdu;
}

void release_pdu(LTE_PHY_PDU_T* pdu) {
    if (!pdu) return;

    pthread_mutex_lock(&memory_pool_mutex);
    pdu->data.is_corrupted = false;
    free(pdu->data.data_payload);
    pdu->data.payload_size = 0;
    pthread_mutex_unlock(&memory_pool_mutex);
}
