#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <limits.h>

#define MAX_INSTANCES 10000
#define DATA_PAYLOAD_MIN 1024
#define DATA_PAYLOAD_MAX (1024 * 1024) // 1 MB
#define LOG_VERBOSITY_DEFAULT 1

struct LTE_PHY_PDU_T {
    PHY_TRANSPORT_CHANNEL_CONFIG_T config;
    PHY_TRANSPORT_CHANNEL_DATA_T data;
};

typedef struct pdu_pool_t {
    struct LTE_PHY_PDU_T* pdus;
    size_t num_allocated;
    size_t num_active;
    sem_t sem_active;
    pthread_mutex_t mutex;
} pdu_pool_t;

pdu_pool_t* create_pdu_pool(void) {
    pdu_pool_t* pool = mmap(NULL, sizeof(pdu_pool_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    sem_init(&pool->sem_active, 0, 0);
    pthread_mutex_init(&pool->mutex, NULL);

    pool->pdus = malloc(MAX_INSTANCES * sizeof(struct LTE_PHY_PDU_T));
    if (!pool->pdus) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    pool->num_active = 0;
    pool->num_allocated = MAX_INSTANCES;

    return pool;
}

void destroy_pdu_pool(pdu_pool_t* pool) {
    if (munmap(pool, sizeof(pdu_pool_t)) == -1) {
        perror("munmap");
    }

    free(pool->pdus);
    sem_destroy(&pool->sem_active);
    pthread_mutex_destroy(&pool->mutex);
}

struct LTE_PHY_PDU_T* acquire_pdu(pdu_pool_t* pool) {
    sem_wait(&pool->sem_active);

    pthread_mutex_lock(&pool->mutex);
    if (pool->num_allocated == pool->num_active && pool->num_allocated < MAX_INSTANCES) {
        size_t index = pool->num_active++;
        struct LTE_PHY_PDU_T* pdu = &pool->pdus[index];

        pthread_mutex_unlock(&pool->mutex);
        sem_post(&pool->sem_active);
        return pdu;
    }

    pthread_mutex_unlock(&pool->mutex);
    sem_post(&pool->sem_active);

    return NULL;
}

void release_pdu(struct LTE_PHY_PDU_T* pdu, pdu_pool_t* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pdu->data.payload && --pool->num_active == 0 && pool->num_allocated > pool->num_active) {
        size_t chunk_size = 1024; // Adjust this value to control the number of system calls for memory allocations.
        size_t num_chunks = (pool->num_allocated - pool->num_active) / chunk_size + 1;

        free(pool->pdus);
        pool->pdus = malloc((pool->num_active + chunk_size * num_chunks) * sizeof(struct LTE_PHY_PDU_T));
        if (!pool->pdus) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }

        memmove(&pool->pdus[pool->num_active], &pool->pdus[0], pool->num_active * sizeof(struct LTE_PHY_PDU_T));

        pool->num_allocated -= chunk_size * num_chunks;
    }

    pthread_mutex_unlock(&pool->mutex);
    sem_post(&pool->sem_active);
}

void* generate_data(void* pdu) {
    struct LTE_PHY_PDU_T* pdu_ptr = (struct LTE_PHY_PDU_T*)pdu;

    // Initialize the data structures with valid configurations.
    // Generate a random payload size within the specified bounds.
    pdu_ptr->data.payload = malloc(rand() % (DATA_PAYLOAD_MAX - DATA_PAYLOAD_MIN + 1) + DATA_PAYLOAD_MIN);
    if (!pdu_ptr->data.payload) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Implement logging and error handling as needed.
    // ...

    return NULL;
}

void query_average_payload_size(pdu_pool_t* pool) {
    pthread_mutex_lock(&pool->mutex);

    double sum = 0;
    size_t count = 0;
    for (size_t i = 0; i < pool->num_active; ++i) {
        if (pool->pdus[i].data.payload) {
            sum += strlen((char*)pool->pdus[i].data.payload);
            count++;
        }
    }

    pthread_mutex_unlock(&pool->mutex);

    if (count > 0) {
        printf("Average data payload size: %.2f bytes\n", sum / count);
    } else {
        printf("No active instances with data payloads.\n");
    }
}
