double get_avg_timeout() {
    double total = 0.0, count = 0.0;
    pthread_mutex_lock(&connections_lock);
    for (size_t i = 0; i < total_conn / CHUNK_SIZE; ++i) {
        if (connections[i].state == ACTIVE) {
            total += connections[i].data.timeout;
            ++count;
        }
    }
    pthread_mutex_unlock(&connections_lock);
    return total / count;
}

// Helper function to find a free connection slot
void *find_free_slot(void *arg) {
    size_t i;
    for (i = 0; i < total_conn / CHUNK_SIZE; ++i) {
        pthread_mutex_lock(&connections[i].lock);
        if (!connections[i].is_active) {
            connections[i].is_active = true;
            pthread_mutex_unlock(&connections[i].lock);
            pthread_cond_signal(&conn_ready_condition);
            break;
        }
        pthread_mutex_unlock(&connections[i].lock);
    }
    if (i == total_conn / CHUNK_SIZE) {
        // Extend array if needed
        size_t new_size = (total_conn + CHUNK_SIZE) * 2;
        NETWORK_CONNECTION_T *new_connections = realloc(connections, sizeof(NETWORK_CONNECTION_T) * new_size);
        if (!new_connections) {
            perror("Failed to extend memory for connections");
            exit(1);
        }
        memset(&new_connections[total_conn / CHUNK_SIZE], 0, sizeof(NETWORK_CONNECTION_T) * (new_size - total_conn / CHUNK_SIZE));
        connections = new_connections;
        total_conn = new_size;
    }
    return NULL;
}

void create_connection(time_t timeout, const char *user_data) {
    pthread_t tid;
    NETWORK_CONNECTION_T *conn;
    init_connections();

    if (pthread_create(&tid, NULL, find_free_slot, NULL)) {
        perror("Failed to create thread for finding free slot");
        exit(1);
    }

    pthread_mutex_lock(&connections_lock);
    while (!get_active_conn_count() < MAX_CONN) pthread_cond_wait(&conn_ready_condition, &connections_lock);
    conn = connections[--total_conn / CHUNK_SIZE];
    conn->state = CONNECTING;
    conn->data.timeout = timeout;
    strcpy(conn->data.user_data, user_data);
    pthread_mutex_init(&conn->lock, NULL);
    pthread_mutex_unlock(&connections_lock);

    if (pthread_create(&tid, NULL, connect_function, conn)) {
        perror("Failed to create thread for connection");
        exit(1);
    }
}

// Placeholder function for handling connection logic
void *connect_function(void *arg) {
    NETWORK_CONNECTION_T *conn = arg;
    // Connection logic goes here...
    conn->state = ACTIVE;
    pthread_mutex_unlock(&conn->lock);
    return NULL;
}

// Clean up inactive connections periodically
void clean_inactive() {
    time_t now = time(NULL);
    size_t i;
    for (i = 0; i < total_conn / CHUNK_SIZE; ++i) {
        pthread_mutex_lock(&connections[i].lock);
        if (connections[i].state == CLOSED || now - connections[i].data.timeout > 60) {
            connections[i].is_active = false;
            memset(&connections[i], 0, sizeof(NETWORK_CONNECTION_T));
        }
        pthread_mutex_unlock(&connections[i].lock);
    }
}
