typedef struct HashTable {
    unsigned long capacity;
    unsigned long size;
    Session **data;
    pthread_mutex_t table_lock;
} HashTable;

// Helper function for computing hash value
unsigned long hash(char *key, unsigned long capacity) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % capacity;
}

// Function to initialize the hash table
HashTable* init_hashtable(unsigned long capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    table->capacity = capacity;
    table->size = 0;
    table->data = calloc(capacity, sizeof(Session*));
    if (!table->data) {
        perror("calloc");
        free(table);
        exit(EXIT_FAILURE);
    }

    table->table_lock = PTHREAD_MUTEX_INITIALIZER;

    return table;
}

// Function to add a session to the hash table
void add_session(HashTable *table, char *session_id, char *payload, time_t timestamp) {
    unsigned long index = hash(session_id, table->capacity);
    pthread_mutex_lock(&table->table_lock);

    // Resize the hash table if necessary
    if (table->size == table->capacity) {
        unsigned long new_capacity = table->capacity * 2;
        Session **new_data = realloc(table->data, new_capacity * sizeof(Session*));
        if (!new_data) {
            perror("realloc");
            pthread_mutex_unlock(&table->table_lock);
            exit(EXIT_FAILURE);
        }
        table->data = new_data;
        table->capacity = new_capacity;
    }

    // Allocate and initialize a new session entry
    Session *session = malloc(sizeof(Session));
    if (!session) {
        perror("malloc");
        pthread_mutex_unlock(&table->table_lock);
        exit(EXIT_FAILURE);
    }

    session->session_id = strdup(session_id);
    session->timestamp = timestamp;
    session->payload = malloc(strlen(payload) + 1);
    if (!session->payload) {
        free(session->session_id);
        free(session);
        perror("malloc");
        pthread_mutex_unlock(&table->table_lock);
        exit(EXIT_FAILURE);
    }

    strcpy(session->payload, payload);
    pthread_mutex_init(&session->payload_lock, NULL);

    table->data[index] = session;
    table->size++;

    pthread_mutex_unlock(&table->table_lock);
}

// Periodic background cleanup function for expired sessions
void clean_expired_sessions(HashTable *table, time_t current_time) {
    pthread_mutex_lock(&table->table_lock);

    unsigned long i;
    for (i = 0; i < table->capacity; i++) {
        Session *session = table->data[i];
        if (!session) continue;

        if (difftime(current_time, session->timestamp) > 60*60) { // Adjust the timeout value as needed
            free(session->session_id);
            free(session->payload);
            pthread_mutex_destroy(&session->payload_lock);
            free(session);

            table->data[i] = NULL;
            table->size--;
        }
    }

    pthread_mutex_unlock(&table->table_lock);
}

