void initList(List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->allocatedCount = 0;
    list->populatedCount = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void insertNode(List* list, Node* node) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        node->prev = list->tail;
        list->head->prev = node;
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

