import java.io.BufferedInputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.*;
import java.util.logging.*;

public class Md5HashFunction {
    private static final Logger LOGGER = Logger.getLogger(Md5HashFunction.class.getName());
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public void calculateHash(String filePath) throws IOException, InterruptedException, ExecutionException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        File file = new File(filePath);
        if (!file.exists()) {
            LOGGER.severe("File not found: " + filePath);
            throw new FileNotFoundException(filePath);
        }
        Path path = Paths.get(filePath);
        if (Files.isSymbolicLink(path)) {
            URL url = new URL(filePath);
            LOGGER.info("Processing remote file: " + url.toURI());
            InputStream is = url.openStream();
            try (BufferedInputStream bis = new BufferedInputStream(is)) {
                processFile(bis, md);
            } catch (IOException e) {
                LOGGER.log(Level.SEVERE, "Error processing remote file: ", e);
                throw e;
            } finally {
                is.close();
            }
        } else if (!file.isFile()) {
            LOGGER.severe("The specified path is not a file: " + filePath);
            throw new IllegalArgumentException("Invalid file path");
        } else {
            processFile(new FileInputStream(file), md);
        }
        BigInteger bigInt = new BigInteger(1, md.digest());
        LOGGER.info("Calculated MD5 hash: " + bigInt.toString(16));
    }

    private void processFile(InputStream is, MessageDigest md) throws IOException {
        final byte[] buffer = new byte[8 * 1024];
        int read;
        while ((read = is.read(buffer)) > 0 && !Thread.currentThread().isInterrupted()) {
            md.update(buffer, 0, read);
        }
        if (read < 0) {
            // End of the file has been reached or thread was interrupted
            LOGGER.info("File processing completed");
        } else if (is instanceof FileInputStream) {
            is.close();
        }
    }

    private void sendMessage() {
        // Implement messaging system logic here
    }

    public static void main(String[] args) throws Exception {
        Md5HashFunction hashFunction = new Md5HashFunction();
        String filePath = "path/to/your/file.txt";
        Random rand = new Random();
        long delayMilliseconds = 100 + (long)(Math.abs(rand.nextInt()) % 200);
        Thread.sleep(delayMilliseconds);
        hashFunction.calculateHash(filePath);
        Thread.sleep(delayMilliseconds);
        hashFunction.sendMessage();
    }
}
