        structures[i].crc_indication_rel8_tag[2] = rand() & 0xFF; // LSBs of RNTI MSBs
        structures[i].crcflag = (rand() % 2) == 1;
        structures[i].timestamp = time(NULL);
    }

    return structures;
}

void prune_unused_structures() {
    if (prune_interval > 0 && structures_in_use > num_structures / 2) {
        log("Pruning unused structures");
        int to_free = structures_in_use - num_structures;
        free(realloc(structures, (max_alloc - to_free) * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
        structures_in_use -= to_free;
    }
}
