#define MAX_ALLOC 1024 // Maximum number of structures allowed in the system at any given time due to resource constraints
pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t prune_cv = PTHREAD_COND_INITIALIZER;
unsigned int num_structures = 0; // Number of structures currently in use

NFAPI_CRC_INDICATION_PDU_T* genStruct(void) {
    NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) { // Handle memory allocation errors
        fprintf(stderr, "Error allocating memory for structure\n");
        return NULL;
    }

    time(&new_struct->timestamp); // Set creation timestamp
    new_struct->CRCFLAG = rand() % 2 == 0; // Set CRCFLAG to random value
    return new_struct;
}

void prune(void) {
    NFAPI_CRC_INDICATION_PDU_T* structures[MAX_ALLOC];
    unsigned int count = 0;

    pthread_mutex_lock(&mtx);
    for (unsigned int i = 0; i < num_structures; ++i) {
        if (time(NULL) - structures[i]->timestamp > 60) { // Prune structures older than 1 minute
            free(structures[i]);
        } else {
            structures[count++] = structures[i];
        }
    }
    num_structures -= MAX_ALLOC - count;
    pthread_mutex_unlock(&mtx);
}

void* generateAndPopulate(int N) {
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* struct_ptr = genStruct();
        if (!struct_ptr) continue; // Handle memory allocation errors and retry logic

        pthread_mutex_lock(&mtx);
        if (num_structures >= MAX_ALLOC) { // Periodic pruning
            prune();
        }
        ++num_structures;
        pthread_mutex_unlock(&mtx);

        printf("Generated structure %d\n", num_structures);
    }
}

int main(int argc, char** argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s N MAX_ALLOC\n", argv[0]);
        return 1;
    }

    int N = atoi(argv[1]);
    int max_alloc = atoi(argv[2]);

    pthread_t tid;
    if (pthread_create(&tid, NULL, generateAndPopulate, (void*)N) != 0) {
        perror("Error creating thread");
        return 1;
    }

    pthread_detach(tid); // Detach the thread to avoid waiting for it to terminate

    while (1) {
        sleep(10); // Adjust this value based on your performance requirements
        prune();
    }

    return 0;
}
