static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t created_structures = 0;

size_t create_and_populate_arr(NFAPI_CRC_INDICATION_PDU_T** arr, size_t num_structures) {
    if (num_structures == 0 || !arr) {
        return 0;
    }

    *arr = calloc(num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!*arr) {
        perror("Memory allocation error");
        return 0;
    }

    pthread_mutex_lock(&mutex);

    // Parallelize structure population with multiple threads to improve performance.
    size_t chunk_size = num_structures / NUM_THREADS + (num_structures % NUM_THREADS > 0 ? 1 : 0);
    pthread_t thread_ids[NUM_THREADS];
    size_t start, end;

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        start = i * chunk_size;
        if (i == NUM_THREADS - 1) {
            end = num_structures;
        } else {
            end = (i + 1) * chunk_size;
        }

        if (pthread_create(&thread_ids[i], NULL, populate_chunk, *arr + start)) {
            perror("Thread creation error");
            pthread_mutex_unlock(&mutex);
            free(*arr);
            return 0;
        }
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(thread_ids[i], NULL)) {
            perror("Thread join error");
            pthread_mutex_unlock(&mutex);
            free(*arr);
            return created_structures;
        }
    }

    pthread_mutex_unlock(&mutex);

    return created_structures;
}

void* populate_chunk(void* chunk) {
