function copyBytes(srcBuffers, destStart, destEnd, numBytes) {
    let dstBuffer = Buffer.allocUnsafe(numBytes);

    for (let i = 0; i < srcBuffers.length; i++) {
        const srcPos = Math.max(0, srcBuffers[i].byteOffset + destStart);
        const len = Math.min(srcBuffers[i].byteLength - srcPos, numBytes - (i - srcBuffers.slice(1).reduce((acc, val) => acc + val.length, 0)));

