void processLogFile(const string &filename, const vector<EventType> &eventTypesToInclude, ostream *out = &cout) {
    ifstream in(filename);
    if (!in.is_open()) {
        cerr << "Error: Could not open log file '" << filename << "'." << endl;
        printHelpMessage();
        return;
    }

    map<string, int> timestamps;
    map<EventType, pair<int, chrono::milliseconds>> eventCountsAndAverages;
