        LogEntry entry;
        ss >> entry.timestamp >> entry.type >> entry.metadata;

        if (entry.type == EventType::DURATION) {
            ss >> entry.start >> entry.end;
        }

        logEntries.push_back(entry);
    }

    int totalLogEntries = logEntries.size();
    out->setf(ios::fixed);
    out->precision(2);

