        if (find(eventTypesToInclude.begin(), eventTypesToInclude.end(), entry.type) != eventTypesToInclude.end()) {
            ++eventCountsAndAverages[entry.type].first;

            if (entry.type == EventType::DURATION && entry.start && entry.end) {
                auto duration = entry.getDuration();
                eventCountsAndAverages[entry.type].second += duration;
            }
        }
    }

    // Process unique timestamps
    for (const LogEntry &entry : logEntries) {
        ++timestamps[entry.timestamp];
    }

    auto it = timestamps.begin();
    advance(it, 1); // Skip first element since it's already sorted
