    // Print event type breakdown
    for (const auto &[type, count] : eventCountsAndAverages) {
        out << type << ": " << count.first << endl;
    }

    // Print average duration of log events with a DURATION field
    if (eventCountsAndAverages.count(EventType::DURATION)) {
        out << "Average duration: " << eventCountsAndAverages[EventType::DURATION].second / totalLogEntries << " ms" << endl;
    }
}

// Print detailed usage instructions
void printHelpMessage() {
    cout << "Usage:\n"
         << "./log_summary [--help] [-o output_file] [event_type...]\n"
         << "\t-h, --help\tPrint this help message.\n"
         << "\t-o output_file, --output output_file\tRedirect the summary to a specified file.\n"
         << "\tevent_type... (optional)\tEvent types to include in the summary. Available event types: INFO, WARNING, ERROR, DURATION." << endl;
}

int main(int argc, char *argv[]) {
    po::options_description desc("Options");
    desc.add_options()
        ("help", "Print help message.")
        ("output,o", po::value<string>()->default_value("-"), "Redirect the summary to a specified file.")
        ("event-type,e", po::value<vector<string>>()->multitoken(), "Event types to include in the summary.");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        printHelpMessage();
        return 0;
    }

    string logFilePath = vm["output"].as<string>();
    vector<EventType> eventTypesToInclude;
    for (const auto &arg : vm["event-type"].as<vector<string>>()) {
        if (arg == "INFO") {
            eventTypesToInclude.push_back(EventType::INFO);
        } else if (arg == "WARNING") {
            eventTypesToInclude.push_back(EventType::WARNING);
        } else if (arg == "ERROR") {
            eventTypesToInclude.push_back(EventType::ERROR);
        } else if (arg == "DURATION") {
            eventTypesToInclude.push_back(EventType::DURATION);
        }
    }

    processLogFile("log.txt", eventTypesToInclude, &logFilePath);

    return 0;
}
```

