    uint32_t SRSC_ID;
    int CHANNEL_MEASUREMENT_RESULT;
    uint8_t MEASUREMENT_QUALITY_FLAG;
} NRUE_INFORMATION_RECORD;

#define STRUCT_SIZE sizeof(NFAPI_L1_API_CONTEXT_T)
#define ELEMENT_COUNT 20000
#define KEY_LEN 32
#define SALT_LEN 8
#define ITERATIONS 100000
#define CIPHER_BLOCK_SIZE AES_BLOCK_SIZE

// Helper function to generate random CRC flag
uint8_t generateRandomCRCFlag() {
    return rand() % 2;
}

// Helper function to generate random number
unsigned int generateRandom(unsigned int max) {
    static const unsigned char seed[] = {
        0x1, 0x2, 0x3, 0x4, 0x5, 0x6, 0x7, 0x8,
        0x9, 0xa, 0xb, 0xc, 0xd, 0xe, 0xf, 0x10
    };

    unsigned int random = seed[rand() % sizeof(seed)];
    for (size_t i = 0; i < 4; ++i) {
        random ^= ((random << 13) | (random >> 19));
        random ^= (random << 8);
    }
    return (random % max);
}

// Function to populate and serialize the NFAList
void populateAndSerializeNFAList(const char *password, size_t *allocated) {
    // Initialize OpenSSL context and cipher
    AES_KEY aesKey;
    unsigned char salt[SALT_LEN];
    memset(salt, 0x0, SALT_LEN);
    for (size_t i = 0; i < SALT_LEN; ++i) {
        salt[i] = rand() % 256;
    }
    PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, SALT_LEN, ITERATIONS, KEY_LEN, key);

    // Initialize doubly linked list and array
    NFAPI_L1_API_CONTEXT_T *head = NULL;
    NFAPI_L1_API_CONTEXT_T *tail = NULL;
    NRUE_INFORMATION_RECORD *nrues = malloc(ELEMENT_COUNT * sizeof(NRUE_INFORMATION_RECORD));

    // Populate structures and serialize list
    size_t populated = 0;
    for (size_t i = 0; i < ELEMENT_COUNT; ++i) {
        NFAPI_L1_API_CONTEXT_T *context = malloc(STRUCT_SIZE);
        if (!context) break; // Handle memory allocation failure

        context->L1_API_VERSION = generateRandom(UINT32_MAX);
        context->RXUEINFO.SRS_REPORTING_CONFIG_ID = generateRandom(UINT32_MAX);
        context->RXUEINFO.SRSC_ID = generateRandom(UINT32_MAX);
        context->RNTI = ((uint64_t)generateRandom(UINT32_MAX) << 32) | generateRandom(UINT32_MAX);
        context->CRC_FLAG = generateRandomCRCFlag();

        if (head == NULL) {
            head = tail = context;
            context->prev = context->next = NULL;
        } else {
            tail->next = context;
            context->prev = tail;
            tail = context;
            tail->next = head;
            head->prev = tail;
        }

        // Serialize the structure and encrypt it using AES-256-CBC
        uint8_t *encryptedData = malloc(STRUCT_SIZE + CIPHER_BLOCK_SIZE);
        if (!encryptedData) break; // Handle memory allocation failure

        AES_CTX_init(&aesContext, &aesKey, salt, ITERATIONS);
        AES_cbc_encrypt((uint8_t *)context, encryptedData, STRUCT_SIZE, &aesContext, iv, AES_ENCRYPT);

        // Populate the corresponding NRUE structure and serialize it
        nrues[populated].SRS_REPORTING_CONFIG_ID = context->L1_API_VERSION;
        nrues[populated].SRSC_ID = context->RXUEINFO.SRS_REPORTING_CONFIG_ID;
        nrues[populated].CHANNEL_MEASUREMENT_RESULT = context->RNTI >> 32;
        nrues[populated].MEASUREMENT_QUALITY_FLAG = generateRandomCRCFlag();

        ++populated;
    }

    // Update the allocated counter and clean up resources
    *allocated = populated;
    free(aesContext.buf);
    free(iv);
    free(head);
}

