#include <iostream>
#include <unordered_map>
#include <vector>
#include <set>
#include <atomic>
#include <boost/asio/io_service.hpp>
#include <boost/asio/deadline_timer.hpp>
#include <boost/interprocess/managed_shared_memory.hpp>
#include <boost/interprocess/containers/vector.hpp>
#include <boost/interprocess/sync/mutex.hpp>
#include <boost/optional.hpp>
#include <boost/log/trivial.hpp>

namespace bip = boost::interprocess;
using namespace std;

struct SensorReading {
    int64_t timestamp;
    int sensorID;
    double value;
};

class TimeSeriesDatabase {
public:
    void processAndPersistSensorData(vector<SensorReading> readings) {
        // Optimistic locking using a version counter
        std::atomic<int64_t> version{0};

        // Create a shared memory segment for data storage
        bip::managed_shared_memory seg(create_only, "timeSeriesData", 1 << 20);
        auto dataMap = seg.find<unordered_map<int, vector<SensorReading>>>("dataMap");
        auto versionLock = seg.find<boost::interprocess::mutex>("versionLock").get_lock();

        // Process and persist readings in batches
        for (size_t i = 0; i < readings.size(); ++i) {
            if (i > 0 && readings[i].timestamp - readings[i - 1].timestamp <= batchSizeMillis)
                continue; // Skip if too close to the last reading

            auto it = dataMap->find(readings[i].sensorID);
            if (it == dataMap->end()) {
                // Create a new vector for this sensor ID and insert the reading
                it = dataMap->emplace(readings[i].sensorID, vector<SensorReading>()).first;
            }
            it->second.push_back(readings[i]);

            // Optimistic locking: increment version counter before writing to shared memory
            ++version;
        }

        versionLock.lock();
        dataMap->modify([](auto& m) {
            for (auto& pair : *m) {
                auto& readings = pair.second;
                sort(readings.begin(), readings.end(), [](const SensorReading& a, const SensorReading& b) { return a.timestamp < b.timestamp; });

                // Remove duplicates and invalid readings (e.g., timestamps out of order or negative values)
                readings.erase(unique(readings.begin(), readings.end()), readings.end());
            }
        });
        versionLock.unlock();

        // Clean up old data based on a configurable retention policy (e.g., delete readings older than 7 days)
        auto retentionDays = 7;
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        auto cutoffTimestamp = now - retentionDays * 24L * 60L * 60L * 1000L;

        for (auto& pair : *dataMap) {
            auto& readings = pair.second;
            readings.erase(remove_if(readings.begin(), readings.end(),
                [cutoffTimestamp](const SensorReading& reading) { return reading.timestamp < cutoffTimestamp; }),
                readings.end());
        }

        // Implement a retry strategy and exponential backoff for network latency and transient failures
        auto ioService = boost::asio::io_service {};
        auto timer = new boost::asio::deadline_timer(ioService);
        auto maxRetries = 3;
        auto backoffFactor = 2.0;

        try {
            seg.dispose(); // Dispose of shared memory segment on success
        } catch (const std::exception& e) {
            int retriesLeft = maxRetries;
            do {
                BOOST_LOG_TRIVIAL(error) << "Failed to dispose of shared memory: " << e.what();
                --retriesLeft;

                auto backoffTimeMillis = std::pow(backoffFactor, retriesLeft);
                timer->expires_from_now(boost::posix_time::milliseconds(backoffTimeMillis));
                timer->async_wait([&](boost::system::error_code ec) {
                    if (!ec) {
                        try {
                            seg.dispose(); // Attempt to dispose of shared memory again
                        } catch (const std::exception& e) {
                            BOOST_LOG_TRIVIAL(error) << "Failed to dispose of shared memory after retry: " << e.what();
                        }
                    }
                });

                ioService.run_one();
            } while (retriesLeft > 0);
        }
    }
private:
    static constexpr size_t batchSizeMillis = 100; // Adjust this value based on desired batch size
};
