    new_packet->timestamp = ts;
    new_packet->payload_size = size;
    acquire_lock(array->lock); // Thread safety
    try {
        if (insert_packet(array, new_packet)) {
            log_operation("Add", id, ts);
        } else {
            log_operation("Error", "Duplicate identifier");
        }
    } finally {
        release_lock(array->lock);
    }
}
```

