    array->size = 0;
    array->capacity = capacity;
    array->alloc = alloc;
    array->dealloc = dealloc;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

// Add a DataPacket to the dynamic array
bool add_packet(DataPacketArray* array, DataPacket* packet) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i]->id == packet->id) {
            pthread_mutex_unlock(&array->lock);
            return false; // Duplicate identifier, ignore this packet
        }
    }

    array->packets[array->size] = packet;
    array->size++;
    pthread_mutex_unlock(&array->lock);

    return true;
}

// Remove a DataPacket from the dynamic array by its identifier
void remove_packet(DataPacketArray* array, int id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i]->id == id) {
            for (size_t j = i + 1; j < array->size; ++j) {
                array->packets[i] = array->packets[j];
            }

            // Resize the dynamic array if needed
            if (array->size > (array->capacity >> 2)) {
                DataPacket** new_packets = realloc(array->packets, array->size * sizeof(DataPacket*));
                if (!new_packets) {
                    fprintf(stderr, "Error: out of memory\n");
                    pthread_mutex_unlock(&array->lock);
                    return;
                }
                array->packets = new_packets;
                array->capacity *= 2;
            }

            array->size--;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

