typedef struct {
    unsigned int cell_id;
    enum MEASUREMENT_REPORT_TYPE report_type;
    void* measurements; // Dynamically allocated array of MEASUREMENT_VALUE_T elements
    struct LTE_RRC_MEASUREMENT_REPORT_T *next;
} LTE_RRC_MEASUREMENT_REPORT_T;

typedef struct {
    unsigned int capacity;
    unsigned int size;
    unsigned int seed;
    unsigned int max_measurements;
    LTE_RRC_MEASUREMENT_REPORT_T *head;
    LTE_RRC_MEASUREMENT_REPORT_T *tail;
    pthread_mutex_t mutex;
    pthread_atomic_t mem_allocations;
} LIST_MANAGER;

unsigned int hash(LIST_MANAGER* manager, unsigned int key) {
    unsigned int prime = 31;
    unsigned int hash = 0;
    for (int i = 0; i < sizeof(key) * 8; ++i) {
        hash = (hash * prime + key & 0xFFFFFFFF) % manager->capacity;
    }
    return hash;
}

LIST_MANAGER* create_list_manager(unsigned int capacity, unsigned int seed, unsigned int max_measurements) {
    LIST_MANAGER* manager = malloc(sizeof(LIST_MANAGER));
    if (!manager) {
        perror("Error allocating memory for list manager");
        return NULL;
    }
    manager->capacity = capacity;
    manager->size = 0;
    manager->seed = seed;
    manager->max_measurements = max_measurements;
    manager->head = NULL;
    manager->tail = NULL;
    manager->mem_allocations = ATOMIC_VAR_INIT(0);
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_list_manager(LIST_MANAGER* manager) {
    if (!manager) {
        return;
    }
    LTE_RRC_MEASUREMENT_REPORT_T *node, *next_node;
    pthread_mutex_lock(&manager->mutex);
    node = manager->head;
    while (node != NULL) {
        next_node = node->next;
        free(node->measurements);
        free(node);
        node = next_node;
    }
    manager->head = manager->tail = NULL;
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && atomic_fetch_add(&manager->mem_allocations, 1) > 10000) { // Limit memory allocations to 10k at a time
        fprintf(stderr, "Error: Too many allocations\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

LTE_RRC_MEASUREMENT_REPORT_T* create_report(unsigned int cell_id, enum MEASUREMENT_REPORT_TYPE report_type) {
    LTE_RRC_MEASUREMENT_REPORT_T *report = malloc(sizeof(LTE_RRC_MEASUREMENT_REPORT_T));
    if (!report) {
        perror("Error allocating memory for report");
        return NULL;
    }
    report->cell_id = cell_id;
    report->report_type = report_type;
    report->measurements = allocate_memory(manager->max_measurements * sizeof(MEASUREMENT_VALUE_T));
    if (!report->measurements) {
        free(report);
        return NULL;
    }
    report->next = NULL;
    return report;
}

void insert_at_head(LIST_MANAGER* manager, LTE_RRC_MEASUREMENT_REPORT_T* report) {
    pthread_mutex_lock(&manager->mutex);
    report->cell_id = hash(manager, report->cell_id);
    if (manager->head == NULL || manager->head->cell_id != report->cell_id) {
        report->next = manager->head;
        manager->head = report;
        if (!manager->tail) {
            manager->tail = report;
        }
    } else {
        LTE_RRC_MEASUREMENT_REPORT_T *current = manager->head;
        while (current->next != NULL && current->next->cell_id == report->cell_id) {
            current = current->next;
        }
        report->next = current->next;
        current->next = report;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void insert_at_tail(LIST_MANAGER* manager, LTE_RRC_MEASUREMENT_REPORT_T* report) {
    pthread_mutex_lock(&manager->mutex);
    report->cell_id = hash(manager, report->cell_id);
    if (manager->head == NULL || manager->tail->cell_id != report->cell_id) {
        if (manager->head) {
            manager->tail = find_last_node(manager->head);
        }
        report->next = manager->head;
        manager->head = report;
    } else {
        manager->tail->next = report;
        manager->tail = report;
    }
    pthread_mutex_unlock(&manager->mutex);
}

LTE_RRC_MEASUREMENT_REPORT_T* find_last_node(LTE_RRC_MEASUREMENT_REPORT_T* node) {
    while (node && node->next != NULL) {
        node = node->next;
    }
    return node;
}

void print_list(LIST_MANAGER* manager, int reverse) {
    LTE_RRC_MEASUREMENT_REPORT_T *current;
    if (reverse) {
        current = manager->tail;
        while (current != NULL) {
            printf("[%u, %d]", current->cell_id, current->report_type);
            current = current->next;
        }
    } else {
        current = manager->head;
        while (current != NULL) {
            printf("[%u, %d]", current->cell_id, current->report_type);
            current = current->next;
        }
    }
}

// ... Add other required functions for logging, double-check locking pattern, memory optimization, and performance analysis
