    pthread_mutex_lock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)(pool->pool_addr + pool->used_size);
    pool->used_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
