void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, struct nfapi_crc_indication_pdu_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    pool->used_size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&pool->lock);
}

void remove_subscription(struct subscription_list *subscriptions, NF_API_SUBSCRIPTION *subscription) {
    pthread_mutex_lock(&subscriptions->list_lock);
    for (size_t i = 0; i < subscriptions->count; ++i) {
        if (subscriptions->nodes[i]->subscription == subscription) {
            list_del(&(subscriptions->nodes[i]->list));
            --subscriptions->count;
            break;
        }
    }
    pthread_mutex_unlock(&subscriptions->list_lock);
}

NF_API_SUBSCRIPTION* find_subscription(struct subscription_list *subscriptions, RNTI rnti) {
    pthread_mutex_lock(&subscriptions->list_lock);
    NF_API_SUBSCRIPTION *subscription = NULL;
    for (size_t i = 0; i < subscriptions->count; ++i) {
        if (subscriptions->nodes[i]->subscription->rnti == rnti) {
            subscription = subscriptions->nodes[i]->subscription;
            break;
        }
    }
    pthread_mutex_unlock(&subscriptions->list_lock);
    return subscription;
}

void init_subscription(NF_API_SUBSCRIPTION *subscription, RNTI rnti) {
    // Initialize the subscription here.
}

void resize_subscription_list(struct subscription_list *subscriptions, size_t new_capacity) {
    pthread_mutex_lock(&subscriptions->resize_sem);
    if (new_capacity > subscriptions->capacity) {
        NF_SUBSCRIPTION_NODE **new_nodes = realloc(subscriptions->nodes, new_capacity * sizeof(NF_SUBSCRIPTION_NODE*));
        if (!new_nodes) {
            log_error("Failed to allocate memory for subscription nodes array.");
            pthread_mutex_unlock(&subscriptions->resize_sem);
            return;
        }
        subscriptions->nodes = new_nodes;
        subscriptions->capacity = new_capacity;
    }
    pthread_mutex_unlock(&subscriptions->resize_sem);
}

void process_batch(struct nfapi_crc_indication_pdu_pool *pdus, struct subscription_list *subscriptions, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_pdu_from_pool(pdus);

        RNTI rnti = pdu->rnti;
        if (!is_valid_rnti(rnti)) {
            log_error("Invalid RNTI encountered.");
            free_pdu(pdu, pdus);
            continue;
        }

        NF_API_SUBSCRIPTION *subscription = find_subscription(subscriptions, rnti);
        if (!subscription) {
            init_subscription(subscription, rnti);
            resize_subscription_list(subscriptions, subscriptions->count + 1);
            subscription = subscriptions->nodes[subscriptions->count - 1]->subscription;
            subscriptions->nodes[subscriptions->count - 1]->subscription = subscription;
        }

        // Process the PDU here.

        free_pdu(pdu, pdus);
    }
}
