        metadata_arr[i].bitrate_estimate_kbps = (rand() % 500) + 200; // In the range of 200-700 kbps.
    }

    return metadata_arr;
}

// Thread-safe wrapper for createMetadataArray to support concurrent access
struct MetadataWrapper {
    int num_elements;
    pthread_mutex_t lock;
    struct MEDIA_FRAME_METADATA *metadata_arr;
};

// Function to create a thread-safe metadata wrapper
struct MetadataWrapper* createMetadataWrapper(int num_elements) {
    if (num_elements <= 0) return NULL;

    struct MetadataWrapper *wrapper = malloc(sizeof(struct MetadataWrapper));
    if (!wrapper) return NULL;

    wrapper->num_elements = num_elements;
    pthread_mutex_init(&wrapper->lock, NULL);
    wrapper->metadata_arr = createMetadataArray(num_elements);

    return wrapper;
}

// Function to get metadata from the wrapper in a thread-safe manner
struct MEDIA_FRAME_METADATA* getMetadataFromWrapper(struct MetadataWrapper *wrapper) {
    pthread_mutex_lock(&wrapper->lock);
    struct MEDIA_FRAME_METADATA *metadata = wrapper->metadata_arr;
    pthread_mutex_unlock(&wrapper->lock);

    return metadata;
}

// Function to destroy a metadata wrapper and free the associated memory
void destroyMetadataWrapper(struct MetadataWrapper *wrapper) {
    if (!wrapper) return;

    free(wrapper->metadata_arr);
    pthread_mutex_destroy(&wrapper->lock);
    free(wrapper);
}
