        static std::vector<ThreadSafeGenerator*> pool;
        std::mutex mtx;
        int id;

    public:
        ThreadSafeGenerator() : id(pool.size()) {}
        ~ThreadSafeGenerator() {}

        static void Initialize(int threads) {
            pool.resize(threads);
            for (auto& gen : pool) gen = new ThreadSafeGenerator();
        }

        int NextInt() {
            std::unique_lock<std::mutex> lock(mtx);
            if (id >= pool.size()) throw "Maximum number of threads exceeded.";
            auto* self = this;
            auto gen = *pool[id];
            lock.unlock();

            std::mt19937 genEngine(static_cast<unsigned int>(std::time(nullptr)));
            std::uniform_int_distribution<> dis(0, std::numeric_limits<int>::max());
            return dis(genEngine);
