            if (id >= pool.size()) throw "Maximum number of threads exceeded.";
            auto* self = this;
            lock.unlock();

            std::mt19937 genEngine(static_cast<unsigned int>(std::time(nullptr)));
            std::uniform_real_distribution<> dis(0.0, 1.0);
            return dis(genEngine);
        }

