#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct LTEPHY_RRCConnectionInfo {
    uint32_t id;
    // Configuration parameters
    // Connection state

    pthread_mutex_t lock;
} LTEPHY_RRCConnectionInfo;

// Function to initialize a new connection info structure and its lock
LTEPHY_RRCConnectionInfo* create_connection(uint32_t id) {
    LTEPHY_RRCConnectionInfo* connection = malloc(sizeof(LTEPHY_RRCConnectionInfo));
    connection->id = id;
    pthread_mutex_init(&connection->lock, NULL);
    return connection;
}

// Function to add a new connection info structure to the list
void push_connection(LTEPHYRRCList** head, LTEPHY_RRCConnectionInfo* connection) {
    pthread_mutex_lock(&connection->lock);
    connection->next = *head;
    *head = connection;
    pthread_mutex_unlock(&connection->lock);
}

// Function to remove a connection info structure from the list by its ID
bool remove_connection(LTEPHYRRCList** head, uint32_t id) {
    LTEPHY_RRCConnectionInfo* current = *head;
    pthread_mutex_lock(&current->lock);

    if (current->id == id) {
        *head = current->next;
        free(current);
        return true;
    }

    while (current->next != NULL && current->next->id != id) {
        current = current->next;
    }

    if (current->next == NULL) {
        pthread_mutex_unlock(&current->lock);
        return false;
    }

    LTEPHY_RRCConnectionInfo* temp = current->next;
    current->next = temp->next;
    free(temp);
    pthread_mutex_unlock(&current->lock);
    return true;
}

// Function to iterate over the list and apply a function to each connection
void for_each_connection(LTEPHYRRCList* head, void (*func)(LTEPHY_RRCConnectionInfo*)) {
    pthread_mutex_t* locks = malloc(sizeof(pthread_mutex_t) * LLONG_MAX);
    LTEPHY_RRCConnectionInfo* current = head;
    long index = 0;

    while (current != NULL) {
        pthread_mutex_lock(&current->lock);
        (*func)(current);
        pthread_mutex_unlock(&current->lock);
        index++;
        current = current->next;
    }

    free(locks);
}
```

