struct TileConfiguration {
    int width, height;
    int TileID;
    std::int64_t lastModified;
    // Associated world configurations
};

class DynamicTileList {
private:
    using Lock = std::mutex;
    std::unordered_map<int, std::unique_ptr<TileConfiguration>> tiles;
    Lock dataLock;
    std::deque<std::unique_ptr<TileConfiguration>> cache;
    std::atomic_size_t cacheSize;
    std::set<std::thread::id> threads;

    void validate(const TileConfiguration& tc) { /* Implement validation logic with retry and fallback */ }
    void integrate(TileConfiguration& tc) { /* Handle integration with other subsystems */ }

public:
    DynamicTileList(std::atomic_size_t initialCacheSize = 10) : cacheSize(initialCacheSize) {}

    int addTile(const TileConfiguration& tc) {
        std::unique_ptr<TileConfiguration> newTC(new TileConfiguration(tc));
        validate(*newTC);
        std::lock_guard<Lock> lock(dataLock);
        auto it = tiles.emplace(tc.TileID, std::move(newTC));
        if (!it.second) {
            it.first->second->lastModified = tc.lastModified;
        }
        return it.first->first;
    }

    void updateTile(int tileID, const TileConfiguration& tc) {
        std::lock_guard<Lock> lock(dataLock);
        auto it = tiles.find(tileID);
        if (it != tiles.end()) {
            validate(*it->second);
            it->second->lastModified = tc.lastModified;
            integrate(*it->second);
        }
    }

    void removeTile(int tileID) {
        std::lock_guard<Lock> lock(dataLock);
        auto it = tiles.find(tileID);
        if (it != tiles.end()) {
            it->second.reset();
            tiles.erase(it);
            // Free resources if cache is full and tile is not in the cache
            if (!cache.empty() && !cache.back()->TileID) {
                integrate(*cache.back());
                cache.pop_back();
            }
        }
    }

    void run(std::function<void(TileConfiguration&)> fn) {
        std::thread t([this, fn]() {
            threads.insert(this_thread::get_id());
            for (const auto& tc : cache) {
                if (!tc->TileID) {
                    continue;
                }
                fn(*tc);
                integrate(*tc);
            }
            while (!threads.erase(this_thread::get_id())) {}
        });
        t.detach();
    }
};
```

