['```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct NetworkEvent {
    int uid;
    time_t timestamp;
    struct trafficStats stats;
} NetworkEvent;

typedef struct TrafficStats {
    long long bytesSent;
    long long bytesReceived;
    int packetsSent;
    int packetsReceived;
} TrafficStats;

struct NetworkEventsList {
    NetworkEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

NetworkEventsList* networkEventsListCreate(size_t initialCapacity) {
    NetworkEventsList* list = malloc(sizeof(NetworkEventsList));
    list->capacity = initialCapacity;
    list->size = 0;
    list->events = calloc(initialCapacity, sizeof(NetworkEvent));
    list->lock = PTHREAD_MUTEX_INITIALIZER;
    return list;
}

void networkEventsListPush(NetworkEventsList* list, const NetworkEvent* event) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NetworkEvent* newEvents = realloc(list->events, newCapacity * sizeof(NetworkEvent));
        if (!newEvents) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->events = newEvents;
        list->capacity = newCapacity;
    }

    memcpy(&list->events[list->size], event, sizeof(NetworkEvent));
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void networkEventsListUpdateTrafficStats(NetworkEvent* event, const TrafficStats* newStats) {
    event->stats.bytesSent += newStats->bytesSent;
    event->stats.bytesReceived += newStats->bytesReceived;
    event->stats.packetsSent += newStats->packetsSent;
    event->stats.packetsReceived += newStats->packetsReceived;
}
