void deriveKey(const char* password, int iterations, const char* salt, unsigned char* derivedKey, size_t derivedKeyLength) {
    EVP_MD_CTX *ctx;
    int ret = 0;

    ctx = EVP_MD_CTX_create();
    if(!ctx) return;

    // Initialize the PBKDF2 context
    ret = EVP_PKEY_pbkdf2((EVP_PKEY*)NULL, NULL, 0, salt, strlen(salt), iterations, EVP_sha256(), derivedKey, derivedKeyLength);
    if(ret <= 0) {
        fprintf(stderr, "Error during key derivation.\n");
        EVP_MD_CTX_destroy(ctx);
        return;
    }

    // Hash the password using the derived key
    ret = EVP_DigestInit_ex(ctx, NULL, EVP_sha256(), nullptr, password);
    if(ret <= 0) {
        fprintf(stderr, "Error during password hashing.\n");
        EVP_MD_CTX_destroy(ctx);
        return;
    }

    ret = EVP_DigestFinal_ex(ctx, derivedKey, derivedKeyLength);
    if(ret <= 0) {
        fprintf(stderr, "Error during password hashing.\n");
        EVP_MD_CTX_destroy(ctx);
        return;
    }

    EVP_MD_CTX_destroy(ctx);
}
