        totalAllocated++;
        events[event->EVENT_ID] = event;

        longstart = clock();

        // Process the event and integrate with third-party logging service here.

        elapsedTime = (long)(clock() - start);
        successfulAllocations++;
        averageProcessingTime += elapsedTime;
        memoryUsage += sizeof(LOG_EVENT_T);
    }

public:
    static LogManager* getInstance() {
        if (!instance) {
            instance = new LogManager();
        }
        return instance;
    }

    void processEvents(int numberOfEventsToProcess) {
        lock_guard<mutex> guard(mtx);
        for (int i = 0; i < numberOfEventsToProcess && !events.empty(); ++i) {
            LOG_EVENT_T* event = events.begin()->second;
            logEvent(event);
            events.erase(events.begin());
        }
