    public static void main(String[] args) throws ExecutionException, InterruptedException {
        ProtocolMessageCache<MyClass> cache = new ProtocolMessageCache<>(new CacheLoader<Class<MyClass>, LoadingCache<ProtocolKey, MyClass>>() {
            @Override
            public LoadingCache<ProtocolKey, MyClass> load(Class<MyClass> clazz) throws Exception {
                return CacheBuilder.newBuilder()
                        .maximumSize(100) // Configure cache size here...
                        .build((key, callable) -> cache.getIfPresent(key));
            }
        });

        byte[] serializedData = // Load serialized data from a source...

        MyClass instance = cache.getUnchecked(serializedData).call();
