struct pdu_pool* create_pdu_pool(size_t capacity) {
    struct pdu_pool *pdu_pool = (struct pdu_pool*) malloc(sizeof(struct pdu_pool));
    if (!pdu_pool) return NULL;

    pdu_pool->capacity = capacity;
    pdu_pool->used = 0;
    pdu_pool->data = (NFAPI_CRC_INDICATION_PDU_T*) calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_pool->data) {
        free(pdu_pool);
        return NULL;
    }

    return pdu_pool;
}

NFAPI_CRC_INDICATION_PDU_T* acquire_pdus(struct pdu_pool *pool, size_t count) {
    if (pool->used + count > pool->capacity) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *result = &pool->data[pool->used];
    pool->used += count;
    return result;
}
