        std::mt19937 gen(rd()); //MT19937 is a Mersenne Twister pseudo-random number generator
        std::uniform_int_distribution<> distr(0, 1); //Uniform distribution with range [0, 1]

        for (int i = 0; i < contextCount; ++i) {
            UEContext* context = nullptr;

            // Try to get a context from the cache
            {
                std::lock_guard<std::mutex> lock(cacheMutex);
                if (!contextCache.empty()) {
                    context = &contextCache.begin()->second;
                    contextCache.erase(contextCache.begin());
                }
