            // If not found in cache, allocate a new one
            if (!context) {
                context = new UEContext();
                context->UE_ID = i;
                context->RNTI = rand() % 100000;
                context->ServingCellID = rand() % 100 + 1;
                context->RB_ALLOC_FLAG = distr(gen) < 0.8 ? true : false;
