        HandlerRegistration registration = new HandlerRegistration(handlerName, handler);
        // Statically registered handlers can be added here if needed
        if (registration.isDynamic()) {
            synchronized (this) {
                handlers.add(registration);
            }
        }
    }

    public void handleMessage(Message message) {
        long subscriberID = message.getSubscriberID();
        SubscriberContext context;

        // Use cache for efficient memory management and concurrent access
        CompletableFuture<SubscriberContext> futureContext = contextCache.getUnchecked(subscriberID);
        context = futureContext.join();

        // Process the message with the registered handlers
        for (HandlerRegistration registration : handlers) {
            if (context.getSubscriptionStatus()) {
                try {
                    Future<Void> result = registration.handler.handle(message, context);
                    result.thenRunAsync(() -> LOGGER.info("Message handled by {} successfully", registration.name));
                } catch (Exception e) {
                    LOGGER.error("Error while handling message by {}", registration.name, e);
                }
            }
        }

        // Monitor performance and report anomalies or errors
        Duration elapsed = Duration.between(message.getTimestamp(), Clock.systemUTC().millis());
        LOGGER.info("Time taken to process message: {}", elapsed.toMillis());
    }

    private class SubscriberContext {
        // Context fields and getters/setters here
    }

    private class HandlerRegistration {
        final String name;
        final MessageHandlerImpl handler;
        final boolean dynamic;

        public HandlerRegistration(String name, MessageHandlerImpl handler) {
            this.name = name;
            this.handler = handler;
            this.dynamic = true; // Set to false if statically registered
        }

        public boolean isDynamic() {
            return dynamic;
        }
    }
}
```
