typedef struct {
    uint16_t rxiitag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
} ListNode;

ListNode* create_list() {
    ListNode *head = NULL, *current = NULL;
    uint32_t unique_rntis[100000] = { 0 };
    unsigned int used_rntis = 0;

    srand(time(NULL));

    for (unsigned int i = 0; i < 100000 && used_rntis < 100000; ++i) {
        uint32_t rnti = rand() % 0xFFFFFFFF;
        if (!unique_rntis[rnti]) {
            unique_rntis[rnti] = 1;
            ++used_rntis;

            ListNode *new_node = malloc(sizeof(ListNode));
            if (!new_node) {
                // Handle memory allocation failure
                printf("Error: Out of memory\n");
                return NULL;
            }

            new_node->data.rxiitag = rand() % 0xFFFF + 1;
            new_node->data.crc_indication_rel8_tag = rand() % 3 + 2;
            new_node->data.crcflag = rand() % 2;
            new_node->data.rnti = rnti;

            if (!head) {
                head = current = new_node;
            } else {
                current->next = new_node;
                current = new_node;
            }
        }
    }

    return head;
}

void serialize_list(ListNode* list, const char* filename) {
    FILE *file = fopen(filename, "w");

    if (!file) {
        // Handle file I/O error
        printf("Error: Cannot open file for writing\n");
        return;
    }

    ListNode *current = list;
    while (current != NULL) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %d\n", current->data.rxiitag);
        fprintf(file, "RNTI: %" PRIu32 "\n", current->data.rnti);
        fprintf(file, "CRC_INDICATION_REL8_TAG: %d\n", current->data.crc_indication_rel8_tag);
        fprintf(file, "CRCFLAG: %d\n", current->data.crcflag);
        fprintf(file, "\n");

        current = current->next;
    }

    fclose(file);
}

void resume_from_file(ListNode** list, const char* filename) {
    FILE *file = fopen(filename, "r");

    if (!file) {
        // Handle file I/O error
        printf("Error: Cannot open file for reading\n");
        return;
    }

    ListNode *head = NULL, *current = NULL;

    while (!feof(file)) {
        ListNode *new_node = malloc(sizeof(ListNode));
        if (!new_node) {
            // Handle memory allocation failure
            printf("Error: Out of memory\n");
            free_list(head);
            return;
        }

        fscanf(file, "RX_UE_INFORMATION_TAG: %d", &new_node->data.rxiitag);
        fscanf(file, "RNTI: %" PRIu32, &new_node->data.rnti);
        fscanf(file, "CRC_INDICATION_REL8_TAG: %d", &new_node->data.crc_indication_rel8_tag);
        fscanf(file, "CRCFLAG: %d\n", &new_node->data.crcflag);

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    fclose(file);
}

void free_list(ListNode *list) {
    ListNode *current = list;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }
}
