    int threadCount = 0, elementsProcessed = 0;

    for (int i = 0; i < N && elementsProcessed < N; ++i) {
        if (!findRNTI(indications, elementsProcessed, indications[elementsProcessed].rnti)) {
            memcpy(&indications[elementsProcessed], generateIndication(), sizeof(NFAPI_CRC_INDICATION_PDU_T));
            ++elementsProcessed;
        }
    }

    // Parallel processing for encryption and CRC calculation
    for (int i = 0; i < elementsProcessed; ++i) {
        pthread_create(&threads[threadCount++], NULL, encryptAndCalculateCRC, &indications[i]);
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Filtering and Metrics handling
    uint64_t maxWeightedSum = 0, maxIndex = -1;
    int filteredTransactionsCount = 0;

    for (int i = 0; i < elementsProcessed; ++i) {
        if (filterCriteria(&indications[i].transaction)) {
            updateMetrics(metricsHandle, &indications[i]);
            uint64_t weightedSum = calculateWeightedSum(indications[i].weight);

            if (weightedSum > maxWeightedSum) {
                maxWeightedSum = weightedSum;
                maxIndex = i;
            }
            ++filteredTransactionsCount;
        }
    }

    // Serialization and Return
