    std::shared_ptr<MAC_PDU> allocate() {
        std::lock_guard<std::mutex> lock(mtx);

        if (!freeList.empty()) {
            auto pdum = std::move(freeList.back());
            freeList.pop_back();
            return pdum;
        }

        return std::make_shared<MAC_PDU>();
