        std::lock_guard<std::mutex> lock(mtx);
        pdum->sequenceNumber = std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now() - pdum->timestamp).count();
        freeList.push_back(std::move(*pdum));
    }
