#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    uint32_t ue_id;
    uint32_t cell_id;
    void *data_buffer;
} lte_ue_context_t;

#define MAX_UE_CONTEXTS 10000
#define THRESHOLD (5 * 1024 * 1024) // 5 MB

bool initialize_lte_ue_contexts(lte_ue_context_t **ctx_list, size_t *num_allocated) {
    *ctx_list = calloc(MAX_UE_CONTEXTS, sizeof(lte_ue_context_t));
    if (!*ctx_list) {
        perror("Failed to allocate memory for UE context list");
        return false;
    }

    size_t allocated = MAX_UE_CONTEXTS;
    *num_allocated = 0;
    size_t total_size = 0;

    for (size_t i = 0; i < MAX_UE_CONTEXTS && total_size < THRESHOLD; ++i) {
        lte_ue_context_t *ctx = &((*ctx_list)[*num_allocated]);

        ctx->ue_id = i + 1;
        ctx->cell_id = i % 5 + 1; // Assign cell ID based on UE index modulo 5

        size_t buffer_size = (i + 1) * sizeof(uint8_t); // Allocate buffer linearly proportional to UE index
        if (buffer_size > THRESHOLD - total_size) {
            break;
        }

        ctx->data_buffer = malloc(buffer_size);
        if (!ctx->data_buffer) {
            perror("Failed to allocate memory for data buffer");
            free(*ctx_list); // Free allocated memory up to current index
            *ctx_list = NULL;
            return false;
        }

        total_size += buffer_size;
        (*num_allocated)++;
    }

    return true;
}
```
