    manager->capacity = 0;
    manager->size = 0;
    manager->threshold = threshold;
    manager->data_source = data_source;
    manager->contexts = NULL;

    return manager;
}

void add_ue_context(lte_ue_context_manager* manager, uint32_t ue_id, uint32_t cell_id, size_t buffer_size) {
    if (manager->size + 1 > manager->capacity && manager->size != 0) {
        // Reallocate capacity when needed
        lte_ue_context** new_contexts = realloc(manager->contexts, sizeof(lte_ue_context*) * (manager->capacity + 1));
        if (!new_contexts) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        }
        manager->contexts = new_contexts;
        manager->capacity++;
    }

    lte_ue_context* context = malloc(sizeof(lte_ue_context));
    if (!context) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    context->ue_id = ue_id;
    context->cell_id = cell_id;
    context->buffer_size = buffer_size;
    context->uplink_data_buf = malloc(context->buffer_size);
    if (!context->uplink_data_buf) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&context->mutex, NULL);

    manager->contexts[manager->size++] = context;

    check_memory_usage(manager);
}

void check_memory_usage(lte_ue_context_manager* manager) {
    if (manager->size * sizeof(lte_ue_context) + manager->capacity * sizeof(lte_ue_context*) > manager->threshold) {
        // Remove unused UE contexts to free memory
        lte_ue_context** new_contexts = malloc(sizeof(lte_ue_context*) * (manager->capacity - 1));
        if (!new_contexts) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        }

        size_t i;
        for (i = 0; i < manager->size; ++i) {
            if (manager->contexts[i]->buffer_size != 0) {
                new_contexts[i] = manager->contexts[i];
            } else {
                free(manager->contexts[i]);
            }
        }

        free(manager->contexts);
        manager->contexts = new_contexts;
        manager->capacity--;
    }
}

void update_ue_contexts(lte_ue_context_manager* manager) {
