typedef struct {
    int max_connections;
    int threshold;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    struct sockaddr_in addr;
    int *connections;
} ConnectionPool;

ConnectionPool* create_pool(int max_connections, int threshold, struct sockaddr_in addr) {
    ConnectionPool *pool = mmap(NULL, sizeof(ConnectionPool), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    pool->max_connections = max_connections;
    pool->threshold = threshold;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->addr = addr;
    pool->connections = calloc(max_connections, sizeof(int));
    return pool;
}

void* connection_handler(void *arg) {
    ConnectionPool *pool = arg;
    int connection = -1;

    while (1) {
        pthread_mutex_lock(&pool->mutex);
        while ((connection = find_idle_connection(pool)) == -1 && pool->connections_in_use < pool->max_connections) {
            pthread_cond_wait(&pool->cond, &pool->mutex);
        }
        if (connection == -1) break; // Resource allocation failure or shutdown signal
        pool->connections[connection] = -2; // Mark the connection as in use
        pthread_mutex_unlock(&pool->mutex);

        handle_stream(connection, &pool->addr);

        pthread_mutex_lock(&pool->mutex);
        pool->connections[connection] = -1; // Mark the connection as idle
        update_resources(); // Update resource usage statistics and trigger dynamic scaling if necessary
        pthread_mutex_unlock(&pool->mutex);
    }

    return NULL;
}

int get_connection(ConnectionPool *pool) {
    int connection = -1;

    pthread_mutex_lock(&pool->mutex);
    while ((connection = find_idle_connection(pool)) == -1 && pool->connections_in_use < pool->max_connections) {
        create_new_connection(pool); // Create a new connection if all existing connections are in use and more can be created without exceeding the threshold
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    if (connection == -1) throw_error("Could not get a connection.");
    pool->connections[connection] = -2; // Mark the connection as in use
    pthread_mutex_unlock(&pool->mutex);

    return connection;
}

void release_connection(ConnectionPool *pool, int connection) {
    if (connection < 0 || pool->connections[connection] != -2) throw_error("Trying to release an invalid or unused connection.");

    pthread_mutex_lock(&pool->mutex);
    pool->connections[connection] = -1; // Mark the connection as idle
    update_resources(); // Update resource usage statistics and trigger dynamic scaling if necessary
    pthread_mutex_unlock(&pool->mutex);
}

void terminate_pool(ConnectionPool *pool) {
    for (int i = 0; i < pool->max_connections; ++i) {
        if (pool->connections[i] != -1) release_connection(pool, i);
    }

    munmap(pool, sizeof(ConnectionPool));
}

void create_new_connection(ConnectionPool *pool) {
    int connection = pool->max_connections; // Start from the last index since we're adding a new connection
    if (connection_creation_failed()) return; // Handle resource allocation failure

    pool->connections[connection] = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (pool->connections[connection] == -1) return; // Handle socket creation failure

    struct sockaddr_in sock_addr = pool->addr;
    socklen_t addr_len = sizeof(sock_addr);
    if (bind(pool->connections[connection], (struct sockaddr *) &sock_addr, addr_len) == -1) return; // Handle bind failure
    if (listen(pool->connections[connection], SOMAXCONN) == -1) return; // Handle listen failure
}

int find_idle_connection(ConnectionPool *pool) {
    for (int i = 0; i < pool->max_connections; ++i) {
        if (pool->connections[i] == -1) return i;
    }
    return -1; // No idle connections found
}

