    io_service service;
    thread_group group;
    std::deque<std::shared_ptr<socket>> sockets;
    std::mutex mtx;
    size_t maxClients = 0, currentClients = 0;

    void start(const ip::tcp::endpoint& endpoint) {
        acceptor acc(service, endpoint);
        do {
            accept(acc, *sockets.front(), 0);
            ++currentClients;
            sockets.pop_front();

            group.create_thread([this, sock = sockets.back()]() {
                std::shared_ptr<socket> s(sock, socketDeleter{});
                io_service::work work{s->get_io_service()};
                work.run();
            });
        } while (currentClients < maxClients && acc.is_open());
    }

