    for (const auto& endpoint : endpoints) {
        if (servers.size() < servers.max_load_factor()) {
            auto server = servers.emplace(endpoint.port(), Server()).first->second;
            server->start(endpoint);
        } else {
            int minLoad = INT32_MAX;
            int bestPort = -1;
            for (auto& p : servers) {
                if (p.second.currentClients < minLoad) {
                    minLoad = p.second.currentClients;
                    bestPort = p.first;
                }
            }

            auto server = servers[bestPort];
            server->start(endpoint);
        }
    }
}
