class UEContextCache {
public:
    UEContextCache(size_t maxSize) : _maxSize(maxSize), _cache(), _mutex() {}

    std::unique_ptr<UEContext> getOrCreate(const UEContext& context) {
        auto iter = _cache.find(context.UE_ID);
        if (iter != _cache.end())
            return std::move(iter->second);

        std::unique_ptr<UEContext> newContext(new UEContext(context));
        if (_cache.size() >= _maxSize) {
            auto evictedIter = _cache.begin();
            std::advance(evictedIter, rand() % _cache.size()); // Randomly select an item to evict
            _cache.erase(evictedIter);
        }
        _cache[newContext->UE_ID] = std::move(newContext);
        return newContext;
    }

