typedef struct _MemoryPool {
    void *data;
    size_t size;
    struct _MemoryPool *next;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = (MemoryPool *) malloc(sizeof(MemoryPool));
    pool->size = size;
    pool->data = malloc(size);
    pool->next = NULL;
    return pool;
}

void* allocate(MemoryPool **pool, size_t size) {
    if (*pool == NULL || (*pool)->size <= 0) {
        *pool = create_memory_pool(size);
    } else {
        void *data = (*pool)->data;
        (*pool)->data = memmove((*pool)->data + size, (*pool)->data, (*pool)->size - size);
        (*pool)->size -= size;
        data += (*pool)->size;
        (*pool)->data = data;
    }
    return (*pool)->data;
}

void free_memory(MemoryPool **pool, void *ptr) {
    if (*pool && ptr >= (*pool)->data && ptr < (*pool)->data + (*pool)->size) {
        // ... Implement error checking and logging ...
        memmove((*pool)->data, ptr, (*pool)->size - (ptr - (*pool)->data));
        (*pool)->size += size;
    } else {
        free(ptr);
    }
}
