int parse_log(const char* filename, const char** event_types) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    LogEntry entry;
    int total_entries = 0;
    time_t last_timestamp = 0;
    char** event_types_copy = calloc(sizeof(char*), strlen(event_types));
    strcpy(event_types_copy, event_types);

    while (fscanf(file, "%*[^ ]%s %*c%s %*c\n", entry.event, entry.metadata) != EOF) {
        if (!strchr(entry.event, ',') && strchr(event_types_copy, entry.event)) {
            ++total_entries;

            struct tm parsed_timestamp;
            strptime(ctime(&entry.timestamp), "%a %b %d %H:%M:%S %Y", &parsed_timestamp);

            if (last_timestamp == 0 || last_timestamp != entry.timestamp) {
                printf("%s :\n", ctime(&entry.timestamp));
                last_timestamp = entry.timestamp;
            }

            printf("\t%s - %s\n", entry.event, entry.metadata);
        }
    }

    free(event_types_copy);
    fclose(file);

    if (total_entries == 0) {
        perror("Log file is empty");
        return EXIT_FAILURE;
    }

    // Continue with average duration calculation, timestamp count, etc.
}

