    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"output", required_argument, 0, 'o'},
        {0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "ho:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                help_flag = true;
                break;
            case 'o':
                output = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [--help] -o outputfile\n", argv[0]);
