    size_t allocated;
    size_t used;
    pthread_mutex_t mutex;
} UE_CONTEXT_POOL;

UE_CONTEXT_POOL* init_ue_context_pool(size_t N, size_t max_buffer_size, size_t threshold) {
    UE_CONTEXT_POOL *pool = malloc(sizeof(UE_CONTEXT_POOL));
    pool->contexts = NULL;
    pool->allocated = 0;
    pool->used = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    if (N > threshold) {
        fprintf(stderr, "Error: Number of contexts exceeds the specified threshold\n");
        free(pool);
        return NULL;
    }

    size_t total_buffer_size = max_buffer_size * N;
    void* buffer = malloc(total_buffer_size);
    if (!buffer) {
        fprintf(stderr, "Error: Failed to allocate memory for the uplink data buffers\n");
        free(pool);
        return NULL;
    }

    pool->contexts = malloc(N * sizeof(LTE_UE_CONTEXT));
    if (!pool->contexts) {
        fprintf(stderr, "Error: Failed to allocate memory for the LTE UE contexts\n");
        free(buffer);
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        LTE_UE_CONTEXT* ctx = pool->contexts + i;
        ctx->RX_UE_INFORMATION_TAG = generate_unique_tag();
        ctx->RNTI = generate_unique_RNTI();
        ctx->CRC_INDICATION_REL8_TAG = rand() % 256;
        ctx->CRCFLAG = rand() % 2 == 0;
        ctx->uplink_data_buffer = buffer + (i * max_buffer_size);
        ctx->max_buffer_size = max_buffer_size;
        ctx->cell_id = -1; // Initialize with an invalid cell ID
        ctx->UE_ID = i + 1;
    }

    pool->allocated = N;
    return pool;
}

void deinit_ue_context_pool(UE_CONTEXT_POOL *pool) {
    free(pool->contexts);
    free(pool);
}

