    unsigned long hash = 5381;
    const unsigned char* data = (const unsigned char*)key;
    for (int i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        hash += (hash << 5) + hash + data[i];
