    uint32_t seq_number;
    uint32_t ack_number;
    struct tcp_header header;
    time_t log_timestamp;
};

typedef struct SegmentPool {
    void *mem_map;
    size_t size;
    size_t num_segments;
    sem_t sem_mutex;
} SegmentPool;

SegmentPool* create_segment_pool(size_t num_segments) {
    SegmentPool *pool = malloc(sizeof(SegmentPool));
    pool->num_segments = num_segments;
    pool->size = sizeof(TCP_segment) * num_segments;

    void *mem_map = mmap(NULL, pool->size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (mem_map == MAP_FAILED) {
        free(pool);
        perror("mmap failed");
        return NULL;
    }

    pool->mem_map = mem_map;
    sem_init(&pool->sem_mutex, 0, 1); // Only one thread can access the pool at a time
    return pool;
}

TCP_segment* allocate_tcp_segment(SegmentPool *pool) {
    TCP_segment *seg = (TCP_segment*)pool->mem_map;
    sem_wait(&pool->sem_mutex); // Lock the pool to ensure thread safety

    seg->log_timestamp = time(NULL);
    seg->seq_number = get_valid_sequence_number(); // Ensure sequence number is valid
    seg->ack_number = get_valid_ack_number(); // Ensure ack number is valid

    // Initialize other fields as per requirements

    if (log_to_distributed_service(seg->seq_number, seg->ack_number)) {
        sem_post(&pool->sem_mutex); // Unlock the pool after logging
        return seg;
    }

    // Logging failed, release resources and return NULL
    sem_post(&pool->sem_mutex);
    return NULL;
}

void free_tcp_segment(TCP_segment *seg) {
    free_logged_data(seg); // Free any logged data associated with the segment
    memmove(pool->mem_map, seg, sizeof(TCP_segment)); // Move the freed segment to the start of the pool for reuse
}

void destroy_segment_pool(SegmentPool *pool) {
    munmap(pool->mem_map, pool->size); // Free the memory mapped region
    free(pool); // Free the SegmentPool structure
}
```

