typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct thread_data {
    NFAPI_CRC_INDICATION_PDU_T* list;
    size_t start, end;
};

void* generate_element(void* data) {
    struct thread_data* td = (struct thread_data*)data;
    for (size_t i = td->start; i < td->end; ++i) {
        td->list[i].RX_UE_INFORMATION_TAG = rand();
        td->list[i].RNTI = rand() % 65536 + 1; // Ensuring RNTIs are between 1 and 65536
        td->list[i].CRC_INDICATION_REL8_TAG = rand();
        td->list[i].CRCFLAG = (rand() % 2) == 0;
    }
    return NULL;
}

void serialize_list(const NFAPI_CRC_INDICATION_PDU_T* list, size_t size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < size; ++i) {
        fwrite(list + i, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void* deserialize_list(void* data, const char* filename, size_t* size) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    size_t temp_size;
    fread(&temp_size, sizeof(size_t), 1, file);
    *size = temp_size;

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < *size; ++i) {
        fread(list + i, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);

    return list;
}

// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures.
NFAPI_CRC_INDICATION_PDU_T* generate_list(size_t size, uint16_t min_rnti, uint16_t max_rnti) {
    if (size > 1000000) {
        printf("Warning: The requested list size exceeds the recommended limit of 1,000,000 elements.\n");
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    pthread_t threads[1 + (size - 1) / getconf(_SC_NPROCESSORS_CONF]];
    struct thread_data data[1 + (size - 1) / getconf(_SC_NPROCESSORS_CONF]];

    for (size_t i = 0; i < size; ++i) list[i].CRCFLAG = false;

    size_t part_size = (size - 1) / getconf(_SC_NPROCESSORS_CONF] + 1;
    for (size_t i = 0; i <= size; ++i) {
        data[i].list = list;
        data[i].start = i * part_size;
        if (i < size - 1)
            data[i].end = (i + 1) * part_size;
        else
            data[i].end = size;
    }

    for (size_t i = 0; i <= size; ++i) {
        pthread_create(&threads[i], NULL, generate_element, &data[i]);
    }

    for (size_t i = 0; i <= size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Ensuring all RNTIs are unique within the list
    qsort(list, size, sizeof(NFAPI_CRC_INDICATION_PDU_T), [](const void* a, const void* b) { return ((NFAPI_CRC_INDICATION_PDU_T*)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T*)b)->RNTI; });

    return list;
}
