typedef struct EventPool {
    void** pool;
    size_t capacity;
    size_t used;
} EventPool;

EventPool* createEventPool(size_t capacity, size_t size) {
    EventPool* pool = malloc(sizeof(EventPool));
    if (!pool) return NULL;
    pool->capacity = capacity;
    pool->used = 0;
    pool->pool = calloc(capacity, sizeof(void*));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    for (size_t i = 0; i < capacity; ++i)
        pool->pool[i] = malloc(size);
    return pool;
}

void destroyEventPool(EventPool* pool) {
    if (!pool) return;
    for (size_t i = 0; i < pool->capacity; ++i)
        free(pool->pool[i]);
    free(pool->pool);
    free(pool);
}

