        if (powerSourceAvailable && powerSourceDrainRate <= powerSourceCapacity) {
            powerSourceCapacity -= powerSourceDrainRate;
        }
        powerSourceAvailable = powerSourceCapacity > 0;
    }

    Attack selectAttack() {
