                auto it = cooldownCache.find(attacks.front().id);
                apiMutex.lock(current);
                if (it != cooldownCache.end() && next > it->second + attacks.front().duration) {
                    it->second = std::chrono::steady_clock::now();
                    apiCall(attacks.front()); // Update cooldown on the API
                }
                apiMutex.unlock();
            }
            attacks.pop();
        }

        Attack attack = attacks.front();
        if (canAffordEnergy(attack.energyCost)) {
            currentEnergy -= attack.energyCost;
            energyMutex.lock();
            currentEnergy += energyRegenerationRate * std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
            energyMutex.unlock();
        }
        attacks.pop();

        // Adaptive attack distribution based on player behavior and combat conditions
        // (This logic is not included in the provided code, as it may vary greatly depending on specific game mechanics)

        return attack;
    }

private:
    bool canAffordEnergy(float energyCost) {
        if (!powerSourceAvailable || currentEnergy < energyCost) return false;
        return true;
    }
};
