#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ALLOCATIONS 10000000
#define LOGGING_THRESHOLD 10000
#define TIMESTAMP_ENABLED 1

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int allocations_success = 0, retries = 0, memory_failures = 0, log_count = 0;
static size_t allocation_sizes[MAX_ALLOCATIONS] = { 0 };

NFAPI_CRC_INDICATION_PDU_T* allocate_structures(int N) {
    if (N <= 0 || N > MAX_ALLOCATIONS) return NULL;

    int unique_tags[N], unique_rn[N];
    for (int i = 0; i < N; ++i) {
        unique_tags[i] = -1;
        unique_rn[i] = -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) return NULL;

    pthread_mutex_lock(&mutex);
    allocations_success += N;
    pthread_mutex_unlock(&mutex);

    int index = 0;
    for (int i = 0; i < N; ) {
        uint32_t tag, rn;
        do {
            tag = rand() % (1 << 16);
            rn = rand() % ((1LL << 48) - 1);
        } while (unique_tags[tag] >= 0 || unique_rn[rn] >= 0);

        unique_tags[tag] = index;
        unique_rn[rn] = index;

        structures[index].RX_UE_INFORMATION_TAG = tag;
        structures[index].RNTI = rn;
        structures[index].CRC_INDICATION_REL8_TAG = rand() % (1 << 32);
        structures[index].CRCFLAG = rand() % 2 == 0;
        if (TIMESTAMP_ENABLED) structures[index].timestamp = time(NULL);
        ++i;
    }

    return structures;
}

void deallocate_structures(NFAPI_CRC_INDICATION_PDU_T* structures, int N) {
    if (!structures || N <= 0) return;

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < N; ++i) {
        struct { int tag, rn } check[2] = { { structures[i].RX_UE_INFORMATION_TAG, structures[i].RNTI } };
        for (int j = 0; j < allocations_success; ++j) {
            if (check[0].tag == allocated_structures[j].RX_UE_INFORMATION_TAG && check[1].rn == allocated_structures[j].RNTI) {
                allocated_structures[j] = { -1, -1, 0, false };
                break;
            }
        }
    }
    pthread_mutex_unlock(&mutex);
    free(structures);
}

void log_stats() {
    if (log_count >= LOGGING_THRESHOLD) return;

    printf("Allocated structures: %d\n", allocations_success);
    printf("Memory allocation failures: %d\n", memory_failures);
    printf("Retries due to memory allocation: %d\n", retries);
    printf("Frequency of each allocation size:\n");
    for (int i = 0; i < MAX_ALLOCATIONS; ++i) {
        if (allocation_sizes[i] > 0)
            printf("Size %d: %ld\n", i, allocation_sizes[i]);
    }
}

void handle_memory_failure(void* data) {
    ++retries;
    log_stats();
}

int main(int argc, char** argv) {
    // Implement the adaptive allocation strategy based on system load metrics here.
    // ...

    int N = atoi(argv[1]);

    clock_t start = clock();
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* structures = allocate_structures(1);
        if (!structures) {
            handle_memory_failure(NULL);
            continue;
        }
        // Use the allocated structure and then deallocate it.
        deallocate_structures(structures, 1);
    }
    clock_t end = clock();
    printf("Allocated and deallocated %d structures in %.3fs\n", N, (double)(end - start) / CLOCKS_PER_SEC);

    log_stats();
    return 0;
}
```

