enum LogLevel { DEBUG, INFO, WARN, ERROR };

void log(enum LogLevel level, const char* format, ...) {
    time_t now;
    struct tm *tm;
    FILE* logfile;

    time(&now);
    tm = localtime(&now);

    if (!(logfile = fopen("log.txt", "a"))) return;

    fprintf(logfile, "[%04d-%02d-%02d %02d:%02d:%02d] [%s]: ", 1900 + tm->tm_year, 1 + tm->tm_mon, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, level == ERROR ? "ERROR" : level == WARN ? "WARNING" : level == INFO ? "INFO" : "DEBUG");
    va_list args;
    va_start(args, format);
    vfprintf(logfile, format, args);
    va_end(args);
    fputc('\n', logfile);
    fclose(logfile);
}

int createPDUArray(size_t num_ues, NFAPI_CRC_INDICATION_PDU_T*** ppdu) {
    size_t i;
    *ppdu = (NFAPI_CRC_INDICATION_PDU_T**) malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (*ppdu == NULL) {
        log(ERROR, "Failed to allocate memory for PDU array.");
        return -1;
    }

    for (i = 0; i < num_ues; ++i) {
        (*ppdu)[i] = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if ((*ppdu)[i] == NULL) {
            log(ERROR, "Failed to allocate memory for PDU at index %zu.", i);
            return -1;
        }

        // Initialize each structure
        memset((*ppdu)[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*ppdu)[i]->rnti = i + 1;
        (*ppdu)[i]->crc_indication.crcflag = rand() % 2;
    }

    return 0;
}

pthread_mutex_t mutex;
void pthread_init(void) {
    pthread_mutex_init(&mutex, NULL);
}

int pthread_lock(void) {
    return pthread_mutex_lock(&mutex);
}

int pthread_unlock(void) {
    return pthread_mutex_unlock(&mutex);
}
