    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char key[AES_KEYSIZE_256/8];
    char encrypted_data[MAX_STRING_LENGTH * num_ues];
    int total_length = 0;

    va_start(params, max_params);
    for (int i = 0; i < max_params && i < num_ues; ++i) {
        char* param = va_arg(params, char*);
        if (param != NULL) {
            int len = strlen(param);
            assert(len <= MAX_STRING_LENGTH);
            if (!ignore_whitespace) {
                lengths[i] = len;
                params_arr[i] = param;
            } else {
                int new_len = 0;
                for (int j = 0; j < len && new_len + MAX_STRING_LENGTH <= total_length; ++j) {
                    if (!isspace(param[j])) {
                        params_arr[i] = &param[new_len];
                        lengths[i] -= new_len;
                        new_len += strlen(&param[j]);
                    } else {
                        ++j;
                    }
                }
                assert(new_len <= MAX_STRING_LENGTH);
                params_arr[i] = &param[0];
                lengths[i] = new_len;
            }
            total_length += lengths[i];
        }
    }
    va_end(params);

    // Derive key securely using PBKDF2 with a specified number of iterations and salt
    unsigned char derived_key[SHA256_DIGEST_LENGTH];
    PBKDF2(EVP_sha256(), (const unsigned char*)salt, strlen(salt), iterations, NULL, derived_key, SHA256_DIGEST_LENGTH);

    // Initialize cipher context and generate a new IV for each operation
    EVP_EncryptInit_ex(&cipher_ctx, EVP_aes_256_cbc(), derived_key, iv, NULL);

    pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_ues; ++i) {
        // Initialize PDU structure with random CRCFLAG
        pdu_array[i].crc_indication_rel8_tag.crcflag = rand() % 2;

        // Concatenate parameters and compute MD5 hash for efficient memory usage
        char concat_str[total_length];
        int offset = 0;
        for (int j = 0; j < max_params && i < num_ues; ++j) {
            strncat(concat_str + offset, params_arr[j], lengths[j]);
            offset += lengths[j];
        }
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        SHA1((const unsigned char*)concat_str, total_length, md5_hash);

        // Verify the correctness of the cipher initialization
        assert(EVP_CIPHER_CTX_get_iv(cipher_ctx) == iv);

        // Encrypt the PDU data and add it to encrypted_data
        int pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        unsigned char* pdu_data = (unsigned char*)(&pdu_array[i]);
        EVP_EncryptUpdate(cipher_ctx, encrypted_data + i * pdu_size, &pdu_size, pdu_data, pdu_size);

        // Generate a new IV for the next PDU operation
        RAND_bytes(iv, AES_BLOCK_SIZE);
        EVP_EncryptInit_ex(&cipher_ctx, EVP_aes_256_cbc(), derived_key, iv, NULL);
    }

    // Finalize cipher context and add encrypted data to encrypted_data
    unsigned char* final_encrypted_data = (unsigned char*)calloc(1, sizeof(encrypted_data[0]) * (num_ues + AES_BLOCK_SIZE));
    EVP_EncryptFinal_ex(cipher_ctx, final_encrypted_data + num_ues * pdu_size, &pdu_size);
    memcpy(final_encrypted_data, encrypted_data, num_ues * pdu_size);

    free(params_arr);
    free(lengths);
    free(cipher_ctx);

    // Log any errors encountered during execution to a specified file using a custom logging mechanism
    if (log_file) {
        pthread_mutex_lock(&log_mutex);
        fprintf(log_file, "Encrypted data: [%s]\n", final_encrypted_data);
        pthread_mutex_unlock(&log_mutex);
    }
}
