#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void initList() {
    head = NULL;
    pthread_mutex_init(&list_mutex, NULL);
}

bool addToList(NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false;
    new_node->data = *new_entry;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    Node *iter = head;
    bool duplicate_rnti = false;
    while (iter != NULL) {
        if (iter->data.rnti == new_node->data.rnti) {
            duplicate_rnti = true;
            break;
        }
        iter = iter->next;
    }
    pthread_mutex_unlock(&list_mutex);

    if (!duplicate_rnti) {
        if (head == NULL) {
            head = new_node;
        } else {
            Node *iter = head;
            while (iter->next != NULL) iter = iter->next;
            iter->next = new_node;
        }
    }
    return !duplicate_rnti;
}

void populateArray(NFAPI_CRC_INDICATION_PDU_T *arr, int N) {
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.tag = (RX_UE_INFORMATION_TAG)(i % 5);
        entry.rnti = i;
        entry.crc_indication.crcflag = rand() % 2;

        if (!addToList(&entry)) {
            printf("Memory allocation failure\n");
            return;
        }
    }

    int index = 0;
    Node *iter = head;
    while (iter != NULL) {
        arr[index++] = iter->data;
        iter = iter->next;
    }
}
