#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define NFAPI_CRCI_STRUCT_SIZE sizeof(NFAPI_CRCI_STRUCT_T)
#define MAX_MEMORY_USAGE 0.8

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRCI_STRUCT_T;

static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated_count = 0, current_allocations = 0;
static double memory_usage = 0.0;
static bool log_enabled = false;

void set_log_enabled(bool enabled) {
    log_enabled = enabled;
}

void log_memory_usage() {
    if (!log_enabled) return;
    printf("Current memory usage: %.2f%%\n", memory_usage * 100);
}

NFAPI_CRCI_STRUCT_T* allocate_crci_structure() {
    NFAPI_CRCI_STRUCT_T *struct_ptr;

    pthread_mutex_lock(&memory_mutex);
    if (current_allocations + 1 > 1000) {
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }

    struct_ptr = malloc(NFAPI_CRCI_STRUCT_SIZE);
    if (!struct_ptr) {
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }

    allocated_count++;
    current_allocations++;
    memory_usage += (double)NFAPI_CRCI_STRUCT_SIZE / sysconf(_SC_PAGE_SIZE);
    if (current_allocations == 1) {
        printf("Initializing allocation system...\n");
    }

    struct_ptr->tag = GENERIC_RX_UE_INFORMATION;
    struct_ptr->rnti = 0x00000001;
    struct_ptr->crc_indication.CRC_INDICATION_REL8 = 0b10000000;

    // Efficient and fair random number generator based on Xorshift algorithm
    static uint32_t x = 123456789, y = 362436069, z = 521288629, w = 88675123;
    uint32_t t;

    // Ensure CRCFLAG is set to true with a probability of exactly 75%
    do {
        t = x ^ (x << 16);
        x = y;
        y = z;
        z = w;
        w = t ^ (t >> 32);
    } while ((w & 0x80000000) == 0);

