import java.util.*;
import java.security.SecureRandom;
import java.time.Instant;

public class CRCIndicationGenerator {
    static class NFAPI_CRC_INDICATION_PDU_T {
        public int RX_UE_INFORMATION_TAG;
        public int RNTI;
        public int CRC_INDICATION_REL8_TAG;
        public boolean CRCFLAG;
    }

    static class DisjointSet {
        private Map<Integer, Integer> parent = new HashMap<>();
        private Map<Integer, Integer> rank = new HashMap<>();

        public void makeSet(int id) {
            parent.put(id, id);
            rank.put(id, 1);
        }

        public int findSet(int id) {
            if (parent.get(id) != id)
                parent.put(id, findSet(parent.get(id)));
            return parent.get(id);
        }

        public void union(int a, int b) {
            int rootA = findSet(a);
            int rootB = findSet(b);

            long start = Instant.now().toEpochMilli();
            if (rank.get(rootA) > rank.get(rootB)) {
                parent.put(rootB, rootA);
                rank.put(rootA, Math.max(rank.get(rootA), rank.get(rootB) + 1));
            } else {
                parent.put(rootA, rootB);
                rank.put(rootB, Math.max(rank.get(rootA), rank.get(rootB) + 1));
            }
            System.out.printf("Union operation time: %.3f ms\n", Instant.now().toEpochMilli() - start);
        }
    }

    public static void main(String[] args) {
        int N = 10000; // Number of structures to create
        DisjointSet ds = new DisjointSet();
        SecureRandom random = new SecureRandom();
        List<NFAPI_CRC_INDICATION_PDU_T> list = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            int rxiTag = random.nextInt(Integer.MAX_VALUE);
            int rnti = random.nextInt(16 * 32 + 1); // Valid range for RNTI
            int crcRel8Tag = random.nextInt(4096); // Valid range for CRC_INDICATION_REL8_TAG
            boolean crcFlag = random.nextBoolean();

            NFAPI_CRC_INDICATION_PDU_T structure = new NFAPI_CRC_INDICATION_PDU_T();
            structure.RX_UE_INFORMATION_TAG = rxiTag;
            structure.RNTI = rnti;
            structure.CRC_INDICATION_REL8_TAG = crcRel8Tag;
            structure.CRCFLAG = crcFlag;

            int setId = ds.findSet(structure.RX_UE_INFORMATION_TAG);
            ds.makeSet(structure.RNTI + structure.CRC_INDICATION_REL8_TAG * 16);
            list.add(structure);
            ds.union(setId, structure.RNTI + structure.CRC_INDICATION_REL8_TAG * 16);
        }
    }
}
